// All potentially exportable visuals/takes contribute their genuinely mapped
// scalar fields. This keeps queued/batch export snapshots self-contained
// without retaining remembered mappings from Constant bindings.
bool SessionPotentiallyNeedsRoughnessMotionFields(
    const PreviewLayerSession& session) {
    const auto needsFields = [&session](PointCloudStyleState style) {
        style = invisible_places::renderer::pointcloud::
            MakePointCloudStyleForSceneRole(style, session.sceneRole);
        return invisible_places::renderer::pointcloud::
                   PointCloudStyleHasActiveRoughnessMotion(style) &&
               !style.roughnessMotionFullLayer;
    };
    if (needsFields(session.pointStyle)) {
        return true;
    }
    return std::any_of(
        session.pointVisuals.begin(),
        session.pointVisuals.end(),
        [&needsFields](const SavedPointVisualState& visual) {
            return needsFields(visual.style);
        });
}

invisible_places::app::UsedScalarFieldSet CollectRequiredScalarFieldNames(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& session) {
    invisible_places::app::UsedScalarFieldSet used;
    const auto addStyle = [&used](const PointCloudStyleState& style) {
        used.AddBinding(style.pointSize);
        used.AddBinding(style.surfelDiameter);
        used.AddBinding(style.opacity);
        used.AddBinding(style.emissiveStrength);
        used.AddBinding(style.depthFade);
        used.AddBinding(style.colormapPosition);
    };
    addStyle(session.pointStyle);
    for (const auto& visual : session.pointVisuals) {
        addStyle(visual.style);
    }
    if (SessionPotentiallyNeedsRoughnessMotionFields(session)) {
        for (const auto& available : session.availableScalarFields) {
            const auto normalized =
                NormalizeMotionScalarFieldName(available.name);
            if (normalized.find("roughness") != std::string::npos ||
                normalized.find("groundid") != std::string::npos) {
                used.AddFieldName(available.name);
            }
        }
    }
    // Colourise selectors carry no per-role scoping, and the same field set
    // ships in every density variant and role of a scene, so every effect
    // in every exportable take contributes to every session rather than
    // risking a miss when batch export selects a take not currently open.
    for (const auto& takeState : runtimeState.water.timingTakeSceneStates) {
        for (const auto& effect : takeState.colouriseEffects) {
            used.AddColouriseEffect(effect);
        }
    }
    return used;
}

invisible_places::io::PointCloudScalarFieldFilter
CollectScalarFieldLoadFilter(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& session) {
    invisible_places::io::PointCloudScalarFieldFilter filter;
    if (runtimeState.projectSettings.loadAllScalarFields) {
        return filter;
    }
    filter.mode =
        invisible_places::io::PointCloudScalarFieldFilter::Mode::Selected;
    filter.names = CollectRequiredScalarFieldNames(runtimeState, session).Names();
    filter.containsPatterns =
        invisible_places::app::AlwaysResidentScalarFieldPatterns();
    if (SessionPotentiallyNeedsRoughnessMotionFields(session)) {
        filter.containsPatterns.push_back("roughness");
        filter.containsPatterns.push_back("groundid");
    }
    return filter;
}

// First required-but-unloaded field of a session whose source offers it, or
// nullopt when the session is fully satisfied.
std::optional<std::string> SessionMissingRequiredScalarFieldName(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& session) {
    if (session.kind != LayerKind::PointCloud || !session.cpuResident ||
        session.offlinePointCloud == nullptr ||
        session.availableScalarFields.empty()) {
        return std::nullopt;
    }
    const auto required = CollectRequiredScalarFieldNames(runtimeState, session);
    if (required.Empty()) {
        return std::nullopt;
    }
    for (const auto& available : session.availableScalarFields) {
        if (!required.Contains(available.name)) {
            continue;
        }
        const bool resident = std::any_of(
            session.scalarFields.begin(),
            session.scalarFields.end(),
            [&available](const invisible_places::io::ScalarFieldStats& field) {
                return field.name == available.name;
            });
        if (!resident) {
            return available.name;
        }
    }
    return std::nullopt;
}

void StartScalarFieldLoad(
    PreviewRuntimeState* runtimeState,
    std::size_t sessionIndex,
    const std::string& fieldName) {
    if (runtimeState == nullptr ||
        runtimeState->pendingScalarFieldLoad.has_value() ||
        sessionIndex >= runtimeState->sessions.size()) {
        return;
    }
    auto& session = runtimeState->sessions[sessionIndex];
    if (session.offlinePointCloud == nullptr) {
        return;
    }
    const auto expectedPointCount = session.offlinePointCloud->PointCount();
    std::int32_t sourceIndex = -1;
    for (const auto& available : session.availableScalarFields) {
        if (available.name == fieldName) {
            sourceIndex = static_cast<std::int32_t>(available.sourceIndex);
            break;
        }
    }
    if (sourceIndex < 0 || expectedPointCount == 0U) {
        return;
    }

    auto backgroundState = std::make_shared<BackgroundScalarFieldLoadState>();
    const auto sourcePath = session.sourcePath;
    std::jthread backgroundThread{[backgroundState,
                                   sourcePath,
                                   fieldName,
                                   sourceIndex,
                                   expectedPointCount](std::stop_token stopToken) {
#ifdef __APPLE__
        // Field streams are opportunistic prefetch/backfill: run them at
        // utility QoS so they never compete with the render loop for
        // performance cores.
        pthread_set_qos_class_self_np(QOS_CLASS_UTILITY, 0);
#endif
        ScalarFieldLoadResult result;
        result.stats.name = fieldName;
        result.stats.sourceIndex = sourceIndex;
        try {
            result.values.assign(expectedPointCount, 0.0F);
        } catch (const std::exception& error) {
            result.errorMessage =
                std::string{"Scalar field allocation failed: "} + error.what();
            std::scoped_lock lock(backgroundState->mutex);
            backgroundState->result = std::move(result);
            return;
        }
        // A cached column is a single contiguous read; the interleaved PLY
        // scan is the fallback, written through for next time.
        if (invisible_places::io::ReadPointCloudCachedField(
                sourcePath,
                fieldName,
                result.values,
                &result.stats)) {
            result.success = true;
            std::scoped_lock lock(backgroundState->mutex);
            backgroundState->result = std::move(result);
            return;
        }
        result.stats = {};
        result.stats.name = fieldName;
        result.stats.sourceIndex = sourceIndex;
        const auto streamResult =
            invisible_places::io::StreamPointCloudSelectedValues(
                sourcePath,
                {.source = invisible_places::io::
                     PointCloudSelectedValueSource::ScalarField,
                 .scalarFieldName = fieldName},
                [&](float value, std::uint64_t pointIndex) {
                    if (stopToken.stop_requested()) {
                        return false;
                    }
                    if (pointIndex < expectedPointCount) {
                        result.values[static_cast<std::size_t>(pointIndex)] =
                            value;
                        result.stats.Include(value);
                    }
                    return true;
                });
        if (stopToken.stop_requested()) {
            return;
        }
        if (!streamResult.success) {
            result.errorMessage = streamResult.errorMessage.empty()
                                      ? "Scalar field stream failed."
                                      : streamResult.errorMessage;
        } else if (streamResult.pointCount != expectedPointCount) {
            result.errorMessage =
                "Scalar field stream returned an unexpected point count.";
        } else {
            result.success = true;
            if (!invisible_places::io::WritePointCloudCachedField(
                    sourcePath,
                    result.stats,
                    result.values)) {
                std::cerr << "Field cache write-through failed for '"
                          << fieldName << "'." << std::endl;
            }
        }
        std::scoped_lock lock(backgroundState->mutex);
        backgroundState->result = std::move(result);
    }};

    runtimeState->pendingScalarFieldLoad = PendingScalarFieldLoad{
        .sessionIndex = sessionIndex,
        .fieldName = fieldName,
        .contentGeneration = session.pointCloudContentGeneration,
        .backgroundState = std::move(backgroundState),
        .backgroundThread = std::move(backgroundThread),
        .startedAt = std::chrono::steady_clock::now(),
    };
    runtimeState->statusMessage =
        "Loading scalar field '" + fieldName + "' for " +
        session.displayName + " in the background...";
}

bool RemoveGeneratedScalarFieldsFromSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    std::span<const std::string_view> fieldNames);

// Combined CPU+GPU bytes one resident field costs: the field-major CPU
// column plus, for GPU-resident sessions, its share of the host-visible
// scalar buffer.
std::uint64_t SessionScalarFieldBytesPerField(const PreviewLayerSession& session) {
    const auto pointCount =
        session.offlinePointCloud != nullptr
            ? session.offlinePointCloud->PointCount()
            : 0U;
    return static_cast<std::uint64_t>(pointCount) * sizeof(float) *
           (session.gpuResident ? 2U : 1U);
}

// Runs the least-recently-referenced eviction pass once the resident
// scalar payload exceeds the configured budget. One session's batch per
// sweep: each removal compacts that session's field matrix and replaces
// its GPU scalar buffer, so batching per session bounds the stall.
void EvictScalarFieldsOverBudget(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    const auto budgetGigabytes =
        runtimeState->projectSettings.scalarFieldBudgetGigabytes;
    if (!(budgetGigabytes > 0.0F)) {
        return;
    }
    const auto budgetBytes = static_cast<std::uint64_t>(
        static_cast<double>(budgetGigabytes) * 1024.0 * 1024.0 * 1024.0);

    std::vector<invisible_places::app::ScalarFieldResidencyCandidate> candidates;
    std::uint64_t residentBytes = 0U;
    for (std::size_t sessionIndex = 0U;
         sessionIndex < runtimeState->sessions.size();
         ++sessionIndex) {
        const auto& session = runtimeState->sessions[sessionIndex];
        if (session.kind != LayerKind::PointCloud ||
            session.offlinePointCloud == nullptr) {
            continue;
        }
        const auto bytesPerField = SessionScalarFieldBytesPerField(session);
        const auto required = session.gpuResident
                                  ? CollectRequiredScalarFieldNames(
                                        *runtimeState,
                                        session)
                                  : invisible_places::app::UsedScalarFieldSet{};
        for (const auto& field : session.scalarFields) {
            residentBytes += bytesPerField;
            std::uint64_t lastTick = 0U;
            if (const auto tickIt =
                    session.scalarFieldLastRequiredTick.find(field.name);
                tickIt != session.scalarFieldLastRequiredTick.end()) {
                lastTick = tickIt->second;
            }
            candidates.push_back({
                .sessionIndex = sessionIndex,
                .fieldName = field.name,
                .bytes = bytesPerField,
                .lastRequiredTick = lastTick,
                .required = required.Contains(field.name),
                // Every disk-backed field can be streamed back on demand.
                // Generated Water overlays carry explicit content semantics,
                // so source-cloud slots no longer need a compatibility floor.
                .evictable = field.sourceIndex >= 0 && session.loaded,
            });
        }
    }
    const auto selected = invisible_places::app::SelectScalarFieldEvictions(
        candidates,
        residentBytes,
        budgetBytes);
    if (selected.empty()) {
        return;
    }
    const auto targetSession = candidates[selected.front()].sessionIndex;
    std::vector<std::string> names;
    for (const auto index : selected) {
        if (candidates[index].sessionIndex == targetSession) {
            names.push_back(candidates[index].fieldName);
        }
    }
    std::vector<std::string_view> nameViews{names.begin(), names.end()};
    if (!RemoveGeneratedScalarFieldsFromSession(
            runtimeState,
            viewport,
            targetSession,
            nameViews)) {
        return;
    }
    auto& session = runtimeState->sessions[targetSession];
    // Removal renumbers the surviving slots, so slot-keyed histogram
    // caches for this session are stale.
    session.visualsFieldHistograms.clear();
    for (const auto& name : names) {
        session.scalarFieldLastRequiredTick.erase(name);
    }
    runtimeState->statusMessage =
        "Freed " + std::to_string(names.size()) +
        " unused scalar field" + (names.size() == 1U ? "" : "s") + " from " +
        session.displayName + " (over the scalar-field budget).";
}

// Streams at most one missing required field at a time and applies the
// budget eviction pass, checked on a small frame cadence. Heavy work only
// starts while the app is otherwise idle for it: never during an offline
// export, a whole-cloud load, or the shared-cache high-memory slot.
void EnsureRequiredScalarFieldsResident(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr ||
        runtimeState->pendingScalarFieldLoad.has_value() ||
        runtimeState->pendingLoad.has_value() ||
        runtimeState->offlineRenderJob.active ||
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
        runtimeState->water.waterSurfaceCachePreprocessPending) {
        return;
    }
    constexpr std::uint64_t kResidencyCheckIntervalFrames = 15U;
    if ((runtimeState->scalarFieldResidencyPollCounter++ %
         kResidencyCheckIntervalFrames) != 0U) {
        return;
    }
    const auto sweepTick = runtimeState->scalarFieldResidencyPollCounter;
    for (std::size_t sessionIndex = 0U;
         sessionIndex < runtimeState->sessions.size();
         ++sessionIndex) {
        auto& session = runtimeState->sessions[sessionIndex];
        // CPU-only canonical analysis and retired display bundles never
        // render their point material. Backfilling visual fields into those
        // large support clouds wastes I/O and memory; export sessions are
        // checked explicitly by EnsureFullDensityExportSourcesReady.
        if (!session.gpuResident) {
            continue;
        }
        if (session.kind == LayerKind::PointCloud &&
            session.offlinePointCloud != nullptr &&
            !session.scalarFields.empty()) {
            // Stamp every currently referenced resident field; fields that
            // drop out of the required set age from their last stamp.
            const auto required =
                CollectRequiredScalarFieldNames(*runtimeState, session);
            for (const auto& field : session.scalarFields) {
                if (required.Contains(field.name)) {
                    session.scalarFieldLastRequiredTick[field.name] = sweepTick;
                }
            }
        }
        const auto missing =
            SessionMissingRequiredScalarFieldName(*runtimeState, session);
        if (missing.has_value()) {
            StartScalarFieldLoad(runtimeState, sessionIndex, missing.value());
            return;
        }
    }
    // The histogram/flow-worker guard matches the append deferral: both
    // mutate the field-major arrays those workers may be reading.
    if (runtimeState->timingColouriseHistogram.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.pendingCapture) {
        return;
    }
    EvictScalarFieldsOverBudget(runtimeState, viewport);
}

void BeginLayerLoad(
    std::size_t sessionIndex,
    PreviewRuntimeState* runtimeState,
    PointCloudLoadPurpose purpose = PointCloudLoadPurpose::Interactive,
    std::uint64_t sceneSwitchGeneration = 0U) {
    if (runtimeState == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return;
    }

    if (purpose == PointCloudLoadPurpose::Interactive) {
        runtimeState->selectedSessionIndex = sessionIndex;
    }
    auto& session = runtimeState->sessions[sessionIndex];

    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->statusMessage = "Please wait for the current layer to finish loading.";
        return;
    }

    const bool cpuOnlyLoad = purpose == PointCloudLoadPurpose::AnalysisCpuOnly ||
                             purpose == PointCloudLoadPurpose::StagedDisplay;
    const bool alreadyReady = cpuOnlyLoad ? session.cpuResident : session.gpuResident;
    if (alreadyReady) {
        runtimeState->statusMessage = session.displayName + " is already loaded.";
        runtimeState->errorMessage.clear();
        return;
    }

    const bool exclusiveHighMemoryWorkActive =
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
        runtimeState->water.waterSurfaceCachePreprocessPending;
    if (exclusiveHighMemoryWorkActive) {
        const auto alreadyQueued = std::any_of(
            runtimeState->persistence.queuedLoads.begin(),
            runtimeState->persistence.queuedLoads.end(),
            [&](const QueuedLayerLoad& queued) {
                return queued.sessionIndex == sessionIndex &&
                       queued.purpose == purpose &&
                       queued.sceneSwitchGeneration == sceneSwitchGeneration;
            });
        if (!alreadyQueued) {
            runtimeState->persistence.queuedLoads.push_back({
                .sessionIndex = sessionIndex,
                .purpose = purpose,
                .sceneSwitchGeneration = sceneSwitchGeneration,
            });
        }
        runtimeState->statusMessage =
            "Queued " + session.displayName +
            " until the active shared-cache high-memory slot completes.";
        runtimeState->errorMessage.clear();
        return;
    }

    if (session.kind == LayerKind::PointCloud && session.cpuResident && session.offlinePointCloud != nullptr) {
        runtimeState->pendingLoad = PendingLayerLoad{
            .sessionIndex = sessionIndex,
            .purpose = purpose,
            .sceneSwitchGeneration = sceneSwitchGeneration,
            .phase = PendingLoadPhase::UploadPending,
            .backgroundState = nullptr,
            .backgroundThread = {},
            .completedResult = std::nullopt,
            .useResidentPointCloud = true,
            .showUploadOverlayFrame = true,
            .startedAt = std::chrono::steady_clock::now(),
        };
        runtimeState->statusMessage = cpuOnlyLoad
                                          ? "Preparing resident " + session.displayName + " in CPU memory..."
                                          : "Uploading resident " + session.displayName + " to the GPU...";
        runtimeState->errorMessage.clear();
        return;
    }

    const auto layerKind = session.kind;
    const auto filePath = session.sourcePath;
    const auto transformPath = session.transformPath;
    // Resolved on the main thread against the session's authored state at
    // spawn time; fields referenced by later edits stream in on demand.
    const auto scalarFieldFilter =
        layerKind == LayerKind::PointCloud
            ? CollectScalarFieldLoadFilter(*runtimeState, session)
            : invisible_places::io::PointCloudScalarFieldFilter{};
    runtimeState->statusMessage = "Loading " + session.displayName + " in the background...";
    runtimeState->errorMessage.clear();
    std::cout << "Loading " << LayerKindLabel(layerKind) << ": " << filePath.filename().string() << std::endl;

    auto backgroundState = std::make_shared<BackgroundLayerLoadState>();
    std::jthread backgroundThread{
        [backgroundState, layerKind, filePath, transformPath, scalarFieldFilter](std::stop_token stopToken) {
            if (stopToken.stop_requested()) {
                return;
            }

            LayerLoadResult result =
                layerKind == LayerKind::PointCloud
                    ? LayerLoadResult{invisible_places::io::LoadPointCloudWithFieldCache(
                          filePath,
                          scalarFieldFilter)}
                    : LayerLoadResult{
                          invisible_places::io::LoadGaussianSplat(filePath, transformPath)};
            if (stopToken.stop_requested()) {
                return;
            }

            std::scoped_lock lock(backgroundState->mutex);
            backgroundState->result = std::move(result);
        }};

    runtimeState->pendingLoad = PendingLayerLoad{
        .sessionIndex = sessionIndex,
        .purpose = purpose,
        .sceneSwitchGeneration = sceneSwitchGeneration,
        .phase = PendingLoadPhase::CpuLoading,
        .backgroundState = std::move(backgroundState),
        .backgroundThread = std::move(backgroundThread),
        .completedResult = std::nullopt,
        .useResidentPointCloud = false,
        .showUploadOverlayFrame = false,
        .startedAt = std::chrono::steady_clock::now(),
    };
}

// Completes one background scalar-field stream: appends the field to the
// resident cloud (append keeps every existing slot stable, so name-resolved
// bindings, colourise slots, and per-slot histogram caches stay valid) and
// replaces the GPU scalar buffer for GPU-resident sessions.
void PollPendingScalarFieldLoad(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr ||
        !runtimeState->pendingScalarFieldLoad.has_value() ||
        runtimeState->offlineRenderJob.active) {
        return;
    }
    // Appending grows the field-major value vector, which may reallocate.
    // Workers that hold the cloud's shared_ptr and read those arrays
    // (colourise histograms, Flow trail builds) must not be mid-read when
    // that happens; defer completion until they settle.
    if (runtimeState->timingColouriseHistogram.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.pendingCapture) {
        return;
    }
    auto& pending = runtimeState->pendingScalarFieldLoad.value();
    std::optional<ScalarFieldLoadResult> result;
    {
        std::scoped_lock lock(pending.backgroundState->mutex);
        if (!pending.backgroundState->result.has_value()) {
            return;
        }
        result = std::move(pending.backgroundState->result);
        pending.backgroundState->result.reset();
    }
    const auto sessionIndex = pending.sessionIndex;
    const auto contentGeneration = pending.contentGeneration;
    const auto fieldName = pending.fieldName;
    runtimeState->pendingScalarFieldLoad.reset();

    if (!result->success) {
        runtimeState->errorMessage = "Scalar field '" + fieldName +
                                     "' failed to load: " + result->errorMessage;
        runtimeState->statusMessage.clear();
        std::cerr << runtimeState->errorMessage << std::endl;
        return;
    }
    if (sessionIndex >= runtimeState->sessions.size()) {
        return;
    }
    auto& session = runtimeState->sessions[sessionIndex];
    if (session.offlinePointCloud == nullptr ||
        session.pointCloudContentGeneration != contentGeneration ||
        session.offlinePointCloud->PointCount() != result->values.size()) {
        // The payload changed while the stream ran; the residency sweep will
        // re-request the field against the new payload if still needed.
        return;
    }
    auto& cloud = *session.offlinePointCloud;
    const bool alreadyResident = std::any_of(
        cloud.scalarFields.begin(),
        cloud.scalarFields.end(),
        [&fieldName](const invisible_places::io::ScalarFieldStats& field) {
            return field.name == fieldName;
        });
    if (alreadyResident) {
        return;
    }
    try {
        cloud.scalarFieldValues.insert(
            cloud.scalarFieldValues.end(),
            result->values.begin(),
            result->values.end());
    } catch (const std::exception& error) {
        runtimeState->errorMessage = "Scalar field '" + fieldName +
                                     "' could not be appended: " + error.what();
        runtimeState->statusMessage.clear();
        return;
    }
    cloud.scalarFields.push_back(result->stats);
    session.scalarFields = cloud.scalarFields;

    if (session.gpuResident) {
        try {
            viewport->UploadPointCloudScalarFields(
                sessionIndex,
                cloud.scalarFields,
                cloud.scalarFieldValues);
        } catch (const std::exception& error) {
            runtimeState->errorMessage =
                "GPU upload failed while adding scalar field '" + fieldName +
                "': " + std::string{error.what()};
            runtimeState->statusMessage.clear();
            return;
        }
    }
    runtimeState->statusMessage = "Loaded scalar field '" + fieldName +
                                  "' for " + session.displayName + ".";
    runtimeState->errorMessage.clear();
}

void PollPendingLayerLoad(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    // Retire completed histogram readers before scalar-field completion
    // considers mutating the same field-major arrays. Keeping this in the
    // shared poll makes smokes and benchmarks follow the live-loop ordering;
    // a finished-but-unpolled jthread must not look permanently active.
    PollTimingColouriseHistogram(runtimeState);
    // Scalar-field residency shares this poll site so every frame pump —
    // live loop, smokes, benchmarks — services field streams without extra
    // wiring. Both calls are cheap no-ops in the common case.
    PollPendingScalarFieldLoad(runtimeState, viewport);
    EnsureRequiredScalarFieldsResident(runtimeState, viewport);
    if (!runtimeState->pendingLoad.has_value()) {
        return;
    }

    auto& pendingLoad = runtimeState->pendingLoad.value();

    if (pendingLoad.phase == PendingLoadPhase::CpuLoading) {
        const auto completedResult = TakeCompletedBackgroundResult(pendingLoad.backgroundState);
        if (!completedResult.has_value()) {
            return;
        }

        if (!LoadResultSucceeded(completedResult.value())) {
            runtimeState->statusMessage.clear();
            runtimeState->errorMessage = "Load failed: " + LoadResultErrorMessage(completedResult.value());
            std::cerr << runtimeState->errorMessage << std::endl;
            HandleScenePurposeLoadFailed(
                runtimeState,
                viewport,
                pendingLoad.sessionIndex,
                pendingLoad.purpose,
                pendingLoad.sceneSwitchGeneration,
                runtimeState->errorMessage);
            runtimeState->pendingLoad.reset();
            return;
        }

        pendingLoad.completedResult = std::move(completedResult);
        pendingLoad.phase = PendingLoadPhase::UploadPending;
        pendingLoad.showUploadOverlayFrame = true;
        const bool cpuOnlyLoad =
            pendingLoad.purpose == PointCloudLoadPurpose::AnalysisCpuOnly ||
            pendingLoad.purpose == PointCloudLoadPurpose::StagedDisplay;
        runtimeState->statusMessage = cpuOnlyLoad
                                          ? "Preparing " +
                                                runtimeState->sessions[pendingLoad.sessionIndex].displayName +
                                                " in CPU memory..."
                                          : "Uploading " +
                                                runtimeState->sessions[pendingLoad.sessionIndex].displayName +
                                                " to the GPU...";
        return;
    }

    if (pendingLoad.showUploadOverlayFrame) {
        pendingLoad.showUploadOverlayFrame = false;
        return;
    }

    if (pendingLoad.useResidentPointCloud) {
        const auto purpose = pendingLoad.purpose;
        const auto completedSessionIndex = pendingLoad.sessionIndex;
        const auto sceneSwitchGeneration = pendingLoad.sceneSwitchGeneration;
        const bool cpuOnlyLoad = purpose == PointCloudLoadPurpose::AnalysisCpuOnly ||
                                 purpose == PointCloudLoadPurpose::StagedDisplay;
        const PointCloudActivationOptions options{
            .uploadToGpu = !cpuOnlyLoad,
            .makeVisible = purpose == PointCloudLoadPurpose::Interactive,
            .selectSession = purpose == PointCloudLoadPurpose::Interactive,
            .focusWhenFirstVisible = purpose == PointCloudLoadPurpose::Interactive,
        };
        const bool succeeded = cpuOnlyLoad
                                   ? true
                                   : UploadResidentPointCloud(
                                         completedSessionIndex,
                                         runtimeState,
                                         viewport,
                                         options);
        runtimeState->pendingLoad.reset();
        if (!succeeded) {
            HandleScenePurposeLoadFailed(
                runtimeState,
                viewport,
                completedSessionIndex,
                purpose,
                sceneSwitchGeneration,
                runtimeState->errorMessage);
            return;
        }
        HandleScenePurposeLoadCompleted(
            runtimeState,
            viewport,
            completedSessionIndex,
            purpose,
            sceneSwitchGeneration);
        if (purpose == PointCloudLoadPurpose::Interactive &&
            HasValidManualFlowPath(runtimeState->water)) {
            QueueWaterFlowTrailRefresh(
                runtimeState,
                WaterOverlayRefreshPersistence::InMemoryOnly,
                std::chrono::milliseconds{0});
        }
        if (purpose == PointCloudLoadPurpose::Interactive) {
            RestoreWaterRippleRuntimeCachesForLoadedSessions(runtimeState, viewport);
        }
        return;
    }

    if (!pendingLoad.completedResult.has_value()) {
        return;
    }

    auto completedLoad = std::move(pendingLoad.completedResult.value());
    pendingLoad.completedResult.reset();
    const auto completedSessionIndex = pendingLoad.sessionIndex;
    const auto completedPurpose = pendingLoad.purpose;
    const auto completedSwitchGeneration = pendingLoad.sceneSwitchGeneration;
    bool activationSucceeded = false;

    std::visit(
        [&](auto&& loadResult) {
            using LoadType = std::decay_t<decltype(loadResult)>;
            if (!loadResult.success) {
                runtimeState->statusMessage.clear();
                runtimeState->errorMessage = "Load failed: " + loadResult.errorMessage;
                std::cerr << runtimeState->errorMessage << std::endl;
                return;
            }

            if constexpr (std::is_same_v<LoadType, invisible_places::io::PointCloudLoadResult>) {
                const bool cpuOnlyLoad =
                    completedPurpose == PointCloudLoadPurpose::AnalysisCpuOnly ||
                    completedPurpose == PointCloudLoadPurpose::StagedDisplay;
                const PointCloudActivationOptions options{
                    .uploadToGpu = !cpuOnlyLoad,
                    .makeVisible = completedPurpose == PointCloudLoadPurpose::Interactive,
                    .selectSession = completedPurpose == PointCloudLoadPurpose::Interactive,
                    .focusWhenFirstVisible = completedPurpose == PointCloudLoadPurpose::Interactive,
                };
                activationSucceeded = ActivateLoadedPointCloud(
                    pendingLoad.sessionIndex,
                    std::move(loadResult.cloud),
                    runtimeState,
                    viewport,
                    options);
            } else {
                activationSucceeded = ActivateLoadedGaussianSplats(
                    pendingLoad.sessionIndex,
                    std::move(loadResult.splats),
                    runtimeState,
                    viewport);
            }
        },
        std::move(completedLoad));

    runtimeState->pendingLoad.reset();
    if (activationSucceeded) {
        HandleScenePurposeLoadCompleted(
            runtimeState,
            viewport,
            completedSessionIndex,
            completedPurpose,
            completedSwitchGeneration);
    } else {
        HandleScenePurposeLoadFailed(
            runtimeState,
            viewport,
            completedSessionIndex,
            completedPurpose,
            completedSwitchGeneration,
            runtimeState->errorMessage);
        return;
    }
    const bool hasManualFlowPath = HasValidManualFlowPath(runtimeState->water);
    if (completedPurpose == PointCloudLoadPurpose::Interactive &&
        ((runtimeState->water.pathCacheLoaded && !runtimeState->water.pathCacheStale) ||
         hasManualFlowPath)) {
        const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
        const bool completedAffectsSupport =
            supportIndex.has_value() &&
            supportIndex.value() < runtimeState->sessions.size() &&
            completedSessionIndex < runtimeState->sessions.size() &&
            (supportIndex.value() == completedSessionIndex ||
             (completedPurpose == PointCloudLoadPurpose::AnalysisCpuOnly &&
              SessionsShareSceneFolder(
                  runtimeState->sessions[supportIndex.value()],
                  runtimeState->sessions[completedSessionIndex])));
        if (completedAffectsSupport) {
            const auto& supportSession = runtimeState->sessions[supportIndex.value()];
            bool generatedCacheUsable = runtimeState->water.pathCacheLoaded &&
                                        !runtimeState->water.pathCacheStale;
            if (generatedCacheUsable) {
                const auto expectedSignature = CombinedWaterSupportSignature(
                    *runtimeState,
                    supportSession,
                    ActiveProfileDefaultWaterSourceSettings(runtimeState->water).path);
                if (runtimeState->water.pathCache.supportSignature != expectedSignature) {
                    runtimeState->water.pathCacheStale = true;
                    runtimeState->water.pathDirty = true;
                    generatedCacheUsable = false;
                }
            }
            if (generatedCacheUsable || hasManualFlowPath) {
                QueueWaterFlowTrailRefresh(
                    runtimeState,
                    WaterOverlayRefreshPersistence::InMemoryOnly,
                    std::chrono::milliseconds{0});
            }
        }
    }
    if (completedPurpose == PointCloudLoadPurpose::Interactive) {
        RestoreWaterRippleRuntimeCachesForLoadedSessions(runtimeState, viewport);
    }
}

void UnloadLayerByIndex(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    bool releaseCpuResources = true) {
    if (runtimeState == nullptr || viewport == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return;
    }

    auto& session = runtimeState->sessions[sessionIndex];
    if (!session.loaded) {
        session.gpuResident = false;
        session.visible = false;
        if (releaseCpuResources) {
            session.cpuResident = false;
            session.pivotSamples.clear();
            session.offlinePointCloud.reset();
        }
        ForgetWaterSeepageLayerAttachment(&runtimeState->water, sessionIndex);
        ClearPreviewLodSampleCache(&session);
        return;
    }

    if (session.kind == LayerKind::PointCloud) {
        if (session.waterFlowGpuPreview) {
            viewport->RemoveWaterFlowGpuSource(sessionIndex);
        } else {
            viewport->RemovePointCloud(sessionIndex);
        }
    } else {
        viewport->RemoveGaussianSplats(sessionIndex);
    }

    session.loaded = false;
    session.gpuResident = false;
    session.visible = false;
    if (releaseCpuResources) {
        session.cpuResident = false;
        session.pivotSamples.clear();
        session.offlinePointCloud.reset();
    }
    ForgetWaterSeepageLayerAttachment(&runtimeState->water, sessionIndex);
    ClearPreviewLodSampleCache(&session);
}

ScenePointCloudRuntime* FindScenePointCloudRuntimeContainingSession(
    PreviewRuntimeState* runtimeState,
    std::size_t sessionIndex) {
    if (runtimeState == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return nullptr;
    }
    return FindScenePointCloudRuntime(runtimeState, runtimeState->sessions[sessionIndex]);
}

std::string WaterSeepageLayerAttachmentKey(std::size_t sessionIndex) {
    return "layer=" + std::to_string(sessionIndex);
}

void ForgetWaterSeepageLayerAttachment(
    WaterWorkflowState* water,
    std::size_t sessionIndex) {
    if (water == nullptr) {
        return;
    }
    const auto key = WaterSeepageLayerAttachmentKey(sessionIndex);
    water->seepageTopologyFingerprints.erase(key);
    water->seepageAttachmentSemanticKeys.erase(key);
    water->seepageParamsFingerprints.erase(key);
}

std::string WaterSeepageSurfaceCacheIdentityKey(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& session,
    const ScenePointCloudRuntime* scene) {
    const auto& cache = runtimeState.water.waterSurfaceCache;
    const auto sourceFolderKey = NormalizePathKey(session.sourcePath.parent_path());
    const bool cacheMatchesSession =
        cache != nullptr &&
        ((scene != nullptr &&
          runtimeState.water.waterSurfaceSceneGroupName == scene->sceneGroupName &&
          runtimeState.water.waterSurfaceCacheSignature == scene->waterSurfaceSignature) ||
         (scene == nullptr &&
          std::any_of(
              cache->sources.begin(),
              cache->sources.end(),
              [&](const auto& source) {
                  return NormalizePathKey(source.sourcePath.parent_path()) == sourceFolderKey;
              })));
    if (cacheMatchesSession) {
        const auto& identity = cache->cacheIdentity;
        std::ostringstream value;
        value << (identity.sourceSignature.empty()
                      ? cache->signature
                      : identity.sourceSignature);
        if (identity.Valid()) {
            value << ":" << std::hex << std::setfill('0');
            for (const auto word : identity.contentDigest) {
                value << std::setw(16) << word;
            }
        }
        return value.str();
    }
    if (scene != nullptr && !scene->waterSurfaceSignature.empty()) {
        return scene->waterSurfaceSignature;
    }
    std::ostringstream fallback;
    fallback << std::setprecision(std::numeric_limits<double>::max_digits10)
             << "standalone:" << NormalizePathKey(session.sourcePath)
             << "|load=" << session.pointCloudContentGeneration
             << "|points=" << session.totalPrimitives
             << "|transform=" << NormalizePathKey(session.transformPath);
    for (const auto value : session.localToWorld.values) {
        fallback << ',' << value;
    }
    if (session.localBounds.valid) {
        fallback << "|local_bounds="
                 << session.localBounds.minimum.x << ','
                 << session.localBounds.minimum.y << ','
                 << session.localBounds.minimum.z << ','
                 << session.localBounds.maximum.x << ','
                 << session.localBounds.maximum.y << ','
                 << session.localBounds.maximum.z;
    }
    return fallback.str();
}

std::string WaterSeepageSemanticTopologyKey(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& session) {
    const auto* scene = FindScenePointCloudRuntime(runtimeState, session);
    auto role = NormalizeSceneRoleName(session.sceneRole);
    if (role == "VEGETATION") {
        role = "VEG";
    }
    std::ostringstream key;
    key << "seepage-role-topology-v2|scene="
        << (scene != nullptr ? scene->sceneGroupName : session.sceneGroupName)
        << "|folder="
        << NormalizePathKey(
               scene != nullptr ? scene->sourceFolder : session.sourcePath.parent_path())
        << "|surface="
        << WaterSeepageSurfaceCacheIdentityKey(runtimeState, session, scene)
        << "|role=" << role
        << "|authored="
        << invisible_places::water::WaterSeepageAuthoredTopologyFingerprint(
               runtimeState.water.seepageNodes,
               role);
    return key.str();
}

std::string WaterSeepageSupportNodeFingerprint(
    std::string_view semanticKey,
    const WaterSeepageNode& node,
    std::string_view role) {
    // Strip the aggregate authored hash while retaining scene, cache identity,
    // and role. Unchanged nodes can then reuse their settled connected-cell
    // selection when a sibling node changes topology.
    const auto authoredOffset = semanticKey.find("|authored=");
    std::ostringstream key;
    key << (authoredOffset == std::string_view::npos
                ? semanticKey
                : semanticKey.substr(0U, authoredOffset))
        << "|node="
        << invisible_places::water::WaterSeepageAuthoredTopologyFingerprint(
               std::span<const WaterSeepageNode>{&node, 1U},
               role);
    return key.str();
}

// A newly uploaded density variant receives the already-settled semantic
// topology before it can become visible. This is a descriptor attachment, not
// a guide trace or spatial-grid build.
void AttachCachedWaterSeepageTopologyToSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex) {
    if (runtimeState == nullptr || viewport == nullptr ||
        sessionIndex >= runtimeState->sessions.size()) {
        return;
    }
    const auto& session = runtimeState->sessions[sessionIndex];
    if (!IsAuthoredWaterTerrainSession(session)) {
        return;
    }
    const auto semanticKey = WaterSeepageSemanticTopologyKey(*runtimeState, session);
    const auto gridIt = runtimeState->water.seepageRuntimeGrids.find(semanticKey);
    if (gridIt == runtimeState->water.seepageRuntimeGrids.end()) {
        return;
    }
    const auto attachmentKey = WaterSeepageLayerAttachmentKey(sessionIndex);
    viewport->UploadWaterSeepageTopology(sessionIndex, gridIt->second);
    runtimeState->water.seepageTopologyFingerprints[attachmentKey] =
        invisible_places::water::WaterSeepageTopologyFingerprint(gridIt->second);
    runtimeState->water.seepageAttachmentSemanticKeys[attachmentKey] = semanticKey;
    runtimeState->water.seepageParamsFingerprints[attachmentKey] =
        invisible_places::water::WaterSeepageParamsFingerprint(gridIt->second);
    ++runtimeState->water.seepageDescriptorAttachmentRevision;
    ++runtimeState->water.seepageTopologyUploadRevision;
    ++runtimeState->water.seepageParamsUploadRevision;
}

const SceneDisplayBundleRuntime* FindSceneDisplayBundle(
    const ScenePointCloudRuntime& scene,
    invisible_places::scene::PointSpacingMicrometres spacingMicrometres) {
    const auto it = std::find_if(
        scene.displayBundles.begin(),
        scene.displayBundles.end(),
        [&](const SceneDisplayBundleRuntime& bundle) {
            return bundle.spacingMicrometres == spacingMicrometres;
        });
    return it == scene.displayBundles.end() ? nullptr : &*it;
}

bool SceneAnalysisSourcesReady(
    const PreviewRuntimeState& runtimeState,
    const ScenePointCloudRuntime& scene) {
    return std::all_of(
        scene.analysisSessionIndices.begin(),
        scene.analysisSessionIndices.end(),
        [&](const std::optional<std::size_t>& sessionIndex) {
            return sessionIndex.has_value() &&
                   sessionIndex.value() < runtimeState.sessions.size() &&
                   IsCpuReadyAnalysisPointCloudSource(runtimeState.sessions[sessionIndex.value()]);
        });
}

bool LoadAlreadyQueued(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex,
    PointCloudLoadPurpose purpose,
    std::uint64_t generation) {
    return std::any_of(
        runtimeState.persistence.queuedLoads.begin(),
        runtimeState.persistence.queuedLoads.end(),
        [&](const QueuedLayerLoad& queued) {
            return queued.sessionIndex == sessionIndex &&
                   queued.purpose == purpose &&
                   queued.sceneSwitchGeneration == generation;
        });
}

void QueueLayerLoad(
    PreviewRuntimeState* runtimeState,
    std::size_t sessionIndex,
    PointCloudLoadPurpose purpose,
    std::uint64_t generation = 0U) {
    if (runtimeState == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return;
    }
    if (!LoadAlreadyQueued(*runtimeState, sessionIndex, purpose, generation)) {
        runtimeState->persistence.queuedLoads.push_back({
            .sessionIndex = sessionIndex,
            .purpose = purpose,
            .sceneSwitchGeneration = generation,
        });
    }
}

bool QueueSceneAnalysisSourceLoads(
    PreviewRuntimeState* runtimeState,
    ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || scene == nullptr) {
        return false;
    }
    for (const auto sessionIndex : scene->analysisSessionIndices) {
        if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState->sessions.size()) {
            scene->switchError =
                "Canonical ROCK/VEG 1 mm and SAND 2 mm analysis sources are required for this scene.";
            return false;
        }
    }
    for (const auto sessionIndex : scene->analysisSessionIndices) {
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.analysisSource = true;
        if (!session.cpuResident) {
            QueueLayerLoad(
                runtimeState,
                sessionIndex.value(),
                PointCloudLoadPurpose::AnalysisCpuOnly);
        }
    }
    return true;
}

ScenePointCloudRuntime* ActiveSceneForDeferredAnalysis(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    if (runtimeState->selectedSessionIndex.has_value() &&
        runtimeState->selectedSessionIndex.value() < runtimeState->sessions.size()) {
        if (auto* scene = FindScenePointCloudRuntime(
                runtimeState,
                runtimeState->sessions[runtimeState->selectedSessionIndex.value()]);
            scene != nullptr) {
            return scene;
        }
    }
    if (runtimeState->water.activeSupportSessionIndex.has_value() &&
        runtimeState->water.activeSupportSessionIndex.value() < runtimeState->sessions.size()) {
        if (auto* scene = FindScenePointCloudRuntime(
                runtimeState,
                runtimeState->sessions[runtimeState->water.activeSupportSessionIndex.value()]);
            scene != nullptr) {
            return scene;
        }
    }
    const auto sceneIt = std::find_if(
        runtimeState->pointCloudScenes.begin(),
        runtimeState->pointCloudScenes.end(),
        [](const ScenePointCloudRuntime& scene) {
            return scene.displayLoaded && scene.displayVisible;
        });
    return sceneIt == runtimeState->pointCloudScenes.end() ? nullptr : &*sceneIt;
}

bool EnsureSceneAnalysisReadyForAction(
    PreviewRuntimeState* runtimeState,
    DeferredSceneAnalysisAction action,
    std::string_view actionLabel) {
    auto* scene = ActiveSceneForDeferredAnalysis(runtimeState);
    if (scene == nullptr || SceneAnalysisSourcesReady(*runtimeState, *scene)) {
        return true;
    }
    if (!QueueSceneAnalysisSourceLoads(runtimeState, scene)) {
        runtimeState->errorMessage = scene->switchError;
        runtimeState->statusMessage.clear();
        return false;
    }
    scene->deferredAnalysisActions |= DeferredSceneAnalysisActionBit(action);
    runtimeState->statusMessage =
        "Loading canonical analysis sources for " + std::string{actionLabel} +
        "; the action will resume automatically.";
    runtimeState->errorMessage.clear();
    return false;
}

void RollBackSceneDisplaySwitch(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene,
    std::string_view errorMessage) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr) {
        return;
    }
    const auto failedGeneration = scene->switchGeneration;
    for (const auto sessionIndex : scene->pendingDisplaySessionIndices) {
        if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState->sessions.size()) {
            continue;
        }
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.pendingDisplaySource = false;
        if (!session.committedDisplaySource &&
            (session.gpuResident || session.cpuResident)) {
            UnloadLayerByIndex(
                runtimeState,
                viewport,
                sessionIndex.value(),
                !session.analysisSource);
        }
    }
    std::erase_if(
        runtimeState->persistence.queuedLoads,
        [&](const QueuedLayerLoad& queued) {
            return queued.purpose == PointCloudLoadPurpose::StagedDisplay &&
                   queued.sceneSwitchGeneration == failedGeneration;
        });
    scene->pendingDisplaySessionIndices = {};
    scene->pendingDisplaySpacingMicrometres.reset();
    scene->pendingMixedDisplay = false;
    scene->stagedReadyCount = 0U;
    scene->switchError = std::string{errorMessage};
    runtimeState->errorMessage = scene->switchError;
    runtimeState->statusMessage.clear();
}

class PointCloudMutationBatchScope {
  public:
    explicit PointCloudMutationBatchScope(
        invisible_places::renderer::core::VulkanViewportShell* viewport)
        : viewport_{viewport} {
        viewport_->BeginPointCloudMutationBatch();
    }

    PointCloudMutationBatchScope(const PointCloudMutationBatchScope&) = delete;
    PointCloudMutationBatchScope& operator=(const PointCloudMutationBatchScope&) = delete;

    ~PointCloudMutationBatchScope() noexcept {
        if (viewport_ == nullptr) {
            return;
        }
        try {
            viewport_->EndPointCloudMutationBatch();
        } catch (...) {
            // The explicit Finish() path reports failures. During unwinding,
            // preserving the original transaction exception takes priority.
        }
    }

    void Finish() {
        auto* viewport = std::exchange(viewport_, nullptr);
        if (viewport != nullptr) {
            viewport->EndPointCloudMutationBatch();
        }
    }

  private:
    invisible_places::renderer::core::VulkanViewportShell* viewport_ = nullptr;
};

bool CommitSceneDisplaySwitch(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr ||
        runtimeState->offlineRenderJob.active ||
        (!scene->pendingDisplaySpacingMicrometres.has_value() && !scene->pendingMixedDisplay)) {
        return false;
    }
    for (const auto sessionIndex : scene->pendingDisplaySessionIndices) {
        if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState->sessions.size() ||
            !runtimeState->sessions[sessionIndex.value()].cpuResident ||
            runtimeState->sessions[sessionIndex.value()].offlinePointCloud == nullptr) {
            return false;
        }
    }
    const bool hadVisibleLayersBefore = VisibleLayerCount(*runtimeState) > 0U;
    const bool sceneWasLoaded = scene->displayLoaded;

    const auto previousDisplay = scene->committedDisplaySessionIndices;
    const auto nextDisplay = scene->pendingDisplaySessionIndices;
    scene->lastSwitchOldGpuResidentBytes = viewport->PointCloudResidentBytes();
    scene->lastSwitchTargetGpuResidentBytes = 0U;
    scene->lastSwitchPeakGpuResidentBytes = scene->lastSwitchOldGpuResidentBytes;
    scene->lastSwitchGpuSettleCount = 0U;
    scene->lastSwitchFailedTargetResourcesClean = true;

    // The target bundle is staged in CPU memory. Settle once, retire the old
    // GPU bundle, then upload all target roles hidden. No frame is submitted
    // inside this transaction, so rendering can observe only a complete old or
    // complete new role set. Nested resource mutations share this batch's one
    // device settle, and the guard balances it if any Vulkan operation throws.
    std::optional<PointCloudMutationBatchScope> mutationBatch;
    try {
        mutationBatch.emplace(viewport);
    } catch (const std::exception& error) {
        RollBackSceneDisplaySwitch(
            runtimeState,
            viewport,
            scene,
            "Could not settle the prior scene display before replacement: " +
                std::string{error.what()});
        return false;
    }
    std::vector<std::size_t> retiredPreviousSessions;
    std::string transactionError;
    for (const auto sessionIndex : previousDisplay) {
        if (!sessionIndex.has_value() ||
            std::find(nextDisplay.begin(), nextDisplay.end(), sessionIndex) != nextDisplay.end()) {
            continue;
        }
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.visible = false;
        if (session.gpuResident) {
            // Retain CPU data until every target role and its cached Seepage
            // attachment succeeds, so rollback never rescans a PLY file.
            retiredPreviousSessions.push_back(sessionIndex.value());
            try {
                UnloadLayerByIndex(runtimeState, viewport, sessionIndex.value(), false);
            } catch (const std::exception& error) {
                transactionError =
                    "GPU retirement failed while replacing the scene display bundle: " +
                    std::string{error.what()};
                break;
            }
        }
    }

    std::vector<std::size_t> uploadedTargetSessions;
    for (std::size_t roleIndex = 0U; roleIndex < nextDisplay.size(); ++roleIndex) {
        if (!transactionError.empty()) {
            break;
        }
        const auto sessionIndex = nextDisplay[roleIndex];
        auto& session = runtimeState->sessions[sessionIndex.value()];
        const bool alreadyInPreviousDisplay =
            std::find(previousDisplay.begin(), previousDisplay.end(), sessionIndex) !=
            previousDisplay.end();
        if (!session.gpuResident) {
            if (scene->smokeInjectedUploadFailureRoleIndex == roleIndex) {
                scene->smokeInjectedUploadFailureRoleIndex.reset();
                viewport->SetSmokeFailNextPointCloudUploadAfterPartialAllocation();
            }
            const bool uploaded = UploadResidentPointCloud(
                sessionIndex.value(),
                runtimeState,
                viewport,
                PointCloudActivationOptions{
                    .uploadToGpu = true,
                    .makeVisible = false,
                    .selectSession = false,
                    .focusWhenFirstVisible = false,
                });
            if (!uploaded) {
                transactionError = runtimeState->errorMessage.empty()
                                       ? "GPU upload failed while replacing the scene display bundle."
                                       : runtimeState->errorMessage;
                break;
            }
            uploadedTargetSessions.push_back(sessionIndex.value());
        }
        if (alreadyInPreviousDisplay) {
            continue;
        }
        try {
            AttachCachedWaterSeepageTopologyToSession(
                runtimeState,
                viewport,
                sessionIndex.value());
        } catch (const std::exception& error) {
            transactionError =
                "Seepage attachment failed while replacing the scene display bundle: " +
                std::string{error.what()};
            break;
        }
    }

    if (!transactionError.empty()) {
        for (const auto sessionIndex : uploadedTargetSessions) {
            try {
                UnloadLayerByIndex(runtimeState, viewport, sessionIndex, false);
            } catch (const std::exception& error) {
                transactionError +=
                    " Partial target cleanup also failed: " + std::string{error.what()};
            }
        }

        std::string restoreError;
        for (const auto sessionIndex : retiredPreviousSessions) {
            auto& session = runtimeState->sessions[sessionIndex];
            if (!viewport->HasPointCloudResources(sessionIndex)) {
                if (!UploadResidentPointCloud(
                        sessionIndex,
                        runtimeState,
                        viewport,
                        PointCloudActivationOptions{
                            .uploadToGpu = true,
                            .makeVisible = false,
                            .selectSession = false,
                            .focusWhenFirstVisible = false,
                        })) {
                    restoreError = runtimeState->errorMessage;
                    continue;
                }
            } else {
                session.loaded = true;
                session.gpuResident = true;
            }
            try {
                AttachCachedWaterSeepageTopologyToSession(
                    runtimeState,
                    viewport,
                    sessionIndex);
            } catch (const std::exception& error) {
                restoreError = error.what();
            }
        }
        for (const auto sessionIndex : previousDisplay) {
            if (sessionIndex.has_value()) {
                runtimeState->sessions[sessionIndex.value()].visible =
                    scene->displayVisible &&
                    runtimeState->sessions[sessionIndex.value()].gpuResident;
            }
        }
        if (!restoreError.empty()) {
            transactionError += " Previous display restoration also failed: " + restoreError;
        }
        RollBackSceneDisplaySwitch(runtimeState, viewport, scene, transactionError);
        // The partial target has been removed and the complete prior bundle is
        // resident again. Only now may its source-indexed Ripple bindings be
        // restored; they are never rebound against a mixed display.
        try {
            RestoreWaterRippleRuntimeCachesForLoadedSessions(runtimeState, viewport);
        } catch (const std::exception& error) {
            scene->switchError +=
                " Ripple restoration also failed: " + std::string{error.what()};
            runtimeState->errorMessage = scene->switchError;
        }
        scene->lastSwitchFailedTargetResourcesClean = std::all_of(
            nextDisplay.begin(),
            nextDisplay.end(),
            [&](const auto sessionIndex) {
                return std::find(previousDisplay.begin(), previousDisplay.end(), sessionIndex) !=
                           previousDisplay.end() ||
                       !viewport->HasPointCloudResources(sessionIndex.value());
            });
        mutationBatch->Finish();
        scene->lastSwitchTargetGpuResidentBytes = viewport->PointCloudResidentBytes();
        scene->lastSwitchPeakGpuResidentBytes =
            viewport->LastPointCloudMutationBatchPeakResidentBytes();
        scene->lastSwitchGpuSettleCount =
            viewport->LastPointCloudMutationBatchWaitCount();
        runtimeState->previewRenderStateSignatureValid = false;
        return false;
    }

    for (const auto sessionIndex : nextDisplay) {
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.pendingDisplaySource = false;
        session.committedDisplaySource = true;
        session.visible = scene->displayVisible;
    }
    for (const auto sessionIndex : previousDisplay) {
        if (!sessionIndex.has_value() ||
            std::find(nextDisplay.begin(), nextDisplay.end(), sessionIndex) != nextDisplay.end()) {
            continue;
        }
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.committedDisplaySource = false;
        // GPU resources were retired before target upload. Release CPU data
        // only after the transaction commits, unless analysis still owns it.
        if (!session.analysisSource) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex.value(), true);
        }
    }

    const bool committedMixedDisplay = scene->pendingMixedDisplay;
    scene->committedDisplaySessionIndices = nextDisplay;
    scene->committedDisplaySpacingMicrometres = committedMixedDisplay
                                                    ? std::nullopt
                                                    : scene->pendingDisplaySpacingMicrometres;
    scene->pendingDisplaySessionIndices = {};
    scene->pendingDisplaySpacingMicrometres.reset();
    scene->pendingMixedDisplay = false;
    scene->displayLoaded = true;
    scene->mixedDisplay = committedMixedDisplay;
    scene->stagedReadyCount = 0U;
    scene->switchError.clear();
    if (runtimeState->water.authoritativeWaterSurfaceSceneGroupName.empty() ||
        runtimeState->water.authoritativeWaterSurfaceSceneGroupName ==
            scene->sceneGroupName) {
        runtimeState->water.activeWaterSurfaceSceneGroupName =
            scene->sceneGroupName;
    }
    const bool selectCommittedScene =
        !runtimeState->selectedSessionIndex.has_value() ||
        (runtimeState->selectedSessionIndex.value() < runtimeState->sessions.size() &&
         NormalizePathKey(
             runtimeState->sessions[runtimeState->selectedSessionIndex.value()].sourcePath.parent_path()) ==
             NormalizePathKey(scene->sourceFolder));
    if (selectCommittedScene) {
        runtimeState->selectedSessionIndex = scene->committedDisplaySessionIndices.front();
    }
    if ((!hadVisibleLayersBefore || !sceneWasLoaded) &&
        scene->displayVisible && selectCommittedScene) {
        if (runtimeState->preserveProjectCameraOnNextLayerActivation) {
            runtimeState->preserveProjectCameraOnNextLayerActivation = false;
            SyncPivotOverlayToCamera(runtimeState);
        } else if (scene->committedDisplaySessionIndices.front().has_value()) {
            constexpr float kStartupFocusDistanceScale = 0.46F;
            FocusSessionLayer(
                runtimeState,
                *viewport,
                scene->committedDisplaySessionIndices.front().value(),
                kStartupFocusDistanceScale);
        }
    }
    const std::string committedStatus = committedMixedDisplay
                                            ? "Loaded the saved Mixed display set for " +
                                                  scene->sceneGroupName + "."
                                            : "Visible point cloud switched to " +
                                                  FormatFixed(
                                                      static_cast<double>(
                                                          scene->committedDisplaySpacingMicrometres.value()) /
                                                          1000.0,
                                                      3) +
                                                  " mm for " + scene->sceneGroupName + ".";
    if (scene->committedDisplaySessionIndices.front().has_value()) {
        const auto& visualSession = runtimeState->sessions[
            scene->committedDisplaySessionIndices.front().value()];
        UpdateProjectVisualFieldBindingWarning(
            runtimeState,
            BuildProjectVisualFieldBindingWarning(
                *runtimeState,
                ProjectVisualSceneKey(visualSession),
                visualSession.selectedPointVisualName,
                visualSession.pointStyle));
    }

    // Memberships and presentation fields are source-indexed, so restore/rebuild
    // them only after the exact display bundle becomes committed.
    std::size_t restoredRippleSessions = 0U;
    try {
        restoredRippleSessions =
            RestoreWaterRippleRuntimeCachesForLoadedSessions(runtimeState, viewport);
    } catch (const std::exception& error) {
        runtimeState->water.rippleEffectsDirty = true;
        std::cerr << "Ripple restoration after density commit failed: "
                  << error.what() << std::endl;
    }
    if (!runtimeState->water.rippleLayers.empty() && restoredRippleSessions == 0U) {
        runtimeState->water.rippleEffectsDirty = true;
    }
    if (!runtimeState->water.fieldLayers.empty() ||
        !runtimeState->water.fieldSurfaceEffectOverlay.points.empty()) {
        runtimeState->water.fieldEffectsDirty = true;
    }
    mutationBatch->Finish();
    scene->lastSwitchTargetGpuResidentBytes = viewport->PointCloudResidentBytes();
    scene->lastSwitchPeakGpuResidentBytes =
        viewport->LastPointCloudMutationBatchPeakResidentBytes();
    scene->lastSwitchGpuSettleCount =
        viewport->LastPointCloudMutationBatchWaitCount();
    runtimeState->previewRenderStateSignatureValid = false;
    QueueTimingColouriseHistogramPrewarm(
        runtimeState,
        *scene);
    runtimeState->statusMessage = committedStatus;
    runtimeState->errorMessage.clear();
    return true;
}

void CommitReadySceneDisplaySwitches(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr || runtimeState->offlineRenderJob.active ||
        runtimeState->pendingLoad.has_value()) {
        return;
    }
    for (auto& scene : runtimeState->pointCloudScenes) {
        if ((scene.pendingDisplaySpacingMicrometres.has_value() || scene.pendingMixedDisplay) &&
            scene.stagedReadyCount == invisible_places::scene::kScenePointCloudRoleCount) {
            CommitSceneDisplaySwitch(runtimeState, viewport, &scene);
        }
    }
}

bool RequestSceneDisplaySwitch(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene,
    invisible_places::scene::PointSpacingMicrometres spacingMicrometres) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr) {
        return false;
    }
    if (runtimeState->offlineRenderJob.active) {
        runtimeState->errorMessage = "Visible point-cloud switching is disabled during an active export.";
        return false;
    }
    if (scene->pendingDisplaySpacingMicrometres.has_value() || scene->pendingMixedDisplay) {
        runtimeState->statusMessage = "The current scene density switch is still loading.";
        return false;
    }
    const auto* bundle = FindSceneDisplayBundle(*scene, spacingMicrometres);
    if (bundle == nullptr) {
        runtimeState->errorMessage = "That density is incomplete or ambiguous for this scene.";
        return false;
    }
    if (runtimeState->water.authoritativeWaterSurfaceSceneGroupName.empty() ||
        runtimeState->water.authoritativeWaterSurfaceSceneGroupName ==
            scene->sceneGroupName) {
        runtimeState->water.activeWaterSurfaceSceneGroupName =
            scene->sceneGroupName;
    }
    if (scene->displayLoaded &&
        scene->committedDisplaySpacingMicrometres == spacingMicrometres) {
        for (const auto sessionIndex : scene->committedDisplaySessionIndices) {
            if (sessionIndex.has_value() && runtimeState->sessions[sessionIndex.value()].gpuResident) {
                runtimeState->sessions[sessionIndex.value()].visible = scene->displayVisible;
            }
        }
        return true;
    }

    ++scene->switchGeneration;
    scene->pendingDisplaySpacingMicrometres = spacingMicrometres;
    scene->pendingDisplaySessionIndices = {};
    scene->stagedReadyCount = 0U;
    scene->switchError.clear();
    for (std::size_t roleIndex = 0; roleIndex < bundle->sessionIndices.size(); ++roleIndex) {
        const auto sessionIndex = bundle->sessionIndices[roleIndex];
        scene->pendingDisplaySessionIndices[roleIndex] = sessionIndex;
        auto& session = runtimeState->sessions[sessionIndex];
        session.pendingDisplaySource = true;
        if (session.cpuResident && session.offlinePointCloud != nullptr) {
            ++scene->stagedReadyCount;
        } else {
            QueueLayerLoad(
                runtimeState,
                sessionIndex,
                PointCloudLoadPurpose::StagedDisplay,
                scene->switchGeneration);
        }
    }
    runtimeState->statusMessage = "Loading " +
                                  FormatFixed(static_cast<double>(spacingMicrometres) / 1000.0, 3) +
                                  " mm display bundle for " + scene->sceneGroupName + "...";
    runtimeState->errorMessage.clear();
    if (scene->stagedReadyCount == invisible_places::scene::kScenePointCloudRoleCount) {
        return CommitSceneDisplaySwitch(runtimeState, viewport, scene);
    }
    return true;
}

bool RequestSceneMixedDisplayLoad(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene,
    const std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>&
        displaySessionIndices) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr ||
        runtimeState->offlineRenderJob.active ||
        scene->pendingDisplaySpacingMicrometres.has_value() || scene->pendingMixedDisplay) {
        return false;
    }
    if (std::any_of(
            displaySessionIndices.begin(),
            displaySessionIndices.end(),
            [](const std::optional<std::size_t>& index) { return !index.has_value(); })) {
        scene->switchError = "The saved Mixed display set is incomplete and cannot be loaded.";
        return false;
    }
    if (runtimeState->water.authoritativeWaterSurfaceSceneGroupName.empty() ||
        runtimeState->water.authoritativeWaterSurfaceSceneGroupName ==
            scene->sceneGroupName) {
        runtimeState->water.activeWaterSurfaceSceneGroupName =
            scene->sceneGroupName;
    }

    ++scene->switchGeneration;
    scene->pendingMixedDisplay = true;
    scene->pendingDisplaySessionIndices = displaySessionIndices;
    scene->stagedReadyCount = 0U;
    for (const auto sessionIndex : displaySessionIndices) {
        auto& session = runtimeState->sessions[sessionIndex.value()];
        session.pendingDisplaySource = true;
        if (session.cpuResident && session.offlinePointCloud != nullptr) {
            ++scene->stagedReadyCount;
        } else {
            QueueLayerLoad(
                runtimeState,
                sessionIndex.value(),
                PointCloudLoadPurpose::StagedDisplay,
                scene->switchGeneration);
        }
    }
    runtimeState->statusMessage = "Loading saved Mixed display set for " + scene->sceneGroupName + "...";
    runtimeState->errorMessage.clear();
    if (scene->stagedReadyCount == invisible_places::scene::kScenePointCloudRoleCount) {
        return CommitSceneDisplaySwitch(runtimeState, viewport, scene);
    }
    return true;
}

void HandleScenePurposeLoadCompleted(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    PointCloudLoadPurpose purpose,
    std::uint64_t sceneSwitchGeneration) {
    auto* scene = FindScenePointCloudRuntimeContainingSession(runtimeState, sessionIndex);
    if (scene == nullptr) {
        return;
    }
    if (purpose == PointCloudLoadPurpose::AnalysisCpuOnly) {
        if (SceneAnalysisSourcesReady(*runtimeState, *scene)) {
            scene->switchError.clear();
            const auto deferredActions = scene->deferredAnalysisActions;
            scene->deferredAnalysisActions = 0U;
            if ((deferredActions & DeferredSceneAnalysisActionBit(
                                       DeferredSceneAnalysisAction::BakeWaterPath)) != 0U) {
                BakeWaterOverlayForActiveLayer(runtimeState, viewport);
            }
            if ((deferredActions & DeferredSceneAnalysisActionBit(
                                       DeferredSceneAnalysisAction::RefreshWaterField)) != 0U) {
                RefreshWaterFieldOverlays(runtimeState, viewport);
            }
            if ((deferredActions & DeferredSceneAnalysisActionBit(
                                       DeferredSceneAnalysisAction::RefreshWaterRipple)) != 0U) {
                RefreshWaterRippleEffects(runtimeState, viewport);
            }
            if ((deferredActions & DeferredSceneAnalysisActionBit(
                                       DeferredSceneAnalysisAction::RefreshRegionPreviews)) != 0U) {
                QueueWaterRegionPointPreviewsForDirtyRegions(runtimeState, viewport);
            }
            if (deferredActions == 0U) {
                runtimeState->statusMessage =
                    "Canonical analysis sources are ready for " + scene->sceneGroupName + ".";
                runtimeState->errorMessage.clear();
            }
        }
        return;
    }
    if (purpose != PointCloudLoadPurpose::StagedDisplay) {
        return;
    }
    if (scene->switchGeneration != sceneSwitchGeneration ||
        (!scene->pendingDisplaySpacingMicrometres.has_value() && !scene->pendingMixedDisplay)) {
        auto& session = runtimeState->sessions[sessionIndex];
        session.pendingDisplaySource = false;
        if (!session.committedDisplaySource &&
            (session.gpuResident || session.cpuResident)) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex, !session.analysisSource);
        }
        return;
    }
    scene->stagedReadyCount = static_cast<std::size_t>(std::count_if(
        scene->pendingDisplaySessionIndices.begin(),
        scene->pendingDisplaySessionIndices.end(),
        [&](const std::optional<std::size_t>& index) {
            return index.has_value() &&
                   runtimeState->sessions[index.value()].cpuResident &&
                   runtimeState->sessions[index.value()].offlinePointCloud != nullptr;
        }));
    CommitSceneDisplaySwitch(runtimeState, viewport, scene);
}

void HandleScenePurposeLoadFailed(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    PointCloudLoadPurpose purpose,
    std::uint64_t sceneSwitchGeneration,
    std::string_view errorMessage) {
    auto* scene = FindScenePointCloudRuntimeContainingSession(runtimeState, sessionIndex);
    if (scene == nullptr) {
        return;
    }
    if (purpose == PointCloudLoadPurpose::StagedDisplay &&
        scene->switchGeneration == sceneSwitchGeneration) {
        RollBackSceneDisplaySwitch(runtimeState, viewport, scene, errorMessage);
    } else if (purpose == PointCloudLoadPurpose::AnalysisCpuOnly) {
        scene->switchError = "Analysis source unavailable: " + std::string{errorMessage};
        scene->deferredAnalysisActions = 0U;
        std::erase_if(
            runtimeState->persistence.queuedLoads,
            [&](const QueuedLayerLoad& queued) {
                return queued.purpose == PointCloudLoadPurpose::AnalysisCpuOnly &&
                       std::find(
                           scene->analysisSessionIndices.begin(),
                           scene->analysisSessionIndices.end(),
                           std::optional<std::size_t>{queued.sessionIndex}) !=
                           scene->analysisSessionIndices.end();
            });
        runtimeState->errorMessage = scene->switchError;
        runtimeState->statusMessage.clear();
    }
}

bool UnloadGeneratedWaterOverlays(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool unloadedAny = false;
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        if (IsGeneratedWaterOverlaySession(runtimeState->sessions[index]) &&
            runtimeState->sessions[index].loaded) {
            UnloadLayerByIndex(runtimeState, viewport, index);
            unloadedAny = true;
        }
    }
    return unloadedAny;
}

bool UnloadGeneratedWaterOverlaySessionsWithStemSuffix(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::string_view suffix) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool unloadedAny = false;
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!session.loaded || !IsGeneratedWaterOverlaySession(session)) {
            continue;
        }
        if (session.sourcePath.stem().string().ends_with(suffix)) {
            UnloadLayerByIndex(runtimeState, viewport, index);
            unloadedAny = true;
        }
    }
    return unloadedAny;
}

