SavedWaterTrailProfileState MakeWaterTrailProfileState(const WaterTrailProfileDocument& document) {
    auto profile = MakeWaterTrailProfile(document.name, document.geometry, document.style);
    profile.objectOverride = document.objectOverride;
    profile.ownerObjectId = document.ownerObjectId;
    profile.baseProfileName = document.baseProfileName;
    return profile;
}

void ImportLegacyWaterVisualsAsTrailProfiles(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    for (const auto& visual : water.pointVisuals) {
        const auto normalized = NormalizeWaterProfileName(visual.name);
        if (IsProtectedWaterTrailProfileName(*runtimeState, normalized) ||
            FindWaterTrailProfileIndex(water, normalized).has_value()) {
            continue;
        }
        water.trailProfiles.push_back(
            MakeWaterTrailProfile(normalized, water.defaultTrailGeometry, visual.style));
    }
}

void MigrateLegacyWaterEmitterProfiles(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    for (auto& emitter : water->emitters) {
        emitter.pathProfileName = NormalizeWaterProfileName(emitter.pathProfileName, kWaterProfileGlobalName);
        emitter.laneProfileName = NormalizeWaterProfileName(emitter.laneProfileName, kWaterProfileGlobalName);
        emitter.trailProfileName = NormalizeWaterProfileName(emitter.trailProfileName, kWaterProfileGlobalName);
        if (emitter.pathProfileName != kWaterProfileGlobalName ||
            !emitter.sourceSettings.has_value()) {
            continue;
        }
        const auto profileName = NormalizeWaterProfileName(emitter.name + " Path");
        if (!FindWaterPathProfileIndex(*water, profileName).has_value()) {
            water->pathProfiles.push_back({
                .name = profileName,
                .settings = emitter.sourceSettings->path,
            });
        }
        emitter.pathProfileName = profileName;
        emitter.sourceSettingsAssignment = WaterSourceSettingsAssignment::Default;
        emitter.sourceSettings.reset();
        emitter.tempSourceSettings.reset();
        emitter.linkedSourceSettingsEmitterId.reset();
    }
}

WaterPathGenerationSettings WaterPathProfileSettingsByName(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    if (const auto builtIn = BuiltInWaterPathProfileSettings(normalized); builtIn.has_value()) {
        return builtIn.value();
    }
    if (const auto index = FindWaterPathProfileIndex(water, normalized); index.has_value()) {
        return water.pathProfiles[index.value()].settings;
    }
    return water.defaultSourceSettings.path;
}

WaterFlowTrailSettings WaterLaneProfileSettingsByName(
    const WaterWorkflowState& water,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    if (const auto builtIn = BuiltInWaterLaneProfileSettings(normalized); builtIn.has_value()) {
        return builtIn.value();
    }
    if (const auto index = FindWaterLaneProfileIndex(water, normalized); index.has_value()) {
        return water.laneProfiles[index.value()].settings;
    }
    return water.flowTrailSettings;
}

SavedWaterTrailProfileState WaterTrailProfileByName(
    const PreviewRuntimeState& runtimeState,
    std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    if (const auto builtIn = BuiltInWaterTrailProfile(runtimeState, normalized); builtIn.has_value()) {
        return builtIn.value();
    }
    if (const auto index = FindWaterTrailProfileIndex(runtimeState.water, normalized); index.has_value()) {
        const auto& profile = runtimeState.water.trailProfiles[index.value()];
        return MakeWaterTrailProfile(profile.name, profile.geometry, profile.style);
    }
    return MakeWaterTrailProfile(
        kWaterProfileDefaultName,
        runtimeState.water.tempDefaultTrailGeometry.value_or(runtimeState.water.defaultTrailGeometry),
        runtimeState.water.tempDefaultPointVisualStyle.value_or(runtimeState.water.defaultPointVisualStyle));
}

WaterPathGenerationSettings ViewedGlobalWaterPathSettings(const WaterWorkflowState& water) {
    if (water.editedPathProfileSettings.has_value()) {
        return water.editedPathProfileSettings.value();
    }
    return WaterPathProfileSettingsByName(water, water.selectedPathProfileName);
}

WaterFlowTrailSettings ViewedGlobalWaterLaneSettings(const WaterWorkflowState& water) {
    if (water.editedLaneProfileSettings.has_value()) {
        return water.editedLaneProfileSettings.value();
    }
    return WaterLaneProfileSettingsByName(water, water.selectedLaneProfileName);
}

SavedWaterTrailProfileState ViewedGlobalWaterTrailProfile(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.water.editedTrailProfile.has_value()) {
        return MakeWaterTrailProfile(
            runtimeState.water.editedTrailProfile->name,
            runtimeState.water.editedTrailProfile->geometry,
            runtimeState.water.editedTrailProfile->style);
    }
    return WaterTrailProfileByName(runtimeState, runtimeState.water.selectedTrailProfileName);
}

SavedWaterTrailProfileState ViewedDynamicMeshWaterTrailProfile(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.water.editedDynamicMeshTrailProfile.has_value()) {
        return MakeWaterTrailProfile(
            runtimeState.water.editedDynamicMeshTrailProfile->name,
            runtimeState.water.editedDynamicMeshTrailProfile->geometry,
            runtimeState.water.editedDynamicMeshTrailProfile->style);
    }
    return WaterTrailProfileByName(runtimeState, runtimeState.water.dynamicMeshFlowSettings.trailProfileName);
}

bool WaterSourceProfileUsesEditedSettings(
    std::string_view assignedProfileName,
    bool lockedToSavedProfile,
    std::string_view selectedProfileName,
    bool hasEditedSettings) {
    if (lockedToSavedProfile || !hasEditedSettings) {
        return false;
    }
    if (IsGlobalWaterProfileName(assignedProfileName)) {
        return true;
    }
    return NormalizeWaterProfileName(assignedProfileName) ==
        NormalizeWaterProfileName(UneditedWaterProfileName(selectedProfileName));
}

void MarkWaterPathProfileUsersDirty(
    PreviewRuntimeState* runtimeState,
    std::string_view selectedProfileName,
    bool includeMatchingNamedProfiles,
    bool includeLockedGlobalProfiles = false) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto savedProfileName = NormalizeWaterProfileName(
        UneditedWaterProfileName(selectedProfileName));
    for (const auto& emitter : runtimeState->water.emitters) {
        const bool usesGlobalProfile = IsGlobalWaterProfileName(emitter.pathProfileName);
        if (emitter.pathProfileLocked &&
            !(includeLockedGlobalProfiles && usesGlobalProfile)) {
            continue;
        }
        const bool usesMatchingNamedProfile =
            includeMatchingNamedProfiles &&
            NormalizeWaterProfileName(emitter.pathProfileName) == savedProfileName;
        if (usesGlobalProfile || usesMatchingNamedProfile) {
            MarkWaterPathDirty(runtimeState, emitter.id);
        }
    }
}

std::string WaterSourceSavedProfileName(
    std::string_view assignedProfileName,
    std::string_view selectedProfileName) {
    if (IsGlobalWaterProfileName(assignedProfileName)) {
        return UneditedWaterProfileName(selectedProfileName);
    }
    return NormalizeWaterProfileName(assignedProfileName);
}

WaterPathGenerationSettings ResolveEmitterWaterPathSettings(
    const WaterWorkflowState& water,
    const WaterEmitter& emitter) {
    if (WaterSourceProfileUsesEditedSettings(
            emitter.pathProfileName,
            emitter.pathProfileLocked,
            water.selectedPathProfileName,
            water.editedPathProfileSettings.has_value())) {
        return water.editedPathProfileSettings.value();
    }
    return WaterPathProfileSettingsByName(
        water,
        WaterSourceSavedProfileName(emitter.pathProfileName, water.selectedPathProfileName));
}

WaterFlowTrailSettings ResolveEmitterWaterLaneSettings(
    const WaterWorkflowState& water,
    const WaterEmitter& emitter) {
    if (WaterSourceProfileUsesEditedSettings(
            emitter.laneProfileName,
            emitter.laneProfileLocked,
            water.selectedLaneProfileName,
            water.editedLaneProfileSettings.has_value())) {
        return water.editedLaneProfileSettings.value();
    }
    return WaterLaneProfileSettingsByName(
        water,
        WaterSourceSavedProfileName(emitter.laneProfileName, water.selectedLaneProfileName));
}

SavedWaterTrailProfileState ResolveEmitterWaterTrailProfile(
    const PreviewRuntimeState& runtimeState,
    const WaterEmitter& emitter) {
    const auto& water = runtimeState.water;
    if (WaterSourceProfileUsesEditedSettings(
            emitter.trailProfileName,
            emitter.trailProfileLocked,
            water.selectedTrailProfileName,
            water.editedTrailProfile.has_value())) {
        return MakeWaterTrailProfile(
            water.editedTrailProfile->name,
            water.editedTrailProfile->geometry,
            water.editedTrailProfile->style);
    }
    return WaterTrailProfileByName(
        runtimeState,
        WaterSourceSavedProfileName(emitter.trailProfileName, water.selectedTrailProfileName));
}

WaterFlowTrailSettings ResolveManualFlowPathLaneSettings(
    const WaterWorkflowState& water,
    const WaterManualFlowPathSource& source) {
    if (WaterSourceProfileUsesEditedSettings(
            source.laneProfileName,
            source.laneProfileLocked,
            water.selectedLaneProfileName,
            water.editedLaneProfileSettings.has_value())) {
        return water.editedLaneProfileSettings.value();
    }
    return WaterLaneProfileSettingsByName(
        water,
        WaterSourceSavedProfileName(source.laneProfileName, water.selectedLaneProfileName));
}

SavedWaterTrailProfileState ResolveManualFlowPathTrailProfile(
    const PreviewRuntimeState& runtimeState,
    const WaterManualFlowPathSource& source) {
    const auto& water = runtimeState.water;
    if (WaterSourceProfileUsesEditedSettings(
            source.trailProfileName,
            source.trailProfileLocked,
            water.selectedTrailProfileName,
            water.editedTrailProfile.has_value())) {
        return MakeWaterTrailProfile(
            water.editedTrailProfile->name,
            water.editedTrailProfile->geometry,
            water.editedTrailProfile->style);
    }
    return WaterTrailProfileByName(
        runtimeState,
        WaterSourceSavedProfileName(source.trailProfileName, water.selectedTrailProfileName));
}

WaterFlowTrailSettings MakeEmitterFlowSettings(
    const WaterWorkflowState& water,
    const WaterEmitter& emitter,
    const SavedWaterTrailProfileState& trailProfile) {
    return invisible_places::water::ApplyWaterTrailGeometryToFlowTrailSettings(
        ResolveEmitterWaterLaneSettings(water, emitter),
        trailProfile.geometry);
}

float WaterFlowRuntimeSpeedScale(
    float resolvedSpeedMetersPerSecond,
    float bakedSpeedMetersPerSecond);

bool ApplyWaterFlowSourceLiveSettings(
    PreviewRuntimeState* runtimeState,
    std::uint32_t sourceId,
    const WaterFlowTrailSettings& settings,
    const SavedWaterTrailProfileState& trailProfile) {
    if (runtimeState == nullptr) {
        return false;
    }
    if (const auto cachedIt = runtimeState->water.flowTrailSourceRequests.find(sourceId);
        cachedIt != runtimeState->water.flowTrailSourceRequests.end()) {
        cachedIt->second.settings = settings;
        cachedIt->second.trailProfile = trailProfile;
    }

    bool updated = false;
    for (auto& session : runtimeState->sessions) {
        if (!session.loaded || !session.waterFlowSourceId.has_value() ||
            session.waterFlowSourceId.value() != sourceId ||
            !IsGeneratedWaterFlowOverlaySession(session)) {
            continue;
        }
        session.pointStyle = MakeWaterTrailSessionStyle(
            trailProfile.style,
            trailProfile.geometry);
        session.pointStyle.waterFlowSpeedScale = WaterFlowRuntimeSpeedScale(
            settings.speedMetersPerSecond,
            session.waterFlowBakedSpeedMetersPerSecond);
        session.selectedPointVisualName = NormalizeWaterProfileName(trailProfile.name);
        session.pointVisualNameBuffer = BaseWaterProfileName(session.selectedPointVisualName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({
            .name = session.selectedPointVisualName,
            .style = session.pointStyle,
        });
        EnsurePointVisuals(&session);
        updated = true;
    }
    if (updated) {
        runtimeState->previewRenderStateSignatureValid = false;
    }
    return updated;
}

void StoreManualFlowPathLaneProfileEdit(
    WaterWorkflowState* water,
    WaterManualFlowPathSource* source,
    const WaterFlowTrailSettings& settings) {
    if (water == nullptr || source == nullptr) {
        return;
    }
    // Moving a base value writes this source's own profile copy. Keyed
    // slider edits never call this path.
    CommitWaterFlowObjectProfileEdit(
        &water->laneProfiles,
        &source->laneProfileName,
        water->selectedLaneProfileName,
        source->id,
        WaterFlowSourceDisplayName(source->name, source->id),
        [&](SavedWaterLaneProfileState* profile) {
            profile->settings = settings;
        });
}

void StoreManualFlowPathTrailProfileEdit(
    PreviewRuntimeState* runtimeState,
    WaterManualFlowPathSource* source,
    const SavedWaterTrailProfileState& profile) {
    if (runtimeState == nullptr || source == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    CommitWaterFlowObjectProfileEdit(
        &water.trailProfiles,
        &source->trailProfileName,
        water.selectedTrailProfileName,
        source->id,
        WaterFlowSourceDisplayName(source->name, source->id),
        [&](SavedWaterTrailProfileState* copy) {
            copy->geometry = profile.geometry;
            copy->style = MakeWaterTrailSessionStyle(profile.style, profile.geometry);
        });
}

WaterSourceSettings ActiveProfileDefaultWaterSourceSettings(const WaterWorkflowState& water) {
    WaterSourceSettings settings = water.tempDefaultSourceSettings.value_or(water.defaultSourceSettings);
    settings.path = ViewedGlobalWaterPathSettings(water);
    return settings;
}

std::vector<WaterEmitter> WaterEmittersWithResolvedPathProfiles(const WaterWorkflowState& water) {
    std::vector<WaterEmitter> resolved = water.emitters;
    const auto defaultSettings = ActiveProfileDefaultWaterSourceSettings(water);
    for (auto& emitter : resolved) {
        auto sourceSettings = defaultSettings;
        sourceSettings.path = ResolveEmitterWaterPathSettings(water, emitter);
        emitter.sourceSettings = sourceSettings;
        emitter.tempSourceSettings.reset();
        emitter.sourceSettingsAssignment = WaterSourceSettingsAssignment::Custom;
        emitter.linkedSourceSettingsEmitterId.reset();
    }
    return resolved;
}

WaterOverlay WaterPathAnchorsFromCacheWithProfileSettings(const PreviewRuntimeState& runtimeState) {
    const auto emitters = WaterEmittersWithResolvedPathProfiles(runtimeState.water);
    return invisible_places::water::BuildWaterPathAnchorsFromCache(
        runtimeState.water.pathCache,
        emitters,
        ActiveProfileDefaultWaterSourceSettings(runtimeState.water));
}

std::string WaterProfileFileToken(std::string_view name) {
    const auto normalized = NormalizeWaterProfileName(name);
    std::string token;
    token.reserve(normalized.size());
    for (const char character : normalized) {
        const auto byte = static_cast<unsigned char>(character);
        token.push_back(std::isalnum(byte) != 0 ? static_cast<char>(byte) : '_');
    }
    return token.empty() ? "Default" : token;
}

std::filesystem::path BuildWaterTrailOverlayPath(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    std::uint32_t sourceId,
    std::string_view trailProfileName) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    const auto waterDirectory = projectPath.empty()
                                    ? std::filesystem::path{"Saved"} / "water"
                                    : projectPath.parent_path() / "water";
    return waterDirectory /
           (sourceSession.sourcePath.stem().string() + "-WaterFlowTrails-" +
            std::to_string(sourceId) + "-" + WaterProfileFileToken(trailProfileName) + ".generated");
}

std::optional<std::size_t> FindLoadedWaterFlowSourceSessionIndex(
    const PreviewRuntimeState& runtimeState,
    std::uint32_t sourceId) {
    for (std::size_t index = 0U; index < runtimeState.sessions.size(); ++index) {
        const auto& session = runtimeState.sessions[index];
        if (session.loaded && session.waterFlowSourceId.has_value() &&
            session.waterFlowSourceId.value() == sourceId &&
            IsGeneratedWaterFlowOverlaySession(session) &&
            IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string())) {
            return index;
        }
    }
    return std::nullopt;
}

void AppendWaterTrailOverlay(
    WaterTrailOverlay* target,
    WaterTrailOverlay source) {
    if (target == nullptr || source.samples.empty()) {
        return;
    }
    const auto routeOffset = static_cast<float>(target->samples.size());
    target->samples.reserve(target->samples.size() + source.samples.size());
    for (auto& sample : source.samples) {
        sample.routeStartIndex += routeOffset;
        target->bounds.Expand(sample.position);
        target->samples.push_back(sample);
    }
}

const invisible_places::water::WaterPathAnalysisCache* FlowPathAnalysisForLanes(
    const WaterWorkflowState& water) {
    if (!water.pathCacheLoaded ||
        !invisible_places::water::WaterPathAnalysisCacheCompatible(water.pathCache) ||
        !water.pathCache.analysis.has_value()) {
        return nullptr;
    }
    // `pathCacheStale` means newer Path inputs still need Bake Path. The last
    // baked anchors and their matching analysis remain the correct snapshot for
    // Lane/Trail-only edits, and must stay usable until that bake replaces them.
    return &water.pathCache.analysis.value();
}

bool HasValidManualFlowPath(const WaterWorkflowState& water) {
    return std::any_of(
        water.manualFlowPaths.begin(),
        water.manualFlowPaths.end(),
        [](const WaterManualFlowPathSource& source) {
            if (source.controlPoints.size() < 2U) {
                return false;
            }
            const auto first = ToGlm(source.controlPoints.front());
            return std::any_of(
                source.controlPoints.begin() + 1,
                source.controlPoints.end(),
                [&](const invisible_places::io::Float3& point) {
                    const auto delta = ToGlm(point) - first;
                    return glm::dot(delta, delta) > 1.0e-10F;
                });
        });
}

std::uint64_t WaterFlowTrailSourceFingerprint(
    const PreviewRuntimeState& runtimeState,
    std::uint32_t sourceId,
    const WaterOverlay& anchors,
    const WaterFlowTrailSettings& settings,
    bool usesPathAnalysis,
    bool useSurfaceGuide);

void AppendWaterTrailOverlayGroup(
    std::vector<WaterTrailOverlayGroup>* groups,
    std::uint32_t sourceId,
    const SavedWaterTrailProfileState& profile,
    std::shared_ptr<const WaterTrailOverlay> overlay,
    float bakedSpeedMetersPerSecond,
    float resolvedSpeedMetersPerSecond,
    bool requiresUpload = true) {
    if (groups == nullptr || overlay == nullptr || overlay->samples.empty()) {
        return;
    }
    WaterTrailOverlayGroup group;
    group.sourceId = sourceId;
    group.trailProfile = profile;
    group.bakedSpeedMetersPerSecond = bakedSpeedMetersPerSecond;
    group.resolvedSpeedMetersPerSecond = resolvedSpeedMetersPerSecond;
    group.overlay = std::move(overlay);
    group.requiresUpload = requiresUpload;
    groups->push_back(std::move(group));
}

float WaterFlowRuntimeSpeedScale(
    float resolvedSpeedMetersPerSecond,
    float bakedSpeedMetersPerSecond) {
    const float safeResolvedSpeed =
        std::isfinite(resolvedSpeedMetersPerSecond)
            ? std::max(0.0F, resolvedSpeedMetersPerSecond)
            : 0.0F;
    const float safeBakedSpeed =
        std::isfinite(bakedSpeedMetersPerSecond) && bakedSpeedMetersPerSecond > 1.0e-4F
            ? bakedSpeedMetersPerSecond
            : std::max(1.0e-4F, safeResolvedSpeed);
    return invisible_places::renderer::pointcloud::SanitizeWaterFlowSpeedScale(
        safeResolvedSpeed / safeBakedSpeed);
}

std::vector<WaterTrailOverlayGroup> BuildFlowTrailOverlayGroups(
    PreviewRuntimeState& runtimeState) {
    std::vector<WaterTrailOverlayGroup> groups;
    const auto* pathAnalysis = FlowPathAnalysisForLanes(runtimeState.water);
    std::unordered_set<std::uint32_t> activeSourceIds;
    const auto addOverlay =
        [&](std::uint32_t sourceId,
            const WaterOverlay& anchors,
            const WaterFlowTrailSettings& settings,
            bool usesPathAnalysis,
            bool useSurfaceGuide,
            const SavedWaterTrailProfileState& profile,
            WaterTrailOverlay overlay) {
        auto cachedOverlay = std::make_shared<WaterTrailOverlay>(std::move(overlay));
        runtimeState.water.flowTrailSourceArtifacts.insert_or_assign(
            sourceId,
            WaterFlowTrailSourceArtifact{
                .sourceId = sourceId,
                .fingerprint = WaterFlowTrailSourceFingerprint(
                    runtimeState,
                    sourceId,
                    anchors,
                    settings,
                    usesPathAnalysis,
                    useSurfaceGuide),
                .trailProfile = profile,
                .overlay = cachedOverlay,
                .bakedSpeedMetersPerSecond = settings.speedMetersPerSecond,
            });
        activeSourceIds.insert(sourceId);
        AppendWaterTrailOverlayGroup(
            &groups,
            sourceId,
            profile,
            std::move(cachedOverlay),
            settings.speedMetersPerSecond,
            settings.speedMetersPerSecond);
    };

    std::unordered_map<std::uint32_t, WaterOverlay> anchorsByEmitter;
    anchorsByEmitter.reserve(runtimeState.water.emitters.size());
    for (const auto& point : runtimeState.water.pathAnchors.points) {
        const auto emitterId = static_cast<std::uint32_t>(
            std::max(0.0F, std::floor(point.emitterId + 0.5F)));
        auto& anchors = anchorsByEmitter[emitterId];
        anchors.bounds.Expand(point.position);
        anchors.points.push_back(point);
    }

    bool usedRouteAnchors = false;
    for (const auto& emitter : runtimeState.water.emitters) {
        const auto anchorsIt = anchorsByEmitter.find(emitter.id);
        if (anchorsIt == anchorsByEmitter.end() || anchorsIt->second.points.empty()) {
            continue;
        }
        usedRouteAnchors = true;
        const auto trailProfile = ResolveEmitterWaterTrailProfile(runtimeState, emitter);
        const auto flowSettings = MakeEmitterFlowSettings(runtimeState.water, emitter, trailProfile);
        auto overlay =
            invisible_places::water::BuildFlowTrailOverlayFromPathAnchors(
                anchorsIt->second,
                flowSettings,
                pathAnalysis);
        addOverlay(
            emitter.id,
            anchorsIt->second,
            flowSettings,
            true,
            false,
            trailProfile,
            std::move(overlay));
    }

    for (const auto& source : runtimeState.water.manualFlowPaths) {
        const auto trailProfile = ResolveManualFlowPathTrailProfile(runtimeState, source);
        auto flowSettings = invisible_places::water::ApplyWaterTrailGeometryToFlowTrailSettings(
            ResolveManualFlowPathLaneSettings(runtimeState.water, source),
            trailProfile.geometry);
        const float anchorSpacing = std::clamp(
            trailProfile.geometry.pointSpacingMeters * 2.0F,
            0.005F,
            0.05F);
        const auto anchors = invisible_places::water::BuildManualFlowPathAnchors(
            source,
            anchorSpacing,
            flowSettings.laneSpreadMeters);
        if (anchors.points.size() < 2U) {
            continue;
        }
        usedRouteAnchors = true;
        auto overlay =
            invisible_places::water::BuildFlowTrailOverlayFromPathAnchors(
                anchors,
                flowSettings,
                nullptr,
                invisible_places::water::WaterFlowTrailBuildOptions{
                    .surfaceCache = runtimeState.water.waterSurfaceCache.get(),
                    .useSurfaceGuide = source.useSurfaceGuide,
                });
        addOverlay(
            source.id,
            anchors,
            flowSettings,
            false,
            source.useSurfaceGuide,
            trailProfile,
            std::move(overlay));
    }

    if (!usedRouteAnchors && !runtimeState.water.pathAnchors.points.empty()) {
        WaterEmitter fallbackEmitter;
        fallbackEmitter.id = 0U;
        fallbackEmitter.name = "Global";
        const auto trailProfile = ViewedGlobalWaterTrailProfile(runtimeState);
        const auto flowSettings = MakeEmitterFlowSettings(runtimeState.water, fallbackEmitter, trailProfile);
        auto overlay =
            invisible_places::water::BuildFlowTrailOverlayFromPathAnchors(
                runtimeState.water.pathAnchors,
                flowSettings,
                pathAnalysis);
        addOverlay(
            0U,
            runtimeState.water.pathAnchors,
            flowSettings,
            true,
            false,
            trailProfile,
            std::move(overlay));
    }
    std::erase_if(
        runtimeState.water.flowTrailSourceArtifacts,
        [&](const auto& entry) { return !activeSourceIds.contains(entry.first); });
    return groups;
}

std::uint64_t WaterFlowTrailSourceFingerprint(
    const PreviewRuntimeState& runtimeState,
    std::uint32_t sourceId,
    const WaterOverlay& anchors,
    const WaterFlowTrailSettings& settings,
    bool usesPathAnalysis,
    bool useSurfaceGuide) {
    std::uint64_t hash = 0x9E3779B97F4A7C15ULL;
    HashCombine(&hash, sourceId);
    HashBool(&hash, settings.enabled);
    HashCombine(&hash, settings.trailCountTotal);
    HashCombine(&hash, settings.laneCount);
    HashFloat(&hash, settings.trailLengthMeters);
    HashFloat(&hash, settings.trailPointSpacingMeters);
    HashBool(&hash, settings.startFadeEnabled);
    HashFloat(&hash, settings.startFadeFullDistanceMeters);
    HashFloat(&hash, settings.startFadeRandomBeginDistanceMeters);
    HashBool(&hash, settings.endFadeEnabled);
    HashFloat(&hash, settings.endFadeFullDistanceMeters);
    HashFloat(&hash, settings.endFadeRandomBeginDistanceMeters);
    // Width, streak length, speed, and the display/profile name are style
    // inputs. They are deliberately excluded so visual-only edits update the
    // mapped source style without invalidating route/trail compute output.
    HashFloat(&hash, settings.surfaceOffsetMeters);
    HashFloat(&hash, settings.pathAttraction);
    HashFloat(&hash, settings.laneSpreadMeters);
    HashFloat(&hash, settings.laneCrossing);
    HashFloat(&hash, settings.trailSmoothness);
    HashFloat(&hash, settings.trailLooseness);
    HashFloat(&hash, settings.turbulence);
    HashFloat(&hash, settings.surfaceFollow);
    HashFloat(&hash, settings.downhillPull);
    HashFloat(&hash, settings.terrainWidthResponse);
    HashFloat(&hash, settings.turbulenceScaleMeters);
    HashCombine(&hash, settings.seed);
    HashCombine(&hash, anchors.points.size());
    for (const auto& point : anchors.points) {
        HashVec3(&hash, ToGlm(point.position));
        HashVec3(&hash, ToGlm(point.normal));
        HashFloat(&hash, point.flowId);
        HashFloat(&hash, point.emitterId);
        HashFloat(&hash, point.pathDistance);
        HashFloat(&hash, point.confidence);
        HashFloat(&hash, point.accumulation);
        HashFloat(&hash, point.laneSpanMeters);
    }
    HashBool(&hash, usesPathAnalysis);
    HashBool(&hash, useSurfaceGuide);
    if (useSurfaceGuide) {
        HashString(&hash, runtimeState.water.waterSurfaceCacheSignature);
        HashCombine(
            &hash,
            runtimeState.water.waterSurfaceCache != nullptr
                ? runtimeState.water.waterSurfaceCache->revision
                : 0U);
    }
    if (usesPathAnalysis) {
        HashString(&hash, runtimeState.water.pathCache.supportSignature);
        HashString(&hash, runtimeState.water.pathCache.emitterSettingsFingerprint);
        HashCombine(&hash, runtimeState.water.pathCache.branches.size());
    }
    return hash;
}

void EnsureWaterFlowPathAnalysisSnapshot(WaterWorkflowState* water) {
    if (water == nullptr || !water->pathCache.analysis.has_value()) {
        if (water != nullptr) {
            water->flowPathAnalysisSnapshot.reset();
            water->flowPathAnalysisSnapshotFingerprint = 0U;
        }
        return;
    }
    const auto& analysis = water->pathCache.analysis.value();
    std::uint64_t fingerprint = 0xD6E8FEB86659FD93ULL;
    HashString(&fingerprint, water->pathCache.supportSignature);
    HashString(&fingerprint, water->pathCache.emitterSettingsFingerprint);
    HashCombine(&fingerprint, water->pathCache.branches.size());
    HashCombine(&fingerprint, analysis.branches.size());
    if (water->flowPathAnalysisSnapshot != nullptr &&
        water->flowPathAnalysisSnapshotFingerprint == fingerprint) {
        return;
    }
    water->flowPathAnalysisSnapshot =
        std::make_shared<invisible_places::water::WaterPathAnalysisCache>(analysis);
    water->flowPathAnalysisSnapshotFingerprint = fingerprint;
}

WaterFlowTrailBuildRequest CaptureWaterFlowTrailBuildRequest(
    PreviewRuntimeState& runtimeState,
    std::uint64_t requestId,
    bool savePathCache,
    bool gpuSnapshotOnly = false,
    bool refreshAllSources = true,
    const std::unordered_set<std::uint32_t>* dirtySourceIds = nullptr) {
    WaterFlowTrailBuildRequest request;
    request.requestId = requestId;
    request.savePathCache = savePathCache;
    request.gpuSnapshotOnly = gpuSnapshotOnly;
    request.surfaceCache = runtimeState.water.waterSurfaceCache;

    std::unordered_set<std::uint32_t> hiddenBranchIds{
        runtimeState.water.pathCache.hiddenBranchIds.begin(),
        runtimeState.water.pathCache.hiddenBranchIds.end()};
    const auto sourceNeedsRefresh = [&](std::uint32_t sourceId) {
        return refreshAllSources ||
               runtimeState.water.flowTrailSourceRequests.find(sourceId) ==
                   runtimeState.water.flowTrailSourceRequests.end() ||
               (dirtySourceIds != nullptr && dirtySourceIds->contains(sourceId));
    };
    const auto cpuSnapshotIsRequired = [&](std::uint32_t sourceId) {
        if (!gpuSnapshotOnly) {
            return false;
        }
        const auto sessionIt = std::find_if(
            runtimeState.sessions.begin(),
            runtimeState.sessions.end(),
            [&](const PreviewLayerSession& session) {
                return session.loaded && session.waterFlowGpuPreview &&
                       session.waterFlowSourceId.has_value() &&
                       session.waterFlowSourceId.value() == sourceId;
            });
        return sessionIt != runtimeState.sessions.end() &&
               (sessionIt->offlinePointCloud == nullptr ||
                sessionIt->waterFlowCpuSnapshotRevision < sessionIt->waterFlowGpuRevision);
    };
    const auto attachArtifact = [&](WaterFlowTrailSourceBuildRequest* sourceRequest) {
        if (sourceRequest == nullptr) {
            return;
        }
        sourceRequest->cachedOverlay.reset();
        const auto cachedIt = runtimeState.water.flowTrailSourceArtifacts.find(
            sourceRequest->sourceId);
        if (cachedIt != runtimeState.water.flowTrailSourceArtifacts.end() &&
            cachedIt->second.fingerprint == sourceRequest->fingerprint &&
            cachedIt->second.overlay != nullptr) {
            sourceRequest->cachedOverlay = cachedIt->second.overlay;
            sourceRequest->cachedBakedSpeedMetersPerSecond =
                cachedIt->second.bakedSpeedMetersPerSecond;
        }
    };
    const auto appendCachedSource = [&](std::uint32_t sourceId) {
        const auto cachedIt = runtimeState.water.flowTrailSourceRequests.find(sourceId);
        if (cachedIt == runtimeState.water.flowTrailSourceRequests.end()) {
            return false;
        }
        auto sourceRequest = cachedIt->second;
        sourceRequest.gpuRefreshRequired = false;
        sourceRequest.cpuSnapshotRequired = cpuSnapshotIsRequired(sourceId);
        attachArtifact(&sourceRequest);
        request.activeSourceIds.push_back(sourceId);
        request.sources.push_back(std::move(sourceRequest));
        return true;
    };
    const auto appendPreparedSource = [&runtimeState, &request, &attachArtifact, &cpuSnapshotIsRequired](
        std::uint32_t sourceId,
        WaterOverlay anchors,
        WaterFlowTrailSettings settings,
        SavedWaterTrailProfileState trailProfile,
        bool usesPathAnalysis,
        bool useSurfaceGuide,
        invisible_places::water::WaterFlowGpuInputKind gpuInputKind,
        std::vector<invisible_places::io::Float3> gpuControlPoints,
        std::vector<invisible_places::water::WaterManualFlowPathLaneWidth>
            gpuControlPointLaneWidths) {
        WaterFlowTrailSourceBuildRequest sourceRequest;
        sourceRequest.sourceId = sourceId;
        sourceRequest.anchors =
            std::make_shared<const WaterOverlay>(std::move(anchors));
        sourceRequest.fingerprint = WaterFlowTrailSourceFingerprint(
            runtimeState,
            sourceId,
            *sourceRequest.anchors,
            settings,
            usesPathAnalysis,
            useSurfaceGuide);
        sourceRequest.settings = settings;
        sourceRequest.trailProfile = std::move(trailProfile);
        sourceRequest.usesPathAnalysis = usesPathAnalysis;
        sourceRequest.useSurfaceGuide = useSurfaceGuide;
        sourceRequest.gpuInputKind = gpuInputKind;
        sourceRequest.gpuControlPoints =
            std::make_shared<const std::vector<invisible_places::io::Float3>>(
                std::move(gpuControlPoints));
        auto compactInput =
            gpuInputKind == invisible_places::water::WaterFlowGpuInputKind::ManualCatmullRomControlPoints
                ? invisible_places::water::BuildWaterFlowGpuManualSplineSourceInput(
                      *sourceRequest.gpuControlPoints,
                      gpuControlPointLaneWidths,
                      sourceId,
                      1U)
                : invisible_places::water::BuildWaterFlowGpuSampledSourceInput(
                      sourceRequest.anchors->points,
                      sourceRequest.settings,
                      usesPathAnalysis ? FlowPathAnalysisForLanes(runtimeState.water) : nullptr);
        sourceRequest.gpuCompactSourceInput =
            std::make_shared<const invisible_places::water::WaterFlowGpuCompactSourceInput>(
                std::move(compactInput));
        sourceRequest.gpuPreviewEligible =
            sourceRequest.gpuCompactSourceInput->Valid() &&
            invisible_places::water::BuildWaterFlowGpuOutputLayout(
                *sourceRequest.gpuCompactSourceInput,
                sourceRequest.settings).Valid();
        sourceRequest.gpuRefreshRequired = !request.gpuSnapshotOnly;
        sourceRequest.cpuSnapshotRequired = cpuSnapshotIsRequired(sourceId);
        attachArtifact(&sourceRequest);
        auto persistentRequest = sourceRequest;
        persistentRequest.cachedOverlay.reset();
        persistentRequest.gpuRefreshRequired = false;
        persistentRequest.cpuSnapshotRequired = false;
        runtimeState.water.flowTrailSourceRequests.insert_or_assign(
            sourceId,
            std::move(persistentRequest));
        request.activeSourceIds.push_back(sourceId);
        request.sources.push_back(std::move(sourceRequest));
    };

    std::unordered_map<std::uint32_t, WaterOverlay> anchorsByEmitter;
    if (refreshAllSources) {
        anchorsByEmitter.reserve(runtimeState.water.emitters.size());
        // Lane/Trail profile assignments derive from the last baked route
        // snapshot. Partition once for a full refresh; source-local edits scan
        // only the affected emitter below.
        for (const auto& point : runtimeState.water.pathAnchors.points) {
            const auto branchId = static_cast<std::uint32_t>(
                std::max(0.0F, std::floor(point.flowId + 0.5F)));
            if (hiddenBranchIds.contains(branchId)) {
                continue;
            }
            const auto emitterId = static_cast<std::uint32_t>(
                std::max(0.0F, std::floor(point.emitterId + 0.5F)));
            auto& anchors = anchorsByEmitter[emitterId];
            anchors.bounds.Expand(point.position);
            anchors.points.push_back(point);
        }
    }
    const auto buildEmitterAnchors = [&](std::uint32_t emitterId) {
        if (refreshAllSources) {
            const auto anchorsIt = anchorsByEmitter.find(emitterId);
            return anchorsIt == anchorsByEmitter.end()
                       ? WaterOverlay{}
                       : std::move(anchorsIt->second);
        }
        WaterOverlay anchors;
        for (const auto& point : runtimeState.water.pathAnchors.points) {
            const auto pointEmitterId = static_cast<std::uint32_t>(
                std::max(0.0F, std::floor(point.emitterId + 0.5F)));
            if (pointEmitterId != emitterId) {
                continue;
            }
            const auto branchId = static_cast<std::uint32_t>(
                std::max(0.0F, std::floor(point.flowId + 0.5F)));
            if (hiddenBranchIds.contains(branchId)) {
                continue;
            }
            anchors.bounds.Expand(point.position);
            anchors.points.push_back(point);
        }
        return anchors;
    };

    bool usesGeneratedAnchors = false;
    for (const auto& emitter : runtimeState.water.emitters) {
        if (!sourceNeedsRefresh(emitter.id) && appendCachedSource(emitter.id)) {
            usesGeneratedAnchors = true;
            continue;
        }
        auto anchors = buildEmitterAnchors(emitter.id);
        if (anchors.points.size() < 2U) {
            continue;
        }
        const auto trailProfile = ResolveEmitterWaterTrailProfile(runtimeState, emitter);
        appendPreparedSource(
            emitter.id,
            std::move(anchors),
            MakeEmitterFlowSettings(runtimeState.water, emitter, trailProfile),
            trailProfile,
            true,
            false,
            invisible_places::water::WaterFlowGpuInputKind::SampledAnchors,
            {},
            {});
        usesGeneratedAnchors = true;
    }

    for (const auto& source : runtimeState.water.manualFlowPaths) {
        if (!sourceNeedsRefresh(source.id) && appendCachedSource(source.id)) {
            continue;
        }
        const auto trailProfile = ResolveManualFlowPathTrailProfile(runtimeState, source);
        const auto settings = invisible_places::water::ApplyWaterTrailGeometryToFlowTrailSettings(
            ResolveManualFlowPathLaneSettings(runtimeState.water, source),
            trailProfile.geometry);
        const float anchorSpacing = std::clamp(
            trailProfile.geometry.pointSpacingMeters * 2.0F,
            0.005F,
            0.05F);
        auto anchors = invisible_places::water::BuildManualFlowPathAnchors(
            source,
            anchorSpacing,
            settings.laneSpreadMeters);
        if (anchors.points.size() < 2U) {
            continue;
        }
        appendPreparedSource(
            source.id,
            std::move(anchors),
            settings,
            trailProfile,
            false,
            source.useSurfaceGuide,
            invisible_places::water::WaterFlowGpuInputKind::ManualCatmullRomControlPoints,
            source.controlPoints,
            source.controlPointLaneWidths);
    }

    if (request.sources.empty() && !runtimeState.water.pathAnchors.points.empty()) {
        WaterOverlay fallbackAnchors;
        for (const auto& point : runtimeState.water.pathAnchors.points) {
            const auto branchId = static_cast<std::uint32_t>(
                std::max(0.0F, std::floor(point.flowId + 0.5F)));
            if (hiddenBranchIds.contains(branchId)) {
                continue;
            }
            fallbackAnchors.bounds.Expand(point.position);
            fallbackAnchors.points.push_back(point);
        }
        if (fallbackAnchors.points.size() >= 2U) {
            WaterEmitter fallbackEmitter;
            fallbackEmitter.id = 0U;
            fallbackEmitter.name = "Global";
            const auto trailProfile = ViewedGlobalWaterTrailProfile(runtimeState);
            appendPreparedSource(
                0U,
                std::move(fallbackAnchors),
                MakeEmitterFlowSettings(runtimeState.water, fallbackEmitter, trailProfile),
                trailProfile,
                true,
                false,
                invisible_places::water::WaterFlowGpuInputKind::SampledAnchors,
                {},
                {});
            usesGeneratedAnchors = true;
        }
    }

    if (usesGeneratedAnchors) {
        if (const auto* analysis = FlowPathAnalysisForLanes(runtimeState.water); analysis != nullptr) {
            (void)analysis;
            EnsureWaterFlowPathAnalysisSnapshot(&runtimeState.water);
            request.pathAnalysis = runtimeState.water.flowPathAnalysisSnapshot;
        }
    }
    const std::unordered_set<std::uint32_t> activeSourceIds{
        request.activeSourceIds.begin(),
        request.activeSourceIds.end()};
    std::erase_if(
        runtimeState.water.flowTrailSourceRequests,
        [&](const auto& entry) { return !activeSourceIds.contains(entry.first); });
    return request;
}

void StartPendingWaterFlowTrailBuild(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        runtimeState->water.flowTrailBuildJob.worker.joinable() ||
        !runtimeState->water.flowTrailBuildJob.pendingCapture ||
        std::chrono::steady_clock::now() < runtimeState->water.flowTrailBuildJob.pendingNotBefore) {
        return;
    }

    auto& job = runtimeState->water.flowTrailBuildJob;
    auto request = CaptureWaterFlowTrailBuildRequest(
        *runtimeState,
        job.pendingRequestId,
        job.pendingSavePathCache,
        job.pendingCpuSnapshotOnly,
        job.pendingFullSourceRefresh,
        &job.pendingDirtySourceIds);
    job.pendingCapture = false;
    job.pendingCpuSnapshotOnly = false;
    job.pendingFullSourceRefresh = false;
    job.pendingDirtySourceIds.clear();
    job.activeRequestId = request.requestId;
    auto shared = std::make_shared<WaterFlowTrailBuildJobShared>();
    job.shared = shared;
    job.worker = std::jthread(
        [shared, request = std::move(request)](std::stop_token stopToken) mutable {
            WaterFlowTrailBuildJobResult result;
            result.requestId = request.requestId;
            result.sourceCount = request.sources.size();
            result.activeSourceIds = request.activeSourceIds;
            result.savePathCache = request.savePathCache;
            result.gpuSnapshotOnly = request.gpuSnapshotOnly;
            try {
                const auto buildStartedAt = std::chrono::steady_clock::now();
                for (const auto& source : request.sources) {
                    if (stopToken.stop_requested()) {
                        result.cancelled = true;
                        break;
                    }
                    if (source.cachedOverlay != nullptr) {
                        ++result.reusedSourceCount;
                        AppendWaterTrailOverlayGroup(
                            &result.groups,
                            source.sourceId,
                            source.trailProfile,
                            source.cachedOverlay,
                            source.cachedBakedSpeedMetersPerSecond,
                            source.settings.speedMetersPerSecond,
                            source.cpuSnapshotRequired);
                        continue;
                    }
                    const auto* analysis =
                        source.usesPathAnalysis && request.pathAnalysis != nullptr
                            ? request.pathAnalysis.get()
                            : nullptr;
                    auto overlay = invisible_places::water::BuildFlowTrailOverlayFromPathAnchors(
                        source.anchors != nullptr ? *source.anchors : WaterOverlay{},
                        source.settings,
                        analysis,
                        invisible_places::water::WaterFlowTrailBuildOptions{
                            .stopToken = &stopToken,
                            .surfaceCache = source.useSurfaceGuide && request.surfaceCache != nullptr
                                ? request.surfaceCache.get()
                                : nullptr,
                            .useSurfaceGuide = source.useSurfaceGuide,
                        });
                    if (stopToken.stop_requested()) {
                        result.cancelled = true;
                        break;
                    }
                    ++result.rebuiltSourceCount;
                    auto cachedOverlay = std::make_shared<WaterTrailOverlay>(std::move(overlay));
                    result.rebuiltArtifacts.push_back({
                        .sourceId = source.sourceId,
                        .fingerprint = source.fingerprint,
                        .trailProfile = source.trailProfile,
                        .overlay = cachedOverlay,
                        .bakedSpeedMetersPerSecond = source.settings.speedMetersPerSecond,
                    });
                    AppendWaterTrailOverlayGroup(
                        &result.groups,
                        source.sourceId,
                        source.trailProfile,
                        std::move(cachedOverlay),
                        source.settings.speedMetersPerSecond,
                        source.settings.speedMetersPerSecond);
                }
                result.buildMs = std::chrono::duration<double, std::milli>(
                                     std::chrono::steady_clock::now() - buildStartedAt)
                                     .count();

                if (!result.cancelled) {
                    const auto packStartedAt = std::chrono::steady_clock::now();
                    for (auto& group : result.groups) {
                        if (stopToken.stop_requested()) {
                            result.cancelled = true;
                            break;
                        }
                        if (group.overlay == nullptr) {
                            continue;
                        }
                        result.sampleCount += group.overlay->samples.size();
                        if (!group.requiresUpload) {
                            continue;
                        }
                        group.packedCloud = invisible_places::water::BuildWaterTrailOverlayPointCloud(
                            *group.overlay,
                            {},
                            group.trailProfile.name,
                            &stopToken);
                        if (stopToken.stop_requested()) {
                            result.cancelled = true;
                            break;
                        }
                    }
                    result.packMs = std::chrono::duration<double, std::milli>(
                                        std::chrono::steady_clock::now() - packStartedAt)
                                        .count();
                }
            } catch (const std::exception& error) {
                result.errorMessage = error.what();
            }
            {
                std::lock_guard lock{shared->mutex};
                shared->result = std::move(result);
                shared->completed = true;
            }
        });
}

bool QueueWaterFlowTrailRefresh(
    PreviewRuntimeState* runtimeState,
    WaterOverlayRefreshPersistence persistence,
    std::chrono::milliseconds debounce = std::chrono::milliseconds{0},
    std::optional<std::uint32_t> dirtySourceId) {
    if (runtimeState == nullptr || runtimeState->pendingLoad.has_value()) {
        return false;
    }
    auto& job = runtimeState->water.flowTrailBuildJob;
    const auto requestId = job.nextRequestId++;
    job.pendingCapture = true;
    job.pendingSavePathCache =
        persistence == WaterOverlayRefreshPersistence::SavePathCache;
    job.pendingCpuSnapshotOnly = false;
    if (dirtySourceId.has_value()) {
        if (!job.pendingFullSourceRefresh) {
            job.pendingDirtySourceIds.insert(dirtySourceId.value());
        }
    } else {
        job.pendingFullSourceRefresh = true;
        job.pendingDirtySourceIds.clear();
    }
    job.pendingRequestId = requestId;
    job.pendingNotBefore = std::chrono::steady_clock::now() +
                           std::max(debounce, std::chrono::milliseconds{33});
    if (job.worker.joinable()) {
        if (!job.worker.get_stop_token().stop_requested()) {
            job.worker.request_stop();
            ++job.cancellationCount;
        }
    }
    runtimeState->statusMessage = "Updating Flow lanes and trails in the background...";
    runtimeState->errorMessage.clear();
    return true;
}

bool QueueWaterFlowCpuExportSnapshot(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || runtimeState->pendingLoad.has_value()) {
        return false;
    }
    auto& job = runtimeState->water.flowTrailBuildJob;
    if (job.worker.joinable() || job.pendingCapture) {
        return false;
    }
    job.pendingCapture = true;
    job.pendingSavePathCache = false;
    job.pendingCpuSnapshotOnly = true;
    // GPU inputs have already been captured by the per-source request cache.
    // Reuse them all and rebuild/pack only missing or stale export snapshots.
    job.pendingFullSourceRefresh = false;
    job.pendingDirtySourceIds.clear();
    job.pendingRequestId = job.nextRequestId++;
    job.pendingNotBefore = std::chrono::steady_clock::now();
    return true;
}

bool QueueEditedWaterProfileUserRefresh(
    PreviewRuntimeState* runtimeState,
    bool laneProfile,
    WaterOverlayRefreshPersistence persistence,
    std::chrono::milliseconds debounce) {
    if (runtimeState == nullptr) {
        return false;
    }
    const auto& water = runtimeState->water;
    const std::string selectedProfileName =
        laneProfile
            ? water.selectedLaneProfileName
            : water.selectedTrailProfileName;
    const bool hasEditedSettings =
        laneProfile
            ? water.editedLaneProfileSettings.has_value()
            : water.editedTrailProfile.has_value();
    const auto sourceUsesEdit = [&](std::string_view assignedName, bool locked) {
        return WaterSourceProfileUsesEditedSettings(
            assignedName,
            locked,
            selectedProfileName,
            hasEditedSettings);
    };

    bool queued = false;
    for (const auto& emitter : water.emitters) {
        const bool affected =
            laneProfile
                ? sourceUsesEdit(emitter.laneProfileName, emitter.laneProfileLocked)
                : sourceUsesEdit(emitter.trailProfileName, emitter.trailProfileLocked);
        if (affected) {
            queued |= QueueWaterFlowTrailRefresh(
                runtimeState,
                persistence,
                debounce,
                emitter.id);
        }
    }
    for (const auto& source : water.manualFlowPaths) {
        const bool affected =
            laneProfile
                ? sourceUsesEdit(source.laneProfileName, source.laneProfileLocked)
                : sourceUsesEdit(source.trailProfileName, source.trailProfileLocked);
        if (affected) {
            queued |= QueueWaterFlowTrailRefresh(
                runtimeState,
                persistence,
                debounce,
                source.id);
        }
    }
    if (water.emitters.empty() && water.manualFlowPaths.empty() &&
        !water.pathAnchors.points.empty()) {
        queued |= QueueWaterFlowTrailRefresh(
            runtimeState,
            persistence,
            debounce,
            0U);
    }
    return queued;
}

bool RefreshResolvedWaterFlowSourceSettings(
    PreviewRuntimeState* runtimeState,
    std::chrono::milliseconds debounce = std::chrono::milliseconds{0}) {
    if (runtimeState == nullptr) {
        return false;
    }
    bool queued = false;
    const auto applyOrQueue = [&](
        std::uint32_t sourceId,
        const WaterFlowTrailSettings& settings,
        const SavedWaterTrailProfileState& trailProfile) {
        const auto cachedIt = runtimeState->water.flowTrailSourceRequests.find(sourceId);
        const bool topologyUnchanged =
            cachedIt != runtimeState->water.flowTrailSourceRequests.end() &&
            invisible_places::water::WaterFlowLaneRouteInputsEqual(
                cachedIt->second.settings,
                settings);
        if (topologyUnchanged && ApplyWaterFlowSourceLiveSettings(
                                     runtimeState,
                                     sourceId,
                                     settings,
                                     trailProfile)) {
            return;
        }
        queued |= QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::InMemoryOnly,
            debounce,
            sourceId);
    };
    for (const auto& emitter : runtimeState->water.emitters) {
        const auto trailProfile = ResolveEmitterWaterTrailProfile(*runtimeState, emitter);
        applyOrQueue(
            emitter.id,
            MakeEmitterFlowSettings(runtimeState->water, emitter, trailProfile),
            trailProfile);
    }
    for (const auto& source : runtimeState->water.manualFlowPaths) {
        const auto trailProfile = ResolveManualFlowPathTrailProfile(*runtimeState, source);
        applyOrQueue(
            source.id,
            invisible_places::water::ApplyWaterTrailGeometryToFlowTrailSettings(
                ResolveManualFlowPathLaneSettings(runtimeState->water, source),
                trailProfile.geometry),
            trailProfile);
    }
    if (runtimeState->water.emitters.empty() &&
        runtimeState->water.manualFlowPaths.empty() &&
        !runtimeState->water.pathAnchors.points.empty()) {
        WaterEmitter fallbackEmitter;
        fallbackEmitter.id = 0U;
        const auto trailProfile = ViewedGlobalWaterTrailProfile(*runtimeState);
        applyOrQueue(
            0U,
            MakeEmitterFlowSettings(runtimeState->water, fallbackEmitter, trailProfile),
            trailProfile);
    }
    return queued;
}

void CancelWaterFlowTrailBuildJob(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    auto& job = water->flowTrailBuildJob;
    if (!job.pendingCapture && !job.worker.joinable() && job.shared == nullptr) {
        return;
    }

    job.pendingCapture = false;
    job.pendingSavePathCache = false;
    job.pendingCpuSnapshotOnly = false;
    job.pendingFullSourceRefresh = false;
    job.pendingDirtySourceIds.clear();
    job.pendingRequestId = 0U;
    ++job.nextRequestId;
    if (job.worker.joinable()) {
        if (!job.worker.get_stop_token().stop_requested()) {
            job.worker.request_stop();
            ++job.cancellationCount;
        }
        job.worker = std::jthread{};
    }
    job.shared.reset();
    job.activeRequestId = 0U;
}

PointCloudStyleState MakeEffectiveFastBasicStyle(
    const PointCloudStyleState& sourceStyle,
    bool hasSourceRgb,
    bool waterOverlay) {
    auto style = invisible_places::renderer::pointcloud::MakeFastBasicPointCloudStyle(sourceStyle, hasSourceRgb);
    if (waterOverlay && (sourceStyle.flowAnimation || sourceStyle.waterTrailOverlay)) {
        style.flowAnimation = true;
        style.waterPathView = sourceStyle.waterPathView;
        style.waterTrailOverlay = sourceStyle.waterTrailOverlay;
        style.waterTrailStyleGeometry = sourceStyle.waterTrailStyleGeometry;
        if (style.waterPathView) {
            style.pointSize = sourceStyle.pointSize;
        }
    }
    return style;
}

std::size_t AddOrRefreshWaterOverlaySession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& overlayPath,
    std::string_view visualName = "Water Flow_preset",
    std::optional<PointCloudStyleState> defaultStyle = std::nullopt) {
    const auto headerResult = invisible_places::io::ParsePlyHeader(overlayPath);
    if (!headerResult.success) {
        if (runtimeState != nullptr) {
            runtimeState->errorMessage = "Water overlay header parse failed: " + headerResult.errorMessage;
        }
        return std::numeric_limits<std::size_t>::max();
    }

    const auto existingIndex = runtimeState != nullptr
                                   ? FindSessionIndexBySourcePath(*runtimeState, overlayPath)
                                   : std::nullopt;
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = overlayPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    } else if (runtimeState->sessions[sessionIndex].loaded) {
        UnloadLayerByIndex(runtimeState, viewport, sessionIndex);
    }

    auto& session = runtimeState->sessions[sessionIndex];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = overlayPath.stem().string();
    session.generatedWaterOverlay = true;
    session.hasSourceRgb = headerResult.header.HasColorRgb();
    session.totalPrimitives = headerResult.header.vertexCount;
    session.pointBudget = invisible_places::renderer::pointcloud::MakePointBudgetState(
        headerResult.header.vertexCount,
        headerResult.header.vertexCount);
    if (!existingIndex.has_value() || session.pointVisuals.empty()) {
        session.pointStyle = defaultStyle.value_or(MakeWaterOverlayDisplayStyle(*runtimeState));
        session.selectedPointVisualName = NormalizeWaterPointVisualName(visualName);
        session.pointVisualNameBuffer = BasePointVisualName(session.selectedPointVisualName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({.name = session.selectedPointVisualName, .style = session.pointStyle});
    } else {
        session.pointStyle.flowAnimation = true;
        session.pointStyle.waterTrailOverlay = NormalizeWaterPointVisualName(visualName) == "Water Flow_preset";
        session.pointStyle.waterPathView =
            NormalizeWaterPointVisualName(visualName) == "Water Flow_preset" &&
            runtimeState->water.overlayViewMode == WaterOverlayViewMode::Path;
        EnsurePointVisuals(&session);
    }
    if (NormalizeWaterPointVisualName(visualName) == "Water Flow_preset") {
        SeedWaterFlowBuiltInVisuals(runtimeState, &session);
    }
    BeginLayerLoad(sessionIndex, runtimeState);
    return sessionIndex;
}

void StoreLiveWaterFlowOverlay(
    PreviewRuntimeState* runtimeState,
    WaterOverlay overlay) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.flowOverlay = std::move(overlay);
    ++runtimeState->water.flowOverlayRevision;
    runtimeState->water.pathDebugCacheRevision = 0;
    runtimeState->water.pathDebugPolylines.clear();
}

std::size_t AddOrRefreshWaterFlowOverlaySession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& overlayPath,
    WaterOverlay overlay) {
    if (runtimeState == nullptr || viewport == nullptr || overlay.points.empty()) {
        return std::numeric_limits<std::size_t>::max();
    }

    StoreLiveWaterFlowOverlay(runtimeState, std::move(overlay));
    const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, overlayPath);
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = overlayPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    }

    auto& session = runtimeState->sessions[sessionIndex];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = overlayPath.stem().string();
    session.generatedWaterOverlay = true;
    if (!existingIndex.has_value() || session.pointVisuals.empty()) {
        session.pointStyle = MakeWaterOverlayDisplayStyle(*runtimeState);
        session.selectedPointVisualName = "Water Flow_preset";
        session.pointVisualNameBuffer = "Water Flow";
        session.pointVisuals.clear();
        session.pointVisuals.push_back({.name = "Water Flow_preset", .style = session.pointStyle});
    } else {
        session.pointStyle.flowAnimation = true;
        session.pointStyle.waterTrailOverlay = true;
        session.pointStyle.waterPathView = runtimeState->water.overlayViewMode == WaterOverlayViewMode::Path;
        EnsurePointVisuals(&session);
    }
    SeedWaterFlowBuiltInVisuals(runtimeState, &session);

    auto cloud = invisible_places::water::BuildWaterOverlayPointCloud(
        runtimeState->water.flowOverlay,
        overlayPath,
        session.displayName);
    if (!ActivateLoadedPointCloud(sessionIndex, std::move(cloud), runtimeState, viewport)) {
        return std::numeric_limits<std::size_t>::max();
    }
    auto& installedSession = runtimeState->sessions[sessionIndex];
    installedSession.waterFlowGpuPreview = false;
    installedSession.waterFlowGpuFingerprint = 0U;
    installedSession.waterFlowGpuRevision = 0U;
    return sessionIndex;
}

void StoreLiveWaterFlowTrailOverlay(
    PreviewRuntimeState* runtimeState,
    WaterTrailOverlay overlay) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.flowTrailOverlay = std::move(overlay);
    ++runtimeState->water.flowOverlayRevision;
    runtimeState->water.pathDebugCacheRevision = 0;
    runtimeState->water.pathDebugPolylines.clear();
}

std::size_t AddOrRefreshWaterTrailOverlaySession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& overlayPath,
    WaterTrailOverlay overlay,
    std::string_view visualName,
    bool storeAsFlowOverlay,
    std::optional<PointCloudStyleState> defaultStyle = std::nullopt,
    std::optional<invisible_places::io::LoadedPointCloud> preparedCloud = std::nullopt,
    std::optional<std::uint32_t> flowSourceId = std::nullopt) {
    if (runtimeState == nullptr || viewport == nullptr || overlay.samples.empty()) {
        return std::numeric_limits<std::size_t>::max();
    }

    if (storeAsFlowOverlay) {
        StoreLiveWaterFlowTrailOverlay(runtimeState, overlay);
        overlay = runtimeState->water.flowTrailOverlay;
    }
    const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, overlayPath);
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = overlayPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    }

    auto& session = runtimeState->sessions[sessionIndex];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = overlayPath.stem().string();
    session.generatedWaterOverlay = true;
    session.waterFlowSourceId = flowSourceId;
    if (defaultStyle.has_value()) {
        const auto profileName = NormalizeWaterProfileName(visualName);
        session.pointStyle = MakeWaterTrailExportStyle(defaultStyle.value());
        session.selectedPointVisualName = profileName;
        session.pointVisualNameBuffer = BaseWaterProfileName(profileName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({.name = session.selectedPointVisualName, .style = session.pointStyle});
    } else if (!existingIndex.has_value() || session.pointVisuals.empty()) {
        session.pointStyle = MakeWaterOverlayDisplayStyle(*runtimeState);
        session.selectedPointVisualName = std::string{visualName};
        session.pointVisualNameBuffer = BasePointVisualName(session.selectedPointVisualName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({.name = session.selectedPointVisualName, .style = session.pointStyle});
    } else {
        session.pointStyle.flowAnimation = true;
        session.pointStyle.waterTrailOverlay = true;
        session.pointStyle.waterPathView = false;
        EnsurePointVisuals(&session);
    }
    if (!defaultStyle.has_value()) {
        SeedWaterFlowBuiltInVisuals(runtimeState, &session);
    }

    auto cloud = preparedCloud.has_value()
                     ? std::move(preparedCloud.value())
                     : invisible_places::water::BuildWaterTrailOverlayPointCloud(
                           storeAsFlowOverlay ? runtimeState->water.flowTrailOverlay : overlay,
                           overlayPath,
                           session.displayName);
    cloud.sourcePath = overlayPath;
    cloud.layerName = session.displayName;
    if (!ActivateLoadedPointCloud(sessionIndex, std::move(cloud), runtimeState, viewport)) {
        return std::numeric_limits<std::size_t>::max();
    }
    auto& installedSession = runtimeState->sessions[sessionIndex];
    installedSession.waterFlowGpuPreview = false;
    installedSession.waterFlowGpuFingerprint = 0U;
    installedSession.waterFlowGpuRevision = 0U;
    return sessionIndex;
}

std::size_t AddOrRefreshDynamicMeshGpuTrailOverlaySession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& overlayPath,
    const MeshSurfaceCache& cache,
    const WaterDynamicMeshFlowSettings& settings,
    const std::vector<WaterEmitter>& emitters,
    const SavedWaterTrailProfileState& profile,
    WaterTrailBuildQuality quality,
    invisible_places::renderer::core::DynamicMeshFlowGpuUploadResult* uploadResult) {
    if (runtimeState == nullptr || viewport == nullptr || uploadResult == nullptr) {
        return std::numeric_limits<std::size_t>::max();
    }

    const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, overlayPath);
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = overlayPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    }

    auto solveSettings = settings;
    solveSettings.trailWidthMeters = profile.geometry.widthMeters;
    solveSettings.trailStreakLengthMeters = profile.geometry.streakLengthMeters;

    auto result = viewport->UploadDynamicMeshFlowPreviewPointCloud(
        sessionIndex,
        cache,
        emitters,
        solveSettings,
        quality);
    if (result.pointCount == 0U) {
        return std::numeric_limits<std::size_t>::max();
    }

    auto& session = runtimeState->sessions[sessionIndex];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = overlayPath.stem().string();
    session.generatedWaterOverlay = true;
    session.hasSourceRgb = true;
    session.hasNormals = true;
    session.totalPrimitives = result.pointCount;
    session.scalarFields = invisible_places::water::WaterTrailOverlayScalarFieldsForPointCount(result.pointCount);
    session.bounds = cache.bounds;
    if (session.bounds.valid) {
        session.bounds.minimum.z += settings.surfaceOffsetMeters;
        session.bounds.maximum.z += settings.surfaceOffsetMeters;
        session.focusPoint = {
            (session.bounds.minimum.x + session.bounds.maximum.x) * 0.5F,
            (session.bounds.minimum.y + session.bounds.maximum.y) * 0.5F,
            (session.bounds.minimum.z + session.bounds.maximum.z) * 0.5F,
        };
        session.hasFocusPoint = true;
    } else {
        session.focusPoint = {};
        session.hasFocusPoint = false;
    }
    session.localBounds = session.bounds;
    session.localFocusPoint = session.focusPoint;
    session.hasLocalFocusPoint = session.hasFocusPoint;
    session.pivotSamples.clear();
    session.loaded = true;
    session.gpuResident = true;
    session.cpuResident = false;
    session.visible = true;
    session.offlinePointCloud.reset();
    session.previewLodSampledIndices.clear();
    session.previewLodRequestedDrawCount = 0;
    session.previewLodSampledDrawCount = 0;
    session.pointBudget = invisible_places::renderer::pointcloud::MakePointBudgetState(
        result.pointCount,
        result.pointCount);
    session.pointStyle = MakeWaterTrailExportStyle(profile.style);
    session.selectedPointVisualName = NormalizeWaterProfileName(profile.name);
    session.pointVisualNameBuffer = BaseWaterProfileName(session.selectedPointVisualName);
    session.pointVisuals.clear();
    session.pointVisuals.push_back({.name = session.selectedPointVisualName, .style = session.pointStyle});
    EnsurePointVisuals(&session);
    *uploadResult = result;
    runtimeState->selectedSessionIndex = sessionIndex;
    return sessionIndex;
}

bool AddOrRefreshWaterFlowGpuSourceSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const PreviewLayerSession& sourceSession,
    const WaterFlowTrailSourceBuildRequest& source,
    std::uint64_t sourceRevision,
    invisible_places::renderer::core::WaterFlowGpuSourceUploadResult* uploadResult,
    std::size_t* uploadedSessionIndex) {
    if (runtimeState == nullptr || viewport == nullptr || uploadResult == nullptr ||
        uploadedSessionIndex == nullptr || source.anchors == nullptr ||
        source.anchors->points.size() < 2U) {
        return false;
    }
    const auto outputPath = BuildWaterTrailOverlayPath(
        *runtimeState,
        sourceSession,
        source.sourceId,
        source.trailProfile.name);
    auto existingIndex = FindLoadedWaterFlowSourceSessionIndex(
        *runtimeState,
        source.sourceId);
    if (!existingIndex.has_value()) {
        existingIndex = FindSessionIndexBySourcePath(*runtimeState, outputPath);
    }
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = outputPath;
        session.displayName = outputPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    }

    auto& session = runtimeState->sessions[sessionIndex];
    if (session.waterFlowGpuPreview && session.loaded &&
        session.waterFlowGpuFingerprint == source.fingerprint) {
        session.pointStyle = MakeWaterTrailSessionStyle(
            source.trailProfile.style,
            source.trailProfile.geometry);
        session.pointStyle.waterFlowSpeedScale =
            WaterFlowRuntimeSpeedScale(
                source.settings.speedMetersPerSecond,
                session.waterFlowBakedSpeedMetersPerSecond);
        session.selectedPointVisualName = NormalizeWaterProfileName(source.trailProfile.name);
        session.pointVisualNameBuffer = BaseWaterProfileName(session.selectedPointVisualName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({
            .name = session.selectedPointVisualName,
            .style = session.pointStyle,
        });
        EnsurePointVisuals(&session);
        uploadResult->accepted = true;
        uploadResult->diagnostics = viewport->WaterFlowGpuSourceState(sessionIndex);
        *uploadedSessionIndex = sessionIndex;
        return true;
    }

    const auto previousDiagnostics = session.waterFlowGpuPreview && session.loaded
                                         ? viewport->WaterFlowGpuSourceState(sessionIndex)
                                         : invisible_places::renderer::core::WaterFlowGpuSourceDiagnostics{};
    const auto previousVisiblePointCount = std::max<std::uint64_t>(
        session.waterFlowGpuPreview && session.loaded ? session.totalPrimitives : 0U,
        previousDiagnostics.activePointCount);

    invisible_places::renderer::core::WaterFlowGpuSourceRequest request;
    request.sourceId = source.sourceId;
    request.sourceRevision = sourceRevision;
    request.inputKind = source.gpuInputKind;
    request.sampledAnchors = source.anchors->points;
    request.controlPoints = source.gpuControlPoints != nullptr
                                ? std::span<const invisible_places::io::Float3>{
                                      *source.gpuControlPoints}
                                : std::span<const invisible_places::io::Float3>{};
    request.compactSourceInput = source.gpuCompactSourceInput;
    request.settings = source.settings;
    request.useSurfaceGuide = source.useSurfaceGuide;
    auto result = viewport->UploadWaterFlowGpuSource(sessionIndex, request);
    if (!result.accepted) {
        *uploadResult = result;
        *uploadedSessionIndex = sessionIndex;
        return false;
    }

    session.kind = LayerKind::PointCloud;
    session.sourcePath = outputPath;
    session.displayName = outputPath.stem().string();
    session.waterFlowSourceId = source.sourceId;
    session.waterFlowGpuFingerprint = source.fingerprint;
    session.waterFlowGpuRevision = sourceRevision;
    session.waterFlowBakedSpeedMetersPerSecond =
        std::max(1.0e-4F, source.settings.speedMetersPerSecond);
    session.waterFlowGpuPreview = true;
    session.hasSourceRgb = true;
    session.hasNormals = true;
    // Compute promotion is asynchronous. Keep enough budget for the currently
    // settled output while a smaller replacement is in flight; the renderer
    // clamps this against its active count and switches atomically on the
    // dispatch fence.
    const auto visiblePointBudget = std::max<std::uint64_t>(
        previousVisiblePointCount,
        result.layout.pointCount);
    session.totalPrimitives = visiblePointBudget;
    session.scalarFields = invisible_places::water::WaterTrailOverlayScalarFieldsForPointCount(
        result.layout.pointCapacity,
        true);
    session.bounds = source.anchors->bounds;
    if (session.bounds.valid) {
        float maximumLaneSpan =
            std::max(0.0F, source.settings.laneSpreadMeters);
        for (const auto& anchor : source.anchors->points) {
            if (std::isfinite(anchor.laneSpanMeters) &&
                anchor.laneSpanMeters >= 0.0F) {
                maximumLaneSpan =
                    std::max(maximumLaneSpan, anchor.laneSpanMeters);
            }
        }
        const float padding = std::max(
            std::abs(source.settings.surfaceOffsetMeters),
            maximumLaneSpan * 0.5F);
        session.bounds.minimum.x -= padding;
        session.bounds.minimum.y -= padding;
        session.bounds.minimum.z -= padding;
        session.bounds.maximum.x += padding;
        session.bounds.maximum.y += padding;
        session.bounds.maximum.z += padding;
        session.focusPoint = {
            (session.bounds.minimum.x + session.bounds.maximum.x) * 0.5F,
            (session.bounds.minimum.y + session.bounds.maximum.y) * 0.5F,
            (session.bounds.minimum.z + session.bounds.maximum.z) * 0.5F,
        };
        session.hasFocusPoint = true;
    } else {
        session.focusPoint = {};
        session.hasFocusPoint = false;
    }
    session.localBounds = session.bounds;
    session.localFocusPoint = session.focusPoint;
    session.hasLocalFocusPoint = session.hasFocusPoint;
    session.pivotSamples.clear();
    session.loaded = true;
    session.gpuResident = true;
    session.cpuResident = false;
    session.visible = true;
    session.offlinePointCloud.reset();
    session.waterFlowCpuSnapshotRevision = 0U;
    session.previewLodSampledIndices.clear();
    session.previewLodRequestedDrawCount = 0U;
    session.previewLodSampledDrawCount = 0U;
    session.pointBudget = invisible_places::renderer::pointcloud::MakePointBudgetState(
        visiblePointBudget,
        visiblePointBudget);
    session.pointStyle = MakeWaterTrailSessionStyle(
        source.trailProfile.style,
        source.trailProfile.geometry);
    session.pointStyle.waterFlowSpeedScale = 1.0F;
    session.selectedPointVisualName = NormalizeWaterProfileName(source.trailProfile.name);
    session.pointVisualNameBuffer = BaseWaterProfileName(session.selectedPointVisualName);
    session.pointVisuals.clear();
    session.pointVisuals.push_back({
        .name = session.selectedPointVisualName,
        .style = session.pointStyle,
    });
    EnsurePointVisuals(&session);
    *uploadResult = result;
    *uploadedSessionIndex = sessionIndex;
    return true;
}

bool UnloadGeneratedWaterFlowOverlaySessions(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool unloadedAny = false;
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!session.loaded || !IsGeneratedWaterFlowOverlaySession(session)) {
            continue;
        }
        const auto stem = session.sourcePath.stem().string();
        if (IsGeneratedWaterFlowTrailOverlayStem(stem)) {
            UnloadLayerByIndex(runtimeState, viewport, index);
            unloadedAny = true;
        }
    }
    return unloadedAny;
}

bool UnloadGeneratedWaterFlowSourceSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::uint32_t sourceId) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    bool unloadedAny = false;
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!session.loaded ||
            !session.waterFlowSourceId.has_value() ||
            session.waterFlowSourceId.value() != sourceId ||
            !IsGeneratedWaterFlowOverlaySession(session) ||
            !IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string())) {
            continue;
        }
        UnloadLayerByIndex(runtimeState, viewport, index);
        unloadedAny = true;
    }
    runtimeState->water.flowTrailSourceArtifacts.erase(sourceId);
    runtimeState->water.flowTrailSourceRequests.erase(sourceId);
    return unloadedAny;
}

std::size_t InstallWaterFlowTrailOverlayGroups(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const PreviewLayerSession& sourceSession,
    std::vector<WaterTrailOverlayGroup> groups) {
    if (runtimeState == nullptr || viewport == nullptr || groups.empty()) {
        return 0U;
    }

    std::size_t sampleCount = 0U;
    for (const auto& group : groups) {
        if (group.overlay != nullptr) {
            sampleCount += group.overlay->samples.size();
        }
    }
    ++runtimeState->water.pathDiagnosticRebuildCounters.laneBuilds;
    ++runtimeState->water.pathDiagnosticRebuildCounters.trailBuilds;
    // Per-source artifacts are now the canonical CPU/reference snapshots. Do
    // not concatenate every source into another multi-million-sample overlay on
    // each edit or deletion; Path View derives its bounded diagnostics lazily.
    StoreLiveWaterFlowTrailOverlay(runtimeState, {});

    bool setLastOverlayPath = false;
    std::unordered_set<std::string> activeOverlayPaths;
    activeOverlayPaths.reserve(groups.size());
    for (auto& group : groups) {
        const auto outputPath =
            BuildWaterTrailOverlayPath(
                *runtimeState,
                sourceSession,
                group.sourceId,
                group.trailProfile.name);
        activeOverlayPaths.insert(outputPath.lexically_normal().generic_string());
        if (!setLastOverlayPath) {
            runtimeState->water.lastOverlayPath = outputPath;
            setLastOverlayPath = true;
        }
        const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, outputPath);
        if (!group.requiresUpload && existingIndex.has_value() &&
            existingIndex.value() < runtimeState->sessions.size() &&
            runtimeState->sessions[existingIndex.value()].loaded) {
            auto& session = runtimeState->sessions[existingIndex.value()];
            session.waterFlowBakedSpeedMetersPerSecond = std::max(
                1.0e-4F,
                group.bakedSpeedMetersPerSecond);
            session.pointStyle = MakeWaterTrailExportStyle(group.trailProfile.style);
            session.pointStyle.waterFlowSpeedScale = WaterFlowRuntimeSpeedScale(
                group.resolvedSpeedMetersPerSecond,
                session.waterFlowBakedSpeedMetersPerSecond);
            session.selectedPointVisualName = NormalizeWaterProfileName(group.trailProfile.name);
            session.pointVisualNameBuffer = BaseWaterProfileName(session.selectedPointVisualName);
            session.pointVisuals.clear();
            session.pointVisuals.push_back({
                .name = session.selectedPointVisualName,
                .style = session.pointStyle,
            });
            EnsurePointVisuals(&session);
            continue;
        }
        const auto installedIndex = AddOrRefreshWaterTrailOverlaySession(
            runtimeState,
            viewport,
            outputPath,
            group.overlay != nullptr ? *group.overlay : WaterTrailOverlay{},
            group.trailProfile.name,
            false,
            group.trailProfile.style,
            std::move(group.packedCloud),
            group.sourceId);
        if (installedIndex < runtimeState->sessions.size()) {
            auto& session = runtimeState->sessions[installedIndex];
            session.waterFlowBakedSpeedMetersPerSecond = std::max(
                1.0e-4F,
                group.bakedSpeedMetersPerSecond);
            session.pointStyle.waterFlowSpeedScale = WaterFlowRuntimeSpeedScale(
                group.resolvedSpeedMetersPerSecond,
                session.waterFlowBakedSpeedMetersPerSecond);
            for (auto& visual : session.pointVisuals) {
                visual.style.waterFlowSpeedScale = session.pointStyle.waterFlowSpeedScale;
            }
        }
    }
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!session.loaded ||
            !IsGeneratedWaterFlowOverlaySession(session) ||
            !IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string()) ||
            activeOverlayPaths.contains(session.sourcePath.lexically_normal().generic_string())) {
            continue;
        }
        UnloadLayerByIndex(runtimeState, viewport, index);
    }
    return sampleCount;
}

bool ScaleWaterFlowTrailSpeedScalars(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const WaterFlowTrailSettings& previousSettings,
    const WaterFlowTrailSettings& nextSettings) {
    if (runtimeState == nullptr || viewport == nullptr ||
        !invisible_places::water::WaterFlowLaneSpeedOnlyEdit(previousSettings, nextSettings)) {
        return false;
    }

    std::unordered_set<std::uint32_t> affectedSourceIds;
    for (const auto& emitter : runtimeState->water.emitters) {
        if (WaterSourceProfileUsesEditedSettings(
                emitter.laneProfileName,
                emitter.laneProfileLocked,
                runtimeState->water.selectedLaneProfileName,
                runtimeState->water.editedLaneProfileSettings.has_value())) {
            affectedSourceIds.insert(emitter.id);
        }
    }
    for (const auto& source : runtimeState->water.manualFlowPaths) {
        if (WaterSourceProfileUsesEditedSettings(
                source.laneProfileName,
                source.laneProfileLocked,
                runtimeState->water.selectedLaneProfileName,
                runtimeState->water.editedLaneProfileSettings.has_value())) {
            affectedSourceIds.insert(source.id);
        }
    }
    if (affectedSourceIds.empty() &&
        runtimeState->water.emitters.empty() &&
        runtimeState->water.manualFlowPaths.empty() &&
        !runtimeState->water.pathAnchors.points.empty()) {
        affectedSourceIds.insert(0U);
    }

    for (const auto sourceId : affectedSourceIds) {
        if (const auto cachedIt = runtimeState->water.flowTrailSourceRequests.find(sourceId);
            cachedIt != runtimeState->water.flowTrailSourceRequests.end()) {
            cachedIt->second.settings.speedMetersPerSecond =
                nextSettings.speedMetersPerSecond;
        }
    }

    bool updatedAny = false;
    for (auto& session : runtimeState->sessions) {
        const auto stem = session.sourcePath.stem().string();
        if (!session.loaded ||
            !IsGeneratedWaterFlowOverlaySession(session) ||
            !IsGeneratedWaterFlowTrailOverlayStem(stem) ||
            !session.waterFlowSourceId.has_value() ||
            !affectedSourceIds.contains(session.waterFlowSourceId.value())) {
            continue;
        }
        session.pointStyle.waterFlowSpeedScale =
            WaterFlowRuntimeSpeedScale(
                nextSettings.speedMetersPerSecond,
                session.waterFlowBakedSpeedMetersPerSecond);
        for (auto& visual : session.pointVisuals) {
            visual.style.waterFlowSpeedScale = session.pointStyle.waterFlowSpeedScale;
        }
        updatedAny = true;
    }

    if (!updatedAny) {
        return false;
    }

    runtimeState->water.lastInstalledLaneSettings = nextSettings;
    runtimeState->previewRenderStateSignatureValid = false;
    runtimeState->statusMessage =
        "Water flow speed updated through source style uniforms; no route dispatch or scalar upload.";
    runtimeState->errorMessage.clear();
    return true;
}

std::size_t AddOrRefreshWaterEffectOverlaySession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& overlayPath,
    const WaterEffectOverlay& overlay,
    std::string_view visualName) {
    if (runtimeState == nullptr || viewport == nullptr || overlay.points.empty()) {
        return std::numeric_limits<std::size_t>::max();
    }

    const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, overlayPath);
    const auto sessionIndex = existingIndex.value_or(runtimeState->sessions.size());
    if (!existingIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = overlayPath.stem().string();
        runtimeState->sessions.push_back(std::move(session));
    }

    auto& session = runtimeState->sessions[sessionIndex];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = overlayPath.stem().string();
    session.generatedWaterOverlay = true;
    if (!existingIndex.has_value() || session.pointVisuals.empty()) {
        session.pointStyle = MakeWaterEffectOverlayStyle(visualName);
        session.selectedPointVisualName = std::string{visualName};
        session.pointVisualNameBuffer = BasePointVisualName(session.selectedPointVisualName);
        session.pointVisuals.clear();
        session.pointVisuals.push_back({.name = session.selectedPointVisualName, .style = session.pointStyle});
    } else {
        EnsurePointVisuals(&session);
    }

    auto cloud = invisible_places::water::BuildWaterEffectOverlayPointCloud(
        overlay,
        overlayPath,
        session.displayName);
    if (!ActivateLoadedPointCloud(sessionIndex, std::move(cloud), runtimeState, viewport)) {
        return std::numeric_limits<std::size_t>::max();
    }
    return sessionIndex;
}

std::filesystem::path BuildWaterOverlayPath(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    const auto waterDirectory = projectPath.empty()
                                    ? std::filesystem::path{"Saved"} / "water"
                                    : projectPath.parent_path() / "water";
    const auto suffix = "-WaterFlowTrails.generated";
    return waterDirectory / (sourceSession.sourcePath.stem().string() + suffix);
}

std::filesystem::path BuildWaterPathCacheDirectory(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    const auto cacheDirectory = !sourceSession.sourcePath.parent_path().empty()
                                    ? sourceSession.sourcePath.parent_path() /
                                          ".invisible_places" / "cache" / "flow"
                                    : (projectPath.empty()
                                           ? std::filesystem::path{"Saved"} / "water"
                                           : projectPath.parent_path() /
                                                 ".invisible_places" / "cache" / "flow");
    return cacheDirectory;
}

std::filesystem::path BuildWaterFieldCachePath(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    const auto waterDirectory = projectPath.empty()
                                    ? std::filesystem::path{"Saved"} / "water"
                                    : projectPath.parent_path() / "water";
    return waterDirectory / (sourceSession.sourcePath.stem().string() + "-WaterFieldCache.bin");
}

std::string WaterSupportSignature(const PreviewLayerSession& sourceSession) {
    std::ostringstream signature;
    signature << sourceSession.sourcePath.generic_string()
              << "|points=" << sourceSession.totalPrimitives
              << "|normals=" << (sourceSession.hasNormals ? 1 : 0);
    if (sourceSession.bounds.valid) {
        signature << "|min="
                  << sourceSession.bounds.minimum.x << ","
                  << sourceSession.bounds.minimum.y << ","
                  << sourceSession.bounds.minimum.z
                  << "|max="
                  << sourceSession.bounds.maximum.x << ","
                  << sourceSession.bounds.maximum.y << ","
                  << sourceSession.bounds.maximum.z;
    }
    return signature.str();
}

float WaterSupportSamplingMultiplierForRole(std::string_view role) {
    if (role == "SAND" || role == "VEG") {
        return 2.0F;
    }
    return 1.0F;
}

std::vector<invisible_places::water::WaterSceneSupportLayer> BuildWaterSceneSupportLayers(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    std::vector<invisible_places::water::WaterSceneSupportLayer> layers;
    if (!IsSceneGroupedPointCloud(sourceSession)) {
        return layers;
    }
    for (const auto& session : runtimeState.sessions) {
        if (!IsVisibleLoadedWaterSupportSession(session) ||
            session.offlinePointCloud == nullptr ||
            !SessionsShareSceneFolder(session, sourceSession)) {
            continue;
        }
        layers.push_back({
            .cloud = session.offlinePointCloud.get(),
            .role = session.sceneRole,
            .pointSpacingMeters = EffectivePointSpacingMeters(session),
            .samplingMultiplier = WaterSupportSamplingMultiplierForRole(session.sceneRole),
        });
    }
    return layers;
}

std::string CombinedWaterSupportSignature(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    const WaterPathGenerationSettings& settings) {
    if (!IsSceneGroupedPointCloud(sourceSession)) {
        return WaterSupportSignature(sourceSession);
    }

    std::ostringstream signature;
    signature << "scene=" << sourceSession.sceneGroupName
              << "|builder=combined-v2"
              << "|voxel=" << settings.supportVoxelSize
              << "|samples=" << settings.supportSampleLimit;
    for (const auto& session : runtimeState.sessions) {
        if (!IsVisibleLoadedWaterSupportSession(session) ||
            session.offlinePointCloud == nullptr ||
            !SessionsShareSceneFolder(session, sourceSession)) {
            continue;
        }
        signature << "|layer=" << session.sceneRole
                  << "," << session.sourcePath.generic_string()
                  << ",spacing=" << EffectivePointSpacingMeters(session)
                  << ",multiplier=" << WaterSupportSamplingMultiplierForRole(session.sceneRole)
                  << ",points=" << session.offlinePointCloud->positions.size();
        if (session.bounds.valid) {
            signature << ",min="
                      << session.bounds.minimum.x << ","
                      << session.bounds.minimum.y << ","
                      << session.bounds.minimum.z
                      << ",max="
                      << session.bounds.maximum.x << ","
                      << session.bounds.maximum.y << ","
                      << session.bounds.maximum.z;
        }
    }
    return signature.str();
}

const invisible_places::io::LoadedPointCloud* EnsureWaterSupportCloud(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    const WaterPathGenerationSettings& settings) {
    if (runtimeState == nullptr || sourceSession.offlinePointCloud == nullptr) {
        return nullptr;
    }
    if (!IsSceneGroupedPointCloud(sourceSession)) {
        return sourceSession.offlinePointCloud.get();
    }

    const auto layers = BuildWaterSceneSupportLayers(*runtimeState, sourceSession);
    if (layers.empty()) {
        return sourceSession.offlinePointCloud.get();
    }
    const auto signature = CombinedWaterSupportSignature(*runtimeState, sourceSession, settings);
    if (runtimeState->water.combinedSupportCloud != nullptr &&
        runtimeState->water.combinedSupportSignature == signature) {
        return runtimeState->water.combinedSupportCloud.get();
    }

    auto combined = std::make_shared<invisible_places::io::LoadedPointCloud>(
        invisible_places::water::BuildCombinedWaterSupportCloud(layers, settings));
    if (combined->positions.empty()) {
        return sourceSession.offlinePointCloud.get();
    }
    runtimeState->water.combinedSupportCloud = std::move(combined);
    runtimeState->water.combinedSupportSignature = signature;
    return runtimeState->water.combinedSupportCloud.get();
}

std::vector<invisible_places::water::WaterSceneSupportLayer> BuildWaterSourcePickSupportLayers(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    auto layers = BuildWaterSceneSupportLayers(runtimeState, sourceSession);
    if (!layers.empty()) {
        return layers;
    }
    if (sourceSession.offlinePointCloud != nullptr) {
        layers.push_back({
            .cloud = sourceSession.offlinePointCloud.get(),
            .role = sourceSession.sceneRole,
            .pointSpacingMeters = EffectivePointSpacingMeters(sourceSession),
            .samplingMultiplier = 1.0F,
        });
    }
    return layers;
}

std::string WaterSeepageSurfaceGuideSupportKey(
    const PreviewLayerSession& sourceSession,
    std::span<const invisible_places::water::WaterSceneSupportLayer> supportLayers) {
    std::ostringstream key;
    key << "seepage-surface-guide-v1|scene="
        << (sourceSession.sceneGroupName.empty()
                ? NormalizePathKey(sourceSession.sourcePath)
                : sourceSession.sceneGroupName + "|" +
                      NormalizePathKey(sourceSession.sourcePath.parent_path()));
    auto targetRole = NormalizeSceneRoleName(sourceSession.sceneRole);
    if (targetRole == "VEGETATION") {
        targetRole = "VEG";
    }
    key << "|target_role=" << targetRole;
    for (const auto& layer : supportLayers) {
        key << "|role=" << layer.role
            << ",spacing=" << layer.pointSpacingMeters
            << ",cloud=" << static_cast<const void*>(layer.cloud);
        if (layer.cloud == nullptr) {
            continue;
        }
        key << ",points=" << layer.cloud->positions.size()
            << ",normals=" << (layer.cloud->hasNormals ? 1 : 0);
        if (layer.cloud->bounds.valid) {
            key << ",min="
                << layer.cloud->bounds.minimum.x << ","
                << layer.cloud->bounds.minimum.y << ","
                << layer.cloud->bounds.minimum.z
                << ",max="
                << layer.cloud->bounds.maximum.x << ","
                << layer.cloud->bounds.maximum.y << ","
                << layer.cloud->bounds.maximum.z;
        }
    }
    return key.str();
}

std::string NormalizeWaterSeepageRoleName(std::string_view role) {
    auto normalized = NormalizeSceneRoleName(role);
    if (normalized == "VEGETATION") {
        normalized = "VEG";
    }
    return normalized;
}

std::vector<WaterSeepageNode> WaterSeepageNodesForRole(
    std::span<const WaterSeepageNode> nodes,
    std::string_view targetRole) {
    const auto normalizedTarget = NormalizeWaterSeepageRoleName(targetRole);
    std::vector<WaterSeepageNode> result;
    result.reserve(nodes.size());
    for (const auto& node : nodes) {
        const bool targetsRole = std::any_of(
            node.targetSceneRoles.begin(),
            node.targetSceneRoles.end(),
            [&](const auto& role) {
                return NormalizeWaterSeepageRoleName(role) == normalizedTarget;
            });
        if (!targetsRole) {
            continue;
        }
        result.push_back(node);
        // Guide tracing is role-local. Adding or removing an unrelated target
        // role must not change this role's cached guide.
        result.back().targetSceneRoles = {std::string{targetRole}};
    }
    return result;
}

std::string WaterSeepageSurfaceGuideNodeFingerprint(
    const WaterSeepageNode& node,
    std::string_view targetRole) {
    std::ostringstream fingerprint;
    fingerprint << std::setprecision(std::numeric_limits<float>::max_digits10);
    fingerprint << "id=" << node.id
                << ",p=" << node.position.x << "," << node.position.y << "," << node.position.z
                << ",n=" << node.surfaceNormal.x << "," << node.surfaceNormal.y << "," << node.surfaceNormal.z
                << ",d=" << node.downAxis.x << "," << node.downAxis.y << "," << node.downAxis.z
                << ",selection_reach=" << node.selectionReachLimitMeters
                << ",selection_width=" << node.selectionWidthLimitMeters
                << ",depth=" << node.depthToleranceMeters
                << ",edge=" << node.edgeFeatherMeters
                << ",role=" << NormalizeWaterSeepageRoleName(targetRole);
    return fingerprint.str();
}

std::string WaterSeepageSurfaceGuideNodesFingerprint(
    std::span<const WaterSeepageNode> nodes,
    std::string_view targetRole) {
    std::ostringstream fingerprint;
    for (const auto& node : nodes) {
        fingerprint << '|'
                    << WaterSeepageSurfaceGuideNodeFingerprint(node, targetRole);
    }
    return fingerprint.str();
}

template <typename BuildGuides>
const std::vector<WaterSeepageSurfaceGuide>* UpdateWaterSeepageSurfaceGuidesPerNode(
    WaterWorkflowState* water,
    std::string_view supportKey,
    std::span<const WaterSeepageNode> nodes,
    std::string_view targetRole,
    BuildGuides&& buildGuides) {
    if (water == nullptr) {
        return nullptr;
    }
    auto& guides = water->seepageSurfaceGuides[std::string{supportKey}];
    auto& fingerprints =
        water->seepageSurfaceGuideNodeFingerprints[std::string{supportKey}];
    std::unordered_set<std::uint32_t> activeNodeIds;
    activeNodeIds.reserve(nodes.size());
    for (const auto& node : nodes) {
        activeNodeIds.insert(node.id);
    }
    std::erase_if(
        guides,
        [&](const WaterSeepageSurfaceGuide& guide) {
            return !activeNodeIds.contains(guide.nodeId);
        });
    std::erase_if(
        fingerprints,
        [&](const auto& entry) {
            return !activeNodeIds.contains(entry.first);
        });

    std::vector<WaterSeepageNode> changedNodes;
    changedNodes.reserve(nodes.size());
    for (const auto& node : nodes) {
        const auto fingerprint =
            WaterSeepageSurfaceGuideNodeFingerprint(node, targetRole);
        const auto existingGuide = std::find_if(
            guides.begin(),
            guides.end(),
            [&](const WaterSeepageSurfaceGuide& guide) {
                return guide.nodeId == node.id;
            });
        const auto existingFingerprint = fingerprints.find(node.id);
        if (existingGuide != guides.end() &&
            existingFingerprint != fingerprints.end() &&
            existingFingerprint->second == fingerprint) {
            continue;
        }
        changedNodes.push_back(node);
    }

    if (!changedNodes.empty()) {
        auto rebuilt = buildGuides(std::span<const WaterSeepageNode>{changedNodes});
        for (const auto& node : changedNodes) {
            WaterSeepageSurfaceGuide replacement;
            replacement.nodeId = node.id;
            if (const auto rebuiltGuide = std::find_if(
                    rebuilt.begin(),
                    rebuilt.end(),
                    [&](const WaterSeepageSurfaceGuide& candidate) {
                        return candidate.nodeId == node.id;
                    });
                rebuiltGuide != rebuilt.end()) {
                replacement = std::move(*rebuiltGuide);
            }
            if (const auto existingGuide = std::find_if(
                    guides.begin(),
                    guides.end(),
                    [&](const WaterSeepageSurfaceGuide& guide) {
                        return guide.nodeId == node.id;
                    });
                existingGuide == guides.end()) {
                guides.push_back(std::move(replacement));
            } else {
                *existingGuide = std::move(replacement);
            }
            fingerprints[node.id] =
                WaterSeepageSurfaceGuideNodeFingerprint(node, targetRole);
        }
        water->seepageSurfaceGuideBuildCount += changedNodes.size();
    }

    std::vector<WaterSeepageSurfaceGuide> ordered;
    ordered.reserve(guides.size());
    for (const auto& node : nodes) {
        const auto guide = std::find_if(
            guides.begin(),
            guides.end(),
            [&](const WaterSeepageSurfaceGuide& candidate) {
                return candidate.nodeId == node.id;
            });
        if (guide != guides.end()) {
            ordered.push_back(*guide);
        }
    }
    guides = std::move(ordered);
    water->seepageSurfaceGuideFingerprints[std::string{supportKey}] =
        WaterSeepageSurfaceGuideNodesFingerprint(nodes, targetRole);
    return &guides;
}

const std::vector<WaterSeepageSurfaceGuide>* EnsureWaterSeepageSurfaceGuidesForSession(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    std::string* resolvedSupportKey = nullptr) {
    if (runtimeState == nullptr || runtimeState->water.seepageNodes.empty() ||
        !IsAuthoredWaterTerrainSession(sourceSession)) {
        return nullptr;
    }
    const auto targetRole = NormalizeWaterSeepageRoleName(sourceSession.sceneRole);
    const auto roleNodes = WaterSeepageNodesForRole(
        runtimeState->water.seepageNodes,
        targetRole);

    // Prefer the shared orientation-independent 10 mm surface aggregate. It
    // is built once from the stable ROCK/SAND analysis layers and avoids ever
    // walking the visible high-density cloud to trace a Seepage guide.
    const auto& surfaceCache = runtimeState->water.waterSurfaceCache;
    const auto sourceFolderKey = NormalizePathKey(sourceSession.sourcePath.parent_path());
    const bool surfaceCacheMatchesSession =
        surfaceCache != nullptr &&
        !surfaceCache->flowSurfaceSurfels.empty() &&
        std::any_of(
            surfaceCache->sources.begin(),
            surfaceCache->sources.end(),
            [&](const auto& source) {
                return NormalizePathKey(source.sourcePath.parent_path()) == sourceFolderKey;
            });
    if (surfaceCacheMatchesSession) {
        const auto supportKey =
            "seepage-surface-cache-v3|scene=" + sourceSession.sceneGroupName +
            "|identity=" + WaterSeepageSurfaceCacheIdentityKey(
                                *runtimeState,
                                sourceSession,
                                FindScenePointCloudRuntime(*runtimeState, sourceSession)) +
            "|target_role=" + targetRole;
        if (resolvedSupportKey != nullptr) {
            *resolvedSupportKey = supportKey;
        }
        const auto* cachedGuides = UpdateWaterSeepageSurfaceGuidesPerNode(
            &runtimeState->water,
            supportKey,
            roleNodes,
            targetRole,
            [&](std::span<const WaterSeepageNode> changedNode) {
                return invisible_places::water::BuildWaterSeepageSurfaceGuides(
                    changedNode,
                    *surfaceCache);
            });
        runtimeState->water.seepageSurfaceGuideWarning.clear();
        return cachedGuides;
    }

    // A grouped scene starts warming the shared cache as soon as it is loaded.
    // Do not fall back to a multi-million-point scan while that compact cache
    // is still being prepared; the nodes become visible when warm-up commits.
    if (!sourceSession.sceneGroupName.empty() &&
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() &&
        runtimeState->water.waterSurfaceCacheWarmup.sceneGroupName == sourceSession.sceneGroupName) {
        runtimeState->water.seepageSurfaceGuideWarning =
            "Seepage support is waiting for the shared 10 mm surface cache.";
        return nullptr;
    }

    // Standalone/non-catalogue clouds retain the capped point-graph fallback.
    const auto supportLayers = BuildWaterSourcePickSupportLayers(*runtimeState, sourceSession);
    if (supportLayers.empty()) {
        return nullptr;
    }
    const auto supportKey = WaterSeepageSurfaceGuideSupportKey(sourceSession, supportLayers);
    if (resolvedSupportKey != nullptr) {
        *resolvedSupportKey = supportKey;
    }
    return UpdateWaterSeepageSurfaceGuidesPerNode(
        &runtimeState->water,
        supportKey,
        roleNodes,
        targetRole,
        [&](std::span<const WaterSeepageNode> changedNode) {
            return invisible_places::water::BuildWaterSeepageSurfaceGuides(
                changedNode,
                supportLayers,
                kWaterSeepageSurfaceGuideSampleLimit);
        });
}

const WaterSeepageSurfaceGuide* FindWaterSeepageSurfaceGuide(
    std::span<const WaterSeepageSurfaceGuide> guides,
    std::uint32_t nodeId) {
    const auto guide = std::find_if(
        guides.begin(),
        guides.end(),
        [nodeId](const WaterSeepageSurfaceGuide& candidate) {
            return candidate.nodeId == nodeId;
        });
    return guide == guides.end() ? nullptr : &*guide;
}

std::vector<WaterSeepageNode> WaterSeepageNodesWithValidSurfaceGuides(
    std::span<const WaterSeepageNode> nodes,
    std::span<const WaterSeepageSurfaceGuide> guides) {
    std::vector<WaterSeepageNode> filtered;
    filtered.reserve(nodes.size());
    for (const auto& node : nodes) {
        const auto* guide = FindWaterSeepageSurfaceGuide(guides, node.id);
        if (guide != nullptr && guide->valid && guide->sampleCount >= 2U) {
            filtered.push_back(node);
        }
    }
    return filtered;
}

std::uint64_t WaterSupportLayerPointCount(
    std::span<const invisible_places::water::WaterSceneSupportLayer> layers) {
    std::uint64_t count = 0;
    for (const auto& layer : layers) {
        if (layer.cloud != nullptr) {
            count += static_cast<std::uint64_t>(layer.cloud->positions.size());
        }
    }
    return count;
}

std::string WaterSupportLayerSummary(
    std::span<const invisible_places::water::WaterSceneSupportLayer> layers) {
    if (layers.empty()) {
        return "no role layers";
    }

    std::ostringstream summary;
    for (std::size_t index = 0; index < layers.size(); ++index) {
        if (index > 0U) {
            summary << ", ";
        }
        const auto& layer = layers[index];
        const auto pointCount = layer.cloud == nullptr ? 0ULL : static_cast<std::uint64_t>(layer.cloud->positions.size());
        summary << (layer.role.empty() ? "POINTS" : layer.role)
                << "=" << FormatPointCount(pointCount);
    }
    return summary.str();
}

std::shared_ptr<invisible_places::io::LoadedPointCloud> BuildFocusedWaterPathSupportCloud(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    const WaterPathGenerationSettings& settings,
    std::span<const WaterEmitter> emitters) {
    const auto layers = BuildWaterSceneSupportLayers(runtimeState, sourceSession);
    if (layers.empty()) {
        return nullptr;
    }

    std::vector<invisible_places::io::Float3> priorityPoints;
    priorityPoints.reserve(emitters.size());
    for (const auto& emitter : emitters) {
        if (emitter.status != WaterEmitterStatus::Disabled) {
            priorityPoints.push_back(emitter.position);
        }
    }
    if (settings.attractorEnabled && settings.attractorStrength > 1.0e-4F) {
        priorityPoints.push_back(settings.attractorPosition);
    }
    if (priorityPoints.empty()) {
        return nullptr;
    }

    auto focused = std::make_shared<invisible_places::io::LoadedPointCloud>(
        invisible_places::water::BuildCombinedWaterSupportCloud(
            layers,
            settings,
            priorityPoints));
    return focused->positions.empty() ? nullptr : focused;
}

std::optional<ResolvedPivot> ResolveWaterSourceSupportPivot(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    const auto supportIndex = ResolveWaterRuntimeSessionIndex(runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState.sessions.size()) {
        return std::nullopt;
    }
    const auto& sourceSession = runtimeState.sessions[supportIndex.value()];
    const auto layers = BuildWaterSourcePickSupportLayers(runtimeState, sourceSession);
    if (layers.empty()) {
        return std::nullopt;
    }

    std::uint64_t rawPointCount = 0;
    for (const auto& layer : layers) {
        if (layer.cloud != nullptr) {
            rawPointCount += static_cast<std::uint64_t>(layer.cloud->positions.size());
        }
    }
    if (rawPointCount == 0U) {
        return std::nullopt;
    }

    if (!IsInsideRenderViewport(viewport, screenPoint)) {
        screenPoint = CurrentUiViewportCenter(viewport);
    }
    const auto viewportSize = CurrentUiViewportSize(viewport);
    const float viewportHeight = std::max(1.0F, viewportSize.y);
    const auto matrices = runtimeState.camera.Matrices(CurrentAspectRatio(viewport));
    const auto screenRay = MakeScreenRay(matrices, viewport, screenPoint);
    if (!screenRay.has_value()) {
        return std::nullopt;
    }

    auto collectCandidates = [&](float pickRadiusPixels) {
        std::vector<PivotCandidate> candidates;
        candidates.reserve(1024);
        const float tanHalfFov = std::tan(runtimeState.camera.FovDegrees() * kPi / 360.0F);
        const std::uint64_t pickBudget = std::min(rawPointCount, kWaterSourcePickSampleLimit);
        const std::uint64_t layerCount = std::max<std::uint64_t>(1U, layers.size());
        const std::uint64_t layerFloor = std::min<std::uint64_t>(
            128000ULL,
            std::max<std::uint64_t>(1ULL, pickBudget / std::max<std::uint64_t>(1ULL, layerCount * 4ULL)));

        for (const auto& layer : layers) {
            if (layer.cloud == nullptr || layer.cloud->positions.empty()) {
                continue;
            }
            const auto& cloud = *layer.cloud;
            const auto cloudPointCount = static_cast<std::uint64_t>(cloud.positions.size());
            std::uint64_t layerTarget = static_cast<std::uint64_t>(
                std::ceil(
                    (static_cast<double>(cloudPointCount) / static_cast<double>(rawPointCount)) *
                    static_cast<double>(pickBudget)));
            layerTarget = std::max<std::uint64_t>(
                layerTarget,
                std::min<std::uint64_t>(cloudPointCount, layerFloor));
            layerTarget = std::clamp<std::uint64_t>(layerTarget, 1ULL, cloudPointCount);
            const auto stride = static_cast<std::size_t>(
                std::max<std::uint64_t>(1ULL, (cloudPointCount + layerTarget - 1ULL) / layerTarget));

            for (std::size_t pointIndex = 0; pointIndex < cloud.positions.size(); pointIndex += stride) {
                const auto& sample = cloud.positions[pointIndex];
                const glm::vec3 worldPoint{sample.x, sample.y, sample.z};
                const auto projected = ProjectWorldPoint(matrices, viewport, worldPoint);
                if (!projected.has_value()) {
                    continue;
                }

                const glm::vec3 pointFromRayOrigin = worldPoint - screenRay->origin;
                const float alongRay = glm::dot(pointFromRayOrigin, screenRay->direction);
                if (alongRay <= runtimeState.camera.NearPlane()) {
                    continue;
                }

                const float dx = projected->screen.x - screenPoint.x;
                const float dy = projected->screen.y - screenPoint.y;
                const float screenDistance = std::sqrt((dx * dx) + (dy * dy));
                if (screenDistance > pickRadiusPixels) {
                    continue;
                }

                const glm::vec3 closestPointOnRay = screenRay->origin + (screenRay->direction * alongRay);
                const float rayDistance = glm::length(worldPoint - closestPointOnRay);
                const float worldUnitsPerPixel =
                    (2.0F * std::max(0.001F, alongRay) * tanHalfFov) / viewportHeight;
                const float pickRadiusWorld = std::max(0.0001F, worldUnitsPerPixel * pickRadiusPixels);
                if (rayDistance > pickRadiusWorld) {
                    continue;
                }

                glm::vec3 pointNormal{0.0F, 0.0F, 0.0F};
                if (cloud.hasNormals && pointIndex < cloud.normals.size()) {
                    const auto& sourceNormal = cloud.normals[pointIndex];
                    pointNormal = {sourceNormal.x, sourceNormal.y, sourceNormal.z};
                    if (PivotNormalValid(pointNormal)) {
                        pointNormal = glm::normalize(pointNormal);
                    }
                }
                candidates.push_back(
                    {.point = worldPoint,
                     .normal = pointNormal,
                     .sceneRole = layer.role,
                     .rayDistance = rayDistance,
                     .alongRay = alongRay,
                     .depth = projected->depth,
                     .screenDistance = screenDistance,
                     .pickRadiusWorld = pickRadiusWorld,
                     .confidence = std::clamp(
                         1.0F - std::max(
                                    screenDistance / pickRadiusPixels,
                                    rayDistance / pickRadiusWorld),
                         0.0F,
                         1.0F)});
            }
        }
        return candidates;
    };

    auto candidates = collectCandidates(kWaterSourcePickRadiusPixels);
    if (candidates.empty()) {
        candidates = collectCandidates(kWaterSourceFallbackPickRadiusPixels);
    }
    if (candidates.empty()) {
        return std::nullopt;
    }

    auto cluster = SelectPivotDepthCluster(candidates);
    const auto* best = BestPrecisePivotCandidate(cluster);
    if (best == nullptr) {
        return std::nullopt;
    }

    const PivotCandidate* normalSource = best;
    if (SceneRoleIs(best->sceneRole, "VEG")) {
        const float rockSearchRadius = std::max(0.15F, best->pickRadiusWorld * 2.0F);
        const auto rockCandidate = std::min_element(
            candidates.begin(),
            candidates.end(),
            [&](const PivotCandidate& left, const PivotCandidate& right) {
                const auto score = [&](const PivotCandidate& candidate) {
                    if (!SceneRoleIs(candidate.sceneRole, "ROCK") ||
                        !PivotNormalValid(candidate.normal)) {
                        return std::numeric_limits<float>::max();
                    }
                    const float distance = glm::length(candidate.point - best->point);
                    return distance <= rockSearchRadius ? distance : std::numeric_limits<float>::max();
                };
                return score(left) < score(right);
            });
        if (rockCandidate != candidates.end() &&
            SceneRoleIs(rockCandidate->sceneRole, "ROCK") &&
            PivotNormalValid(rockCandidate->normal) &&
            glm::length(rockCandidate->point - best->point) <= rockSearchRadius) {
            normalSource = &*rockCandidate;
        }
    }
    const glm::vec3 resolvedNormal = ResolvePivotClusterNormal(cluster, normalSource);
    return ResolvedPivot{
        .point = FromGlm(best->point),
        .normal = FromGlm(resolvedNormal),
        .sceneRole = best->sceneRole,
        .confidence = best->confidence * (PivotNormalValid(resolvedNormal) ? 1.0F : 0.65F),
        .matchedSurface = true,
        .sampleCount = cluster.size()};
}

std::optional<ResolvedPivot> ResolveWaterSourcePlacementPivot(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (const auto supportPivot = ResolveWaterSourceSupportPivot(runtimeState, viewport, screenPoint);
        supportPivot.has_value()) {
        return supportPivot;
    }
    const bool restrictToSelectedScene =
        runtimeState.selectedSessionIndex.has_value() &&
        runtimeState.selectedSessionIndex.value() < runtimeState.sessions.size() &&
        IsSceneGroupedPointCloud(runtimeState.sessions[runtimeState.selectedSessionIndex.value()]);
    return ResolveSurfacePivot(
        runtimeState,
        viewport,
        screenPoint,
        restrictToSelectedScene);
}

const TrailSurfaceIndex* EnsureTrailSurfaceIndexForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    WaterTrailBuildDiagnostics* diagnostics) {
    if (runtimeState == nullptr || sourceSession.offlinePointCloud == nullptr) {
        return nullptr;
    }

    const auto supportSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water).path;
    const auto* supportCloud = EnsureWaterSupportCloud(runtimeState, sourceSession, supportSettings);
    if (supportCloud == nullptr) {
        return nullptr;
    }
    const auto signature = CombinedWaterSupportSignature(*runtimeState, sourceSession, supportSettings);
    if (runtimeState->water.trailSurfaceIndex != nullptr &&
        runtimeState->water.trailSurfaceIndexSupportSignature == signature &&
        NormalizePathKey(runtimeState->water.trailSurfaceIndexSupportPath) ==
            NormalizePathKey(sourceSession.sourcePath)) {
        if (diagnostics != nullptr) {
            diagnostics->surfaceSampleCount = invisible_places::water::TrailSurfaceIndexSampleCount(
                *runtimeState->water.trailSurfaceIndex);
        }
        return runtimeState->water.trailSurfaceIndex.get();
    }

    runtimeState->water.trailSurfaceIndex =
        invisible_places::water::BuildTrailSurfaceIndex(supportCloud);
    runtimeState->water.trailSurfaceIndexSupportSignature = signature;
    runtimeState->water.trailSurfaceIndexSupportPath = sourceSession.sourcePath;
    if (diagnostics != nullptr && runtimeState->water.trailSurfaceIndex != nullptr) {
        diagnostics->surfaceIndexBuildMs = invisible_places::water::TrailSurfaceIndexBuildMilliseconds(
            *runtimeState->water.trailSurfaceIndex);
        diagnostics->surfaceSampleCount = invisible_places::water::TrailSurfaceIndexSampleCount(
            *runtimeState->water.trailSurfaceIndex);
    }
    return runtimeState->water.trailSurfaceIndex == nullptr ? nullptr : runtimeState->water.trailSurfaceIndex.get();
}

void AppendWaterPathBakeSettingsFingerprint(
    std::ostringstream* stream,
    const WaterPathGenerationSettings& settings) {
    if (stream == nullptr) {
        return;
    }
    (*stream) << "|auto=" << (settings.autoTune ? 1 : 0)
              << "|voxel=" << settings.supportVoxelSize
              << "|bridge=" << settings.maxBridgeDistance
              << "|length=" << settings.pathLength
              << "|sample=" << settings.pathSampleSpacing
              << "|branch=" << settings.branching
              << "|coverage=" << settings.coverage
              << "|gap=" << settings.gapTolerance
              << "|attractor=" << (settings.attractorEnabled ? 1 : 0)
              << "," << settings.attractorPosition.x
              << "," << settings.attractorPosition.y
              << "," << settings.attractorPosition.z
              << "," << settings.attractorStrength
              << "|steps=" << settings.maxSteps
              << "|samples=" << settings.supportSampleLimit;
}

std::string WaterEmitterBakeFingerprint(
    const WaterWorkflowState& water,
    const WaterEmitter& emitter) {
    std::ostringstream fingerprint;
    fingerprint << "emitter=" << emitter.id
                << "," << static_cast<int>(emitter.status)
                << "," << emitter.position.x
                << "," << emitter.position.y
                << "," << emitter.position.z
                << "," << emitter.radius
                << "," << emitter.strength
                << "," << emitter.speed
                << "," << NormalizeWaterProfileName(emitter.pathProfileName, kWaterProfileGlobalName);
    AppendWaterPathBakeSettingsFingerprint(
        &fingerprint,
        ResolveEmitterWaterPathSettings(water, emitter));
    return fingerprint.str();
}

std::unordered_map<std::uint32_t, std::string> WaterEmitterBakeFingerprints(
    const WaterWorkflowState& water,
    std::span<const WaterEmitter> emitters) {
    std::unordered_map<std::uint32_t, std::string> fingerprints;
    fingerprints.reserve(emitters.size());
    for (const auto& emitter : emitters) {
        if (emitter.status == WaterEmitterStatus::Disabled) {
            continue;
        }
        fingerprints.emplace(emitter.id, WaterEmitterBakeFingerprint(water, emitter));
    }
    return fingerprints;
}

bool CachedWaterEmitterBranchesReusable(
    const WaterPathCache& cache,
    std::uint32_t emitterId,
    const std::string& bakeFingerprint) {
    bool foundBranch = false;
    for (const auto& branch : cache.branches) {
        if (branch.emitterId != emitterId) {
            continue;
        }
        foundBranch = true;
        if (branch.bakeFingerprint.empty() || branch.bakeFingerprint != bakeFingerprint) {
            return false;
        }
    }
    return foundBranch;
}

std::uint32_t MaxWaterPathBranchId(std::span<const WaterPathBranch> branches) {
    std::uint32_t maxBranchId = 0U;
    for (const auto& branch : branches) {
        maxBranchId = std::max(maxBranchId, branch.id);
    }
    return maxBranchId;
}

void RemapWaterPathBranchIds(
    WaterPathCache* cache,
    std::uint32_t nextBranchId) {
    if (cache == nullptr) {
        return;
    }

    std::unordered_map<std::uint32_t, std::uint32_t> remappedIds;
    remappedIds.reserve(cache->branches.size());
    for (const auto& branch : cache->branches) {
        remappedIds[branch.id] = nextBranchId++;
    }
    for (auto& branch : cache->branches) {
        const auto originalId = branch.id;
        branch.id = remappedIds[originalId];
        if (branch.parentId.has_value()) {
            const auto parentIt = remappedIds.find(branch.parentId.value());
            if (parentIt != remappedIds.end()) {
                branch.parentId = parentIt->second;
            } else {
                branch.parentId.reset();
            }
        }
        for (auto& point : branch.rawAnchors) {
            point.flowId = static_cast<float>(branch.id);
        }
    }
}

void StampWaterPathBranchFingerprints(
    WaterPathCache* cache,
    const std::unordered_map<std::uint32_t, std::string>& bakeFingerprints) {
    if (cache == nullptr) {
        return;
    }
    for (auto& branch : cache->branches) {
        const auto fingerprintIt = bakeFingerprints.find(branch.emitterId);
        if (fingerprintIt != bakeFingerprints.end()) {
            branch.bakeFingerprint = fingerprintIt->second;
        }
    }
}

void RefreshWaterPathCacheDiagnostics(
    WaterPathCache* cache,
    std::string summary) {
    if (cache == nullptr) {
        return;
    }

    float confidenceSum = 0.0F;
    std::uint32_t lowConfidenceBranchCount = 0U;
    for (const auto& branch : cache->branches) {
        confidenceSum += branch.confidence;
        if (branch.confidence < 0.45F || branch.gapCount >= 2U) {
            ++lowConfidenceBranchCount;
        }
    }

    cache->diagnostics.branchCount = static_cast<std::uint32_t>(cache->branches.size());
    cache->diagnostics.lowConfidenceBranchCount = lowConfidenceBranchCount;
    cache->diagnostics.averageConfidence =
        cache->branches.empty()
            ? 0.0F
            : std::clamp(confidenceSum / static_cast<float>(cache->branches.size()), 0.0F, 1.0F);
    cache->diagnostics.summary = std::move(summary);
}

std::string WaterEmitterSettingsFingerprint(const PreviewRuntimeState& runtimeState) {
    std::ostringstream fingerprint;
    const auto defaultSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState.water);
    fingerprint << "default"
                << "|path_profile=" << NormalizeWaterProfileName(runtimeState.water.selectedPathProfileName)
                << "|path_edited=" << (runtimeState.water.editedPathProfileSettings.has_value() ? 1 : 0);
    AppendWaterPathBakeSettingsFingerprint(&fingerprint, defaultSettings.path);
    for (const auto& emitter : runtimeState.water.emitters) {
        fingerprint << "|" << WaterEmitterBakeFingerprint(runtimeState.water, emitter);
    }
    return fingerprint.str();
}

bool WaterPathCacheMatchesSupportAndSettings(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    const WaterPathCache& cache) {
    const auto supportPathMatches = [&]() {
        if (NormalizePathKey(cache.supportLayerPath) == NormalizePathKey(sourceSession.sourcePath)) {
            return true;
        }
        if (!IsSceneGroupedPointCloud(sourceSession)) {
            return false;
        }
        const auto cacheSessionIndex = FindSessionIndexBySourcePath(runtimeState, cache.supportLayerPath);
        if (!cacheSessionIndex.has_value() || cacheSessionIndex.value() >= runtimeState.sessions.size()) {
            return false;
        }
        const auto& cacheSession = runtimeState.sessions[cacheSessionIndex.value()];
        return SessionsShareSceneFolder(cacheSession, sourceSession) &&
               cacheSession.analysisSource;
    };
    const auto defaultSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState.water);
    return supportPathMatches() &&
           cache.supportSignature == CombinedWaterSupportSignature(runtimeState, sourceSession, defaultSettings.path) &&
           cache.emitterSettingsFingerprint == WaterEmitterSettingsFingerprint(runtimeState);
}

bool WaterPathCacheMatchesSupport(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    const WaterPathCache& cache,
    const WaterPathGenerationSettings& supportSettings) {
    const auto supportPathMatches = [&]() {
        if (NormalizePathKey(cache.supportLayerPath) == NormalizePathKey(sourceSession.sourcePath)) {
            return true;
        }
        if (!IsSceneGroupedPointCloud(sourceSession)) {
            return false;
        }
        const auto cacheSessionIndex = FindSessionIndexBySourcePath(runtimeState, cache.supportLayerPath);
        if (!cacheSessionIndex.has_value() || cacheSessionIndex.value() >= runtimeState.sessions.size()) {
            return false;
        }
        const auto& cacheSession = runtimeState.sessions[cacheSessionIndex.value()];
        return SessionsShareSceneFolder(cacheSession, sourceSession) &&
               cacheSession.analysisSource;
    };
    return supportPathMatches() &&
           cache.supportSignature == CombinedWaterSupportSignature(runtimeState, sourceSession, supportSettings);
}

bool SaveWaterPathCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession) {
    if (runtimeState == nullptr || runtimeState->water.pathCache.branches.empty()) {
        return false;
    }
    auto& cache = runtimeState->water.pathCache;
    cache.supportLayerPath = sourceSession.sourcePath;
    cache.supportSignature =
        CombinedWaterSupportSignature(
            *runtimeState,
            sourceSession,
            ActiveProfileDefaultWaterSourceSettings(runtimeState->water).path);
    cache.emitterSettingsFingerprint = WaterEmitterSettingsFingerprint(*runtimeState);
    cache.stale = runtimeState->water.pathCacheStale;
    runtimeState->water.pathCacheLoaded = true;
    return true;
}

bool PersistSettledWaterPathCache(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    std::string* errorMessage) {
    if (runtimeState == nullptr || runtimeState->water.pathCacheStale ||
        runtimeState->water.pathCache.stale ||
        runtimeState->water.pathCache.branches.empty()) {
        if (errorMessage != nullptr) {
            *errorMessage = "Only a clean settled Flow path cache can be persisted.";
        }
        return false;
    }

    const auto outputDirectory = BuildWaterPathCacheDirectory(*runtimeState, sourceSession);
    invisible_places::serialization::WaterPathCacheManifestDocument manifest;
    std::filesystem::path outputPath;
    if (invisible_places::serialization::SaveContentAddressedWaterPathCacheDocument(
            runtimeState->water.pathCache,
            outputDirectory,
            errorMessage,
            &manifest,
            &outputPath)) {
        return true;
    }

    const std::filesystem::path projectPath{runtimeState->persistence.projectFilePath};
    if (projectPath.empty()) {
        return false;
    }
    const auto fallbackDirectory = projectPath.parent_path() /
                                   ".invisible_places" / "cache" / "flow";
    if (NormalizePathKey(fallbackDirectory) == NormalizePathKey(outputDirectory)) {
        return false;
    }
    if (errorMessage != nullptr) {
        errorMessage->clear();
    }
    return invisible_places::serialization::SaveContentAddressedWaterPathCacheDocument(
        runtimeState->water.pathCache,
        fallbackDirectory,
        errorMessage,
        &manifest,
        &outputPath);
}

enum class WaterFlowGpuPreviewDispatchResult {
    Unavailable,
    Deferred,
    Dispatched,
};

WaterFlowGpuPreviewDispatchResult TryDispatchPendingWaterFlowGpuPreview(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return WaterFlowGpuPreviewDispatchResult::Unavailable;
    }
    auto& job = runtimeState->water.flowTrailBuildJob;
    if (!job.pendingCapture || job.worker.joinable() ||
        std::chrono::steady_clock::now() < job.pendingNotBefore) {
        return WaterFlowGpuPreviewDispatchResult::Deferred;
    }

    auto request = CaptureWaterFlowTrailBuildRequest(
        *runtimeState,
        job.pendingRequestId,
        job.pendingSavePathCache,
        false,
        job.pendingFullSourceRefresh,
        &job.pendingDirtySourceIds);
    const bool needsSurfaceGuide = std::any_of(
            request.sources.begin(),
            request.sources.end(),
            [](const WaterFlowTrailSourceBuildRequest& source) {
                return source.useSurfaceGuide;
            });
    const auto surfaceView = viewport->WaterSurfaceFlowView();
    const bool surfaceCacheExpected =
        runtimeState->water.waterSurfaceCache != nullptr ||
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable();
    const bool expectedSurfaceResident =
        runtimeState->water.waterSurfaceCache == nullptr ||
        (surfaceView.cacheIdentity != nullptr &&
         *surfaceView.cacheIdentity ==
             runtimeState->water.waterSurfaceCache->cacheIdentity);
    if (needsSurfaceGuide && surfaceCacheExpected &&
        (viewport->WaterSurfaceUploadPending() ||
         !surfaceView.valid || !surfaceView.preprocessingComplete ||
         !expectedSurfaceResident)) {
        job.pendingNotBefore =
            std::chrono::steady_clock::now() + std::chrono::milliseconds{33};
        return WaterFlowGpuPreviewDispatchResult::Deferred;
    }

    const auto supportIndex = ResolveWaterRuntimeSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        return WaterFlowGpuPreviewDispatchResult::Unavailable;
    }
    PreviewLayerSession supportSession;
    supportSession.sourcePath = runtimeState->sessions[supportIndex.value()].sourcePath;

    std::unordered_set<std::string> activePaths;
    activePaths.reserve(request.sources.size());
    // A source falls back only when its compact branch table/output layout is
    // invalid or exceeds capacity. A matching immutable CPU artifact and
    // settled session let that exceptional source coexist with GPU sources.
    for (const auto& source : request.sources) {
        const auto outputPath = BuildWaterTrailOverlayPath(
            *runtimeState,
            supportSession,
            source.sourceId,
            source.trailProfile.name);
        activePaths.insert(outputPath.lexically_normal().generic_string());
        if (source.gpuPreviewEligible) {
            continue;
        }
        auto existingIndex = FindLoadedWaterFlowSourceSessionIndex(
            *runtimeState,
            source.sourceId);
        if (!existingIndex.has_value()) {
            existingIndex = FindSessionIndexBySourcePath(*runtimeState, outputPath);
        }
        const bool hasSettledCpuSession =
            existingIndex.has_value() &&
            existingIndex.value() < runtimeState->sessions.size() &&
            runtimeState->sessions[existingIndex.value()].loaded &&
            !runtimeState->sessions[existingIndex.value()].waterFlowGpuPreview;
        if (source.cachedOverlay == nullptr || !hasSettledCpuSession) {
            return WaterFlowGpuPreviewDispatchResult::Unavailable;
        }
    }

    std::size_t activePointCount = 0U;
    std::uint32_t dispatchCount = 0U;
    std::uint64_t bytesTransferred = 0U;
    for (const auto& source : request.sources) {
        const auto existingSourceIndex = FindLoadedWaterFlowSourceSessionIndex(
            *runtimeState,
            source.sourceId);
        if (!source.gpuRefreshRequired && existingSourceIndex.has_value()) {
            activePointCount +=
                runtimeState->sessions[existingSourceIndex.value()].totalPrimitives;
            continue;
        }
        if (!source.gpuPreviewEligible) {
            const auto outputPath = BuildWaterTrailOverlayPath(
                *runtimeState,
                supportSession,
                source.sourceId,
                source.trailProfile.name);
            if (const auto existingIndex = FindSessionIndexBySourcePath(*runtimeState, outputPath);
                existingIndex.has_value() &&
                existingIndex.value() < runtimeState->sessions.size()) {
                activePointCount += runtimeState->sessions[existingIndex.value()].totalPrimitives;
            }
            continue;
        }
        const auto outputPath = BuildWaterTrailOverlayPath(
            *runtimeState,
            supportSession,
            source.sourceId,
            source.trailProfile.name);
        const auto previousSessionIndex = FindSessionIndexBySourcePath(*runtimeState, outputPath);
        const auto previousGpuDiagnostics =
            previousSessionIndex.has_value() &&
                    previousSessionIndex.value() < runtimeState->sessions.size() &&
                    runtimeState->sessions[previousSessionIndex.value()].waterFlowGpuPreview
                ? viewport->WaterFlowGpuSourceState(previousSessionIndex.value())
                : invisible_places::renderer::core::WaterFlowGpuSourceDiagnostics{};
        invisible_places::renderer::core::WaterFlowGpuSourceUploadResult upload;
        std::size_t sessionIndex = std::numeric_limits<std::size_t>::max();
        const auto sourceRevision = job.nextGpuSourceRevision++;
        if (!AddOrRefreshWaterFlowGpuSourceSession(
                runtimeState,
                viewport,
                supportSession,
                source,
                sourceRevision,
                &upload,
                &sessionIndex)) {
            if (upload.diagnostics.pending) {
                job.pendingNotBefore =
                    std::chrono::steady_clock::now() + std::chrono::milliseconds{33};
                return WaterFlowGpuPreviewDispatchResult::Deferred;
            }
            return WaterFlowGpuPreviewDispatchResult::Unavailable;
        }
        activePointCount += upload.layout.pointCount > 0U
                                ? upload.layout.pointCount
                                : (sessionIndex < runtimeState->sessions.size()
                                       ? runtimeState->sessions[sessionIndex].totalPrimitives
                                       : 0U);
        const auto sourceDispatchCount =
            upload.diagnostics.computeDispatchCount >= previousGpuDiagnostics.computeDispatchCount
                ? upload.diagnostics.computeDispatchCount - previousGpuDiagnostics.computeDispatchCount
                : upload.diagnostics.computeDispatchCount;
        dispatchCount += sourceDispatchCount;
        runtimeState->water.flowGpuComputeDispatchCount += sourceDispatchCount;
        runtimeState->water.flowGpuComputeDispatchCountBySource[source.sourceId] +=
            sourceDispatchCount;
        bytesTransferred +=
            upload.diagnostics.bytesTransferred >= previousGpuDiagnostics.bytesTransferred
                ? upload.diagnostics.bytesTransferred - previousGpuDiagnostics.bytesTransferred
                : upload.diagnostics.bytesTransferred;
    }

    const std::unordered_set<std::uint32_t> activeSourceIds{
        request.activeSourceIds.begin(),
        request.activeSourceIds.end()};
    for (std::size_t index = 0U; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!session.loaded || !IsGeneratedWaterFlowOverlaySession(session) ||
            !IsGeneratedWaterFlowTrailOverlayStem(session.sourcePath.stem().string()) ||
            (session.waterFlowSourceId.has_value()
                 ? activeSourceIds.contains(session.waterFlowSourceId.value())
                 : activePaths.contains(session.sourcePath.lexically_normal().generic_string()))) {
            continue;
        }
        if (session.waterFlowGpuPreview) {
            viewport->RemoveWaterFlowGpuSource(index);
            session.loaded = false;
            session.gpuResident = false;
            session.visible = false;
            session.cpuResident = false;
            session.pivotSamples.clear();
            session.offlinePointCloud.reset();
            ClearPreviewLodSampleCache(&session);
        } else {
            UnloadLayerByIndex(runtimeState, viewport, index);
        }
    }

    if (request.savePathCache && runtimeState->water.pathCacheLoaded) {
        SaveWaterPathCacheForSupport(
            runtimeState,
            runtimeState->sessions[supportIndex.value()]);
    }
    job.pendingCapture = false;
    job.pendingSavePathCache = false;
    job.pendingCpuSnapshotOnly = false;
    job.pendingFullSourceRefresh = false;
    job.pendingDirtySourceIds.clear();
    job.pendingRequestId = request.requestId;
    job.pendingNotBefore = {};
    job.activeRequestId = request.requestId;
    job.lastSourceCount = request.sources.size();
    job.lastRebuiltSourceCount = dispatchCount;
    job.lastReusedSourceCount = request.sources.size() - dispatchCount;
    job.lastSampleCount = activePointCount;
    job.lastBuildMs = 0.0;
    job.lastPackMs = 0.0;
    job.lastUploadMs = 0.0;
    job.lastGpuDispatchCount = dispatchCount;
    job.lastGpuBytesTransferred = bytesTransferred;
    ++runtimeState->water.pathDiagnosticRebuildCounters.laneBuilds;
    ++runtimeState->water.pathDiagnosticRebuildCounters.trailBuilds;
    StoreLiveWaterFlowTrailOverlay(runtimeState, {});
    runtimeState->statusMessage = request.sources.empty()
                                      ? "Flow trails hidden; no visible route branches remain."
                                      : "Flow source updates dispatched on the GPU (" +
                                            std::to_string(dispatchCount) + " changed, " +
                                            std::to_string(request.sources.size() - dispatchCount) +
                                            " reused).";
    runtimeState->errorMessage.clear();
    return WaterFlowGpuPreviewDispatchResult::Dispatched;
}

void PollWaterFlowTrailBuildJob(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    auto& job = runtimeState->water.flowTrailBuildJob;
    std::optional<WaterFlowTrailBuildJobResult> completedResult;
    if (job.shared != nullptr) {
        std::lock_guard lock{job.shared->mutex};
        if (job.shared->completed) {
            completedResult = std::move(job.shared->result);
        }
    }

    if (completedResult.has_value()) {
        job.worker = std::jthread{};
        job.shared.reset();
        auto result = std::move(completedResult.value());
        const auto latestRequestId = job.nextRequestId > 1U ? job.nextRequestId - 1U : 0U;
        if (result.gpuSnapshotOnly && !result.cancelled &&
            result.requestId == latestRequestId && result.errorMessage.empty()) {
            const std::unordered_set<std::uint32_t> activeSourceIds{
                result.activeSourceIds.begin(),
                result.activeSourceIds.end()};
            std::erase_if(
                runtimeState->water.flowTrailSourceArtifacts,
                [&](const auto& entry) { return !activeSourceIds.contains(entry.first); });
            for (auto& artifact : result.rebuiltArtifacts) {
                runtimeState->water.flowTrailSourceArtifacts.insert_or_assign(
                    artifact.sourceId,
                    std::move(artifact));
            }
            for (auto& group : result.groups) {
                if (!group.packedCloud.has_value()) {
                    continue;
                }
                const auto sessionIt = std::find_if(
                    runtimeState->sessions.begin(),
                    runtimeState->sessions.end(),
                    [&](const PreviewLayerSession& session) {
                        return session.loaded && session.waterFlowGpuPreview &&
                               session.waterFlowSourceId.has_value() &&
                               session.waterFlowSourceId.value() == group.sourceId;
                    });
                if (sessionIt == runtimeState->sessions.end()) {
                    continue;
                }
                auto snapshot = std::make_shared<invisible_places::io::LoadedPointCloud>(
                    std::move(group.packedCloud.value()));
                snapshot->sourcePath = sessionIt->sourcePath;
                snapshot->layerName = sessionIt->displayName;
                sessionIt->offlinePointCloud = std::move(snapshot);
                sessionIt->cpuResident = true;
                sessionIt->waterFlowCpuSnapshotRevision =
                    sessionIt->waterFlowGpuRevision;
            }
            job.lastSourceCount = result.sourceCount;
            job.lastRebuiltSourceCount = result.rebuiltSourceCount;
            job.lastReusedSourceCount = result.reusedSourceCount;
            job.lastBuildMs = result.buildMs;
            job.lastPackMs = result.packMs;
            runtimeState->statusMessage =
                "GPU Flow ready; settled CPU export snapshot cached.";
            runtimeState->errorMessage.clear();
        } else if (!result.cancelled &&
            result.requestId == latestRequestId &&
            result.errorMessage.empty()) {
            const auto supportIndex = ResolveWaterRuntimeSessionIndex(*runtimeState);
            if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
                runtimeState->errorMessage = "Flow trail update finished after its support scene was unloaded.";
                runtimeState->statusMessage.clear();
            } else {
                const std::unordered_set<std::uint32_t> activeSourceIds{
                    result.activeSourceIds.begin(),
                    result.activeSourceIds.end()};
                std::erase_if(
                    runtimeState->water.flowTrailSourceArtifacts,
                    [&](const auto& entry) { return !activeSourceIds.contains(entry.first); });
                for (auto& artifact : result.rebuiltArtifacts) {
                    runtimeState->water.flowTrailSourceArtifacts.insert_or_assign(
                        artifact.sourceId,
                        std::move(artifact));
                }
                const auto uploadStartedAt = std::chrono::steady_clock::now();
                if (result.savePathCache && runtimeState->water.pathCacheLoaded) {
                    SaveWaterPathCacheForSupport(
                        runtimeState,
                        runtimeState->sessions[supportIndex.value()]);
                }
                if (result.groups.empty() || result.sampleCount == 0U) {
                    UnloadGeneratedWaterFlowOverlaySessions(runtimeState, viewport);
                    StoreLiveWaterFlowTrailOverlay(runtimeState, {});
                    runtimeState->statusMessage = "Flow trails hidden; no visible route branches remain.";
                    runtimeState->errorMessage.clear();
                } else {
                    InstallWaterFlowTrailOverlayGroups(
                        runtimeState,
                        viewport,
                        runtimeState->sessions[supportIndex.value()],
                        std::move(result.groups));
                    runtimeState->water.lastInstalledLaneSettings =
                        ViewedGlobalWaterLaneSettings(runtimeState->water);
                    runtimeState->statusMessage =
                        "Flow trails updated in the background with " +
                        FormatPointCount(result.sampleCount) + " surfels.";
                    runtimeState->errorMessage.clear();
                }
                runtimeState->water.flowBranchMaskedSessionIndices.clear();
                job.lastUploadMs = std::chrono::duration<double, std::milli>(
                                       std::chrono::steady_clock::now() - uploadStartedAt)
                                       .count();
                job.lastSourceCount = result.sourceCount;
                job.lastRebuiltSourceCount = result.rebuiltSourceCount;
                job.lastReusedSourceCount = result.reusedSourceCount;
                job.lastSampleCount = result.sampleCount;
                job.lastBuildMs = result.buildMs;
                job.lastPackMs = result.packMs;
            }
        } else if (!result.cancelled &&
                   result.requestId == latestRequestId &&
                   !result.errorMessage.empty()) {
            runtimeState->errorMessage = "Flow trail background update failed: " + result.errorMessage;
            runtimeState->statusMessage.clear();
        }
    }

    if (job.pendingCpuSnapshotOnly) {
        StartPendingWaterFlowTrailBuild(runtimeState);
    } else {
        const auto gpuDispatch = TryDispatchPendingWaterFlowGpuPreview(runtimeState, viewport);
        if (gpuDispatch == WaterFlowGpuPreviewDispatchResult::Unavailable) {
            StartPendingWaterFlowTrailBuild(runtimeState);
        }
    }
}

bool ApplyWaterPathCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    WaterPathCache cache) {
    if (runtimeState == nullptr || cache.branches.empty()) {
        return false;
    }

    const bool matchesSupportAndSettings = WaterPathCacheMatchesSupportAndSettings(
        *runtimeState,
        sourceSession,
        cache);
    if (matchesSupportAndSettings) {
        cache.supportLayerPath = sourceSession.sourcePath;
        cache.supportSignature = CombinedWaterSupportSignature(
            *runtimeState,
            sourceSession,
            ActiveProfileDefaultWaterSourceSettings(runtimeState->water).path);
        cache.emitterSettingsFingerprint = WaterEmitterSettingsFingerprint(*runtimeState);
    }
    cache.stale = cache.stale || !matchesSupportAndSettings;
    runtimeState->water.pathCache = std::move(cache);
    runtimeState->water.pathCacheLoaded = true;
    EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
    runtimeState->water.pathCacheStale = runtimeState->water.pathCache.stale;
    runtimeState->water.pathDirty = runtimeState->water.pathCacheStale;
    const auto supportKey = NormalizePathKey(sourceSession.sourcePath);
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        if (NormalizePathKey(runtimeState->sessions[index].sourcePath) == supportKey) {
            runtimeState->water.activeSupportSessionIndex = index;
            break;
        }
    }
    if (!runtimeState->water.pathCacheStale) {
        runtimeState->water.dirtyEmitterIds.clear();
    }
    runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    return !runtimeState->water.pathCacheStale;
}

bool TryLoadWaterPathCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession) {
    if (runtimeState == nullptr) {
        return false;
    }
    if (runtimeState->water.pathCacheLoaded &&
        !runtimeState->water.pathCache.branches.empty() &&
        WaterPathCacheMatchesSupportAndSettings(*runtimeState, sourceSession, runtimeState->water.pathCache)) {
        auto cache = runtimeState->water.pathCache;
        cache.stale = false;
        return ApplyWaterPathCacheForSupport(runtimeState, sourceSession, std::move(cache));
    }

    // A disk sidecar is only authoritative through the checksum-bearing
    // project manifest loaded into the in-memory cache above. Directory scans
    // cannot choose safely between multiple projects that share terrain and
    // emitter settings but retain different authored hidden-branch state.
    return false;
}

std::optional<WaterPathCache> CurrentWaterPathCacheForDocument(const PreviewRuntimeState& runtimeState) {
    if (!runtimeState.water.pathCacheLoaded || runtimeState.water.pathCache.branches.empty()) {
        return std::nullopt;
    }

    auto cache = runtimeState.water.pathCache;
    cache.stale = runtimeState.water.pathCacheStale || cache.stale;
    if (cache.stale) {
        return std::nullopt;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(runtimeState);
    if (supportIndex.has_value() && supportIndex.value() < runtimeState.sessions.size()) {
        const auto& sourceSession = runtimeState.sessions[supportIndex.value()];
        cache.supportLayerPath = sourceSession.sourcePath;
        if (!cache.stale) {
            cache.supportSignature =
                CombinedWaterSupportSignature(
                    runtimeState,
                    sourceSession,
                    ActiveProfileDefaultWaterSourceSettings(runtimeState.water).path);
            cache.emitterSettingsFingerprint = WaterEmitterSettingsFingerprint(runtimeState);
        }
    }
    return cache;
}

std::vector<WaterEffectLayer> RippleRuntimeLayersForSession(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    bool exportEnabled) {
    std::vector<WaterEffectLayer> layers;
    for (const auto& layer : runtimeState.water.rippleLayers) {
        const bool enabled = exportEnabled ? layer.enabledInExport : layer.enabledInViewport;
        if (!enabled ||
            !WaterRegionLayerClosed(layer) ||
            !WaterEffectLayerTargetsSession(runtimeState, layer, sourceSession, WaterEffectFeatureType::Ripple)) {
            continue;
        }
        layers.push_back(MaterializeWaterEffectLayerForSession(layer, sourceSession));
    }
    return layers;
}

std::string WaterRippleRuntimeMembershipFingerprint(const std::vector<WaterEffectLayer>& layers) {
    std::ostringstream stream;
    stream << "water-ripple-runtime-membership-v1|" << layers.size();
    for (const auto& layer : layers) {
        const auto pattern = invisible_places::water::ActiveWaterRipplePatternSettings(layer);
        stream << '|'
               << layer.id << ','
               << static_cast<int>(layer.featureType) << ','
               << layer.targetLayerSourcePath.generic_string() << ','
               << layer.directionX << ','
               << layer.directionY << ','
               << layer.directionZ << ','
               << pattern.directionX << ','
               << pattern.directionY << ','
               << pattern.directionZ << ','
               << layer.maxAffectedPoints << ','
               << layer.vertices.size();
        for (const auto& vertex : layer.vertices) {
            stream << ':' << vertex.x << ',' << vertex.y << ',' << vertex.z;
        }
    }
    return stream.str();
}

std::vector<WaterRippleRuntimeParams> BuildWaterRippleRuntimeParamsForLayers(
    const std::vector<WaterEffectLayer>& layers) {
    std::vector<WaterRippleRuntimeParams> params;
    params.reserve(layers.size());
    for (const auto& layer : layers) {
        params.push_back(invisible_places::water::BuildWaterRippleRuntimeParams(layer));
    }
    return params;
}

bool WaterRippleRuntimeCacheMatchesSupportAndLayers(
    const WaterRippleRuntimeCacheDocument& cache,
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterEffectLayer>& layers) {
    return !cache.stale &&
           !cache.memberships.empty() &&
           NormalizePathKey(cache.supportLayerPath) == NormalizePathKey(sourceSession.sourcePath) &&
           cache.supportSignature == WaterSupportSignature(sourceSession) &&
           cache.regionFingerprint == WaterRippleRuntimeMembershipFingerprint(layers);
}

bool WaterRippleRuntimeCacheTargetsSupport(
    const WaterRippleRuntimeCacheDocument& cache,
    const PreviewLayerSession& sourceSession) {
    return NormalizePathKey(cache.supportLayerPath) == NormalizePathKey(sourceSession.sourcePath);
}

const WaterRippleRuntimeCacheDocument* FindWaterRippleRuntimeCache(
    const WaterWorkflowState& water,
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterEffectLayer>& layers) {
    if (layers.empty()) {
        return nullptr;
    }
    for (const auto& cache : water.rippleRuntimeCaches) {
        if (WaterRippleRuntimeCacheMatchesSupportAndLayers(cache, sourceSession, layers)) {
            return &cache;
        }
    }
    return nullptr;
}

bool HasWaterRippleRuntimeCacheForSupport(
    const WaterWorkflowState& water,
    const PreviewLayerSession& sourceSession) {
    return std::any_of(
        water.rippleRuntimeCaches.begin(),
        water.rippleRuntimeCaches.end(),
        [&](const WaterRippleRuntimeCacheDocument& cache) {
            return WaterRippleRuntimeCacheTargetsSupport(cache, sourceSession);
        });
}

WaterEffectOverlay BuildWaterRippleDebugOverlayFromMemberships(
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterRippleRuntimeMembership>& memberships) {
    WaterEffectOverlay overlay;
    if (sourceSession.offlinePointCloud == nullptr || memberships.empty()) {
        return overlay;
    }
    const auto& cloud = *sourceSession.offlinePointCloud;
    overlay.points.reserve(memberships.size());
    for (const auto& membership : memberships) {
        const auto pointIndex = static_cast<std::size_t>(membership.pointIndex);
        if (pointIndex >= cloud.positions.size()) {
            continue;
        }
        WaterEffectPoint point;
        point.position = cloud.positions[pointIndex];
        if (cloud.hasNormals && pointIndex < cloud.normals.size()) {
            point.normal = cloud.normals[pointIndex];
        } else {
            point.normal = {0.0F, 0.0F, 1.0F};
        }
        point.sourcePointIndex = membership.pointIndex;
        point.featureType = 1.0F;
        point.mask = 1.0F;
        point.edge = 1.0F;
        point.value = 1.0F;
        overlay.points.push_back(point);
        overlay.bounds.Expand(point.position);
    }
    return overlay;
}

void StoreWaterRegionPointPreviewsFromRippleRuntimeCache(
    WaterWorkflowState* water,
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterEffectLayer>& layers,
    const std::vector<WaterRippleRuntimeMembership>& memberships,
    const std::vector<WaterRippleRuntimeParams>& params) {
    if (water == nullptr || sourceSession.offlinePointCloud == nullptr || layers.empty()) {
        return;
    }
    const auto& cloud = *sourceSession.offlinePointCloud;
    std::vector<invisible_places::water::WaterRegionSelection> selections(layers.size());
    for (std::size_t index = 0; index < layers.size(); ++index) {
        auto& selection = selections[index];
        const auto& layer = layers[index];
        selection.layerId = layer.id;
        selection.featureType = layer.featureType;
        selection.targetLayerSourcePath = layer.targetLayerSourcePath;
        selection.targetLayerKey = layer.targetLayerSourcePath.generic_string();
        selection.boundary = layer.vertices;
        selection.hull = layer.hull.empty()
                             ? invisible_places::water::BuildWaterRegionHull(layer.vertices)
                             : layer.hull;
        for (const auto& vertex : selection.boundary) {
            selection.bounds.Expand(vertex);
        }
    }
    for (const auto& membership : memberships) {
        const auto pointIndex = static_cast<std::size_t>(membership.pointIndex);
        const auto paramIndex = static_cast<std::size_t>(membership.paramIndex);
        if (pointIndex >= cloud.positions.size() || paramIndex >= selections.size()) {
            continue;
        }
        const auto& layer = layers[paramIndex];
        invisible_places::water::WaterRegionSelectedPoint selected;
        selected.pointIndex = membership.pointIndex;
        selected.position = cloud.positions[pointIndex];
        selected.normal =
            cloud.hasNormals && pointIndex < cloud.normals.size()
                ? cloud.normals[pointIndex]
                : invisible_places::io::Float3{0.0F, 0.0F, 1.0F};
        selected.edgeDistance = membership.edgeDistance;
        selected.edgeWeight = std::clamp(
            membership.edgeDistance / std::max(1.0e-5F, layer.edgeBlendWidth),
            0.0F,
            1.0F);
        selected.fieldVector =
            paramIndex < params.size()
                ? FromGlm(params[paramIndex].direction)
                : invisible_places::io::Float3{1.0F, 0.0F, 0.0F};
        selected.blendMode = layer.blendMode;
        selected.response = layer.response;
        selected.sourceLayerId = layer.id;
        selected.effectSpeed = layer.speed;
        selections[paramIndex].points.push_back(std::move(selected));
    }
    for (std::size_t index = 0; index < layers.size(); ++index) {
        if (!selections[index].points.empty()) {
            StoreWaterRegionPointPreview(
                water,
                layers[index],
                selections[index],
                WaterRegionLayerFingerprint(layers[index]));
        }
    }
}

void StoreWaterRippleRuntimeCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterEffectLayer>& layers,
    const std::vector<WaterRippleRuntimeMembership>& memberships,
    const std::vector<WaterRippleRuntimeParams>& params) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto supportKey = NormalizePathKey(sourceSession.sourcePath);
    if (layers.empty() || memberships.empty() || params.empty()) {
        runtimeState->water.rippleRuntimeCaches.erase(
            std::remove_if(
                runtimeState->water.rippleRuntimeCaches.begin(),
                runtimeState->water.rippleRuntimeCaches.end(),
                [&](const WaterRippleRuntimeCacheDocument& cache) {
                    return NormalizePathKey(cache.supportLayerPath) == supportKey;
                }),
            runtimeState->water.rippleRuntimeCaches.end());
        return;
    }

    WaterRippleRuntimeCacheDocument cache;
    cache.supportLayerPath = sourceSession.sourcePath;
    cache.supportSignature = WaterSupportSignature(sourceSession);
    cache.regionFingerprint = WaterRippleRuntimeMembershipFingerprint(layers);
    cache.memberships = memberships;
    cache.params = params;
    cache.stale = false;

    const auto fingerprint = cache.regionFingerprint;
    auto& caches = runtimeState->water.rippleRuntimeCaches;
    caches.erase(
        std::remove_if(
            caches.begin(),
            caches.end(),
            [&](const WaterRippleRuntimeCacheDocument& existing) {
                return NormalizePathKey(existing.supportLayerPath) == supportKey &&
                       existing.regionFingerprint == fingerprint;
            }),
        caches.end());
    caches.push_back(std::move(cache));
}

void UpdateWaterRippleRuntimeCacheParamsForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    const std::vector<WaterEffectLayer>& layers,
    const std::vector<WaterRippleRuntimeParams>& params) {
    if (runtimeState == nullptr || layers.empty() || params.empty()) {
        return;
    }
    const auto fingerprint = WaterRippleRuntimeMembershipFingerprint(layers);
    const auto supportKey = NormalizePathKey(sourceSession.sourcePath);
    for (auto& cache : runtimeState->water.rippleRuntimeCaches) {
        if (NormalizePathKey(cache.supportLayerPath) == supportKey &&
            cache.supportSignature == WaterSupportSignature(sourceSession) &&
            cache.regionFingerprint == fingerprint &&
            !cache.memberships.empty()) {
            cache.params = params;
            cache.stale = false;
            return;
        }
    }
}

bool RestoreWaterRippleRuntimeCacheForSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    WaterEffectOverlay* combinedOverlay,
    std::size_t* restoredMembershipCount,
    std::size_t* restoredRegionCount) {
    if (runtimeState == nullptr ||
        viewport == nullptr ||
        sessionIndex >= runtimeState->sessions.size()) {
        return false;
    }
    const auto& sourceSession = runtimeState->sessions[sessionIndex];
    if (!sourceSession.loaded ||
        sourceSession.offlinePointCloud == nullptr ||
        !IsAssociableLidarSession(sourceSession)) {
        return false;
    }
    const auto layers = RippleRuntimeLayersForSession(*runtimeState, sourceSession, false);
    const auto* cache = FindWaterRippleRuntimeCache(runtimeState->water, sourceSession, layers);
    if (cache == nullptr) {
        return false;
    }
    const auto params = BuildWaterRippleRuntimeParamsForLayers(layers);
    try {
        viewport->UploadSparseWaterRippleMembership(sessionIndex, cache->memberships, params);
    } catch (const std::exception& error) {
        runtimeState->errorMessage =
            "GPU upload failed while restoring cached Ripple membership: " + std::string{error.what()};
        runtimeState->statusMessage.clear();
        return false;
    }
    if (combinedOverlay != nullptr) {
        AppendWaterEffectOverlayPoints(
            combinedOverlay,
            BuildWaterRippleDebugOverlayFromMemberships(sourceSession, cache->memberships));
    }
    StoreWaterRegionPointPreviewsFromRippleRuntimeCache(
        &runtimeState->water,
        sourceSession,
        layers,
        cache->memberships,
        params);
    for (const auto& layer : layers) {
        runtimeState->water.regionEffectsDirtyKeys.erase(WaterRegionPreviewKey(layer));
    }
    if (restoredMembershipCount != nullptr) {
        *restoredMembershipCount += cache->memberships.size();
    }
    if (restoredRegionCount != nullptr) {
        *restoredRegionCount += params.size();
    }
    UpdateWaterRippleRuntimeCacheParamsForSupport(runtimeState, sourceSession, layers, params);
    return true;
}

std::size_t RestoreWaterRippleRuntimeCachesForLoadedSessions(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t* restoredMembershipCount,
    std::size_t* restoredRegionCount) {
    if (!kRippleWaterRuntimeEnabled) {
        return 0U;
    }
    if (runtimeState == nullptr || viewport == nullptr) {
        return 0U;
    }
    WaterEffectOverlay combinedOverlay;
    std::size_t restoredSessionCount = 0U;
    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        if (RestoreWaterRippleRuntimeCacheForSession(
                runtimeState,
                viewport,
                sessionIndex,
                &combinedOverlay,
                restoredMembershipCount,
                restoredRegionCount)) {
            ++restoredSessionCount;
        }
    }
    if (restoredSessionCount > 0U) {
        runtimeState->water.rippleEffectOverlay = std::move(combinedOverlay);
        runtimeState->water.rippleEffectsDirty = std::any_of(
            runtimeState->water.rippleLayers.begin(),
            runtimeState->water.rippleLayers.end(),
            [&](const WaterEffectLayer& layer) {
                return WaterRegionLayerClosed(layer) &&
                       runtimeState->water.regionEffectsDirtyKeys.contains(WaterRegionPreviewKey(layer));
            });
    }
    return restoredSessionCount;
}

std::vector<WaterRippleRuntimeCacheDocument> CurrentWaterRippleRuntimeCachesForDocument(
    const PreviewRuntimeState& runtimeState) {
    std::vector<WaterRippleRuntimeCacheDocument> caches;
    if (!kRippleWaterRuntimeEnabled) {
        return caches;
    }
    for (const auto& cache : runtimeState.water.rippleRuntimeCaches) {
        if (cache.stale ||
            cache.memberships.empty() ||
            cache.memberships.size() >
                invisible_places::serialization::kMaxSerializedWaterRippleRuntimeCacheMemberships) {
            continue;
        }
        const auto sessionIndex = FindSessionIndexBySourcePath(runtimeState, cache.supportLayerPath);
        if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState.sessions.size()) {
            continue;
        }
        const auto& sourceSession = runtimeState.sessions[sessionIndex.value()];
        if (sourceSession.loaded &&
            cache.supportSignature != WaterSupportSignature(sourceSession)) {
            continue;
        }

        bool matchesCurrentLayers = false;
        std::vector<WaterRippleRuntimeParams> params;
        for (const bool exportEnabled : {false, true}) {
            const auto layers = RippleRuntimeLayersForSession(
                runtimeState,
                sourceSession,
                exportEnabled);
            if (!layers.empty() &&
                cache.regionFingerprint == WaterRippleRuntimeMembershipFingerprint(layers)) {
                params = BuildWaterRippleRuntimeParamsForLayers(layers);
                matchesCurrentLayers = true;
                break;
            }
        }
        if (!matchesCurrentLayers || params.empty()) {
            continue;
        }

        auto savedCache = cache;
        savedCache.params = std::move(params);
        savedCache.stale = false;
        caches.push_back(std::move(savedCache));
    }
    return caches;
}

bool WaterFieldCacheMatchesSupportAndSettings(
    const PreviewRuntimeState&,
    const PreviewLayerSession& sourceSession,
    const WaterFieldCache& cache,
    std::string_view settingsFingerprint,
    std::string_view regionFingerprint) {
    return NormalizePathKey(cache.supportLayerPath) == NormalizePathKey(sourceSession.sourcePath) &&
           cache.supportSignature == WaterSupportSignature(sourceSession) &&
           cache.settingsFingerprint == settingsFingerprint &&
           cache.regionFingerprint == regionFingerprint &&
           !cache.stale;
}

void StampWaterFieldCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    std::string_view settingsFingerprint,
    std::string_view regionFingerprint) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& cache = runtimeState->water.fieldCache;
    cache.supportLayerPath = sourceSession.sourcePath;
    cache.supportSignature = WaterSupportSignature(sourceSession);
    cache.settingsFingerprint = std::string{settingsFingerprint};
    cache.regionFingerprint = std::string{regionFingerprint};
    cache.stale = false;
}

bool SaveWaterFieldCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    std::string_view settingsFingerprint,
    std::string_view regionFingerprint) {
    if (runtimeState == nullptr || runtimeState->water.fieldCache.nodes.empty()) {
        return false;
    }
    StampWaterFieldCacheForSupport(runtimeState, sourceSession, settingsFingerprint, regionFingerprint);
    const auto outputPath = BuildWaterFieldCachePath(*runtimeState, sourceSession);
    std::string errorMessage;
    if (!invisible_places::water::SaveWaterFieldCacheBinary(runtimeState->water.fieldCache, outputPath, &errorMessage)) {
        runtimeState->errorMessage = errorMessage;
        return false;
    }
    return true;
}

bool TryLoadWaterFieldCacheForSupport(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& sourceSession,
    std::string_view settingsFingerprint,
    std::string_view regionFingerprint) {
    if (runtimeState == nullptr) {
        return false;
    }
    if (!runtimeState->water.fieldCache.nodes.empty() &&
        WaterFieldCacheMatchesSupportAndSettings(
            *runtimeState,
            sourceSession,
            runtimeState->water.fieldCache,
            settingsFingerprint,
            regionFingerprint)) {
        return true;
    }

    const auto inputPath = BuildWaterFieldCachePath(*runtimeState, sourceSession);
    std::string errorMessage;
    auto cache = invisible_places::water::LoadWaterFieldCacheBinary(inputPath, &errorMessage);
    if (!cache.has_value() ||
        !WaterFieldCacheMatchesSupportAndSettings(
            *runtimeState,
            sourceSession,
            cache.value(),
            settingsFingerprint,
            regionFingerprint)) {
        return false;
    }
    runtimeState->water.fieldCache = std::move(cache.value());
    return true;
}

std::filesystem::path BuildWaterFeatureOverlayPath(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession,
    const char* suffix) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    const auto waterDirectory = projectPath.empty()
                                    ? std::filesystem::path{"Saved"} / "water"
                                    : projectPath.parent_path() / "water";
    return waterDirectory / (sourceSession.sourcePath.stem().string() + suffix);
}

std::filesystem::path WaterSourcesPath(const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    return (projectPath.empty() ? std::filesystem::path{"Saved"} : projectPath.parent_path()) /
           "water_sources.json";
}

void SaveWaterSources(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    invisible_places::serialization::WaterSourcesDocument document;
    document.emitters = runtimeState->water.emitters;
    document.manualFlowPaths = runtimeState->water.manualFlowPaths;
    document.seepageNodes = runtimeState->water.seepageNodes;
    document.shorelineDefaultSettings.reset();
    document.shorelineProfiles =
        runtimeState->water.shorelineProfiles;
    document.selectedShorelineProfileName.clear();
    document.shorelineInstances =
        runtimeState->water.shorelineInstances;
    document.nextShorelineInstanceId =
        runtimeState->water.nextShorelineInstanceId;
    document.seepageDefaultNodeSettings =
        runtimeState->water.defaultSeepageNodeSettings;
    document.seepageNodeSettingsProfiles =
        WithoutPresetSeepageNodeSettingsProfiles(
            runtimeState->water.seepageNodeSettingsProfiles);
    document.seepageDefaultLook = runtimeState->water.defaultSeepageLook;
    document.seepageLookProfiles = WithoutPresetSeepageLookProfiles(
        runtimeState->water.seepageLookProfiles);
    document.seepageResponseProfiles = WithoutPresetSeepageResponseProfiles(
        runtimeState->water.seepageResponseProfiles);
    document.rippleLayers = runtimeState->water.rippleLayers;
    document.fieldLayers = runtimeState->water.fieldLayers;
    document.flowTrailSettings = runtimeState->water.flowTrailSettings;
    document.showFlowTrails = runtimeState->water.showFlowTrails;
    document.trailGeometry = runtimeState->water.defaultTrailGeometry;
    document.fieldSettings = runtimeState->water.fieldSettings;
    document.fieldTrailSettings = runtimeState->water.fieldTrailSettings;
    document.dynamicMeshFlowSettings = runtimeState->water.dynamicMeshFlowSettings;
    document.rainSettings = runtimeState->water.collisionRainSettings;
    document.rainVisualSettings = runtimeState->water.rainVisual;
    document.sourceSettings = runtimeState->water.defaultSourceSettings;
    document.tempSourceSettings = runtimeState->water.tempDefaultSourceSettings;
    document.causticLookSettings = runtimeState->water.defaultCausticLookSettings;
    document.tempCausticLookSettings = runtimeState->water.tempDefaultCausticLookSettings;
    document.selectedPathProfileName = NormalizeWaterProfileName(runtimeState->water.selectedPathProfileName);
    document.selectedLaneProfileName = NormalizeWaterProfileName(runtimeState->water.selectedLaneProfileName);
    document.selectedTrailProfileName = NormalizeWaterProfileName(runtimeState->water.selectedTrailProfileName);
    document.tempPathProfileSettings = runtimeState->water.editedPathProfileSettings;
    document.tempLaneProfileSettings = runtimeState->water.editedLaneProfileSettings;
    document.keyedSettingsProfiles =
        runtimeState->water.keyedSettingsProfiles;
    document.pathProfiles.reserve(runtimeState->water.pathProfiles.size());
    for (const auto& profile : runtimeState->water.pathProfiles) {
        document.pathProfiles.push_back(MakeWaterPathProfileDocument(profile));
    }
    document.laneProfiles.reserve(runtimeState->water.laneProfiles.size());
    for (const auto& profile : runtimeState->water.laneProfiles) {
        document.laneProfiles.push_back(MakeWaterLaneProfileDocument(profile));
    }
    document.trailProfiles.reserve(runtimeState->water.trailProfiles.size());
    for (const auto& profile : runtimeState->water.trailProfiles) {
        document.trailProfiles.push_back(MakeWaterTrailProfileDocument(profile));
    }
    if (runtimeState->water.editedTrailProfile.has_value()) {
        document.tempTrailProfile = MakeWaterTrailProfileDocument(runtimeState->water.editedTrailProfile.value());
    }
    document.pathCache = CurrentWaterPathCacheForDocument(*runtimeState);
    document.rippleRuntimeCaches = CurrentWaterRippleRuntimeCachesForDocument(*runtimeState);
    std::string errorMessage;
    const auto outputPath = WaterSourcesPath(*runtimeState);
    if (invisible_places::serialization::SaveWaterSourcesDocument(document, outputPath, &errorMessage)) {
        runtimeState->statusMessage = "Saved water sources to " + outputPath.string() + ".";
        runtimeState->errorMessage.clear();
    } else {
        runtimeState->errorMessage = errorMessage;
        runtimeState->statusMessage.clear();
    }
}

void LoadWaterSources(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr) {
        return;
    }
    std::string errorMessage;
    const auto inputPath = WaterSourcesPath(*runtimeState);
    const auto document = invisible_places::serialization::LoadWaterSourcesDocument(inputPath, &errorMessage);
    if (!document.has_value()) {
        runtimeState->errorMessage = errorMessage;
        runtimeState->statusMessage.clear();
        return;
    }

    CancelWaterFlowTrailBuildJob(&runtimeState->water);
    runtimeState->water.flowTrailSourceRequests.clear();
    runtimeState->water.flowTrailSourceArtifacts.clear();

    runtimeState->water.emitters = document->emitters;
    runtimeState->water.manualFlowPaths = document->manualFlowPaths;
    runtimeState->water.seepageNodes = document->seepageNodes;
    runtimeState->water.shorelineProfiles =
        document->shorelineProfiles;
    runtimeState->water.shorelineInstances =
        document->shorelineInstances;
    runtimeState->water.nextShorelineInstanceId = std::max(
        document->nextShorelineInstanceId,
        NextAvailableShorelineInstanceId(
            runtimeState->water.shorelineInstances));
    runtimeState->water.selectedShorelineProfileName =
        NormalizeWaterShorelineProfileName(
            document->selectedShorelineProfileName);
    std::optional<PointCloudShorelineWaveSettings> legacyPrimary;
    if (document->schemaVersion <
        invisible_places::serialization::
            kWaterOwnedShorelineSourcesSchemaVersion) {
        if (document->shorelineDefaultSettings.has_value()) {
            legacyPrimary =
                document->shorelineDefaultSettings.value();
            if (const auto profileIndex =
                    FindWaterShorelineProfileIndex(
                        runtimeState->water,
                        runtimeState->water
                            .selectedShorelineProfileName);
                profileIndex.has_value()) {
                legacyPrimary = runtimeState->water
                                    .shorelineProfiles[profileIndex.value()]
                                    .settings;
            }
        } else if (const auto visualIndex =
                       ResolveLoadedPointCloudLookdevIndex(*runtimeState);
                   visualIndex.has_value() &&
                   visualIndex.value() <
                       runtimeState->sessions.size()) {
            const auto settings =
                invisible_places::renderer::pointcloud::
                    ExtractPointCloudShorelineWaveSettings(
                        runtimeState->sessions[visualIndex.value()]
                            .pointStyle);
            if (settings.enabled) {
                legacyPrimary = settings;
            }
        }
    }
    NormalizeWaterShorelineState(
        &runtimeState->water,
        legacyPrimary);
    ClearWaterShorelineFromSavedVisuals(runtimeState);
    runtimeState->water.selectedShorelineInstanceIndex.reset();
    runtimeState->water.defaultSeepageNodeSettings =
        document->seepageDefaultNodeSettings;
    runtimeState->water.seepageNodeSettingsProfiles =
        document->seepageNodeSettingsProfiles;
    runtimeState->water.defaultSeepageLook = document->seepageDefaultLook;
    runtimeState->water.seepageLookProfiles = document->seepageLookProfiles;
    runtimeState->water.seepageResponseProfiles = document->seepageResponseProfiles;
    MigrateLegacyWaterSeepageLooks(
        &runtimeState->water,
        !document->seepageResponseProfiles.empty());
    MigrateLegacyWaterSeepageNodeSettings(&runtimeState->water);
    SeedWaterSeepageProfilePresets(&runtimeState->water);
    ReconcileWaterSeepageObjectProfiles(&runtimeState->water);
    runtimeState->water.rippleLayers = document->rippleLayers;
    runtimeState->water.fieldLayers = document->fieldLayers;
    if (kRippleWaterRuntimeEnabled) {
        runtimeState->water.rippleRuntimeCaches = document->rippleRuntimeCaches;
    } else {
        runtimeState->water.rippleRuntimeCaches.clear();
    }
    runtimeState->water.flowTrailSettings = document->flowTrailSettings;
    runtimeState->water.showFlowTrails = document->showFlowTrails;
    runtimeState->water.defaultTrailGeometry = document->trailGeometry;
    runtimeState->water.fieldSettings = document->fieldSettings;
    runtimeState->water.fieldTrailSettings = document->fieldTrailSettings;
    runtimeState->water.dynamicMeshFlowSettings =
        invisible_places::water::SanitizeWaterDynamicMeshFlowSettings(
            document->dynamicMeshFlowSettings);
    runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
        NormalizeWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.dynamicMeshFlowSettings.particlePresetName = std::string{
        invisible_places::water::NormalizeWaterDynamicMeshParticlePresetName(
            runtimeState->water.dynamicMeshFlowSettings.particlePresetName)};
    runtimeState->water.dynamicMeshTrailProfileNameBuffer =
        BaseWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.dynamicMeshSurfaceCache.reset();
    runtimeState->water.dynamicMeshSurfaceCachePath.clear();
    runtimeState->water.dynamicMeshSurfaceCacheSignature.clear();
    runtimeState->water.dynamicMeshFlowGpuSessionIndex.reset();
    runtimeState->water.dynamicMeshFlowLastUpdateSeconds = 0.0F;
    runtimeState->water.dynamicMeshFlowResetRequested = true;
    runtimeState->water.dynamicMeshFlowAllocationRevision = 0U;
    runtimeState->water.dynamicMeshFlowParameterRevision = 0U;
    runtimeState->water.dynamicMeshFlowDescriptorGeneration = 0U;
    runtimeState->water.dynamicMeshFlowDispatchCount = 0U;
    runtimeState->water.dynamicMeshFlowSharedGroundUploadRevision = 0U;
    runtimeState->water.dynamicMeshFlowContactEventCount = 0U;
    runtimeState->water.dynamicMeshFlowLastActiveSeconds = -1.0F;
    runtimeState->water.collisionRainSettings = document->rainSettings;
    runtimeState->water.rainVisual = document->rainVisualSettings;
    runtimeState->water.defaultSourceSettings = document->sourceSettings;
    runtimeState->water.tempDefaultSourceSettings = document->tempSourceSettings;
    runtimeState->water.defaultCausticLookSettings = document->causticLookSettings;
    runtimeState->water.tempDefaultCausticLookSettings = document->tempCausticLookSettings;
    runtimeState->water.pathProfiles.clear();
    runtimeState->water.pathProfiles.reserve(document->pathProfiles.size());
    for (const auto& profile : document->pathProfiles) {
        runtimeState->water.pathProfiles.push_back(MakeWaterPathProfileState(profile));
    }
    runtimeState->water.laneProfiles.clear();
    runtimeState->water.laneProfiles.reserve(document->laneProfiles.size());
    for (const auto& profile : document->laneProfiles) {
        runtimeState->water.laneProfiles.push_back(MakeWaterLaneProfileState(profile));
    }
    runtimeState->water.trailProfiles.clear();
    runtimeState->water.trailProfiles.reserve(document->trailProfiles.size());
    for (const auto& profile : document->trailProfiles) {
        runtimeState->water.trailProfiles.push_back(MakeWaterTrailProfileState(profile));
    }
    runtimeState->water.selectedPathProfileName = document->selectedPathProfileName;
    runtimeState->water.selectedLaneProfileName = document->selectedLaneProfileName;
    runtimeState->water.selectedTrailProfileName = document->selectedTrailProfileName;
    runtimeState->water.editedPathProfileSettings = document->tempPathProfileSettings;
    runtimeState->water.editedLaneProfileSettings = document->tempLaneProfileSettings;
    runtimeState->water.keyedSettingsProfiles =
        document->keyedSettingsProfiles;
    runtimeState->water.editedTrailProfile =
        document->tempTrailProfile.has_value()
            ? std::optional<SavedWaterTrailProfileState>{
                  MakeWaterTrailProfileState(document->tempTrailProfile.value())}
            : std::nullopt;
    MigrateLegacyWaterEmitterProfiles(&runtimeState->water);
    EnsureWaterProfiles(runtimeState);
    runtimeState->water.regionPointPreviews.clear();
    runtimeState->water.regionPointPreviewOverrides.clear();
    runtimeState->water.regionPointPreviewPendingKeys.clear();
    runtimeState->water.regionEffectsDirtyKeys.clear();
    runtimeState->water.rippleEffectsDirty = std::any_of(
        runtimeState->water.rippleLayers.begin(),
        runtimeState->water.rippleLayers.end(),
        [](const WaterEffectLayer& layer) { return layer.vertices.size() >= 3U; });
    runtimeState->water.fieldEffectsDirty = std::any_of(
        runtimeState->water.fieldLayers.begin(),
        runtimeState->water.fieldLayers.end(),
        [](const WaterEffectLayer& layer) { return layer.vertices.size() >= 3U; });
    for (const auto& layer : runtimeState->water.rippleLayers) {
        if (WaterRegionLayerClosed(layer)) {
            runtimeState->water.regionEffectsDirtyKeys.insert(WaterRegionPreviewKey(layer));
        }
    }
    for (const auto& layer : runtimeState->water.fieldLayers) {
        if (WaterRegionLayerClosed(layer)) {
            runtimeState->water.regionEffectsDirtyKeys.insert(WaterRegionPreviewKey(layer));
        }
    }
    runtimeState->water.nextEmitterId = NextWaterEmitterId(*runtimeState);
    runtimeState->water.nextSeepageNodeId = NextWaterSeepageNodeId(*runtimeState);
    runtimeState->water.nextRippleLayerId = NextWaterRippleLayerId(*runtimeState);
    runtimeState->water.nextFieldLayerId = NextWaterFieldLayerId(*runtimeState);
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.selectedManualFlowPathIndex.reset();
    runtimeState->water.manualFlowPathEditor = {};
    ClearWaterSeepageSelection(&runtimeState->water);
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.seepageTopologyFingerprints.clear();
    runtimeState->water.seepageAttachmentSemanticKeys.clear();
    runtimeState->water.seepageParamsFingerprints.clear();
    runtimeState->water.seepageRuntimeGrids.clear();
    runtimeState->water.seepageSupportJob = {};
    runtimeState->water.seepageSupportSelections.clear();
    runtimeState->water.seepageSupportNodeFingerprints.clear();
    runtimeState->water.seepagePendingSupportSelections.clear();
    runtimeState->water.seepagePendingSupportNodeFingerprints.clear();
    runtimeState->water.seepageSupportFailedKeys.clear();
    runtimeState->water.seepageRuntimeGuideKeys.clear();
    runtimeState->water.seepageSurfaceGuides.clear();
    runtimeState->water.seepageSurfaceGuideFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideNodeFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideWarning.clear();
    runtimeState->water.seepageSupportWarning.clear();
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.selectedRippleLayerIndex.reset();
    runtimeState->water.selectedFieldLayerIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.rippleRegionPlacementArmed = false;
    runtimeState->water.fieldRegionPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    if (document->pathCache.has_value() && !document->pathCache->branches.empty()) {
        runtimeState->water.pathCache = document->pathCache.value();
        runtimeState->water.pathCacheLoaded = true;
        runtimeState->water.pathCacheStale = runtimeState->water.pathCache.stale;
        runtimeState->water.pathDirty = runtimeState->water.pathCacheStale;
        runtimeState->water.dirtyEmitterIds.clear();
        runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
        if (const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
            supportIndex.has_value() && supportIndex.value() < runtimeState->sessions.size() &&
            TryLoadWaterPathCacheForSupport(runtimeState, runtimeState->sessions[supportIndex.value()]) &&
            viewport != nullptr) {
            EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
        }
    } else {
        runtimeState->water.pathCache = {};
        runtimeState->water.pathCacheLoaded = false;
        runtimeState->water.pathCacheStale = false;
        runtimeState->water.pathAnchors = {};
        if (runtimeState->water.emitters.empty()) {
            runtimeState->water.pathDirty = false;
            runtimeState->water.dirtyEmitterIds.clear();
        } else {
            MarkWaterPathDirty(runtimeState);
        }
    }
    if (viewport != nullptr &&
        (!runtimeState->water.pathAnchors.points.empty() || HasValidManualFlowPath(runtimeState->water))) {
        QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::InMemoryOnly);
    }
    std::size_t restoredRippleMemberships = 0U;
    std::size_t restoredRippleRegions = 0U;
    const auto restoredRippleSessions = RestoreWaterRippleRuntimeCachesForLoadedSessions(
        runtimeState,
        viewport,
        &restoredRippleMemberships,
        &restoredRippleRegions);
    runtimeState->statusMessage = "Loaded water sources from " + inputPath.string() + ".";
    if (restoredRippleSessions > 0U) {
        runtimeState->statusMessage +=
            " Restored cached Ripple membership: " + FormatPointCount(restoredRippleMemberships) +
            " points across " + FormatPointCount(restoredRippleRegions) + " params.";
    }
    runtimeState->errorMessage.clear();
    ValidateWaterSourceSettingLinks(runtimeState);
}

void SelectWaterEmitterInViewport(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell&,
    std::size_t emitterIndex) {
    if (runtimeState == nullptr || emitterIndex >= runtimeState->water.emitters.size()) {
        return;
    }

    if (runtimeState->water.manualFlowPathEditor.active &&
        runtimeState->water.manualFlowPathEditor.creating) {
        runtimeState->statusMessage =
            "Save or cancel the new Flow path before selecting a Point Source.";
        runtimeState->errorMessage.clear();
        return;
    }

    const auto& emitter = runtimeState->water.emitters[emitterIndex];
    runtimeState->water.manualFlowPathEditor = {};
    runtimeState->water.selectedEmitterIndex = emitterIndex;
    runtimeState->water.selectedManualFlowPathIndex.reset();
    ClearWaterSeepageSelection(&runtimeState->water);
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = emitter.position;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->cameraPlayback.active = false;
    runtimeState->statusMessage = "Selected water source " + emitter.name + " in the viewport.";
    runtimeState->errorMessage.clear();
}

void SelectManualFlowPathSource(PreviewRuntimeState* runtimeState, std::size_t sourceIndex) {
    if (runtimeState == nullptr || sourceIndex >= runtimeState->water.manualFlowPaths.size()) {
        return;
    }
    auto& water = runtimeState->water;
    if (water.manualFlowPathEditor.active && water.manualFlowPathEditor.creating) {
        runtimeState->statusMessage =
            "Save or cancel the new Flow path before selecting another path.";
        runtimeState->errorMessage.clear();
        return;
    }
    const bool selectionChanged =
        !water.selectedManualFlowPathIndex.has_value() ||
        water.selectedManualFlowPathIndex.value() != sourceIndex;
    if (selectionChanged || water.manualFlowPathEditor.active) {
        water.manualFlowPathEditor = {};
        water.manualFlowPathEditor.sourceIndex = sourceIndex;
    }
    water.selectedManualFlowPathIndex = sourceIndex;
    water.selectedEmitterIndex.reset();
    ClearWaterSeepageSelection(&runtimeState->water);
    water.selectedDynamicMeshAttractorIndex.reset();
    water.movingEmitterIndex.reset();
    water.placementArmed = false;
    water.pathAttractorPlacementArmed = false;
    water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->cameraPlayback.active = false;
    runtimeState->statusMessage =
        "Selected manual Flow path " + water.manualFlowPaths[sourceIndex].name +
        "; node and handle edits save automatically.";
    runtimeState->errorMessage.clear();
}

void BeginCreatingManualFlowPath(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    WaterManualFlowPathSource source;
    source.id = NextWaterEmitterId(*runtimeState);
    source.name = "Path Source " + std::to_string(source.id);
    water.nextEmitterId = source.id + 1U;
    water.manualFlowPathEditor = {};
    water.manualFlowPathEditor.active = true;
    water.manualFlowPathEditor.creating = true;
    water.manualFlowPathEditor.draft = std::move(source);
    water.selectedManualFlowPathIndex.reset();
    water.selectedEmitterIndex.reset();
    water.placementArmed = false;
    water.movingEmitterIndex.reset();
    water.seepagePlacementArmed = false;
    water.movingSeepageNodeIndex.reset();
    water.pathAttractorPlacementArmed = false;
    water.dynamicMeshAttractorPlacementArmed = false;
    water.rippleRegionPlacementArmed = false;
    water.fieldRegionPlacementArmed = false;
    water.activeRegionFeature = WaterRegionFeature::None;
    water.regionEditor = {};
    runtimeState->statusMessage = "Ctrl+left-click the viewport to add manual Flow path nodes.";
    runtimeState->errorMessage.clear();
}

void BeginEditingManualFlowPath(PreviewRuntimeState* runtimeState, std::size_t sourceIndex) {
    if (runtimeState == nullptr || sourceIndex >= runtimeState->water.manualFlowPaths.size()) {
        return;
    }
    auto& water = runtimeState->water;
    water.manualFlowPathEditor = {};
    water.manualFlowPathEditor.active = true;
    water.manualFlowPathEditor.sourceIndex = sourceIndex;
    water.manualFlowPathEditor.draft = water.manualFlowPaths[sourceIndex];
    water.selectedManualFlowPathIndex = sourceIndex;
    water.selectedEmitterIndex.reset();
    water.placementArmed = false;
    water.movingEmitterIndex.reset();
    water.seepagePlacementArmed = false;
    water.movingSeepageNodeIndex.reset();
    water.pathAttractorPlacementArmed = false;
    water.dynamicMeshAttractorPlacementArmed = false;
    water.rippleRegionPlacementArmed = false;
    water.fieldRegionPlacementArmed = false;
    water.activeRegionFeature = WaterRegionFeature::None;
    water.regionEditor = {};
    runtimeState->statusMessage = "Editing " + water.manualFlowPaths[sourceIndex].name + ".";
    runtimeState->errorMessage.clear();
}

void CancelManualFlowPathEdit(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || !runtimeState->water.manualFlowPathEditor.active) {
        return;
    }
    const bool creating = runtimeState->water.manualFlowPathEditor.creating;
    runtimeState->water.manualFlowPathEditor = {};
    if (creating) {
        runtimeState->water.selectedManualFlowPathIndex.reset();
    }
    runtimeState->statusMessage = creating ? "Cancelled new manual Flow path." : "Cancelled manual Flow path edits.";
    runtimeState->errorMessage.clear();
}

bool SaveManualFlowPathEdit(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr || !runtimeState->water.manualFlowPathEditor.active) {
        return false;
    }
    auto& editor = runtimeState->water.manualFlowPathEditor;
    std::vector<invisible_places::io::Float3> cleaned;
    std::vector<invisible_places::water::WaterManualFlowPathLaneWidth>
        cleanedLaneWidths;
    cleaned.reserve(editor.draft.controlPoints.size());
    cleanedLaneWidths.reserve(editor.draft.controlPoints.size());
    for (std::size_t index = 0U;
         index < editor.draft.controlPoints.size();
         ++index) {
        const auto& point = editor.draft.controlPoints[index];
        if (!std::isfinite(point.x) || !std::isfinite(point.y) || !std::isfinite(point.z)) {
            continue;
        }
        if (cleaned.empty() || glm::length(ToGlm(point) - ToGlm(cleaned.back())) > 1.0e-5F) {
            cleaned.push_back(point);
            cleanedLaneWidths.push_back(
                index < editor.draft.controlPointLaneWidths.size()
                    ? editor.draft.controlPointLaneWidths[index]
                    : invisible_places::water::
                          WaterManualFlowPathLaneWidth{});
        }
    }
    editor.draft.controlPoints = std::move(cleaned);
    editor.draft.controlPointLaneWidths =
        std::move(cleanedLaneWidths);
    if (editor.draft.controlPoints.size() < 2U) {
        runtimeState->errorMessage = "A manual Flow path needs at least two distinct nodes.";
        runtimeState->statusMessage.clear();
        return false;
    }
    editor.draft.name = TrimText(editor.draft.name);
    if (editor.draft.name.empty()) {
        editor.draft.name = "Path Source " + std::to_string(editor.draft.id);
    }

    std::size_t savedIndex = 0U;
    if (editor.sourceIndex.has_value() && editor.sourceIndex.value() < runtimeState->water.manualFlowPaths.size()) {
        savedIndex = editor.sourceIndex.value();
        runtimeState->water.manualFlowPaths[savedIndex] = editor.draft;
    } else {
        runtimeState->water.manualFlowPaths.push_back(editor.draft);
        savedIndex = runtimeState->water.manualFlowPaths.size() - 1U;
    }
    runtimeState->water.selectedManualFlowPathIndex = savedIndex;
    runtimeState->water.nextEmitterId = NextWaterEmitterId(*runtimeState);
    const auto savedName = runtimeState->water.manualFlowPaths[savedIndex].name;
    runtimeState->water.manualFlowPathEditor = {};
    if (runtimeState->pendingLoad.has_value() || !ResolveWaterRuntimeSessionIndex(*runtimeState).has_value()) {
        runtimeState->statusMessage = "Saved manual Flow path " + savedName + "; trails will rebuild when the scene is ready.";
        runtimeState->errorMessage.clear();
    } else {
        QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::InMemoryOnly,
            std::chrono::milliseconds{0},
            runtimeState->water.manualFlowPaths[savedIndex].id);
        runtimeState->statusMessage =
            "Saved manual Flow path " + savedName + "; updating trails in the background.";
    }
    return true;
}

void DeselectWaterEmitter(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.selectedManualFlowPathIndex.reset();
    runtimeState->water.manualFlowPathEditor = {};
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->pivotOverlay.visible = false;
    runtimeState->cameraPlayback.active = false;
    runtimeState->statusMessage = runtimeState->water.tempDefaultSourceSettings.has_value()
                                      ? "Editing Default_edited water source settings."
                                      : "Editing Default water source settings.";
    runtimeState->errorMessage.clear();
}

void SelectDynamicMeshAttractorInViewport(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell&,
    std::size_t attractorIndex) {
    if (runtimeState == nullptr ||
        attractorIndex >= runtimeState->water.dynamicMeshFlowSettings.attractors.size()) {
        return;
    }

    const auto& attractor = runtimeState->water.dynamicMeshFlowSettings.attractors[attractorIndex];
    runtimeState->water.selectedDynamicMeshAttractorIndex = attractorIndex;
    runtimeState->water.selectedEmitterIndex.reset();
    ClearWaterSeepageSelection(&runtimeState->water);
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = attractor.position;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->cameraPlayback.active = false;
    runtimeState->statusMessage = "Selected dynamic mesh attractor " + attractor.name + " in the viewport.";
    runtimeState->errorMessage.clear();
}

bool BakeWaterOverlayForActiveLayer(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (!EnsureSceneAnalysisReadyForAction(
            runtimeState,
            DeferredSceneAnalysisAction::BakeWaterPath,
            "Bake Path")) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->errorMessage = "Please wait for the current layer load before generating water flow.";
        runtimeState->statusMessage.clear();
        return false;
    }
    CancelWaterFlowTrailBuildJob(&runtimeState->water);
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage =
            "Canonical analysis sources are still loading or unavailable; water flow cannot be baked from a sparse display cloud.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->water.activeSupportSessionIndex = supportIndex.value();

    auto& sourceSession = runtimeState->sessions[supportIndex.value()];
    if (sourceSession.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return false;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(runtimeState, sourceSession, defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water flow.";
        runtimeState->statusMessage.clear();
        return false;
    }

    runtimeState->errorMessage.clear();
    if (TryLoadWaterPathCacheForSupport(runtimeState, sourceSession) &&
        !runtimeState->water.pathCacheStale) {
        runtimeState->water.pathEditUndoHiddenBranchIds.clear();
        runtimeState->water.selectedPathBranchId.reset();
        runtimeState->water.hoveredPathBranchId.reset();
        if (!RefreshWaterOverlayFromAnchors(
                runtimeState,
                viewport,
                WaterOverlayRefreshPersistence::SavePathCache,
                WaterTrailBuildQuality::Final)) {
            return false;
        }
        runtimeState->water.pathDirty = false;
        runtimeState->water.dirtyEmitterIds.clear();
        std::string cacheSaveError;
        const bool cachePersisted = PersistSettledWaterPathCache(
            runtimeState,
            sourceSession,
            &cacheSaveError);
        runtimeState->statusMessage =
            "Reused cached water main paths with " +
            FormatPointCount(runtimeState->water.pathAnchors.points.size()) + " path anchors and " +
            FormatPointCount(runtimeState->water.pathCache.branches.size()) +
            " branches; updating source-local lanes and trails asynchronously.";
        if (!cachePersisted && !cacheSaveError.empty()) {
            runtimeState->statusMessage += " Flow cache was not persisted: " + cacheSaveError;
        }
        runtimeState->errorMessage.clear();
        return true;
    }

    const auto pathEmitters = WaterEmittersWithResolvedPathProfiles(runtimeState->water);
    if (std::none_of(
            pathEmitters.begin(),
            pathEmitters.end(),
            [](const WaterEmitter& emitter) { return emitter.status != WaterEmitterStatus::Disabled; })) {
        runtimeState->errorMessage = "No enabled water sources were available for path baking.";
        runtimeState->statusMessage.clear();
        return false;
    }

    runtimeState->statusMessage = "Baking water main paths...";
    const auto supportLayers = BuildWaterSourcePickSupportLayers(*runtimeState, sourceSession);
    const auto focusedSupportCloud = BuildFocusedWaterPathSupportCloud(
        *runtimeState,
        sourceSession,
        defaultSourceSettings.path,
        pathEmitters);
    const auto* bakeSupportCloud = focusedSupportCloud != nullptr ? focusedSupportCloud.get() : supportCloud;
    ++runtimeState->water.pathDiagnosticRebuildCounters.pathBakes;

    // Branch fingerprints let Bake Path keep unaffected sources while rebuilding moved,
    // added, deleted, or profile-changed emitters against the same support cloud.
    const auto bakeFingerprints = WaterEmitterBakeFingerprints(runtimeState->water, pathEmitters);
    const bool canReuseExistingCache =
        runtimeState->water.pathCacheLoaded &&
        !runtimeState->water.pathCache.branches.empty() &&
        WaterPathCacheMatchesSupport(
            *runtimeState,
            sourceSession,
            runtimeState->water.pathCache,
            defaultSourceSettings.path);
    const bool rebuildAllEmitters =
        !canReuseExistingCache ||
        (runtimeState->water.pathDirty && runtimeState->water.dirtyEmitterIds.empty());

    std::unordered_set<std::uint32_t> emittersToBakeIds;
    std::vector<WaterEmitter> emittersToBake;
    emittersToBake.reserve(pathEmitters.size());
    for (const auto& emitter : pathEmitters) {
        if (emitter.status == WaterEmitterStatus::Disabled) {
            continue;
        }
        const auto fingerprintIt = bakeFingerprints.find(emitter.id);
        const bool explicitlyDirty = runtimeState->water.dirtyEmitterIds.contains(emitter.id);
        const bool cachedBranchReusable =
            fingerprintIt != bakeFingerprints.end() &&
            CachedWaterEmitterBranchesReusable(
                runtimeState->water.pathCache,
                emitter.id,
                fingerprintIt->second);
        if (rebuildAllEmitters || explicitlyDirty || !cachedBranchReusable) {
            emittersToBakeIds.insert(emitter.id);
            emittersToBake.push_back(emitter);
        }
    }

    const std::size_t rebuiltEmitterCount = emittersToBake.size();
    std::size_t reusedBranchCount = 0U;
    if (canReuseExistingCache) {
        const auto previousCache = runtimeState->water.pathCache;
        const std::unordered_set<std::uint32_t> previousHiddenBranchIds{
            previousCache.hiddenBranchIds.begin(),
            previousCache.hiddenBranchIds.end()};
        auto rebuiltCache = emittersToBake.empty()
                                ? WaterPathCache{}
                                : invisible_places::water::GenerateWaterPathCache(
                                      *bakeSupportCloud,
                                      emittersToBake,
                                      defaultSourceSettings);
        StampWaterPathBranchFingerprints(&rebuiltCache, bakeFingerprints);

        WaterPathCache mergedCache = previousCache;
        mergedCache.branches.clear();
        mergedCache.hiddenBranchIds.clear();
        mergedCache.analysis.reset();
        for (const auto& branch : previousCache.branches) {
            const auto fingerprintIt = bakeFingerprints.find(branch.emitterId);
            if (fingerprintIt == bakeFingerprints.end() ||
                emittersToBakeIds.contains(branch.emitterId) ||
                branch.bakeFingerprint.empty() ||
                branch.bakeFingerprint != fingerprintIt->second) {
                continue;
            }
            if (previousHiddenBranchIds.contains(branch.id)) {
                mergedCache.hiddenBranchIds.push_back(branch.id);
            }
            mergedCache.branches.push_back(branch);
        }
        reusedBranchCount = mergedCache.branches.size();

        RemapWaterPathBranchIds(
            &rebuiltCache,
            MaxWaterPathBranchId(mergedCache.branches) + 1U);
        for (auto& branch : rebuiltCache.branches) {
            mergedCache.branches.push_back(std::move(branch));
        }
        if (rebuiltCache.diagnostics.estimatedPointSpacing > 0.0F) {
            mergedCache.diagnostics.estimatedPointSpacing = rebuiltCache.diagnostics.estimatedPointSpacing;
        }
        mergedCache.diagnostics.supportVoxelSize =
            std::max(mergedCache.diagnostics.supportVoxelSize, rebuiltCache.diagnostics.supportVoxelSize);
        mergedCache.diagnostics.maxBridgeDistance =
            std::max(mergedCache.diagnostics.maxBridgeDistance, rebuiltCache.diagnostics.maxBridgeDistance);
        if (rebuiltCache.diagnostics.pathSampleSpacing > 0.0F) {
            mergedCache.diagnostics.pathSampleSpacing =
                mergedCache.diagnostics.pathSampleSpacing <= 0.0F
                    ? rebuiltCache.diagnostics.pathSampleSpacing
                    : std::min(
                          mergedCache.diagnostics.pathSampleSpacing,
                          rebuiltCache.diagnostics.pathSampleSpacing);
        }
        mergedCache.diagnostics.branchSearchRadius =
            std::max(mergedCache.diagnostics.branchSearchRadius, rebuiltCache.diagnostics.branchSearchRadius);
        mergedCache.diagnostics.iterationCount =
            std::max(mergedCache.diagnostics.iterationCount, rebuiltCache.diagnostics.iterationCount);
        mergedCache.diagnostics.pilotTraceCount = rebuiltCache.diagnostics.pilotTraceCount;
        RefreshWaterPathCacheDiagnostics(
            &mergedCache,
            "Incremental water path bake reused " + FormatPointCount(reusedBranchCount) +
                " cached branches and rebuilt " + FormatPointCount(rebuiltEmitterCount) + " sources.");
        runtimeState->water.pathCache = std::move(mergedCache);
    } else {
        runtimeState->water.pathCache = invisible_places::water::GenerateWaterPathCache(
            *bakeSupportCloud,
            pathEmitters,
            defaultSourceSettings);
        StampWaterPathBranchFingerprints(&runtimeState->water.pathCache, bakeFingerprints);
    }

    runtimeState->water.pathCache.supportLayerPath = sourceSession.sourcePath;
    runtimeState->water.pathCache.supportSignature =
        CombinedWaterSupportSignature(*runtimeState, sourceSession, defaultSourceSettings.path);
    runtimeState->water.pathCache.emitterSettingsFingerprint = WaterEmitterSettingsFingerprint(*runtimeState);
    runtimeState->water.pathCache.requestedSettings = defaultSourceSettings.path;
    runtimeState->water.pathCache.tunedSettings = defaultSourceSettings.path;
    runtimeState->water.pathCache.stale = false;
    runtimeState->water.pathCacheLoaded = true;
    runtimeState->water.pathCacheStale = false;
    invisible_places::water::EnsureWaterPathAnalysis(&runtimeState->water.pathCache);
    EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
    runtimeState->water.pathEditUndoHiddenBranchIds.clear();
    runtimeState->water.selectedPathBranchId.reset();
    runtimeState->water.hoveredPathBranchId.reset();
    runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    if (runtimeState->water.pathCache.branches.empty() || runtimeState->water.pathAnchors.points.empty()) {
        runtimeState->water.pathDirty = true;
        runtimeState->errorMessage =
            "Water path bake found no supported downhill paths from " +
            FormatPointCount(pathEmitters.size()) + " sources using " +
            FormatPointCount(bakeSupportCloud->positions.size()) + " support samples over " +
            FormatPointCount(WaterSupportLayerPointCount(supportLayers)) + " raw role points from " +
            WaterSupportLayerSummary(supportLayers) + ".";
        runtimeState->statusMessage.clear();
        return false;
    }
    SaveWaterPathCacheForSupport(runtimeState, sourceSession);
    if (!QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::SavePathCache)) {
        runtimeState->errorMessage = "Water paths baked, but the asynchronous Flow update could not be queued.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->water.pathDirty = false;
    runtimeState->water.dirtyEmitterIds.clear();
    const std::string bakeAction =
        canReuseExistingCache
            ? "Updated water paths, rebuilt " + FormatPointCount(rebuiltEmitterCount) +
                  " sources, reused " + FormatPointCount(reusedBranchCount) +
                  " cached branches"
            : "Baked water main paths";
    runtimeState->statusMessage =
        bakeAction + " with " +
        FormatPointCount(runtimeState->water.pathAnchors.points.size()) + " path anchors across " +
        FormatPointCount(runtimeState->water.pathCache.branches.size()) +
        " branches; updating source-local lanes and trails asynchronously.";
    std::string cacheSaveError;
    if (!PersistSettledWaterPathCache(runtimeState, sourceSession, &cacheSaveError) &&
        !cacheSaveError.empty()) {
        runtimeState->statusMessage += " Flow cache was not persisted: " + cacheSaveError;
    }
    runtimeState->errorMessage.clear();
    return true;
}

bool RefreshWaterOverlayFromAnchors(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    WaterOverlayRefreshPersistence persistence,
    WaterTrailBuildQuality quality) {
    (void)quality;
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        return false;
    }
    const auto supportIndex = ResolveWaterRuntimeSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->water.pathDirty = !runtimeState->water.emitters.empty();
        runtimeState->statusMessage = runtimeState->water.emitters.empty()
                                          ? "A loaded water support scene is required to build Flow trails."
                                          : "Water path bake required.";
        runtimeState->errorMessage.clear();
        return false;
    }
    if (runtimeState->water.pathCacheLoaded && !runtimeState->water.pathCache.branches.empty()) {
        invisible_places::water::EnsureWaterPathAnalysis(&runtimeState->water.pathCache);
        EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
        runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    }
    const bool hasManualFlowPath = HasValidManualFlowPath(runtimeState->water);
    if (runtimeState->water.pathAnchors.points.empty() && !hasManualFlowPath) {
        runtimeState->water.pathDirty = !runtimeState->water.emitters.empty();
        runtimeState->statusMessage = runtimeState->water.emitters.empty()
                                          ? "No Flow sources are available."
                                          : "Water path bake required.";
        runtimeState->errorMessage.clear();
        return false;
    }
    if (persistence == WaterOverlayRefreshPersistence::SavePathCache && runtimeState->water.pathCacheLoaded) {
        SaveWaterPathCacheForSupport(runtimeState, runtimeState->sessions[supportIndex.value()]);
    }
    if (!QueueWaterFlowTrailRefresh(runtimeState, persistence)) {
        runtimeState->errorMessage = "Flow sources exist, but the asynchronous trail update could not be queued.";
        runtimeState->statusMessage.clear();
        return false;
    }
    if (runtimeState->water.emitters.empty()) {
        runtimeState->water.pathDirty = false;
        runtimeState->water.dirtyEmitterIds.clear();
    }
    runtimeState->statusMessage = "Updating source-local Flow lanes and trails asynchronously.";
    runtimeState->errorMessage.clear();
    return true;
}

constexpr std::string_view kDenseWaterEffectScalarFieldsForCleanup[] = {
    "water_effect_value",
    "water_effect_emission_add",
    "water_effect_opacity_add",
    "water_effect_opacity_multiply",
    "water_effect_point_size_add",
    "water_effect_point_size_multiply",
    "water_effect_colour_red",
    "water_effect_colour_green",
    "water_effect_colour_blue",
    "water_effect_colour_mix",
};

constexpr std::string_view kDenseRippleScalarFieldsForCleanup[] = {
    "ripple_mask",
    "ripple_edge",
    "ripple_value",
    "ripple_seed",
    "ripple_region_id",
    "ripple_distance",
    "ripple_linear_coord",
    "ripple_angle",
    "ripple_speed",
    "ripple_confidence",
    "ripple_wavelength",
    "ripple_warp",
    "ripple_phase",
};

bool RemoveGeneratedScalarFieldsFromSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    std::span<const std::string_view> fieldNames) {
    if (runtimeState == nullptr || viewport == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return false;
    }
    auto& session = runtimeState->sessions[sessionIndex];
    if (!session.loaded || session.kind != LayerKind::PointCloud || session.offlinePointCloud == nullptr) {
        return false;
    }
    const auto pointCount = session.offlinePointCloud->PointCount();
    if (pointCount == 0U || fieldNames.empty()) {
        return false;
    }
    std::unordered_set<std::string> targetNames;
    targetNames.reserve(fieldNames.size());
    for (const auto name : fieldNames) {
        targetNames.insert(NormalizeMotionScalarFieldName(name));
    }
    const auto oldFieldCount = session.offlinePointCloud->scalarFields.size();
    if (oldFieldCount == 0U) {
        return false;
    }
    const auto expectedValueCount = oldFieldCount * pointCount;
    if (session.offlinePointCloud->scalarFieldValues.size() != expectedValueCount) {
        return false;
    }

    std::vector<invisible_places::io::ScalarFieldStats> keptFields;
    std::vector<float> keptValues;
    keptFields.reserve(oldFieldCount);
    keptValues.reserve(session.offlinePointCloud->scalarFieldValues.size());
    bool removedAny = false;
    for (std::size_t fieldIndex = 0; fieldIndex < oldFieldCount; ++fieldIndex) {
        const auto normalized = NormalizeMotionScalarFieldName(
            session.offlinePointCloud->scalarFields[fieldIndex].name);
        if (targetNames.contains(normalized)) {
            removedAny = true;
            continue;
        }
        keptFields.push_back(session.offlinePointCloud->scalarFields[fieldIndex]);
        const auto valueOffset = fieldIndex * pointCount;
        keptValues.insert(
            keptValues.end(),
            session.offlinePointCloud->scalarFieldValues.begin() + static_cast<std::ptrdiff_t>(valueOffset),
            session.offlinePointCloud->scalarFieldValues.begin() +
                static_cast<std::ptrdiff_t>(valueOffset + pointCount));
    }
    if (!removedAny) {
        return false;
    }

    session.offlinePointCloud->scalarFields = std::move(keptFields);
    session.offlinePointCloud->scalarFieldValues = std::move(keptValues);
    session.scalarFields = session.offlinePointCloud->scalarFields;
    try {
        viewport->UploadPointCloudScalarFields(
            sessionIndex,
            session.offlinePointCloud->scalarFields,
            session.offlinePointCloud->scalarFieldValues);
    } catch (const std::exception& error) {
        runtimeState->errorMessage =
            "GPU upload failed while removing stale water scalar fields: " + std::string{error.what()};
        runtimeState->statusMessage.clear();
        return false;
    }
    return true;
}

void AppendWaterEffectOverlayPoints(WaterEffectOverlay* target, const WaterEffectOverlay& source) {
    if (target == nullptr) {
        return;
    }
    target->points.reserve(target->points.size() + source.points.size());
    for (const auto& point : source.points) {
        target->points.push_back(point);
        target->bounds.Expand(point.position);
    }
}

void AppendWaterRippleDebugOverlayPoints(
    WaterEffectOverlay* target,
    const invisible_places::water::WaterRegionSelection& selection) {
    if (target == nullptr) {
        return;
    }
    target->points.reserve(target->points.size() + selection.points.size());
    for (const auto& selected : selection.points) {
        WaterEffectPoint point;
        point.position = selected.position;
        point.normal = selected.normal;
        point.sourcePointIndex = selected.pointIndex;
        point.featureType = 1.0F;
        point.mask = 1.0F;
        point.edge = selected.edgeWeight;
        point.value = 1.0F;
        target->points.push_back(point);
        target->bounds.Expand(point.position);
    }
}

invisible_places::water::WaterRegionSelection ResolveRippleRegionSelectionForRecalculate(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& session,
    const WaterEffectLayer& layer) {
    if (runtimeState == nullptr || session.offlinePointCloud == nullptr) {
        return {};
    }
    const auto layerFingerprint = WaterRegionLayerFingerprint(layer);
    if (const auto* preview = FindWaterRegionPointPreview(runtimeState->water, layer);
        preview != nullptr &&
        NormalizePathKey(preview->targetLayerSourcePath) == NormalizePathKey(layer.targetLayerSourcePath) &&
        preview->layerFingerprint == layerFingerprint) {
        return preview->selection;
    }
    const auto selection = invisible_places::water::BuildWaterRegionSelection(
        *session.offlinePointCloud,
        layer,
        invisible_places::water::WaterRegionSelectionOptions{
            .previewOnly = true,
            .candidatePointIndices = VisibleWaterRegionCandidatePointIndices(*runtimeState, session)});
    StoreWaterRegionPointPreview(
        &runtimeState->water,
        layer,
        selection,
        layerFingerprint);
    return selection;
}

bool RefreshWaterRippleEffects(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (!kRippleWaterRuntimeEnabled) {
        return false;
    }
    if (!EnsureSceneAnalysisReadyForAction(
            runtimeState,
            DeferredSceneAnalysisAction::RefreshWaterRipple,
            "Ripple Recalculate Effects")) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->errorMessage = "Please wait for the current layer load before refreshing ripples.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->errorMessage.clear();

    std::size_t refreshedLayers = 0;
    std::size_t refreshedRegionPoints = 0;
    std::size_t sparseMembershipCount = 0;
    std::size_t sparseRegionCount = 0;
    bool sawCandidateLayers = false;
    bool touchedSparseBuffers = false;
    bool cleanedDenseRippleFields = false;
    WaterEffectOverlay combinedRippleOverlay;
    const bool removedGeneratedRipples =
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-Ripples");
    if (removedGeneratedRipples) {
        runtimeState->water.lastRippleOverlayPath.clear();
    }
    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        const auto& sourceSession = runtimeState->sessions[sessionIndex];
        const bool displayReady = IsSceneGroupedPointCloud(sourceSession)
                                      ? (sourceSession.gpuResident &&
                                         (sourceSession.committedDisplaySource ||
                                          sourceSession.pendingDisplaySource))
                                      : sourceSession.loaded;
        if (!displayReady || sourceSession.offlinePointCloud == nullptr ||
            !IsAssociableLidarSession(sourceSession)) {
            continue;
        }
        const auto candidateLayers = RippleRuntimeLayersForSession(*runtimeState, sourceSession, false);
        sawCandidateLayers = sawCandidateLayers || !candidateLayers.empty();
        if (candidateLayers.empty()) {
            try {
                viewport->UploadSparseWaterRippleMembership(sessionIndex, {}, {});
                touchedSparseBuffers = true;
                StoreWaterRippleRuntimeCacheForSupport(runtimeState, sourceSession, {}, {}, {});
            } catch (const std::exception& error) {
                runtimeState->errorMessage =
                    "GPU upload failed while clearing sparse Ripple membership: " + std::string{error.what()};
                runtimeState->statusMessage.clear();
                return false;
            }
            cleanedDenseRippleFields |= RemoveGeneratedScalarFieldsFromSession(
                runtimeState,
                viewport,
                sessionIndex,
                std::span{kDenseRippleScalarFieldsForCleanup});
            if (runtimeState->water.fieldSurfaceEffectOverlay.points.empty()) {
                cleanedDenseRippleFields |= RemoveGeneratedScalarFieldsFromSession(
                    runtimeState,
                    viewport,
                    sessionIndex,
                    std::span{kDenseWaterEffectScalarFieldsForCleanup});
            }
            if (!runtimeState->errorMessage.empty()) {
                return false;
            }
            continue;
        }

        WaterEffectOverlay sessionRippleOverlay;
        std::vector<invisible_places::water::WaterRippleRuntimeMembership> sessionMemberships;
        std::vector<invisible_places::water::WaterRippleRuntimeParams> sessionParams;
        for (const auto& layer : candidateLayers) {
            auto selection = ResolveRippleRegionSelectionForRecalculate(
                runtimeState,
                sourceSession,
                layer);
            refreshedRegionPoints += selection.points.size();
            const auto paramIndex = static_cast<std::uint32_t>(sessionParams.size());
            sessionParams.push_back(invisible_places::water::BuildWaterRippleRuntimeParams(layer, selection));
            auto layerMemberships = invisible_places::water::BuildWaterRippleRuntimeMemberships(
                selection,
                paramIndex);
            sessionMemberships.insert(
                sessionMemberships.end(),
                layerMemberships.begin(),
                layerMemberships.end());
            AppendWaterRippleDebugOverlayPoints(&sessionRippleOverlay, selection);
        }
        sparseMembershipCount += sessionMemberships.size();
        sparseRegionCount += sessionParams.size();
        try {
            viewport->UploadSparseWaterRippleMembership(sessionIndex, sessionMemberships, sessionParams);
            touchedSparseBuffers = true;
            StoreWaterRippleRuntimeCacheForSupport(
                runtimeState,
                sourceSession,
                candidateLayers,
                sessionMemberships,
                sessionParams);
        } catch (const std::exception& error) {
            runtimeState->errorMessage =
                "GPU upload failed while refreshing sparse Ripple membership: " + std::string{error.what()};
            runtimeState->statusMessage.clear();
            return false;
        }
        cleanedDenseRippleFields |= RemoveGeneratedScalarFieldsFromSession(
            runtimeState,
            viewport,
            sessionIndex,
            std::span{kDenseRippleScalarFieldsForCleanup});
        if (runtimeState->water.fieldSurfaceEffectOverlay.points.empty()) {
            cleanedDenseRippleFields |= RemoveGeneratedScalarFieldsFromSession(
                runtimeState,
                viewport,
                sessionIndex,
                std::span{kDenseWaterEffectScalarFieldsForCleanup});
        }
        if (!runtimeState->errorMessage.empty()) {
            return false;
        }
        AppendWaterEffectOverlayPoints(&combinedRippleOverlay, sessionRippleOverlay);
        if (!sessionMemberships.empty()) {
            ++refreshedLayers;
        }
        ++runtimeState->water.regionEffectOutputRevision;
    }

    if (refreshedLayers == 0U) {
        if (removedGeneratedRipples || touchedSparseBuffers || cleanedDenseRippleFields || sawCandidateLayers) {
            if (!sawCandidateLayers) {
                runtimeState->water.rippleEffectOverlay = {};
            } else {
                runtimeState->water.rippleEffectOverlay = std::move(combinedRippleOverlay);
            }
            runtimeState->water.rippleEffectsDirty = false;
            ClearWaterRegionEffectsDirtyForFeature(&runtimeState->water, WaterEffectFeatureType::Ripple);
            runtimeState->statusMessage =
                !sawCandidateLayers ? "Cleared ripple effects on base cloud."
                                    : "Ripple effects updated with no region points selected.";
            if (removedGeneratedRipples) {
                runtimeState->statusMessage += " Removed old Ripple point-cloud overlay.";
            }
            if (cleanedDenseRippleFields) {
                runtimeState->statusMessage += " Removed old dense Ripple fields.";
            }
            runtimeState->errorMessage.clear();
            SyncWaterRegionPointPreviewHighlights(runtimeState, viewport);
            return true;
        }
        runtimeState->errorMessage = "No enabled ripple layers target a loaded LiDAR layer.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->water.rippleEffectsDirty = false;
    ClearWaterRegionEffectsDirtyForFeature(&runtimeState->water, WaterEffectFeatureType::Ripple);
    runtimeState->water.lastRippleOverlayPath.clear();
    runtimeState->water.rippleEffectOverlay = std::move(combinedRippleOverlay);
    runtimeState->statusMessage =
        "Ripple effects: " + FormatPointCount(refreshedRegionPoints) +
        " region points updated via GPU-parametric sparse membership.";
    runtimeState->statusMessage +=
        " " + FormatPointCount(sparseMembershipCount) + " memberships across " +
        FormatPointCount(sparseRegionCount) + " region params.";
    if (removedGeneratedRipples) {
        runtimeState->statusMessage += " Removed old Ripple point-cloud overlay.";
    }
    if (cleanedDenseRippleFields) {
        runtimeState->statusMessage += " Removed old dense Ripple fields.";
    }
    runtimeState->errorMessage.clear();
    SyncWaterRegionPointPreviewHighlights(runtimeState, viewport);
    return true;
}

std::vector<invisible_places::water::WaterRippleRuntimeParams> BuildCurrentWaterRippleParamsForSession(
    const PreviewRuntimeState& runtimeState,
    const PreviewLayerSession& sourceSession) {
    std::vector<invisible_places::water::WaterRippleRuntimeParams> params;
    if (!sourceSession.loaded ||
        sourceSession.offlinePointCloud == nullptr ||
        !IsAssociableLidarSession(sourceSession)) {
        return params;
    }

    const auto layers = RippleRuntimeLayersForSession(runtimeState, sourceSession, false);
    if (layers.empty()) {
        return params;
    }
    if (FindWaterRippleRuntimeCache(runtimeState.water, sourceSession, layers) != nullptr) {
        return BuildWaterRippleRuntimeParamsForLayers(layers);
    }
    if (HasWaterRippleRuntimeCacheForSupport(runtimeState.water, sourceSession)) {
        return {};
    }

    const auto sourceKey = NormalizePathKey(sourceSession.sourcePath);
    for (const auto& layer : layers) {
        const auto* preview = FindWaterRegionPointPreview(runtimeState.water, layer);
        if (preview == nullptr ||
            NormalizePathKey(preview->targetLayerSourcePath) != sourceKey ||
            preview->layerFingerprint != WaterRegionLayerFingerprint(layer)) {
            params.clear();
            return params;
        }
        params.push_back(invisible_places::water::BuildWaterRippleRuntimeParams(layer, preview->selection));
    }
    return params;
}

bool UpdateWaterRippleParamsFromCachedPreviews(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool updatedAny = false;
    std::size_t updatedRegionCount = 0;
    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        const auto& sourceSession = runtimeState->sessions[sessionIndex];
        const auto layers = RippleRuntimeLayersForSession(*runtimeState, sourceSession, false);
        const auto params = BuildCurrentWaterRippleParamsForSession(*runtimeState, sourceSession);
        const auto activeRegionCount = viewport->SparseWaterRippleRegionCount(sessionIndex);
        if (params.empty()) {
            if (activeRegionCount != 0U) {
                return false;
            }
            continue;
        }
        if (params.size() != activeRegionCount) {
            return false;
        }
        try {
            viewport->UpdateSparseWaterRippleParams(sessionIndex, params);
        } catch (const std::exception& error) {
            runtimeState->errorMessage =
                "GPU upload failed while updating Ripple params: " + std::string{error.what()};
            runtimeState->statusMessage.clear();
            return false;
        }
        updatedAny = true;
        updatedRegionCount += params.size();
        UpdateWaterRippleRuntimeCacheParamsForSupport(runtimeState, sourceSession, layers, params);
    }

    if (updatedAny) {
        runtimeState->statusMessage =
            "Ripple settings updated on GPU for " + FormatPointCount(updatedRegionCount) + " region params.";
        runtimeState->errorMessage.clear();
    }
    return updatedAny;
}

bool RippleEffectsCanRefreshFromCachedPreviews(const PreviewRuntimeState& runtimeState) {
    for (const auto& sourceSession : runtimeState.sessions) {
        if (!sourceSession.loaded || sourceSession.offlinePointCloud == nullptr ||
            !IsAssociableLidarSession(sourceSession)) {
            continue;
        }
        const auto layers = RippleRuntimeLayersForSession(runtimeState, sourceSession, false);
        if (layers.empty()) {
            continue;
        }
        if (FindWaterRippleRuntimeCache(runtimeState.water, sourceSession, layers) != nullptr) {
            continue;
        }
        if (HasWaterRippleRuntimeCacheForSupport(runtimeState.water, sourceSession)) {
            return false;
        }
        for (const auto& layer : layers) {
            if (!WaterRegionPointPreviewCurrentForLayer(runtimeState.water, layer)) {
                return false;
            }
        }
    }
    return true;
}

void QueueWaterRippleLiveEffectRefresh(
    PreviewRuntimeState* runtimeState,
    const WaterEffectLayer& layer,
    std::chrono::milliseconds delay) {
    if (runtimeState == nullptr ||
        layer.featureType != WaterEffectFeatureType::Ripple ||
        !WaterRegionLayerClosed(layer)) {
        return;
    }
    runtimeState->water.pendingRippleLiveEffectKey = WaterRegionPreviewKey(layer);
    runtimeState->water.pendingRippleLiveEffectAt = std::chrono::steady_clock::now() + delay;
    runtimeState->statusMessage = "Ripple settings changed; updating GPU params...";
    runtimeState->errorMessage.clear();
}

void PollWaterRippleLiveEffectRefresh(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (!kRippleWaterRuntimeEnabled) {
        if (runtimeState != nullptr) {
            runtimeState->water.pendingRippleLiveEffectKey.reset();
        }
        return;
    }
    if (runtimeState == nullptr || viewport == nullptr ||
        !runtimeState->water.pendingRippleLiveEffectKey.has_value()) {
        return;
    }
    if (std::chrono::steady_clock::now() < runtimeState->water.pendingRippleLiveEffectAt) {
        return;
    }

    const auto pendingKey = runtimeState->water.pendingRippleLiveEffectKey.value();
    runtimeState->water.pendingRippleLiveEffectKey.reset();
    const auto featureType = static_cast<WaterEffectFeatureType>(
        static_cast<std::uint32_t>(pendingKey >> 32U));
    const auto layerId = static_cast<std::uint32_t>(pendingKey & 0xffff'ffffULL);
    const auto* layer = FindWaterRegionLayerByKey(runtimeState->water, featureType, layerId);
    if (layer == nullptr ||
        layer->featureType != WaterEffectFeatureType::Ripple ||
        !WaterRegionLayerClosed(*layer)) {
        return;
    }
    if (!RippleEffectsCanRefreshFromCachedPreviews(*runtimeState)) {
        runtimeState->statusMessage = "Ripple effects dirty; press Recalculate Effects.";
        return;
    }
    if (!UpdateWaterRippleParamsFromCachedPreviews(runtimeState, viewport)) {
        runtimeState->water.rippleEffectsDirty = true;
        runtimeState->water.regionEffectsDirtyKeys.insert(pendingKey);
        runtimeState->statusMessage = "Ripple effects dirty; press Recalculate Effects.";
    }
}

bool SceneHasCommittedWaterSurfaceDisplay(
    const PreviewRuntimeState& runtimeState,
    const ScenePointCloudRuntime& scene) {
    if (!scene.displayLoaded || !scene.displayVisible) {
        return false;
    }
    const auto sessionIsCommitted = [&](const std::optional<std::size_t>& index) {
        if (!index.has_value() || index.value() >= runtimeState.sessions.size()) {
            return false;
        }
        return IsCommittedDisplayPointCloudReady(
            runtimeState,
            runtimeState.sessions[index.value()]);
    };
    return std::any_of(
        scene.committedDisplaySessionIndices.begin(),
        scene.committedDisplaySessionIndices.end(),
        sessionIsCommitted);
}

ScenePointCloudRuntime* ActiveWaterSurfaceScene(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    const auto findSceneByName =
        [&](std::string_view sceneGroupName) -> ScenePointCloudRuntime* {
        if (sceneGroupName.empty()) {
            return nullptr;
        }
        const auto found = std::find_if(
            runtimeState->pointCloudScenes.begin(),
            runtimeState->pointCloudScenes.end(),
            [&](const ScenePointCloudRuntime& scene) {
                return scene.sceneGroupName == sceneGroupName;
            });
        return found == runtimeState->pointCloudScenes.end() ? nullptr : &*found;
    };
    const auto resolveSessionScene =
        [&](std::size_t sessionIndex) -> ScenePointCloudRuntime* {
        if (sessionIndex >= runtimeState->sessions.size()) {
            return nullptr;
        }
        const auto& session = runtimeState->sessions[sessionIndex];
        if (auto* scene = FindScenePointCloudRuntime(runtimeState, session);
            scene != nullptr) {
            return scene;
        }
        // Generated Mesh Flow sessions deliberately have no terrain role, but
        // carry their owning scene group so selecting the overlay cannot make
        // cache selection drift to another loaded scene.
        if (auto* scene = findSceneByName(session.sceneGroupName);
            scene != nullptr &&
            NormalizePathKey(scene->sourceFolder) ==
                NormalizePathKey(session.sourcePath.parent_path())) {
            return scene;
        }
        return nullptr;
    };
    const auto acceptExplicitScene =
        [&](ScenePointCloudRuntime* scene) -> ScenePointCloudRuntime* {
        if (scene == nullptr ||
            !SceneHasCommittedWaterSurfaceDisplay(*runtimeState, *scene)) {
            return nullptr;
        }
        runtimeState->water.activeWaterSurfaceSceneGroupName =
            scene->sceneGroupName;
        return scene;
    };
    // A project-persisted or user-selected scene remains authoritative even
    // while its display bundle is pending. Returning no terrain here is
    // intentional: adopting a temporarily visible SampleScene would install
    // trails against the wrong Ground table and could remain sticky after the
    // intended scene finishes loading.
    if (!runtimeState->water.authoritativeWaterSurfaceSceneGroupName.empty()) {
        return acceptExplicitScene(
            findSceneByName(
                runtimeState->water.authoritativeWaterSurfaceSceneGroupName));
    }
    // With no persisted/user authority, keep the last successfully resolved
    // scene sticky ahead of a stale selected session.
    if (auto* stickyScene = acceptExplicitScene(
            findSceneByName(
                runtimeState->water.activeWaterSurfaceSceneGroupName));
        stickyScene != nullptr) {
        return stickyScene;
    }
    if (runtimeState->selectedSessionIndex.has_value() &&
        runtimeState->selectedSessionIndex.value() < runtimeState->sessions.size()) {
        if (auto* selectedScene = acceptExplicitScene(
                resolveSessionScene(runtimeState->selectedSessionIndex.value()));
            selectedScene != nullptr) {
            return selectedScene;
        }
    }
    if (runtimeState->water.activeSupportSessionIndex.has_value()) {
        if (auto* supportScene = acceptExplicitScene(
                resolveSessionScene(
                    runtimeState->water.activeSupportSessionIndex.value()));
            supportScene != nullptr) {
            return supportScene;
        }
    }

    // A unique visible scene is safe to infer. If several scenes are visible,
    // require an explicit scene/session owner instead of silently binding the
    // first catalog entry.
    ScenePointCloudRuntime* uniqueVisibleScene = nullptr;
    for (auto& scene : runtimeState->pointCloudScenes) {
        if (!SceneHasCommittedWaterSurfaceDisplay(*runtimeState, scene)) {
            continue;
        }
        if (uniqueVisibleScene != nullptr) {
            return nullptr;
        }
        uniqueVisibleScene = &scene;
    }
    if (uniqueVisibleScene != nullptr) {
        runtimeState->water.activeWaterSurfaceSceneGroupName =
            uniqueVisibleScene->sceneGroupName;
    }
    return uniqueVisibleScene;
}

std::optional<WaterSurfaceCacheWarmupResult> TakeWaterSurfaceCacheWarmupResult(
    const std::shared_ptr<WaterSurfaceCacheWarmupShared>& shared) {
    if (shared == nullptr) {
        return std::nullopt;
    }
    std::scoped_lock lock(shared->mutex);
    if (!shared->result.has_value()) {
        return std::nullopt;
    }
    auto result = std::move(shared->result.value());
    shared->result.reset();
    return result;
}

void CancelWaterSurfaceCacheWarmup(WaterWorkflowState* water) {
    if (water == nullptr || !water->waterSurfaceCacheWarmup.worker.joinable()) {
        return;
    }
    if (water->waterSurfaceCacheWarmup.shared != nullptr) {
        water->waterSurfaceCacheWarmup.shared->cancelRequested.store(true);
    }
    water->waterSurfaceCacheWarmup.worker.request_stop();
    water->waterSurfaceCacheWarmup = {};
}

std::filesystem::path WaterSurfaceCacheRootForScene(
    const PreviewRuntimeState& runtimeState,
    const ScenePointCloudRuntime& scene) {
    if (!scene.sourceFolder.empty()) {
        return scene.sourceFolder;
    }
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    return projectPath.empty() ? runtimeState.waterSurfaceCacheRoot : projectPath.parent_path();
}

std::filesystem::path WaterSurfaceProjectFallbackRoot(
    const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    return projectPath.empty() ? runtimeState.waterSurfaceCacheRoot : projectPath.parent_path();
}

std::filesystem::path WaterSurfaceManifestPath(
    const PreviewRuntimeState& runtimeState,
    const WaterSurfaceCacheManifestDocument& manifest) {
    if (manifest.relativePath.is_absolute()) {
        return manifest.relativePath;
    }
    const std::filesystem::path projectPath{runtimeState.persistence.projectFilePath};
    return projectPath.empty()
               ? manifest.relativePath
               : (projectPath.parent_path() / manifest.relativePath).lexically_normal();
}

WaterSurfaceCacheRuntimeStatus InitialWaterSurfaceCacheStatus(
    const PreviewRuntimeState& runtimeState,
    const ScenePointCloudRuntime& scene) {
    if (!scene.waterSurfaceCache.has_value()) {
        return WaterSurfaceCacheRuntimeStatus::Missing;
    }
    const auto& manifest = scene.waterSurfaceCache.value();
    const auto manifestPath = WaterSurfaceManifestPath(runtimeState, manifest);
    std::error_code sizeError;
    const auto payloadBytes = manifestPath.empty()
                                  ? 0U
                                  : std::filesystem::file_size(manifestPath, sizeError);
    if (manifest.cacheSchema != invisible_places::water::kWaterSurfaceCacheSchemaVersion ||
        manifest.algorithmId != invisible_places::water::kWaterSurfaceCacheAlgorithmId ||
        manifest.sourceFingerprint != scene.waterSurfaceSignature ||
        manifest.requestedRebuildGeneration != manifest.builtRebuildGeneration ||
        manifestPath.empty() || sizeError ||
        (manifest.payloadBytes != 0U && manifest.payloadBytes != payloadBytes)) {
        return WaterSurfaceCacheRuntimeStatus::Stale;
    }
    // The sidecar is a valid warm-load candidate, but it becomes Valid only
    // after its payload has been verified and uploaded for this process.
    return WaterSurfaceCacheRuntimeStatus::Missing;
}

void StartWaterSurfaceCacheWarmup(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr ||
        scene->waterSurfaceSources.empty()) {
        return;
    }
    auto& water = runtimeState->water;
    const auto& signature = scene->waterSurfaceSignature;
    const auto requestedGeneration = scene->waterSurfaceCache.has_value()
                                         ? scene->waterSurfaceCache->requestedRebuildGeneration
                                         : 0U;
    const auto builtGeneration = scene->waterSurfaceCache.has_value()
                                     ? scene->waterSurfaceCache->builtRebuildGeneration
                                     : 0U;
    const bool forceRebuild = requestedGeneration > builtGeneration;
    if (water.waterSurfaceCache != nullptr &&
        water.waterSurfaceSceneGroupName == scene->sceneGroupName &&
        water.waterSurfaceCacheSignature == signature &&
        !forceRebuild) {
        scene->waterSurfaceCacheStatus = water.waterSurfaceCachePreprocessPending
                                             ? WaterSurfaceCacheRuntimeStatus::Building
                                             : WaterSurfaceCacheRuntimeStatus::Valid;
        return;
    }
    if (water.waterSurfaceCacheWarmup.worker.joinable()) {
        if (water.waterSurfaceCacheWarmup.sceneGroupName == scene->sceneGroupName &&
            water.waterSurfaceCacheWarmup.signature == signature) {
            scene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Building;
            return;
        }
        CancelWaterSurfaceCacheWarmup(&water);
    }

    if (water.waterSurfaceCache != nullptr &&
        water.waterSurfaceSceneGroupName != scene->sceneGroupName) {
        // A support-selection worker owns the old cache snapshot. Stop it
        // before retiring that scene so a late result cannot be published
        // under the next scene's topology lifecycle.
        water.seepageSupportJob = {};
        water.seepageSupportSelections.clear();
        water.seepageSupportNodeFingerprints.clear();
        water.seepagePendingSupportSelections.clear();
        water.seepagePendingSupportNodeFingerprints.clear();
        water.seepageSupportFailedKeys.clear();
        water.seepageRuntimeGrids.clear();
        viewport->ClearWaterSurfaceCache();
        water.waterSurfaceCache.reset();
        water.waterSurfaceCacheSignature.clear();
        water.waterSurfaceSceneGroupName.clear();
        water.waterSurfaceCacheLoadedFromDisk = false;
        water.waterSurfaceCachePreprocessPending = false;
        water.dynamicMeshFlowResetRequested = true;
    }

    auto shared = std::make_shared<WaterSurfaceCacheWarmupShared>();
    {
        std::scoped_lock lock(shared->mutex);
        shared->stage = "Reading shared 2 mm role sources into 10 mm cells";
    }
    const auto sources = scene->waterSurfaceSources;
    const auto cacheRoot = WaterSurfaceCacheRootForScene(*runtimeState, *scene);
    const auto fallbackRoot = WaterSurfaceProjectFallbackRoot(*runtimeState);
    const bool fallbackCacheCandidate = [&]() {
        if (fallbackRoot.empty() ||
            NormalizePathKey(fallbackRoot) == NormalizePathKey(cacheRoot)) {
            return false;
        }
        std::error_code currentCacheError;
        if (std::filesystem::is_regular_file(
                invisible_places::water::WaterSurfaceCachePath(fallbackRoot, signature),
                currentCacheError) &&
            !currentCacheError) {
            return true;
        }
        const auto legacyDirectory = fallbackRoot / "cache" / "rain";
        std::error_code directoryError;
        if (!std::filesystem::is_directory(legacyDirectory, directoryError) || directoryError) {
            return false;
        }
        for (std::filesystem::directory_iterator iterator{
                 legacyDirectory,
                 std::filesystem::directory_options::skip_permission_denied,
                 directoryError};
             !directoryError && iterator != std::filesystem::directory_iterator{};
             iterator.increment(directoryError)) {
            std::error_code entryError;
            if (iterator->is_regular_file(entryError) && !entryError &&
                iterator->path().extension() == ".raincache") {
                return true;
            }
        }
        return false;
    }();
    std::jthread worker{
        [shared,
         sources,
         cacheRoot,
         fallbackRoot,
         signature,
         forceRebuild,
         fallbackCacheCandidate](std::stop_token) {
            invisible_places::water::WaterSurfaceBuildResult result;
            std::filesystem::path persistedPath;
            try {
                const auto primaryPath = invisible_places::water::WaterSurfaceCachePath(
                    cacheRoot,
                    signature);
                std::error_code primaryError;
                const bool primaryPresent =
                    std::filesystem::is_regular_file(primaryPath, primaryError) &&
                    !primaryError;
                const auto buildRoot = !forceRebuild && !primaryPresent &&
                                               !primaryError && fallbackCacheCandidate
                                           ? fallbackRoot
                                           : cacheRoot;
                result = invisible_places::water::BuildWaterSurfaceCache(
                    sources,
                    forceRebuild ? std::filesystem::path{} : buildRoot,
                    &shared->cancelRequested,
                    invisible_places::water::WaterSurfaceCacheLoadValidation::
                        DeferGpuPayloadToUpload);
                persistedPath = result.persistedPath;
                if (result.success && !result.cancelled && persistedPath.empty()) {
                    std::string saveError;
                    if (invisible_places::water::SaveWaterSurfaceCache(
                            result.cache,
                            primaryPath,
                            &saveError)) {
                        persistedPath = primaryPath;
                    } else {
                        const auto primarySaveError = saveError;
                        const auto fallbackPath =
                            invisible_places::water::WaterSurfaceCachePath(
                                fallbackRoot,
                                signature);
                        const bool distinctFallback =
                            !fallbackRoot.empty() &&
                            NormalizePathKey(fallbackPath) != NormalizePathKey(primaryPath);
                        saveError.clear();
                        if (distinctFallback &&
                            invisible_places::water::SaveWaterSurfaceCache(
                                result.cache,
                                fallbackPath,
                                &saveError)) {
                            persistedPath = fallbackPath;
                        } else {
                            result.warnings.push_back(
                                "Water surface cache could not be persisted: " +
                                (saveError.empty() ? primarySaveError : saveError));
                        }
                    }
                }
                if (result.success && !result.cancelled && !persistedPath.empty()) {
                    std::error_code persistedError;
                    if (persistedPath.extension() != ".surfacecache" ||
                        !std::filesystem::is_regular_file(persistedPath, persistedError) ||
                        persistedError) {
                        result.warnings.push_back(
                            "Water surface cache persistence did not leave a current sidecar.");
                        persistedPath.clear();
                    }
                }
                result.persistedPath = persistedPath;
            } catch (const std::exception& error) {
                result = {};
                result.errorMessage =
                    "Water surface cache warm-up failed: " + std::string{error.what()};
                persistedPath.clear();
            } catch (...) {
                result = {};
                result.errorMessage = "Water surface cache warm-up failed unexpectedly.";
                persistedPath.clear();
            }
            std::scoped_lock lock(shared->mutex);
            shared->stage = result.cancelled ? "Cancelled" : (result.success ? "Ready" : "Failed");
            shared->result = WaterSurfaceCacheWarmupResult{
                .build = std::move(result),
                .cachePath = std::move(persistedPath),
            };
        }};
    water.waterSurfaceCacheWarmup = {
        .shared = std::move(shared),
        .worker = std::move(worker),
        .sceneGroupName = scene->sceneGroupName,
        .signature = signature,
        .startedAt = std::chrono::steady_clock::now(),
    };
    scene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Building;
}

void PollWaterSurfaceCacheWarmup(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    auto& job = water.waterSurfaceCacheWarmup;
    auto completed = TakeWaterSurfaceCacheWarmupResult(job.shared);
    if (!completed.has_value()) {
        return;
    }
    if (job.worker.joinable()) {
        job.worker.join();
    }
    const auto completedScene = job.sceneGroupName;
    const auto completedSignature = job.signature;
    job = {};
    auto& result = completed->build;
    water.waterSurfaceSourceScanCount += result.diagnostics.sourceScanCount;
    water.waterSurfaceGpuTableBuildCount += result.diagnostics.gpuTableBuildCount;
    water.waterSurfaceFullPayloadHashPassCount +=
        result.diagnostics.fullPayloadHashPassCount;
    if (result.success && !result.cancelled && !result.loadedFromDisk) {
        ++water.waterSurfaceCacheBuildCount;
    }
    if (result.cancelled) {
        return;
    }
    auto* activeScene = ActiveWaterSurfaceScene(runtimeState);
    if (activeScene == nullptr || activeScene->sceneGroupName != completedScene ||
        activeScene->waterSurfaceSignature != completedSignature) {
        return;
    }
    if (!result.success) {
        activeScene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Failed;
        runtimeState->errorMessage = "Water surface cache failed: " + result.errorMessage;
        runtimeState->statusMessage.clear();
        return;
    }
    try {
        viewport->UploadWaterSurfaceCache(result.cache);
    } catch (const std::exception& error) {
        activeScene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Failed;
        runtimeState->errorMessage = "Water surface cache upload failed: " + std::string{error.what()};
        runtimeState->statusMessage.clear();
        return;
    }

    WaterSurfaceCacheManifestDocument manifest =
        activeScene->waterSurfaceCache.value_or(WaterSurfaceCacheManifestDocument{});
    manifest.cacheSchema = result.cache.schemaVersion;
    manifest.algorithmId = std::string{invisible_places::water::kWaterSurfaceCacheAlgorithmId};
    manifest.sourceFingerprint = completedSignature;
    if (!completed->cachePath.empty()) {
        std::error_code sizeError;
        manifest.payloadBytes = std::filesystem::file_size(completed->cachePath, sizeError);
        if (sizeError) {
            manifest.payloadBytes = invisible_places::water::WaterSurfaceCacheEstimatedPersistenceBytes(
                result.cache);
        }
        const std::filesystem::path projectPath{runtimeState->persistence.projectFilePath};
        std::error_code relativeError;
        manifest.relativePath = projectPath.empty()
                                    ? completed->cachePath
                                    : std::filesystem::relative(
                                          completed->cachePath,
                                          projectPath.parent_path(),
                                          relativeError);
        if (relativeError || manifest.relativePath.empty()) {
            manifest.relativePath = completed->cachePath;
        }
    } else {
        // A runtime-only cache (for example one above the persistence ceiling)
        // must not inherit a previously valid sidecar path.
        manifest.relativePath.clear();
        manifest.payloadBytes = 0U;
    }
    const auto identity = invisible_places::water::BuildWaterSurfaceCacheIdentity(result.cache);
    manifest.checksum = identity.contentDigest;
    manifest.builtRebuildGeneration = manifest.requestedRebuildGeneration;
    activeScene->waterSurfaceCache = std::move(manifest);
    activeScene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Building;

    auto installedCache = std::make_shared<WaterSurfaceCache>(std::move(result.cache));
    installedCache->gpuData.surfaceTable.clear();
    installedCache->gpuData.surfaceTable.shrink_to_fit();
    installedCache->gpuData.vegetationTable.clear();
    installedCache->gpuData.vegetationTable.shrink_to_fit();
    installedCache->gpuData.flowSurfaceTable.clear();
    installedCache->gpuData.flowSurfaceTable.shrink_to_fit();
    installedCache->gpuData.groundTable.clear();
    installedCache->gpuData.groundTable.shrink_to_fit();
    water.waterSurfaceCache = std::move(installedCache);
    water.waterSurfaceSceneGroupName = completedScene;
    water.waterSurfaceCacheSignature = completedSignature;
    water.waterSurfaceCacheLoadedFromDisk = result.loadedFromDisk;
    water.waterSurfaceCachePreprocessPending = true;
    water.waterSurfaceCacheWarnings = std::move(result.warnings);
    water.dynamicMeshFlowResetRequested = true;
    ++water.waterSurfaceCacheInstallCount;
    // Cancel any selection still reading the retired cache snapshot. The
    // settled descriptor/grid remains visible until a new identity-keyed
    // connected selection commits.
    water.seepageSupportJob = {};
    water.seepagePendingSupportSelections.clear();
    water.seepagePendingSupportNodeFingerprints.clear();
    water.seepageSupportFailedKeys.clear();
    // Queue new connected cell selections against the committed immutable
    // surfel cache; no display-cloud membership scan is involved.
    InvalidateWaterSeepageTopology(&water);
    const bool hasSurfaceGuidedManualFlow = std::any_of(
        water.manualFlowPaths.begin(),
        water.manualFlowPaths.end(),
        [](const WaterManualFlowPathSource& source) {
            return source.useSurfaceGuide && source.controlPoints.size() >= 2U;
        });
    if (hasSurfaceGuidedManualFlow) {
        // The manual path remains visible while this source-local rebuild runs.
        // Its fingerprint includes the immutable cache revision, so generated
        // point sources and unguided manual sources are reused unchanged.
        QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::InMemoryOnly);
    }
    runtimeState->statusMessage =
        std::string{result.loadedFromDisk ? "Loaded" : "Built"} +
        " shared water surface cache for " + completedScene + " (" +
        FormatPointCount(water.waterSurfaceCache->surfaceCells.size()) + " surface cells, " +
        FormatPointCount(water.waterSurfaceCache->vegetationVoxels.size()) + " vegetation voxels, " +
        FormatPointCount(water.waterSurfaceCache->flowSurfaceSurfels.size()) + " Flow surfels, " +
        FormatPointCount(water.waterSurfaceCache->groundCells.size()) + " Ground cells).";
    runtimeState->errorMessage.clear();
}

void EnsureWaterSurfaceCacheReady(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    PollWaterSurfaceCacheWarmup(runtimeState, viewport);
    if (const auto* scene = ActiveWaterSurfaceScene(runtimeState);
        scene != nullptr &&
        scene->waterSurfaceCacheStatus == WaterSurfaceCacheRuntimeStatus::Failed) {
        // Keep a failed build settled until the user explicitly requests a
        // replacement; otherwise a bad source would launch an unbounded CPU
        // rebuild loop on every frame.
        return;
    }
    if (runtimeState->water.waterSurfaceCachePreprocessPending) {
        const auto surfaceView = viewport->WaterSurfaceFlowView();
        const auto groundView = viewport->WaterGroundFlowView();
        const auto& installedCache = runtimeState->water.waterSurfaceCache;
        if (!WaterSurfaceResidentTablesReady(
                installedCache.get(),
                surfaceView,
                groundView,
                viewport->WaterSurfaceUploadPending())) {
            return;
        }
        runtimeState->water.waterSurfaceCachePreprocessPending = false;
        if (auto* scene = ActiveWaterSurfaceScene(runtimeState); scene != nullptr) {
            scene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Valid;
        }
    }
    if (runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
        runtimeState->pendingLoad.has_value()) {
        return;
    }
    auto* scene = ActiveWaterSurfaceScene(runtimeState);
    if (scene != nullptr) {
        StartWaterSurfaceCacheWarmup(runtimeState, viewport, scene);
    }
}

const char* WaterSurfaceCacheRuntimeStatusLabel(
    WaterSurfaceCacheRuntimeStatus status) {
    switch (status) {
        case WaterSurfaceCacheRuntimeStatus::Missing:
            return "missing";
        case WaterSurfaceCacheRuntimeStatus::Valid:
            return "valid";
        case WaterSurfaceCacheRuntimeStatus::Stale:
            return "stale";
        case WaterSurfaceCacheRuntimeStatus::Building:
            return "building";
        case WaterSurfaceCacheRuntimeStatus::Failed:
            return "failed";
    }
    return "unknown";
}

bool RequestWaterSurfaceCacheRebuild(PreviewRuntimeState* runtimeState) {
    auto* scene = ActiveWaterSurfaceScene(runtimeState);
    if (runtimeState == nullptr || scene == nullptr ||
        scene->waterSurfaceSources.empty() ||
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable()) {
        return false;
    }

    auto manifest = scene->waterSurfaceCache.value_or(
        WaterSurfaceCacheManifestDocument{});
    manifest.cacheSchema = invisible_places::water::kWaterSurfaceCacheSchemaVersion;
    manifest.algorithmId = std::string{invisible_places::water::kWaterSurfaceCacheAlgorithmId};
    manifest.sourceFingerprint = scene->waterSurfaceSignature;
    const auto generation = std::max(
        manifest.requestedRebuildGeneration,
        manifest.builtRebuildGeneration);
    if (generation == std::numeric_limits<std::uint64_t>::max()) {
        manifest.requestedRebuildGeneration = 1U;
        manifest.builtRebuildGeneration = 0U;
    } else {
        manifest.requestedRebuildGeneration = generation + 1U;
    }
    scene->waterSurfaceCache = std::move(manifest);
    scene->waterSurfaceCacheStatus = WaterSurfaceCacheRuntimeStatus::Stale;
    runtimeState->statusMessage =
        "Queued a clean water surface cache rebuild for " +
        scene->sceneGroupName + ". The settled cache remains active until the replacement is ready.";
    runtimeState->errorMessage.clear();
    return true;
}

std::string DynamicMeshSurfaceCacheSignature(
    const WaterDynamicMeshFlowSettings& settings,
    const std::filesystem::path& meshPath) {
    std::ostringstream signature;
    signature << meshPath.generic_string()
              << "|algo=height-plane-grid-v2"
              << "|cell=" << settings.cacheCellSizeMeters
              << "|search=" << settings.projectionSearchRadiusMeters
              << "|amb=" << settings.ambiguityHeightMeters;
    std::error_code error;
    const auto size = std::filesystem::file_size(meshPath, error);
    if (!error) {
        signature << "|bytes=" << size;
    }
    const auto writeTime = std::filesystem::last_write_time(meshPath, error);
    if (!error) {
        const auto writeTimeSeconds =
            std::chrono::duration_cast<std::chrono::seconds>(writeTime.time_since_epoch()).count();
        signature << "|mtime=" << static_cast<long long>(writeTimeSeconds);
    }
    return signature.str();
}

std::filesystem::path DynamicMeshSurfaceCachePathForSettings(
    const PreviewRuntimeState& runtimeState,
    const WaterDynamicMeshFlowSettings& settings) {
    if (const auto sceneMeshPath = ResolveDynamicMeshSceneSurfacePath(runtimeState); sceneMeshPath.has_value()) {
        return sceneMeshPath.value();
    }
    std::error_code meshStatusError;
    if (!settings.meshPath.empty() &&
        std::filesystem::is_regular_file(settings.meshPath, meshStatusError)) {
        return settings.meshPath;
    }
    return {};
}

bool DynamicMeshSurfaceWarmupActive(const WaterWorkflowState& water) {
    return water.dynamicMeshSurfaceCacheWarmup.worker.joinable();
}

std::optional<DynamicMeshSurfaceCacheWarmupResult> TakeDynamicMeshSurfaceWarmupResult(
    const std::shared_ptr<DynamicMeshSurfaceCacheWarmupShared>& shared) {
    if (shared == nullptr) {
        return std::nullopt;
    }
    std::scoped_lock lock(shared->mutex);
    if (!shared->result.has_value()) {
        return std::nullopt;
    }
    auto result = std::move(shared->result.value());
    shared->result.reset();
    return result;
}

bool InstallDynamicMeshSurfaceWarmupResult(
    PreviewRuntimeState* runtimeState,
    DynamicMeshSurfaceCacheWarmupResult result,
    bool publishStatus) {
    if (runtimeState == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    if (!result.success || result.cache == nullptr) {
        if (publishStatus && !result.errorMessage.empty()) {
            runtimeState->errorMessage = "Dynamic mesh cache prewarm failed: " + result.errorMessage;
            runtimeState->statusMessage.clear();
        }
        return false;
    }

    const auto requestedMeshPath = DynamicMeshSurfaceCachePathForSettings(*runtimeState, water.dynamicMeshFlowSettings);
    const auto requestedSignature =
        DynamicMeshSurfaceCacheSignature(water.dynamicMeshFlowSettings, requestedMeshPath);
    if (NormalizePathKey(result.meshPath) != NormalizePathKey(requestedMeshPath) ||
        result.signature != requestedSignature) {
        if (publishStatus) {
            runtimeState->statusMessage = "Ignored stale dynamic mesh cache prewarm result.";
            runtimeState->errorMessage.clear();
        }
        return false;
    }

    water.dynamicMeshSurfaceCache = std::move(result.cache);
    water.dynamicMeshSurfaceCachePath = result.meshPath;
    water.dynamicMeshSurfaceCacheSignature = result.signature;
    water.dynamicMeshFlowDiagnostics = result.diagnostics;
    if (publishStatus) {
        runtimeState->statusMessage =
            "Prewarmed dynamic mesh cache with " +
            FormatPointCount(water.dynamicMeshSurfaceCache->cells.size()) +
            " surface cells.";
        runtimeState->errorMessage.clear();
    }
    return true;
}

void StartDynamicMeshSurfaceCacheWarmup(PreviewRuntimeState* runtimeState, bool publishStatus) {
    if (runtimeState == nullptr) {
        return;
    }
    if (!kMeshFlowWaterRuntimeEnabled) {
        return;
    }
    auto& water = runtimeState->water;
    // This cache is only useful to the enabled Mesh Flow feature. In particular,
    // avoid parsing and indexing a multi-million-triangle mesh in parallel with
    // startup point-cloud loads.
    if (!water.dynamicMeshFlowSettings.enabled ||
        runtimeState->pendingLoad.has_value() ||
        !runtimeState->persistence.queuedLoads.empty() ||
        water.waterSurfaceCacheWarmup.worker.joinable() ||
        water.waterSurfaceCachePreprocessPending) {
        return;
    }
    const auto meshPath = DynamicMeshSurfaceCachePathForSettings(*runtimeState, water.dynamicMeshFlowSettings);
    if (meshPath.empty()) {
        return;
    }
    std::error_code meshStatusError;
    if (!std::filesystem::is_regular_file(meshPath, meshStatusError)) {
        if (publishStatus) {
            runtimeState->errorMessage =
                "Dynamic mesh flow surface was not found or was not readable: " +
                meshPath.string();
            runtimeState->statusMessage.clear();
        }
        return;
    }
    const auto signature = DynamicMeshSurfaceCacheSignature(water.dynamicMeshFlowSettings, meshPath);
    if (water.dynamicMeshSurfaceCache != nullptr &&
        NormalizePathKey(water.dynamicMeshSurfaceCachePath) == NormalizePathKey(meshPath) &&
        water.dynamicMeshSurfaceCacheSignature == signature) {
        return;
    }
    if (DynamicMeshSurfaceWarmupActive(water)) {
        return;
    }

    auto settings = water.dynamicMeshFlowSettings;
    settings.meshPath = meshPath;
    auto shared = std::make_shared<DynamicMeshSurfaceCacheWarmupShared>();
    {
        std::scoped_lock lock(shared->mutex);
        shared->stage = "Reading mesh";
    }
    std::jthread worker{
        [shared, settings, meshPath, signature](std::stop_token stopToken) {
            DynamicMeshSurfaceCacheWarmupResult result;
            result.meshPath = meshPath;
            result.signature = signature;
            const auto publishResult = [&](std::string stage) {
                std::scoped_lock lock(shared->mutex);
                shared->stage = std::move(stage);
                shared->result = std::move(result);
            };
            try {
                const auto loadStartedAt = std::chrono::steady_clock::now();
                auto loadResult = invisible_places::io::LoadTriangleMesh(meshPath);
                result.diagnostics.meshLoadMilliseconds = std::chrono::duration<double, std::milli>(
                    std::chrono::steady_clock::now() - loadStartedAt).count();
                if (stopToken.stop_requested()) {
                    result.errorMessage = "Dynamic mesh cache prewarm was cancelled.";
                    publishResult("Cancelled");
                    return;
                }
                if (!loadResult.success) {
                    result.errorMessage = loadResult.errorMessage;
                    publishResult("Failed");
                    return;
                }

                {
                    std::scoped_lock lock(shared->mutex);
                    shared->stage = "Building surface cache";
                }
                auto cache = std::make_shared<MeshSurfaceCache>(
                    invisible_places::water::BuildMeshSurfaceCache(loadResult.mesh, settings));
                if (stopToken.stop_requested()) {
                    result.errorMessage = "Dynamic mesh cache prewarm was cancelled.";
                    publishResult("Cancelled");
                    return;
                }
                if (cache->cells.empty()) {
                    result.errorMessage = "Dynamic mesh flow cache did not produce surface cells.";
                    publishResult("Failed");
                    return;
                }

                result.success = true;
                result.diagnostics.cacheBuildMilliseconds = cache->buildMilliseconds;
                result.diagnostics.sourceVertexCount = cache->sourceVertexCount;
                result.diagnostics.sourceTriangleCount = cache->sourceTriangleCount;
                result.diagnostics.cacheCellCount = static_cast<std::uint32_t>(std::min<std::size_t>(
                    cache->cells.size(),
                    static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())));
                result.cache = std::move(cache);
                publishResult("Ready");
            } catch (const std::exception& error) {
                result.success = false;
                result.cache.reset();
                result.errorMessage =
                    "Unexpected dynamic mesh cache prewarm failure: " +
                    std::string{error.what()};
                publishResult("Failed");
            } catch (...) {
                result.success = false;
                result.cache.reset();
                result.errorMessage = "Unknown dynamic mesh cache prewarm failure.";
                publishResult("Failed");
            }
        }};

    water.dynamicMeshSurfaceCacheWarmup = DynamicMeshSurfaceCacheWarmupJob{
        .shared = std::move(shared),
        .worker = std::move(worker),
        .meshPath = meshPath,
        .signature = signature,
        .startedAt = std::chrono::steady_clock::now(),
    };
    if (publishStatus) {
        runtimeState->statusMessage =
            "Prewarming dynamic mesh cache from " + meshPath.filename().string() + " in the background.";
        runtimeState->errorMessage.clear();
    }
}

void PollDynamicMeshSurfaceCacheWarmup(PreviewRuntimeState* runtimeState, bool publishStatus = false) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& job = runtimeState->water.dynamicMeshSurfaceCacheWarmup;
    if (job.shared == nullptr) {
        return;
    }
    auto result = TakeDynamicMeshSurfaceWarmupResult(job.shared);
    if (!result.has_value()) {
        return;
    }
    if (job.worker.joinable()) {
        job.worker.join();
    }
    InstallDynamicMeshSurfaceWarmupResult(runtimeState, std::move(result.value()), publishStatus);
    job = {};
}

bool FinishMatchingDynamicMeshSurfaceCacheWarmup(
    PreviewRuntimeState* runtimeState,
    const std::filesystem::path& meshPath,
    std::string_view signature) {
    if (runtimeState == nullptr) {
        return false;
    }
    auto& job = runtimeState->water.dynamicMeshSurfaceCacheWarmup;
    if (!job.worker.joinable() ||
        NormalizePathKey(job.meshPath) != NormalizePathKey(meshPath) ||
        job.signature != signature) {
        return false;
    }

    runtimeState->statusMessage = "Waiting for dynamic mesh cache prewarm to finish...";
    runtimeState->errorMessage.clear();
    job.worker.join();
    auto result = TakeDynamicMeshSurfaceWarmupResult(job.shared);
    job = {};
    if (!result.has_value()) {
        return false;
    }
    return InstallDynamicMeshSurfaceWarmupResult(runtimeState, std::move(result.value()), true);
}

void PopulateMeshSurfaceCacheDiagnostics(
    const MeshSurfaceCache& cache,
    WaterDynamicMeshFlowDiagnostics* diagnostics) {
    if (diagnostics == nullptr) {
        return;
    }
    diagnostics->cacheBuildMilliseconds = cache.buildMilliseconds;
    diagnostics->sourceVertexCount = cache.sourceVertexCount;
    diagnostics->sourceTriangleCount = cache.sourceTriangleCount;
    diagnostics->cacheCellCount = static_cast<std::uint32_t>(std::min<std::size_t>(
        cache.cells.size(),
        static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())));
}

std::shared_ptr<MeshSurfaceCache> EnsureDynamicMeshSurfaceCache(
    PreviewRuntimeState* runtimeState,
    WaterDynamicMeshFlowDiagnostics* diagnostics) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    auto& water = runtimeState->water;
    auto meshPath = DynamicMeshSurfaceCachePathForSettings(*runtimeState, water.dynamicMeshFlowSettings);
    if (meshPath.empty()) {
        runtimeState->errorMessage = "Dynamic mesh flow could not find a mesh PLY in the active scene folder.";
        runtimeState->statusMessage.clear();
        return nullptr;
    }
    std::error_code meshStatusError;
    if (!std::filesystem::is_regular_file(meshPath, meshStatusError)) {
        runtimeState->errorMessage = "Dynamic mesh flow surface was not found: " + meshPath.string();
        runtimeState->statusMessage.clear();
        return nullptr;
    }
    const auto signature = DynamicMeshSurfaceCacheSignature(water.dynamicMeshFlowSettings, meshPath);
    if (water.dynamicMeshSurfaceCache != nullptr &&
        NormalizePathKey(water.dynamicMeshSurfaceCachePath) == NormalizePathKey(meshPath) &&
        water.dynamicMeshSurfaceCacheSignature == signature) {
        if (diagnostics != nullptr) {
            diagnostics->cacheBuildMilliseconds = water.dynamicMeshSurfaceCache->buildMilliseconds;
            diagnostics->sourceVertexCount = water.dynamicMeshSurfaceCache->sourceVertexCount;
            diagnostics->sourceTriangleCount = water.dynamicMeshSurfaceCache->sourceTriangleCount;
            diagnostics->cacheCellCount = static_cast<std::uint32_t>(std::min<std::size_t>(
                water.dynamicMeshSurfaceCache->cells.size(),
                static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())));
        }
        return water.dynamicMeshSurfaceCache;
    }
    if (FinishMatchingDynamicMeshSurfaceCacheWarmup(runtimeState, meshPath, signature)) {
        if (diagnostics != nullptr && water.dynamicMeshSurfaceCache != nullptr) {
            diagnostics->cacheBuildMilliseconds = water.dynamicMeshSurfaceCache->buildMilliseconds;
            diagnostics->sourceVertexCount = water.dynamicMeshSurfaceCache->sourceVertexCount;
            diagnostics->sourceTriangleCount = water.dynamicMeshSurfaceCache->sourceTriangleCount;
            diagnostics->cacheCellCount = static_cast<std::uint32_t>(std::min<std::size_t>(
                water.dynamicMeshSurfaceCache->cells.size(),
                static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())));
        }
        return water.dynamicMeshSurfaceCache;
    }

    const auto loadStartedAt = std::chrono::steady_clock::now();
    auto loadResult = invisible_places::io::LoadTriangleMesh(meshPath);
    const double loadMs = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - loadStartedAt).count();
    if (!loadResult.success) {
        runtimeState->errorMessage = "Dynamic mesh flow load failed: " + loadResult.errorMessage;
        runtimeState->statusMessage.clear();
        return nullptr;
    }
    auto cacheSettings = water.dynamicMeshFlowSettings;
    cacheSettings.meshPath = meshPath;
    auto cache = std::make_shared<MeshSurfaceCache>(
        invisible_places::water::BuildMeshSurfaceCache(loadResult.mesh, cacheSettings));
    if (cache->cells.empty()) {
        runtimeState->errorMessage = "Dynamic mesh flow cache did not produce surface cells.";
        runtimeState->statusMessage.clear();
        return nullptr;
    }
    water.dynamicMeshSurfaceCache = cache;
    water.dynamicMeshSurfaceCachePath = meshPath;
    water.dynamicMeshSurfaceCacheSignature = signature;
    if (diagnostics != nullptr) {
        diagnostics->meshLoadMilliseconds = loadMs;
        diagnostics->cacheBuildMilliseconds = cache->buildMilliseconds;
        diagnostics->sourceVertexCount = cache->sourceVertexCount;
        diagnostics->sourceTriangleCount = cache->sourceTriangleCount;
        diagnostics->cacheCellCount = static_cast<std::uint32_t>(std::min<std::size_t>(
            cache->cells.size(),
            static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max())));
    }
    return cache;
}

bool RefreshWaterDynamicMeshFlowOverlay(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    WaterTrailBuildQuality quality = WaterTrailBuildQuality::Preview) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    if (!kMeshFlowWaterRuntimeEnabled ||
        !water.dynamicMeshFlowSettings.enabled) {
        water.dynamicMeshTrailOverlay = {};
        water.dynamicMeshFlowDiagnostics = {};
        water.lastDynamicMeshTrailOverlayPath.clear();
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-DynamicMeshTrails");
        runtimeState->statusMessage =
            kMeshFlowWaterRuntimeEnabled
                ? "Dynamic mesh flow disabled."
                : "Mesh Flow is inactive; authored settings were preserved.";
        runtimeState->errorMessage.clear();
        return true;
    }
    if (water.emitters.empty()) {
        water.dynamicMeshTrailOverlay = {};
        water.dynamicMeshFlowDiagnostics = {};
        water.lastDynamicMeshTrailOverlayPath.clear();
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-DynamicMeshTrails");
        runtimeState->errorMessage = "Add at least one water source before generating dynamic mesh flow.";
        runtimeState->statusMessage.clear();
        return false;
    }

    WaterDynamicMeshFlowDiagnostics diagnostics;
    auto cache = EnsureDynamicMeshSurfaceCache(runtimeState, &diagnostics);
    if (cache == nullptr) {
        return false;
    }
    const auto profile = ViewedDynamicMeshWaterTrailProfile(*runtimeState);
    auto solveSettings = water.dynamicMeshFlowSettings;
    solveSettings.trailWidthMeters = profile.geometry.widthMeters;
    solveSettings.trailStreakLengthMeters = profile.geometry.streakLengthMeters;
    PreviewLayerSession meshSession;
    meshSession.sourcePath = water.dynamicMeshSurfaceCachePath.empty()
                                 ? water.dynamicMeshFlowSettings.meshPath
                                 : water.dynamicMeshSurfaceCachePath;
    const auto outputPath = BuildWaterFeatureOverlayPath(*runtimeState, meshSession, "-DynamicMeshTrails.generated");
    if (quality == WaterTrailBuildQuality::Preview && solveSettings.gpuPreviewEnabled) {
        try {
            invisible_places::renderer::core::DynamicMeshFlowGpuUploadResult gpuResult;
            const auto sessionIndex = AddOrRefreshDynamicMeshGpuTrailOverlaySession(
                runtimeState,
                viewport,
                outputPath,
                *cache,
                solveSettings,
                water.emitters,
                profile,
                quality,
                &gpuResult);
            if (sessionIndex != std::numeric_limits<std::size_t>::max()) {
                diagnostics.emittedPathCount = gpuResult.particleCount;
                diagnostics.emittedSampleCount = gpuResult.pointCount;
                diagnostics.solveMilliseconds = gpuResult.solveMilliseconds;
                diagnostics.gpuStaticUploadMilliseconds = gpuResult.staticUploadMilliseconds;
                diagnostics.gpuLiveUploadMilliseconds = gpuResult.liveUploadMilliseconds;
                diagnostics.gpuDispatchMilliseconds = gpuResult.dispatchMilliseconds;
                diagnostics.gpuStaticBuffersReused = gpuResult.reusedStaticBuffers;
                diagnostics.gpuAsynchronousDispatch = gpuResult.asynchronousDispatch;
                water.dynamicMeshFlowDiagnostics = diagnostics;
                water.dynamicMeshTrailOverlay = {};
                water.lastDynamicMeshTrailOverlayPath = outputPath;
                runtimeState->statusMessage =
                    "GPU previewed dynamic mesh flow with " +
                    FormatPointCount(gpuResult.particleCount) + " paths and " +
                    FormatPointCount(gpuResult.pointCount) + " trail points.";
                runtimeState->errorMessage.clear();
                return true;
            }
        } catch (const std::exception& error) {
            runtimeState->errorMessage =
                "Dynamic mesh flow GPU preview failed; falling back to CPU preview: " +
                std::string{error.what()};
        }
    }

    auto overlay = invisible_places::water::BuildDynamicMeshWaterTrailOverlay(
        *cache,
        water.emitters,
        solveSettings,
        quality,
        &diagnostics);
    water.dynamicMeshFlowDiagnostics = diagnostics;
    if (overlay.samples.empty()) {
        water.dynamicMeshTrailOverlay = {};
        water.lastDynamicMeshTrailOverlayPath.clear();
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-DynamicMeshTrails");
        runtimeState->errorMessage = "Dynamic mesh flow generated no visible trail samples.";
        runtimeState->statusMessage.clear();
        return false;
    }

    water.lastDynamicMeshTrailOverlayPath = outputPath;
    water.dynamicMeshTrailOverlay = overlay;
    AddOrRefreshWaterTrailOverlaySession(
        runtimeState,
        viewport,
        outputPath,
        std::move(overlay),
        profile.name,
        false,
        profile.style);
    runtimeState->statusMessage =
        std::string{quality == WaterTrailBuildQuality::Preview ? "Previewed" : "Generated"} +
        " dynamic mesh flow with " + FormatPointCount(diagnostics.emittedPathCount) +
        " paths and " + FormatPointCount(diagnostics.emittedSampleCount) + " samples.";
    runtimeState->errorMessage.clear();
    return true;
}

// Mesh Flow is a persistent GPU simulation over the installed shared Ground
// table. This per-frame call only rotates parameter buffers unless the cache
// identity or the two explicit capacity controls changed.
struct WaterDynamicMeshFlowUpdateOptions {
    const WaterDynamicMeshFlowSettings* settings = nullptr;
    std::optional<std::size_t> sessionIndex;
    std::optional<float> deltaSeconds;
    bool resetSimulation = false;
};

// How long after effective activity reaches zero the Mesh Flow simulation
// can still change pixels: flowing particles finish their terminal fade over
// contactFadeSeconds while contact shading on the host clouds persists (and
// twinkles) for the response persistence windows.
float DynamicMeshFlowQuiescenceTailSeconds(
    const invisible_places::water::WaterDynamicMeshFlowSettings& settings) {
    return std::max(
        {std::max(0.01F, settings.contactFadeSeconds),
         settings.rockResponse.persistenceSeconds,
         settings.vegetationResponse.persistenceSeconds});
}

// True when the Mesh Flow simulation provably has nothing on screen and
// nothing still draining: activity has been zero past the fade/persistence
// tail (activity == 0 empties the population gate exactly, so every particle
// has fully faded to Inactive) and the contact-event readback — which lags
// stale-high, never stale-low — reports no live contact shading.
bool DynamicMeshFlowIsQuiescent(
    const PreviewRuntimeState& runtimeState,
    float nowSeconds) {
    const auto& water = runtimeState.water;
    if (water.dynamicMeshFlowContactEventCount > 0U) {
        return false;
    }
    return water.dynamicMeshFlowLastActiveSeconds < 0.0F ||
           nowSeconds - water.dynamicMeshFlowLastActiveSeconds >
               DynamicMeshFlowQuiescenceTailSeconds(
                   water.dynamicMeshFlowSettings);
}

bool EnsureWaterDynamicMeshFlowGpuUpToDate(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const WaterFrameState& frameState,
    float timeSeconds,
    const WaterDynamicMeshFlowUpdateOptions* updateOptions = nullptr) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    auto& liveSettings = water.dynamicMeshFlowSettings;
    if (!kMeshFlowWaterRuntimeEnabled) {
        if (water.dynamicMeshFlowGpuSessionIndex.has_value() &&
            water.dynamicMeshFlowGpuSessionIndex.value() <
                runtimeState->sessions.size()) {
            runtimeState
                ->sessions[water.dynamicMeshFlowGpuSessionIndex.value()]
                .visible = false;
        }
        return false;
    }
    // Disabled is the common idle state: skip the ground-view and active-
    // scene lookups (they normalize scene/session paths every frame) and
    // only keep the overlay session hidden.
    if (updateOptions == nullptr && !liveSettings.enabled) {
        if (water.dynamicMeshFlowGpuSessionIndex.has_value() &&
            water.dynamicMeshFlowGpuSessionIndex.value() <
                runtimeState->sessions.size()) {
            runtimeState
                ->sessions[water.dynamicMeshFlowGpuSessionIndex.value()]
                .visible = false;
        }
        return false;
    }
    auto settings = invisible_places::water::SanitizeWaterDynamicMeshFlowSettings(
        updateOptions != nullptr && updateOptions->settings != nullptr
            ? *updateOptions->settings
            : liveSettings);
    const auto groundView = viewport->WaterGroundFlowView();
    ScenePointCloudRuntime* scene = nullptr;
    if (updateOptions != nullptr &&
        updateOptions->sessionIndex.has_value() &&
        updateOptions->sessionIndex.value() < runtimeState->sessions.size()) {
        const auto& frozenSession =
            runtimeState->sessions[updateOptions->sessionIndex.value()];
        const auto sceneIt = std::find_if(
            runtimeState->pointCloudScenes.begin(),
            runtimeState->pointCloudScenes.end(),
            [&](const ScenePointCloudRuntime& candidate) {
                return candidate.sceneGroupName == frozenSession.sceneGroupName &&
                       NormalizePathKey(candidate.sourceFolder) ==
                           NormalizePathKey(
                               frozenSession.sourcePath.parent_path());
            });
        if (sceneIt != runtimeState->pointCloudScenes.end() &&
            SceneHasCommittedWaterSurfaceDisplay(*runtimeState, *sceneIt)) {
            scene = &*sceneIt;
        }
    } else {
        scene = ActiveWaterSurfaceScene(runtimeState);
    }
    const bool cacheMatchesActiveScene =
        scene != nullptr &&
        water.waterSurfaceCache != nullptr &&
        water.waterSurfaceSceneGroupName == scene->sceneGroupName &&
        water.waterSurfaceCacheSignature == scene->waterSurfaceSignature &&
        water.waterSurfaceCache->signature == scene->waterSurfaceSignature &&
        groundView.cacheIdentity != nullptr &&
        *groundView.cacheIdentity == water.waterSurfaceCache->cacheIdentity;
    if (!settings.enabled || !groundView.valid ||
        water.waterSurfaceCache == nullptr ||
        water.waterSurfaceCachePreprocessPending ||
        !cacheMatchesActiveScene) {
        if (water.dynamicMeshFlowGpuSessionIndex.has_value() &&
            water.dynamicMeshFlowGpuSessionIndex.value() < runtimeState->sessions.size()) {
            runtimeState->sessions[water.dynamicMeshFlowGpuSessionIndex.value()].visible = false;
        }
        return false;
    }

    const auto overlayPath =
        scene->sourceFolder /
        (scene->sceneGroupName + "-DynamicMeshTrails.generated");
    auto sessionIndex =
        updateOptions != nullptr && updateOptions->sessionIndex.has_value()
            ? updateOptions->sessionIndex
            : water.dynamicMeshFlowGpuSessionIndex;
    if (!sessionIndex.has_value() ||
        sessionIndex.value() >= runtimeState->sessions.size() ||
        !PathsReferToSameLocation(
            runtimeState->sessions[sessionIndex.value()].sourcePath,
            overlayPath)) {
        if (updateOptions != nullptr &&
            updateOptions->sessionIndex.has_value()) {
            return false;
        }
        if (sessionIndex.has_value() &&
            sessionIndex.value() < runtimeState->sessions.size()) {
            runtimeState->sessions[sessionIndex.value()].visible = false;
        }
        sessionIndex = FindSessionIndexBySourcePath(*runtimeState, overlayPath);
        water.dynamicMeshFlowResetRequested = true;
    }
    if (!sessionIndex.has_value()) {
        PreviewLayerSession session;
        session.kind = LayerKind::PointCloud;
        session.sourcePath = overlayPath;
        session.displayName = scene->sceneGroupName + " Ground Mesh Flow";
        session.sceneGroupName = scene->sceneGroupName;
        runtimeState->sessions.push_back(std::move(session));
        sessionIndex = runtimeState->sessions.size() - 1U;
        water.dynamicMeshFlowResetRequested = true;
    }

    const float activity =
        invisible_places::water::EffectiveWaterDynamicMeshFlowLevel(
            settings,
            frameState.meshFlowMoisture,
            &frameState.featureOverlay);
    if (updateOptions == nullptr) {
        if (timeSeconds < water.dynamicMeshFlowLastActiveSeconds) {
            // Different pump paths drive this function with different time
            // bases (live wall clock, smoke simulation clocks). A backwards
            // step means the stamp belongs to another base; restart the
            // quiescence tail from now rather than comparing across bases.
            water.dynamicMeshFlowLastActiveSeconds = timeSeconds;
        }
        if (activity > 0.0F) {
            water.dynamicMeshFlowLastActiveSeconds = timeSeconds;
        } else if (
            !water.dynamicMeshFlowResetRequested &&
            DynamicMeshFlowIsQuiescent(*runtimeState, timeSeconds)) {
            // The simulation is provably empty and its contact shading has
            // drained, so dispatching would only re-simulate an all-Inactive
            // population — and the dispatch path unconditionally bumps the
            // viewport's scene revision, forcing a full re-render of every
            // point layer each frame. Skip it until activity returns.
            // Advancing the update clock keeps the resume path free of a
            // spurious time-discontinuity reset; resuming from an empty
            // population spawns exactly as an uninterrupted zero-activity
            // simulation would.
            water.dynamicMeshFlowLastUpdateSeconds = timeSeconds;
            // Session bookkeeping the skipped path would otherwise perform:
            // Show Trails must keep tracking the overlay session's
            // visibility (renderer-mode selection and export snapshots read
            // it) even while no dispatch is needed.
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState->sessions.size()) {
                runtimeState->sessions[sessionIndex.value()].visible =
                    settings.showTrails;
            }
            return true;
        }
        if (!settings.showTrails) {
            // Hidden trails draw nothing, yet the dispatch path
            // unconditionally bumps the viewport's scene revision and
            // re-renders every point layer each frame. Freeze the
            // simulation while it is invisible; advancing the update clock
            // (exactly like the quiescence skip above) lets it resume
            // without a spurious time-discontinuity reset, and a pending
            // reset request stays latched for the next visible dispatch.
            water.dynamicMeshFlowLastUpdateSeconds = timeSeconds;
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState->sessions.size()) {
                runtimeState->sessions[sessionIndex.value()].visible = false;
            }
            return true;
        }
    }
    const float deltaSeconds =
        updateOptions != nullptr &&
                updateOptions->deltaSeconds.has_value()
            ? std::clamp(
                  updateOptions->deltaSeconds.value(),
                  0.0F,
                  0.10F)
            : (water.dynamicMeshFlowLastUpdateSeconds > 0.0F &&
                       timeSeconds >=
                           water.dynamicMeshFlowLastUpdateSeconds
                   ? std::clamp(
                         timeSeconds -
                             water.dynamicMeshFlowLastUpdateSeconds,
                         1.0F / 240.0F,
                         1.0F / 15.0F)
                   : 1.0F / 30.0F);
    const bool timeDiscontinuity =
        water.dynamicMeshFlowLastUpdateSeconds > 0.0F &&
        (timeSeconds < water.dynamicMeshFlowLastUpdateSeconds ||
         timeSeconds - water.dynamicMeshFlowLastUpdateSeconds > 0.50F);
    invisible_places::renderer::core::DynamicMeshFlowGpuFrameRequest request{
        .settings = settings,
        .activity = activity,
        .moisture = frameState.meshFlowMoisture,
        .timeSeconds = timeSeconds,
        .deltaSeconds = deltaSeconds,
        .resetSimulation =
            water.dynamicMeshFlowResetRequested ||
            timeDiscontinuity ||
            (updateOptions != nullptr &&
             updateOptions->resetSimulation),
    };

    invisible_places::renderer::core::DynamicMeshFlowGpuUpdateResult result;
    try {
        result = viewport->UpdateDynamicMeshFlowGpuSimulation(
            sessionIndex.value(),
            request);
    } catch (const std::exception& error) {
        runtimeState->errorMessage =
            "GPU Ground Mesh Flow update failed: " + std::string{error.what()};
        runtimeState->statusMessage.clear();
        return false;
    }
    if (!result.sharedGroundReady || result.pointCount == 0U) {
        return false;
    }

    if (updateOptions == nullptr ||
        updateOptions->settings == nullptr) {
        liveSettings = request.settings;
    }
    water.dynamicMeshFlowGpuSessionIndex = sessionIndex;
    water.dynamicMeshFlowLastUpdateSeconds = timeSeconds;
    water.dynamicMeshFlowResetRequested = false;
    water.dynamicMeshFlowDiagnostics.solveMilliseconds =
        result.allocationMilliseconds + result.parameterUploadMilliseconds +
        result.dispatchMilliseconds;
    water.dynamicMeshFlowDiagnostics.gpuStaticUploadMilliseconds =
        result.allocationMilliseconds;
    water.dynamicMeshFlowDiagnostics.gpuLiveUploadMilliseconds =
        result.parameterUploadMilliseconds;
    water.dynamicMeshFlowDiagnostics.gpuDispatchMilliseconds =
        result.dispatchMilliseconds;
    water.dynamicMeshFlowDiagnostics.cacheCellCount = groundView.occupiedCellCount;
    water.dynamicMeshFlowDiagnostics.emittedPathCount = result.activeParticles;
    water.dynamicMeshFlowDiagnostics.emittedSampleCount = result.pointCount;
    water.dynamicMeshFlowDiagnostics.automaticEntryCandidateCount =
        result.entryCandidateCount;
    water.dynamicMeshFlowDiagnostics.availableRainSeedCount =
        result.rainSeedCount;
    water.dynamicMeshFlowDiagnostics.rainSeedParticleCount =
        result.usedRainSeedParticleCount;
    water.dynamicMeshFlowDiagnostics.routeSampleCount =
        result.routeSampleCount;
    water.dynamicMeshFlowDiagnostics.routeWithinGroundBoundsFraction =
        result.routeWithinGroundBoundsFraction;
    water.dynamicMeshFlowDiagnostics.routeWithinSurfaceToleranceFraction =
        result.routeWithinSurfaceToleranceFraction;
    water.dynamicMeshFlowDiagnostics.maximumRenderedSegmentMeters =
        result.maximumRenderedSegmentMeters;
    water.dynamicMeshFlowDiagnostics.longSegmentCount =
        result.longSegmentCount;
    water.dynamicMeshFlowDiagnostics.unexplainedVerticalJumpCount =
        result.unexplainedVerticalJumpCount;
    water.dynamicMeshFlowDiagnostics.medianTangentDownhillAlignment =
        result.medianTangentDownhillAlignment;
    water.dynamicMeshFlowDiagnostics.gpuStaticBuffersReused =
        !result.allocatedThisUpdate;
    water.dynamicMeshFlowDiagnostics.gpuAsynchronousDispatch =
        result.asynchronousDispatch;
    water.dynamicMeshFlowAllocationRevision = result.allocationRevision;
    water.dynamicMeshFlowParameterRevision = result.parameterRevision;
    water.dynamicMeshFlowDescriptorGeneration = result.descriptorGeneration;
    water.dynamicMeshFlowDispatchCount = result.dispatchCount;
    water.dynamicMeshFlowSharedGroundUploadRevision =
        result.sharedGroundUploadRevision;
    water.dynamicMeshFlowContactEventCount = result.contactEvents;

    auto& session = runtimeState->sessions[sessionIndex.value()];
    session.kind = LayerKind::PointCloud;
    session.sourcePath = overlayPath;
    session.displayName = scene->sceneGroupName + " Ground Mesh Flow";
    session.sceneGroupName = scene->sceneGroupName;
    session.hasSourceRgb = true;
    session.hasNormals = true;
    session.dynamicMeshFlowGpuPreview = true;
    session.totalPrimitives = result.pointCount;
    session.scalarFields =
        invisible_places::water::WaterTrailOverlayScalarFieldsForPointCount(
            result.pointCount);
    session.bounds = groundView.bounds;
    if (session.bounds.valid) {
        session.bounds.minimum.z += settings.surfaceOffsetMeters;
        session.bounds.maximum.z += settings.surfaceOffsetMeters;
        session.focusPoint = {
            (session.bounds.minimum.x + session.bounds.maximum.x) * 0.5F,
            (session.bounds.minimum.y + session.bounds.maximum.y) * 0.5F,
            (session.bounds.minimum.z + session.bounds.maximum.z) * 0.5F,
        };
        session.hasFocusPoint = true;
    }
    session.localBounds = session.bounds;
    session.localFocusPoint = session.focusPoint;
    session.hasLocalFocusPoint = session.hasFocusPoint;
    session.loaded = true;
    session.gpuResident = true;
    session.cpuResident = false;
    session.visible = settings.showTrails;
    session.offlinePointCloud.reset();
    session.pointBudget = invisible_places::renderer::pointcloud::MakePointBudgetState(
        result.pointCount,
        result.pointCount);
    session.pointStyle = MakeDynamicMeshFlowTrailStyle(settings);
    session.pointStyle.flowAnimation = true;
    session.pointStyle.waterTrailOverlay = true;
    // The shared trail shader multiplies a per-trail activity gate and an
    // appearance scale on top of the activity-squared population count. A
    // square-root curve here keeps zero at zero but lets the surviving
    // trails render clearly at the low activity levels the scenarios use.
    session.pointStyle.waterFlowActivity =
        std::sqrt(std::clamp(activity, 0.0F, 1.0F));
    session.selectedPointVisualName = "Subtle Ground Trickles";
    session.pointVisualNameBuffer =
        BaseWaterProfileName(session.selectedPointVisualName);
    if (session.pointVisuals.empty()) {
        session.pointVisuals.push_back({
            .name = session.selectedPointVisualName,
            .style = session.pointStyle,
        });
    } else {
        UpsertPointVisual(
            &session,
            session.selectedPointVisualName,
            session.pointStyle);
    }
    return true;
}

bool RefreshWaterDynamicMeshFlowOverlayIfWarm(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr ||
        !kMeshFlowWaterRuntimeEnabled) {
        return false;
    }
    if (!runtimeState->water.dynamicMeshFlowSettings.enabled ||
        !viewport->WaterGroundFlowView().valid) {
        return false;
    }
    runtimeState->previewRenderStateSignatureValid = false;
    return true;
}

bool RefreshWaterDynamicMeshFlowOverlayFromUiEdit(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr ||
        !kMeshFlowWaterRuntimeEnabled) {
        return false;
    }
    if (!runtimeState->water.dynamicMeshFlowSettings.enabled) {
        return false;
    }
    (void)viewport;
    ++runtimeState->water.dynamicMeshFlowParameterUpdateCount;
    runtimeState->previewRenderStateSignatureValid = false;
    runtimeState->statusMessage =
        "Updated resident Mesh Flow parameters without resetting particles; "
        "the shared Ground cache remains settled.";
    runtimeState->errorMessage.clear();
    return true;
}

std::optional<invisible_places::io::Float3> ProjectScreenRayToDynamicMeshSurface(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    const MeshSurfaceCache& cache,
    ImVec2 screenPoint) {
    const auto matrices = runtimeState.camera.Matrices(CurrentAspectRatio(viewport));
    const auto ray = MakeScreenRay(matrices, viewport, screenPoint);
    if (!ray.has_value()) {
        return std::nullopt;
    }
    const auto projection = invisible_places::water::ProjectRayToMeshSurface(
        cache,
        FromGlm(ray->origin),
        FromGlm(ray->direction));
    if (!projection.hit) {
        return std::nullopt;
    }
    return projection.position;
}

std::optional<invisible_places::io::Float3> ProjectScreenPointToDynamicMeshSurfaceForPlacement(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint,
    std::string_view label) {
    if (runtimeState == nullptr || !runtimeState->water.dynamicMeshFlowSettings.enabled) {
        return std::nullopt;
    }

    const auto visiblePivot = ResolveWaterSourcePlacementPivot(
        *runtimeState,
        viewport,
        screenPoint);
    if (visiblePivot.has_value()) {
        if (runtimeState->water.waterSurfaceCache != nullptr) {
            const auto ground = invisible_places::water::QueryWaterGroundCache(
                *runtimeState->water.waterSurfaceCache,
                visiblePivot->point,
                0.75F);
            if (ground.hit) {
                const float resolution =
                    runtimeState->water.waterSurfaceCache->resolutionMeters;
                return invisible_places::io::Float3{
                    (static_cast<float>(ground.cell.cellX) + 0.5F) * resolution,
                    (static_cast<float>(ground.cell.cellY) + 0.5F) * resolution,
                    ground.cell.height,
                };
            }
        }
        return visiblePivot->point;
    }

    runtimeState->errorMessage =
        "Could not place " + std::string{label} +
        " on visible scene depth or the resident Ground cache.";
    runtimeState->statusMessage.clear();
    return std::nullopt;
}

bool RefreshWaterFieldOverlays(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (!kFieldWaterRuntimeEnabled) {
        return false;
    }
    if (!EnsureSceneAnalysisReadyForAction(
            runtimeState,
            DeferredSceneAnalysisAction::RefreshWaterField,
            "Field Recalculate Effects")) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->errorMessage = "Please wait for the current layer load before building the water field.";
        runtimeState->statusMessage.clear();
        return false;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage =
            "Canonical analysis sources are still loading or unavailable; the water field cannot be built.";
        runtimeState->statusMessage.clear();
        return false;
    }
    auto& sourceSession = runtimeState->sessions[supportIndex.value()];
    std::vector<WaterEffectLayer> candidateFieldLayers;
    for (const auto& layer : runtimeState->water.fieldLayers) {
        const bool fieldControlLayer =
            layer.featureType == WaterEffectFeatureType::FieldSurfaceMotion ||
            layer.featureType == WaterEffectFeatureType::FieldNoFlowRegion ||
            layer.featureType == WaterEffectFeatureType::FieldBridgeAllowedRegion ||
            layer.featureType == WaterEffectFeatureType::FieldBridgeBlockedRegion;
        if (fieldControlLayer &&
            layer.enabledInViewport &&
            layer.vertices.size() >= 3U &&
            WaterEffectLayerTargetsSession(*runtimeState, layer, sourceSession, layer.featureType)) {
            candidateFieldLayers.push_back(MaterializeWaterEffectLayerForSession(layer, sourceSession));
        }
    }
    auto targetFieldLayers = candidateFieldLayers;
    bool hasFieldSurfaceRegion = false;
    for (const auto& layer : targetFieldLayers) {
        hasFieldSurfaceRegion = hasFieldSurfaceRegion ||
                                layer.featureType == WaterEffectFeatureType::FieldSurfaceMotion;
    }
    if (!candidateFieldLayers.empty() && targetFieldLayers.empty()) {
        runtimeState->water.fieldCache = {};
        runtimeState->water.fieldTrailOverlay = {};
        runtimeState->water.fieldSurfaceEffectOverlay = {};
        runtimeState->water.lastFieldTrailOverlayPath.clear();
        runtimeState->water.lastFieldSurfaceOverlayPath.clear();
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-FieldTrails");
        UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-FieldSurface");
        std::vector<WaterEffectOverlay> compositionOverlays;
        if (!ApplyWaterEffectCompositionToDisplaySources(
                runtimeState,
                viewport,
                sourceSession,
                compositionOverlays,
                false)) {
            return false;
        }
        runtimeState->water.fieldEffectsDirty = false;
        ClearWaterFieldRegionEffectsDirty(&runtimeState->water);
        runtimeState->water.fieldCache.stale = false;
        ++runtimeState->water.regionEffectOutputRevision;
        ++runtimeState->water.regionCompositionRevision;
        runtimeState->statusMessage = "Field effects are hidden by Show Region Points.";
        runtimeState->errorMessage.clear();
        return true;
    }
    const auto fieldSettingsFingerprint =
        invisible_places::water::WaterFieldSettingsFingerprint(runtimeState->water.fieldSettings);
    const auto fieldRegionFingerprint =
        hasFieldSurfaceRegion
            ? invisible_places::water::WaterEffectLayersFingerprint(targetFieldLayers)
            : std::string{"path:"} + WaterEmitterSettingsFingerprint(*runtimeState);
    bool fieldCacheLoadedFromDisk = false;
    if (hasFieldSurfaceRegion &&
        TryLoadWaterFieldCacheForSupport(
            runtimeState,
            sourceSession,
            fieldSettingsFingerprint,
            fieldRegionFingerprint)) {
        fieldCacheLoadedFromDisk = true;
    } else if (hasFieldSurfaceRegion) {
        runtimeState->water.fieldCache = invisible_places::water::BuildFieldCacheFromRegions(
            *sourceSession.offlinePointCloud,
            targetFieldLayers,
            runtimeState->water.fieldSettings);
        if (!runtimeState->water.fieldCache.nodes.empty()) {
            SaveWaterFieldCacheForSupport(
                runtimeState,
                sourceSession,
                fieldSettingsFingerprint,
                fieldRegionFingerprint);
        }
    } else {
        if (runtimeState->water.pathAnchors.points.empty()) {
            if (runtimeState->water.pathCacheLoaded && !runtimeState->water.pathCache.branches.empty()) {
                runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
            }
        }
        if (runtimeState->water.pathAnchors.points.empty()) {
            if (!runtimeState->water.fieldSurfaceEffectOverlay.points.empty() ||
                !runtimeState->water.fieldTrailOverlay.samples.empty()) {
                runtimeState->water.fieldCache = {};
                runtimeState->water.fieldTrailOverlay = {};
                runtimeState->water.fieldSurfaceEffectOverlay = {};
                runtimeState->water.lastFieldTrailOverlayPath.clear();
                runtimeState->water.lastFieldSurfaceOverlayPath.clear();
                UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-FieldTrails");
                UnloadGeneratedWaterOverlaySessionsWithStemSuffix(runtimeState, viewport, "-FieldSurface");
                std::vector<WaterEffectOverlay> compositionOverlays;
                if (!ApplyWaterEffectCompositionToDisplaySources(
                        runtimeState,
                        viewport,
                        sourceSession,
                        compositionOverlays,
                        false)) {
                    return false;
                }
                runtimeState->water.fieldEffectsDirty = false;
                ClearWaterFieldRegionEffectsDirty(&runtimeState->water);
                runtimeState->water.fieldCache.stale = false;
                ++runtimeState->water.regionEffectOutputRevision;
                ++runtimeState->water.regionCompositionRevision;
                runtimeState->statusMessage = "Cleared field region effects.";
                runtimeState->errorMessage.clear();
                return true;
            }
            runtimeState->errorMessage = "Bake Flow paths or draw a Field region before building Field trails.";
            runtimeState->statusMessage.clear();
            return false;
        }
        runtimeState->water.fieldCache = invisible_places::water::BuildFieldCacheFromPathAnchors(
            runtimeState->water.pathAnchors,
            runtimeState->water.fieldSettings);
        StampWaterFieldCacheForSupport(
            runtimeState,
            sourceSession,
            fieldSettingsFingerprint,
            fieldRegionFingerprint);
    }
    ++runtimeState->water.fieldCacheRevision;
    if (runtimeState->water.fieldCache.nodes.empty()) {
        runtimeState->errorMessage = "Field cache did not produce any surface-supported nodes.";
        runtimeState->statusMessage.clear();
        return false;
    }

    std::size_t outputPoints = 0;
    if (runtimeState->water.fieldSettings.outputMode == WaterFieldOutputMode::Trails ||
        runtimeState->water.fieldSettings.outputMode == WaterFieldOutputMode::Both) {
        auto trailOverlay = invisible_places::water::BuildFieldTrailOverlay(
            runtimeState->water.fieldCache,
            runtimeState->water.fieldTrailSettings,
            runtimeState->water.emitters);
        outputPoints += trailOverlay.samples.size();
        runtimeState->water.fieldTrailOverlay = trailOverlay;
        const auto outputPath = BuildWaterFeatureOverlayPath(
            *runtimeState,
            sourceSession,
            "-FieldTrails.generated");
        runtimeState->water.lastFieldTrailOverlayPath = outputPath;
        AddOrRefreshWaterTrailOverlaySession(
            runtimeState,
            viewport,
            outputPath,
            trailOverlay,
            "Water Flow_preset",
            false);
    }

    if (runtimeState->water.fieldSettings.outputMode == WaterFieldOutputMode::SurfaceMotion ||
        runtimeState->water.fieldSettings.outputMode == WaterFieldOutputMode::Both) {
        WaterEffectLayer layer;
        layer.id = 1U;
        layer.name = "Field Surface";
        layer.featureType = WaterEffectFeatureType::FieldSurfaceMotion;
        layer.response.colouriseRed = 0.46F;
        layer.response.colouriseGreen = 0.95F;
        layer.response.colouriseBlue = 0.78F;
        layer.regionStrength = 1.0F;
        layer.speed = runtimeState->water.fieldTrailSettings.speedMetersPerSecond;
        layer.maxAffectedPoints = 300000U;
        auto effectOverlay = invisible_places::water::GenerateFieldSurfaceEffectOverlay(
            runtimeState->water.fieldCache,
            layer);
        outputPoints += effectOverlay.points.size();
        runtimeState->water.fieldSurfaceEffectOverlay = effectOverlay;
        std::vector<WaterEffectOverlay> compositionOverlays;
        compositionOverlays.push_back(effectOverlay);
        if (!ApplyWaterEffectCompositionToDisplaySources(
            runtimeState,
            viewport,
            sourceSession,
            compositionOverlays,
            false)) {
            return false;
        }
        ++runtimeState->water.regionCompositionRevision;
        const auto outputPath = BuildWaterFeatureOverlayPath(
            *runtimeState,
            sourceSession,
            "-FieldSurface.generated");
        runtimeState->water.lastFieldSurfaceOverlayPath = outputPath;
        AddOrRefreshWaterEffectOverlaySession(
            runtimeState,
            viewport,
            outputPath,
            effectOverlay,
            "Field Surface");
    }

    runtimeState->statusMessage =
        std::string{fieldCacheLoadedFromDisk ? "Loaded cached water field with " : "Built water field with "} +
        FormatPointCount(runtimeState->water.fieldCache.nodes.size()) +
        " cache nodes and " + FormatPointCount(outputPoints) + " generated overlay points.";
    runtimeState->water.fieldEffectsDirty = false;
    ClearWaterFieldRegionEffectsDirty(&runtimeState->water);
    runtimeState->water.fieldCache.stale = false;
    ++runtimeState->water.regionEffectOutputRevision;
    runtimeState->errorMessage.clear();
    return true;
}

std::optional<std::size_t> FindScalarFieldByName(
    const std::vector<invisible_places::io::ScalarFieldStats>& fields,
    std::string_view name) {
    const auto target = NormalizeMotionScalarFieldName(name);
    for (std::size_t index = 0; index < fields.size(); ++index) {
        if (NormalizeMotionScalarFieldName(fields[index].name) == target) {
            return index;
        }
    }
    return std::nullopt;
}

void UpsertGeneratedScalarField(
    invisible_places::io::LoadedPointCloud* cloud,
    std::string_view name,
    const std::vector<float>& values) {
    if (cloud == nullptr || values.size() != cloud->PointCount()) {
        return;
    }
    const auto pointCount = cloud->PointCount();
    const auto expectedValueCount = cloud->scalarFields.size() * pointCount;
    if (cloud->scalarFieldValues.size() != expectedValueCount) {
        cloud->scalarFieldValues.resize(expectedValueCount, 0.0F);
    }

    auto slot = FindScalarFieldByName(cloud->scalarFields, name);
    if (!slot.has_value()) {
        invisible_places::io::ScalarFieldStats stats;
        stats.name = std::string{name};
        cloud->scalarFields.push_back(stats);
        cloud->scalarFieldValues.resize(cloud->scalarFields.size() * pointCount, 0.0F);
        slot = cloud->scalarFields.size() - 1U;
    }

    auto& stats = cloud->scalarFields[slot.value()];
    stats = {};
    stats.name = std::string{name};
    for (std::size_t pointIndex = 0; pointIndex < pointCount; ++pointIndex) {
        const float value = std::isfinite(values[pointIndex]) ? values[pointIndex] : 0.0F;
        cloud->scalarFieldValues[cloud->ScalarFieldValueIndex(slot.value(), pointIndex)] = value;
        stats.Include(value);
    }
}

constexpr std::string_view kWaterEffectScalarFields[] = {
    "water_effect_value",
    "water_effect_emission_add",
    "water_effect_opacity_add",
    "water_effect_opacity_multiply",
    "water_effect_point_size_add",
    "water_effect_point_size_multiply",
    "water_effect_colour_red",
    "water_effect_colour_green",
    "water_effect_colour_blue",
    "water_effect_colour_mix",
};

constexpr std::string_view kRippleEffectScalarFields[] = {
    "ripple_mask",
    "ripple_edge",
    "ripple_value",
    "ripple_seed",
    "ripple_region_id",
    "ripple_distance",
    "ripple_linear_coord",
    "ripple_angle",
    "ripple_speed",
    "ripple_confidence",
    "ripple_wavelength",
    "ripple_warp",
    "ripple_phase",
};

bool SessionHasWaterEffectCompositionFields(const PreviewLayerSession& session) {
    const bool hasWaterFields = std::any_of(
        std::begin(kWaterEffectScalarFields),
        std::end(kWaterEffectScalarFields),
        [&](std::string_view name) {
            return FindScalarFieldByName(session.scalarFields, name).has_value();
        });
    if (hasWaterFields) {
        return true;
    }
    return std::any_of(
        std::begin(kRippleEffectScalarFields),
        std::end(kRippleEffectScalarFields),
        [&](std::string_view name) {
            return FindScalarFieldByName(session.scalarFields, name).has_value();
        });
}

bool ApplyWaterEffectCompositionFieldsToSession(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::size_t sessionIndex,
    const std::vector<WaterEffectOverlay>& overlays) {
    if (runtimeState == nullptr || viewport == nullptr || sessionIndex >= runtimeState->sessions.size()) {
        return false;
    }
    auto& session = runtimeState->sessions[sessionIndex];
    if (!session.loaded || session.kind != LayerKind::PointCloud || session.offlinePointCloud == nullptr) {
        return false;
    }
    if (overlays.empty() && !SessionHasWaterEffectCompositionFields(session)) {
        return true;
    }

    const auto composition = invisible_places::water::ComposeWaterEffectFields(
        *session.offlinePointCloud,
        overlays);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_value", composition.value);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_emission_add", composition.emissionAdd);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_opacity_add", composition.opacityAdd);
    UpsertGeneratedScalarField(
        session.offlinePointCloud.get(),
        "water_effect_opacity_multiply",
        composition.opacityMultiply);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_point_size_add", composition.pointSizeAdd);
    UpsertGeneratedScalarField(
        session.offlinePointCloud.get(),
        "water_effect_point_size_multiply",
        composition.pointSizeMultiply);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_colour_red", composition.colourRed);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_colour_green", composition.colourGreen);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_colour_blue", composition.colourBlue);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "water_effect_colour_mix", composition.colourMix);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_mask", composition.rippleMask);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_edge", composition.rippleEdge);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_value", composition.rippleValue);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_seed", composition.rippleSeed);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_region_id", composition.rippleRegionId);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_distance", composition.rippleDistance);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_linear_coord", composition.rippleLinearCoord);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_angle", composition.rippleAngle);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_speed", composition.rippleSpeed);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_confidence", composition.rippleConfidence);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_wavelength", composition.rippleWavelength);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_warp", composition.rippleWarp);
    UpsertGeneratedScalarField(session.offlinePointCloud.get(), "ripple_phase", composition.ripplePhase);
    session.scalarFields = session.offlinePointCloud->scalarFields;
    try {
        viewport->UploadPointCloudScalarFields(
            sessionIndex,
            session.offlinePointCloud->scalarFields,
            session.offlinePointCloud->scalarFieldValues);
    } catch (const std::exception& error) {
        runtimeState->errorMessage =
            "GPU upload failed while refreshing water effect composition: " + std::string{error.what()};
        runtimeState->statusMessage.clear();
        return false;
    }
    return true;
}

bool ApplyWaterEffectCompositionToDisplaySources(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const PreviewLayerSession& analysisSession,
    const std::vector<WaterEffectOverlay>& overlays,
    bool includePendingDisplay) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (!IsSceneGroupedPointCloud(analysisSession)) {
        const auto sourceIndex = FindSessionIndex(*runtimeState, analysisSession);
        return sourceIndex.has_value() && ApplyWaterEffectCompositionFieldsToSession(
            runtimeState,
            viewport,
            sourceIndex.value(),
            overlays);
    }

    auto spatialOverlays = overlays;
    for (auto& overlay : spatialOverlays) {
        for (auto& point : overlay.points) {
            // Analysis and display clouds have unrelated point indices. The
            // spatial compositor will resolve the nearest exact display point.
            point.sourcePointIndex = std::numeric_limits<std::uint32_t>::max();
        }
    }

    bool appliedAny = false;
    bool succeeded = true;
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        const auto& session = runtimeState->sessions[index];
        if (!SessionsShareSceneFolder(session, analysisSession) ||
            !session.gpuResident ||
            (!session.committedDisplaySource &&
             !(includePendingDisplay && session.pendingDisplaySource))) {
            continue;
        }
        appliedAny = true;
        succeeded &= ApplyWaterEffectCompositionFieldsToSession(
            runtimeState,
            viewport,
            index,
            spatialOverlays);
    }
    return appliedAny ? succeeded : true;
}

std::vector<WaterEffectOverlay> CurrentFilteredWaterEffectOverlays(const WaterWorkflowState& water) {
    std::vector<WaterEffectOverlay> overlays;
    if (kFieldWaterRuntimeEnabled &&
        !water.fieldSurfaceEffectOverlay.points.empty()) {
        overlays.push_back(water.fieldSurfaceEffectOverlay);
    }
    return overlays;
}

bool ReapplyWaterEffectCompositionForTarget(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const std::filesystem::path& targetLayerSourcePath) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    const auto targetIndex = FindSessionIndexBySourcePath(*runtimeState, targetLayerSourcePath);
    if (!targetIndex.has_value() || targetIndex.value() >= runtimeState->sessions.size()) {
        return false;
    }
    const auto overlays = CurrentFilteredWaterEffectOverlays(runtimeState->water);
    if (!ApplyWaterEffectCompositionFieldsToSession(
            runtimeState,
            viewport,
            targetIndex.value(),
            overlays)) {
        return false;
    }
    ++runtimeState->water.regionCompositionRevision;
    return true;
}

bool WaterEffectLayerTargetsSession(
    const PreviewRuntimeState& runtimeState,
    const WaterEffectLayer& layer,
    const PreviewLayerSession& session,
    WaterEffectFeatureType featureType) {
    if (layer.featureType != featureType) {
        return false;
    }

    const auto roleAllowed = [&]() {
        if (layer.targetSceneRoles.empty()) {
            return true;
        }
        return std::any_of(
            layer.targetSceneRoles.begin(),
            layer.targetSceneRoles.end(),
            [&](const std::string& role) {
                return SceneRoleIs(session.sceneRole, role);
            });
    };
    if (!roleAllowed()) {
        return false;
    }

    if (NormalizePathKey(layer.targetLayerSourcePath) == NormalizePathKey(session.sourcePath)) {
        return true;
    }

    const auto targetIndex = FindSessionIndexBySourcePath(runtimeState, layer.targetLayerSourcePath);
    if (!targetIndex.has_value() || targetIndex.value() >= runtimeState.sessions.size()) {
        return false;
    }
    const auto& targetSession = runtimeState.sessions[targetIndex.value()];
    return SessionsShareSceneFolder(targetSession, session) &&
           (session.analysisSource ||
            session.committedDisplaySource ||
            session.pendingDisplaySource);
}

WaterEffectLayer MaterializeWaterEffectLayerForSession(
    const WaterEffectLayer& layer,
    const PreviewLayerSession& session) {
    auto materialized = layer;
    materialized.targetLayerSourcePath = session.sourcePath;
    return materialized;
}

std::vector<std::size_t> WaterEffectLayerTargetSessionIndices(
    const PreviewRuntimeState& runtimeState,
    const WaterEffectLayer& layer,
    WaterEffectFeatureType featureType,
    bool requireVisible) {
    std::vector<std::size_t> indices;
    for (std::size_t index = 0; index < runtimeState.sessions.size(); ++index) {
        const auto& session = runtimeState.sessions[index];
        const bool groupedAnalysisReady = IsSceneGroupedPointCloud(session) &&
                                          IsCpuReadyAnalysisPointCloudSource(session);
        const bool standaloneReady = !IsSceneGroupedPointCloud(session) &&
                                     session.loaded && session.offlinePointCloud != nullptr &&
                                     (!requireVisible || session.visible);
        if ((!groupedAnalysisReady && !standaloneReady) ||
            session.kind != LayerKind::PointCloud ||
            !IsAssociableLidarSession(session) ||
            !WaterEffectLayerTargetsSession(runtimeState, layer, session, featureType)) {
            continue;
        }
        indices.push_back(index);
    }
    return indices;
}

std::string WaterEffectLayerTargetDisplayName(
    const PreviewRuntimeState& runtimeState,
    const WaterEffectLayer& layer) {
    const auto targetIndex = FindSessionIndexBySourcePath(runtimeState, layer.targetLayerSourcePath);
    if (!targetIndex.has_value() || targetIndex.value() >= runtimeState.sessions.size()) {
        return layer.targetLayerSourcePath.filename().string();
    }

    const auto& targetSession = runtimeState.sessions[targetIndex.value()];
    if (!IsSceneGroupedPointCloud(targetSession)) {
        return targetSession.displayName;
    }

    std::string label = targetSession.sceneGroupName;
    if (!layer.targetSceneRoles.empty()) {
        label += " (";
        for (std::size_t index = 0; index < layer.targetSceneRoles.size(); ++index) {
            if (index > 0U) {
                label += ", ";
            }
            label += layer.targetSceneRoles[index];
        }
        label += ")";
    } else {
        label += " (all roles)";
    }
    return label;
}

void EraseWaterRegionPointPreviewsForLayer(
    WaterWorkflowState* water,
    const WaterEffectLayer& layer) {
    if (water == nullptr) {
        return;
    }

    std::vector<std::uint64_t> staleKeys;
    for (const auto& [key, preview] : water->regionPointPreviews) {
        if (preview.featureType == layer.featureType && preview.layerId == layer.id) {
            staleKeys.push_back(key);
        }
    }
    for (const auto key : staleKeys) {
        water->regionPointPreviews.erase(key);
        water->regionPointPreviewPendingKeys.erase(key);
    }
}

void MarkWaterRippleEffectsDirty(PreviewRuntimeState* runtimeState, bool clearRegionPreviews = true) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.rippleEffectsDirty = true;
    if (clearRegionPreviews) {
        runtimeState->water.pendingRippleLiveEffectKey.reset();
    }
    for (const auto& layer : runtimeState->water.rippleLayers) {
        if (!WaterRegionLayerClosed(layer)) {
            continue;
        }
        const auto key = WaterRegionPreviewKey(layer);
        runtimeState->water.regionEffectsDirtyKeys.insert(key);
        if (clearRegionPreviews) {
            EraseWaterRegionPointPreviewsForLayer(&runtimeState->water, layer);
            runtimeState->water.regionPointPreviewPendingKeys.erase(key);
        }
    }
}

void MarkWaterFieldEffectsDirty(PreviewRuntimeState* runtimeState, bool clearRegionPreviews = true) {
    if (runtimeState == nullptr) {
        return;
    }
    runtimeState->water.fieldEffectsDirty = true;
    for (const auto& layer : runtimeState->water.fieldLayers) {
        if (!WaterRegionLayerClosed(layer)) {
            continue;
        }
        const auto key = WaterRegionPreviewKey(layer);
        runtimeState->water.regionEffectsDirtyKeys.insert(key);
        if (clearRegionPreviews) {
            EraseWaterRegionPointPreviewsForLayer(&runtimeState->water, layer);
            runtimeState->water.regionPointPreviewPendingKeys.erase(key);
        }
    }
    if (!runtimeState->water.fieldCache.nodes.empty()) {
        runtimeState->water.fieldCache.stale = true;
    }
}

void MarkWaterRegionLayerEffectsDirty(
    PreviewRuntimeState* runtimeState,
    const WaterEffectLayer& layer,
    bool clearRegionPreview = true) {
    if (runtimeState == nullptr || !WaterRegionLayerClosed(layer)) {
        return;
    }
    const auto key = WaterRegionPreviewKey(layer);
    runtimeState->water.regionEffectsDirtyKeys.insert(key);
    if (clearRegionPreview) {
        if (runtimeState->water.pendingRippleLiveEffectKey.has_value() &&
            runtimeState->water.pendingRippleLiveEffectKey.value() == key) {
            runtimeState->water.pendingRippleLiveEffectKey.reset();
        }
        EraseWaterRegionPointPreviewsForLayer(&runtimeState->water, layer);
        runtimeState->water.regionPointPreviewPendingKeys.erase(key);
    }
    if (layer.featureType == WaterEffectFeatureType::Ripple) {
        runtimeState->water.rippleEffectsDirty = true;
    } else if (WaterFieldFeatureType(layer.featureType)) {
        runtimeState->water.fieldEffectsDirty = true;
        if (!runtimeState->water.fieldCache.nodes.empty()) {
            runtimeState->water.fieldCache.stale = true;
        }
    }
}

void ClearWaterRegionEffectsDirtyForFeature(
    WaterWorkflowState* water,
    WaterEffectFeatureType featureType) {
    if (water == nullptr) {
        return;
    }
    std::vector<std::uint64_t> staleKeys;
    const auto featurePrefix = static_cast<std::uint64_t>(static_cast<std::uint32_t>(featureType)) << 32U;
    for (const auto key : water->regionEffectsDirtyKeys) {
        if ((key & 0xffff'ffff'0000'0000ULL) == featurePrefix) {
            staleKeys.push_back(key);
        }
    }
    for (const auto key : staleKeys) {
        water->regionEffectsDirtyKeys.erase(key);
    }
}

void ClearWaterFieldRegionEffectsDirty(WaterWorkflowState* water) {
    ClearWaterRegionEffectsDirtyForFeature(water, WaterEffectFeatureType::FieldSurfaceMotion);
    ClearWaterRegionEffectsDirtyForFeature(water, WaterEffectFeatureType::FieldNoFlowRegion);
    ClearWaterRegionEffectsDirtyForFeature(water, WaterEffectFeatureType::FieldBridgeAllowedRegion);
    ClearWaterRegionEffectsDirtyForFeature(water, WaterEffectFeatureType::FieldBridgeBlockedRegion);
}

std::vector<WaterRegionPointPreviewJobRequest> BuildWaterRegionPointPreviewRequests(
    PreviewRuntimeState* runtimeState,
    const std::vector<WaterEffectLayer>& layers,
    const invisible_places::renderer::core::VulkanViewportShell* viewport = nullptr) {
    std::vector<WaterRegionPointPreviewJobRequest> requests;
    if (runtimeState == nullptr) {
        return requests;
    }

    bool useVisibleViewProjection = false;
    glm::mat4 visibleViewProjection{1.0F};
    if (viewport != nullptr && viewport->Width() > 0U && viewport->Height() > 0U) {
        visibleViewProjection = runtimeState->camera.Matrices(CurrentAspectRatio(*viewport)).viewProjection;
        useVisibleViewProjection = true;
    }

    requests.reserve(layers.size());
    for (const auto& layer : layers) {
        if (!WaterRegionLayerClosed(layer) || !layer.enabledInViewport) {
            continue;
        }
        std::unordered_set<std::string> requestedSourceKeys;
        const auto appendRequest = [&](std::size_t targetIndex) {
            if (targetIndex >= runtimeState->sessions.size()) {
                return;
            }
            const auto& session = runtimeState->sessions[targetIndex];
            if (session.offlinePointCloud == nullptr) {
                return;
            }
            const auto sourceKey = NormalizePathKey(session.sourcePath);
            if (!requestedSourceKeys.insert(sourceKey).second) {
                return;
            }
            const auto materializedLayer = MaterializeWaterEffectLayerForSession(layer, session);
            const auto candidateIndices = VisibleWaterRegionCandidatePointIndices(*runtimeState, session);
            requests.push_back({
                .layer = materializedLayer,
                .layerFingerprint = WaterRegionLayerFingerprint(materializedLayer),
                .sessionIndex = targetIndex,
                .sourcePath = session.sourcePath,
                .cloud = std::static_pointer_cast<const invisible_places::io::LoadedPointCloud>(
                    session.offlinePointCloud),
                .candidatePointIndices = std::vector<std::uint32_t>{
                    candidateIndices.begin(),
                    candidateIndices.end()},
                .visibleViewProjection = visibleViewProjection,
                .useVisibleViewProjection = useVisibleViewProjection,
            });
        };
        const auto targetIndices =
            WaterEffectLayerTargetSessionIndices(*runtimeState, layer, layer.featureType, true);
        for (const auto targetIndex : targetIndices) {
            appendRequest(targetIndex);
        }
        // Presentation previews are built asynchronously against the exact
        // display source; analysis indices are never uploaded across densities.
        for (std::size_t displayIndex = 0; displayIndex < runtimeState->sessions.size(); ++displayIndex) {
            const auto& displaySession = runtimeState->sessions[displayIndex];
            if (!IsSceneGroupedPointCloud(displaySession) ||
                !displaySession.gpuResident ||
                (!displaySession.committedDisplaySource && !displaySession.pendingDisplaySource) ||
                !IsAssociableLidarSession(displaySession) ||
                !WaterEffectLayerTargetsSession(
                    *runtimeState,
                    layer,
                    displaySession,
                    layer.featureType)) {
                continue;
            }
            appendRequest(displayIndex);
        }
    }
    return requests;
}

bool StartWaterRegionPointPreviewJob(
    PreviewRuntimeState* runtimeState,
    std::vector<WaterRegionPointPreviewJobRequest> requests) {
    if (runtimeState == nullptr || requests.empty()) {
        return false;
    }

    auto& water = runtimeState->water;
    for (const auto& request : requests) {
        const auto key = WaterRegionPreviewKey(request.layer, request.sourcePath);
        water.regionPointPreviewPendingKeys.insert(key);
        water.regionPointPreviews.erase(key);
    }

    auto& job = water.regionPointPreviewJob;
    if (job.worker.joinable()) {
        job.worker.request_stop();
        job.worker = std::jthread{};
    }

    auto shared = std::make_shared<WaterRegionPointPreviewJobShared>();
    const std::uint64_t jobId = job.nextJobId++;
    job.activeJobId = jobId;
    job.shared = shared;
    job.worker = std::jthread(
        [shared, jobId, requests = std::move(requests)](std::stop_token stopToken) {
            const auto startedAt = std::chrono::steady_clock::now();
            WaterRegionPointPreviewJobResult result;
            result.jobId = jobId;
            result.previews.reserve(requests.size());
            try {
                for (const auto& request : requests) {
                    if (stopToken.stop_requested()) {
                        result.cancelled = true;
                        break;
                    }
                    {
                        std::lock_guard lock{shared->mutex};
                        shared->stage = "Selecting " + request.layer.name;
                    }
                    const auto selectionStart = std::chrono::steady_clock::now();
                    const auto selection = invisible_places::water::BuildWaterRegionSelection(
                        *request.cloud,
                        request.layer,
                        invisible_places::water::WaterRegionSelectionOptions{
                            .previewOnly = true,
                            .candidatePointIndices = request.candidatePointIndices,
                            .visibleViewProjection = request.useVisibleViewProjection
                                                         ? &request.visibleViewProjection
                                                         : nullptr,
                            .stopToken = &stopToken,
                        });
                    if (stopToken.stop_requested()) {
                        result.cancelled = true;
                        break;
                    }
                    const double selectionMs = std::chrono::duration<double, std::milli>(
                                                   std::chrono::steady_clock::now() - selectionStart)
                                                   .count();
                    auto preview = MakeWaterRegionPointPreview(
                        request.layer,
                        selection,
                        request.layerFingerprint,
                        selectionMs);
                    {
                        std::lock_guard lock{shared->mutex};
                        shared->selectedPointCount += preview.selectedPointCount;
                    }
                    result.previews.push_back(std::move(preview));
                }
            } catch (const std::exception& error) {
                result.errorMessage = error.what();
            }
            result.elapsedMs = std::chrono::duration<double, std::milli>(
                                   std::chrono::steady_clock::now() - startedAt)
                                   .count();
            {
                std::lock_guard lock{shared->mutex};
                shared->result = std::move(result);
                shared->completed = true;
            }
        });
    return true;
}

bool QueueWaterRegionPointPreviewForLayers(
    PreviewRuntimeState* runtimeState,
    const std::vector<WaterEffectLayer>& layers,
    const invisible_places::renderer::core::VulkanViewportShell* viewport = nullptr) {
    if (!layers.empty() &&
        !EnsureSceneAnalysisReadyForAction(
            runtimeState,
            DeferredSceneAnalysisAction::RefreshRegionPreviews,
            "region point preview")) {
        return false;
    }
    return StartWaterRegionPointPreviewJob(
        runtimeState,
        BuildWaterRegionPointPreviewRequests(runtimeState, layers, viewport));
}

bool QueueWaterRegionPointPreviewForLayer(
    PreviewRuntimeState* runtimeState,
    const WaterEffectLayer& layer,
    const invisible_places::renderer::core::VulkanViewportShell* viewport = nullptr) {
    return QueueWaterRegionPointPreviewForLayers(runtimeState, std::vector<WaterEffectLayer>{layer}, viewport);
}

void QueueWaterRegionPointPreviewsForAllRegions(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr ||
        (!kRippleWaterRuntimeEnabled && !kFieldWaterRuntimeEnabled)) {
        return;
    }
    std::vector<WaterEffectLayer> layers;
    layers.reserve(runtimeState->water.rippleLayers.size() + runtimeState->water.fieldLayers.size());
    const auto append = [&](const WaterEffectLayer& layer) {
        if (WaterRegionLayerClosed(layer) && layer.enabledInViewport) {
            layers.push_back(layer);
        }
    };
    for (const auto& layer : runtimeState->water.rippleLayers) {
        append(layer);
    }
    for (const auto& layer : runtimeState->water.fieldLayers) {
        append(layer);
    }
    if (!layers.empty()) {
        QueueWaterRegionPointPreviewForLayers(runtimeState, layers, viewport);
    }
}

void QueueWaterRegionPointPreviewsForDirtyRegions(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr ||
        (!kRippleWaterRuntimeEnabled && !kFieldWaterRuntimeEnabled)) {
        return;
    }

    std::vector<WaterEffectLayer> layers;
    layers.reserve(runtimeState->water.rippleLayers.size() + runtimeState->water.fieldLayers.size());
    auto appendDirty = [&](const WaterEffectLayer& layer) {
        if (!WaterRegionLayerClosed(layer)) {
            return;
        }
        const auto key = WaterRegionPreviewKey(layer);
        const auto previewIt = runtimeState->water.regionPointPreviews.find(key);
        const bool previewCurrent =
            previewIt != runtimeState->water.regionPointPreviews.end() &&
            previewIt->second.layerFingerprint == WaterRegionLayerFingerprint(layer);
        if ((runtimeState->water.regionEffectsDirtyKeys.contains(key) ||
             runtimeState->water.regionPointPreviewOverrides.contains(key)) &&
            !previewCurrent &&
            !runtimeState->water.regionPointPreviewPendingKeys.contains(key)) {
            layers.push_back(layer);
        }
    };
    for (const auto& layer : runtimeState->water.rippleLayers) {
        appendDirty(layer);
    }
    for (const auto& layer : runtimeState->water.fieldLayers) {
        appendDirty(layer);
    }
    if (!layers.empty()) {
        QueueWaterRegionPointPreviewForLayers(runtimeState, layers, viewport);
    }
}

void PollWaterRegionPointPreviewJob(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr || runtimeState->water.regionPointPreviewJob.shared == nullptr) {
        return;
    }
    auto& job = runtimeState->water.regionPointPreviewJob;
    WaterRegionPointPreviewJobResult result;
    {
        std::lock_guard lock{job.shared->mutex};
        if (!job.shared->completed) {
            return;
        }
        result = std::move(job.shared->result);
    }

    if (result.jobId != job.activeJobId) {
        return;
    }
    if (job.worker.joinable()) {
        job.worker = std::jthread{};
    }
    job.shared.reset();
    job.activeJobId = 0;

    if (result.cancelled) {
        return;
    }
    if (!result.errorMessage.empty()) {
        runtimeState->errorMessage = "Region point preview failed: " + result.errorMessage;
        runtimeState->statusMessage.clear();
        return;
    }

    std::size_t selectedPointCount = 0;
    for (auto& preview : result.previews) {
        auto* layer = FindWaterRegionLayerByKey(&runtimeState->water, preview.featureType, preview.layerId);
        const auto key = WaterRegionPreviewKey(preview.featureType, preview.layerId, preview.targetLayerSourcePath);
        runtimeState->water.regionPointPreviewPendingKeys.erase(key);
        const auto targetIndex = FindSessionIndexBySourcePath(*runtimeState, preview.targetLayerSourcePath);
        if (layer == nullptr ||
            !targetIndex.has_value() ||
            targetIndex.value() >= runtimeState->sessions.size() ||
            !WaterEffectLayerTargetsSession(
                *runtimeState,
                *layer,
                runtimeState->sessions[targetIndex.value()],
                preview.featureType)) {
            continue;
        }
        const auto materializedLayer =
            MaterializeWaterEffectLayerForSession(*layer, runtimeState->sessions[targetIndex.value()]);
        if (WaterRegionLayerFingerprint(materializedLayer) != preview.layerFingerprint) {
            continue;
        }
        selectedPointCount += preview.selectedPointCount;
        runtimeState->water.regionPointPreviews[key] = std::move(preview);
    }
    if (selectedPointCount > 0U) {
        ++runtimeState->water.regionPreviewRevision;
        runtimeState->statusMessage =
            "Selected " + FormatPointCount(selectedPointCount) +
            " region points for preview.";
        runtimeState->errorMessage.clear();
    }
}

void DisarmWaterRegionPlacementForModeSwitch(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    (void)viewport;
    const bool wasRipplePlacementArmed = runtimeState->water.rippleRegionPlacementArmed;
    const bool wasFieldPlacementArmed = runtimeState->water.fieldRegionPlacementArmed;
    runtimeState->water.placementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.rippleRegionPlacementArmed = false;
    runtimeState->water.fieldRegionPlacementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    if (wasRipplePlacementArmed) {
        runtimeState->statusMessage = "Ripple vertex placement stopped; selecting region points.";
        runtimeState->errorMessage.clear();
        if (runtimeState->water.selectedRippleLayerIndex.has_value() &&
            runtimeState->water.selectedRippleLayerIndex.value() < runtimeState->water.rippleLayers.size() &&
            WaterRegionLayerClosed(runtimeState->water.rippleLayers[runtimeState->water.selectedRippleLayerIndex.value()])) {
            QueueWaterRegionPointPreviewForLayer(
                runtimeState,
                runtimeState->water.rippleLayers[runtimeState->water.selectedRippleLayerIndex.value()],
                viewport);
        }
    }
    if (wasFieldPlacementArmed) {
        runtimeState->statusMessage = "Field region vertex placement stopped; selecting region points.";
        runtimeState->errorMessage.clear();
        if (runtimeState->water.selectedFieldLayerIndex.has_value() &&
            runtimeState->water.selectedFieldLayerIndex.value() < runtimeState->water.fieldLayers.size() &&
            WaterRegionLayerClosed(runtimeState->water.fieldLayers[runtimeState->water.selectedFieldLayerIndex.value()])) {
            QueueWaterRegionPointPreviewForLayer(
                runtimeState,
                runtimeState->water.fieldLayers[runtimeState->water.selectedFieldLayerIndex.value()],
                viewport);
        }
    }
}

void InvalidateWaterSeepageTopology(WaterWorkflowState* water) {
    if (water == nullptr) {
        return;
    }
    // The semantic key is derived from authored geometry, target role, and
    // immutable surface identity. Keep unaffected role grids and per-node
    // guides alive; the next maintenance pass builds only new keys and prunes
    // superseded entries after every active role has been visited.
    water->seepageSurfaceGuideWarning.clear();
    water->seepageSupportWarning.clear();
}

void InvalidateWaterSeepageParams(WaterWorkflowState* water) {
    if (water != nullptr) {
        water->seepageParamsFingerprints.clear();
    }
}

invisible_places::io::Float3 WaterSeepageFallbackDownAxis(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport) {
    const auto matrices = runtimeState.camera.Matrices(CurrentAspectRatio(viewport));
    const glm::mat3 inverseView = glm::inverse(glm::mat3{matrices.view});
    glm::vec3 screenDown = inverseView * glm::vec3{0.0F, -1.0F, 0.0F};
    if (!PivotNormalValid(screenDown)) {
        screenDown = {0.0F, 0.0F, -1.0F};
    }
    return FromGlm(glm::normalize(screenDown));
}

invisible_places::io::Float3 WaterSeepageSurfaceNormal(
    const ResolvedPivot& pivot,
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport) {
    glm::vec3 normal = ToGlm(pivot.normal);
    if (PivotNormalValid(normal)) {
        return FromGlm(glm::normalize(normal));
    }
    const auto matrices = runtimeState.camera.Matrices(CurrentAspectRatio(viewport));
    normal = matrices.position - ToGlm(pivot.point);
    normal.z = 0.0F;
    if (!PivotNormalValid(normal)) {
        normal = {0.0F, 1.0F, 0.0F};
    }
    return FromGlm(glm::normalize(normal));
}

std::uint32_t WaterSeepagePlacementRoleMask(const WaterSeepageNode* node) {
    bool permitsRock = node == nullptr;
    bool permitsSand = false;
    if (node != nullptr) {
        for (const auto& role : node->targetSceneRoles) {
            const auto normalizedRole = NormalizeWaterSeepageRoleName(role);
            // VEG support follows its connected ROCK substrate. SAND remains
            // explicitly opt-in, including while an existing node is moved.
            permitsRock = permitsRock || normalizedRole == "ROCK" || normalizedRole == "VEG";
            permitsSand = permitsSand || normalizedRole == "SAND";
        }
    }
    std::uint32_t roleMask = 0U;
    if (permitsRock) {
        roleMask |= invisible_places::water::kWaterSurfaceRockRoleMask;
    }
    if (permitsSand) {
        roleMask |= invisible_places::water::kWaterSurfaceSandRoleMask;
    }
    return roleMask;
}

std::optional<ResolvedPivot> ResolveWaterSeepagePlacementPivot(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint,
    const WaterSeepageNode* node = nullptr) {
    const bool restrictToSelectedScene =
        runtimeState.selectedSessionIndex.has_value() &&
        runtimeState.selectedSessionIndex.value() < runtimeState.sessions.size() &&
        IsSceneGroupedPointCloud(runtimeState.sessions[runtimeState.selectedSessionIndex.value()]);
    auto pivot = ResolveSurfacePivot(
        runtimeState,
        viewport,
        screenPoint,
        restrictToSelectedScene,
        true);
    if (!pivot.has_value()) {
        return std::nullopt;
    }

    const auto& cache = runtimeState.water.waterSurfaceCache;
    const PreviewLayerSession* activeSession = nullptr;
    if (runtimeState.selectedSessionIndex.has_value() &&
        runtimeState.selectedSessionIndex.value() < runtimeState.sessions.size() &&
        IsSceneGroupedPointCloud(
            runtimeState.sessions[runtimeState.selectedSessionIndex.value()])) {
        activeSession =
            &runtimeState.sessions[runtimeState.selectedSessionIndex.value()];
    } else {
        const auto visible = std::find_if(
            runtimeState.sessions.begin(),
            runtimeState.sessions.end(),
            [&](const PreviewLayerSession& session) {
                return IsRenderablePointCloudSource(runtimeState, session) &&
                       IsAuthoredWaterTerrainSession(session);
            });
        if (visible != runtimeState.sessions.end()) {
            activeSession = &*visible;
        }
    }
    const bool cacheMatchesActiveScene =
        cache != nullptr && !cache->flowSurfaceSurfels.empty() &&
        activeSession != nullptr &&
        (activeSession->sceneGroupName.empty() ||
         runtimeState.water.waterSurfaceSceneGroupName ==
             activeSession->sceneGroupName);
    const auto roleMask = WaterSeepagePlacementRoleMask(node);
    if (!cacheMatchesActiveScene || roleMask == 0U) {
        // Standalone scenes retain visible-display placement while grouped
        // scenes are warming their cache. The asynchronous connected support
        // build will not publish until the matching cache is resident.
        return pivot;
    }

    const float snapDistance = std::clamp(
        std::max(0.05F, cache->resolutionMeters * 2.25F),
        cache->resolutionMeters,
        0.25F);
    const auto snapped = invisible_places::water::QueryWaterSurfaceCache(
        *cache,
        pivot->point,
        snapDistance,
        pivot->normal,
        roleMask);
    if (!snapped.hit) {
        // A resident grouped cache is authoritative: never author a node on
        // an unrelated/background surface when no permitted substrate exists.
        return std::nullopt;
    }
    pivot->point = snapped.surfel.centroid;
    pivot->normal = snapped.surfel.normal;
    pivot->sceneRole = snapped.surfel.role == WaterSurfaceRole::Sand ? "SAND" : "ROCK";
    pivot->confidence = std::clamp(
        snapped.surfel.confidence *
            (0.45F + 0.55F * snapped.surfel.normalCoherence),
        0.0F,
        1.0F);
    pivot->matchedSurface = true;
    return pivot;
}

bool PlaceWaterSeepageNodeAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }
    const auto pivot = ResolveWaterSeepagePlacementPivot(*runtimeState, viewport, screenPoint);
    if (!pivot.has_value()) {
        runtimeState->errorMessage =
            "No visible permitted authored cache surface was available for Seepage placement.";
        runtimeState->statusMessage.clear();
        return false;
    }

    WaterSeepageNode node;
    invisible_places::water::ApplyWaterSeepageNodeSettings(
        runtimeState->water.defaultSeepageNodeSettings,
        &node);
    node.id = NextWaterSeepageNodeId(*runtimeState);
    node.name = "Seepage " + std::to_string(node.id);
    node.position = pivot->point;
    node.surfaceNormal = WaterSeepageSurfaceNormal(*pivot, *runtimeState, viewport);
    node.downAxis = invisible_places::water::DeriveWaterSeepageDownAxis(
        node.surfaceNormal,
        WaterSeepageFallbackDownAxis(*runtimeState, viewport));
    node.seed = node.id * 2654435761U;

    runtimeState->water.nextSeepageNodeId = node.id + 1U;
    runtimeState->water.seepageNodes.push_back(std::move(node));
    SetWaterSeepageSingleSelection(
        &runtimeState->water,
        runtimeState->water.seepageNodes.size() - 1U);
    SyncWaterSeepageNameBuffersFromPrimary(&runtimeState->water);
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.movingSeepageNodeIndex.reset();
    InvalidateWaterSeepageTopology(&runtimeState->water);
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = pivot->point;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();

    const glm::vec3 normal = ToGlm(runtimeState->water.seepageNodes.back().surfaceNormal);
    const glm::vec3 projectedGravity =
        glm::vec3{0.0F, 0.0F, -1.0F} - normal * glm::dot(glm::vec3{0.0F, 0.0F, -1.0F}, normal);
    if (glm::dot(projectedGravity, projectedGravity) < 0.02F) {
        runtimeState->statusMessage =
            "Placed seepage node; the surface is nearly horizontal, so screen-down orientation was used.";
    } else if (pivot->confidence < 0.35F) {
        runtimeState->statusMessage =
            "Placed Seepage node with low surface confidence; inspect its connected support footprint.";
    } else {
        runtimeState->statusMessage =
            "Placed Seepage node on the visible authored surface; resident cache snapping is active when available.";
    }
    runtimeState->errorMessage.clear();
    return true;
}

bool MoveWaterSeepageNodeAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr || !runtimeState->water.movingSeepageNodeIndex.has_value()) {
        return false;
    }
    const auto index = runtimeState->water.movingSeepageNodeIndex.value();
    if (index >= runtimeState->water.seepageNodes.size()) {
        runtimeState->water.movingSeepageNodeIndex.reset();
        runtimeState->errorMessage = "The selected seepage node is no longer available to move.";
        return false;
    }
    const auto pivot = ResolveWaterSeepagePlacementPivot(
        *runtimeState,
        viewport,
        screenPoint,
        &runtimeState->water.seepageNodes[index]);
    if (!pivot.has_value()) {
        runtimeState->errorMessage =
            "No visible permitted authored cache surface was available for moving the Seepage node.";
        runtimeState->statusMessage.clear();
        return false;
    }

    auto& node = runtimeState->water.seepageNodes[index];
    node.position = pivot->point;
    node.surfaceNormal = WaterSeepageSurfaceNormal(*pivot, *runtimeState, viewport);
    node.downAxis = invisible_places::water::DeriveWaterSeepageDownAxis(
        node.surfaceNormal,
        WaterSeepageFallbackDownAxis(*runtimeState, viewport));
    runtimeState->water.selectedSeepageNodeIndex = index;
    // A reposition of the primary keeps any wider multi-selection; only an
    // index that was not yet selected collapses to a single selection.
    if (runtimeState->water.selectedSeepageNodeIndices.count(index) == 0U) {
        SetWaterSeepageSingleSelection(&runtimeState->water, index);
    }
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    InvalidateWaterSeepageTopology(&runtimeState->water);
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = pivot->point;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    const glm::vec3 normal = ToGlm(node.surfaceNormal);
    const glm::vec3 projectedGravity =
        glm::vec3{0.0F, 0.0F, -1.0F} - normal * glm::dot(glm::vec3{0.0F, 0.0F, -1.0F}, normal);
    runtimeState->statusMessage =
        glm::dot(projectedGravity, projectedGravity) < 0.02F
            ? "Moved " + node.name + "; the surface is nearly horizontal, so screen-down orientation was used."
            : "Moved " + node.name + ".";
    runtimeState->errorMessage.clear();
    return true;
}

bool PlaceWaterEmitterAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }

    const auto pivot =
        ResolveWaterSourcePlacementPivot(*runtimeState, viewport, screenPoint);
    if (!pivot.has_value()) {
        runtimeState->errorMessage =
            "No CPU-ready canonical analysis surface was available for water "
            "source placement.";
        runtimeState->statusMessage.clear();
        return false;
    }

    WaterEmitter emitter;
    emitter.id = NextWaterEmitterId(*runtimeState);
    emitter.name = "Source " + std::to_string(emitter.id);
    const auto pathSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water).path;
    emitter.position = pivot->point;
    emitter.radius = std::max(0.05F, pathSettings.maxBridgeDistance * 0.75F);
    emitter.strength = 1.0F;
    emitter.speed = 1.0F;
    emitter.origin = WaterEmitterOrigin::Manual;
    emitter.status = WaterEmitterStatus::Accepted;
    emitter.confidence = pivot->matchedSurface ? 1.0F : 0.55F;
    const auto placedEmitterId = emitter.id;
    const auto placedPosition = emitter.position;
    runtimeState->water.nextEmitterId = emitter.id + 1U;
    runtimeState->water.emitters.push_back(std::move(emitter));
    runtimeState->water.selectedEmitterIndex = runtimeState->water.emitters.size() - 1U;
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    MarkWaterPathDirty(runtimeState, placedEmitterId);
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = placedPosition;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->statusMessage =
        "Placed water source from viewport; path bake required.";
    runtimeState->errorMessage.clear();
    return true;
}

bool PlaceWaterPathAttractorAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }

    const auto pivot = ResolveWaterSourcePlacementPivot(*runtimeState, viewport, screenPoint);
    if (!pivot.has_value()) {
        runtimeState->errorMessage = "No CPU-ready canonical analysis surface was available for water path attractor placement.";
        runtimeState->statusMessage.clear();
        return false;
    }

    auto pathSettings = ViewedGlobalWaterPathSettings(runtimeState->water);
    pathSettings.attractorEnabled = true;
    pathSettings.attractorPosition = pivot->point;
    if (pathSettings.attractorStrength <= 1.0e-4F) {
        pathSettings.attractorStrength = 0.35F;
    }
    runtimeState->water.editedPathProfileSettings = pathSettings;
    runtimeState->water.selectedPathProfileName = EditedWaterProfileName(runtimeState->water.selectedPathProfileName);
    runtimeState->water.pathProfileNameBuffer = BaseWaterProfileName(runtimeState->water.selectedPathProfileName);
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.placementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->water.rippleRegionPlacementArmed = false;
    runtimeState->water.fieldRegionPlacementArmed = false;
    MarkWaterPathDirty(runtimeState);
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = pivot->point;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->statusMessage = "Placed water path attractor; path bake required.";
    runtimeState->errorMessage.clear();
    return true;
}

std::optional<std::filesystem::path> SelectedCausticTargetLayerPath(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.selectedSessionIndex.has_value() &&
        runtimeState.selectedSessionIndex.value() < runtimeState.sessions.size()) {
        const auto& session = runtimeState.sessions[runtimeState.selectedSessionIndex.value()];
        if (!IsSceneGroupedPointCloud(session) &&
            session.loaded && IsAssociableLidarSession(session)) {
            return session.sourcePath;
        }
    }
    const auto supportIndex = ResolveWaterRuntimeSessionIndex(runtimeState);
    if (supportIndex.has_value() && supportIndex.value() < runtimeState.sessions.size()) {
        const auto& session = runtimeState.sessions[supportIndex.value()];
        if ((session.loaded || IsCpuReadyAnalysisPointCloudSource(session)) &&
            IsAssociableLidarSession(session)) {
            return session.sourcePath;
        }
    }
    return std::nullopt;
}

bool AddWaterRippleVertexAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }
    const auto pivot = ResolveSurfacePivot(*runtimeState, viewport, screenPoint, true);
    if (!pivot.has_value()) {
        runtimeState->errorMessage = "No CPU-ready surface was available for ripple placement.";
        runtimeState->statusMessage.clear();
        return false;
    }
    if (!runtimeState->water.selectedRippleLayerIndex.has_value() ||
        runtimeState->water.selectedRippleLayerIndex.value() >= runtimeState->water.rippleLayers.size()) {
        const auto targetPath = SelectedCausticTargetLayerPath(*runtimeState);
        if (!targetPath.has_value()) {
            runtimeState->errorMessage = "Select a loaded LiDAR layer before creating ripples.";
            runtimeState->statusMessage.clear();
            return false;
        }
        WaterEffectLayer layer;
        layer.id = NextWaterRippleLayerId(*runtimeState);
        layer.name = "Ripple " + std::to_string(layer.id);
        layer.targetLayerSourcePath = targetPath.value();
        layer.featureType = WaterEffectFeatureType::Ripple;
        layer.rippleOverlayType = WaterRippleOverlayType::CausticLace;
        invisible_places::water::InitializeWaterRipplePatternSettings(&layer);
        runtimeState->water.nextRippleLayerId = layer.id + 1U;
        runtimeState->water.regionPointPreviewOverrides.insert(WaterRegionPreviewKey(layer));
        runtimeState->water.rippleLayers.push_back(std::move(layer));
        runtimeState->water.selectedRippleLayerIndex = runtimeState->water.rippleLayers.size() - 1U;
    }
    auto& layer = runtimeState->water.rippleLayers[runtimeState->water.selectedRippleLayerIndex.value()];
    layer.vertices.push_back(pivot->point);
    layer.hull = invisible_places::water::BuildWaterRegionHull(layer.vertices);
    if (layer.vertices.size() >= 3U) {
        MarkWaterRegionLayerEffectsDirty(runtimeState, layer);
    }
    runtimeState->statusMessage =
        "Added ripple vertex " + std::to_string(layer.vertices.size()) + " to " + layer.name + ".";
    runtimeState->errorMessage.clear();
    return true;
}

bool AddWaterFieldVertexAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }
    const auto pivot = ResolveSurfacePivot(*runtimeState, viewport, screenPoint, true);
    if (!pivot.has_value()) {
        runtimeState->errorMessage = "No CPU-ready surface was available for field region placement.";
        runtimeState->statusMessage.clear();
        return false;
    }
    if (!runtimeState->water.selectedFieldLayerIndex.has_value() ||
        runtimeState->water.selectedFieldLayerIndex.value() >= runtimeState->water.fieldLayers.size()) {
        const auto targetPath = SelectedCausticTargetLayerPath(*runtimeState);
        if (!targetPath.has_value()) {
            runtimeState->errorMessage = "Select a loaded LiDAR layer before creating a field region.";
            runtimeState->statusMessage.clear();
            return false;
        }
        WaterEffectLayer layer;
        layer.id = NextWaterFieldLayerId(*runtimeState);
        layer.name = "Field Region " + std::to_string(layer.id);
        layer.targetLayerSourcePath = targetPath.value();
        layer.featureType = WaterEffectFeatureType::FieldSurfaceMotion;
        layer.response.intensity = 1.0F;
        layer.response.emissionAdd = 0.52F;
        layer.response.opacityAdd = 0.30F;
        layer.response.colouriseRed = 0.46F;
        layer.response.colouriseGreen = 0.95F;
        layer.response.colouriseBlue = 0.78F;
        runtimeState->water.nextFieldLayerId = layer.id + 1U;
        runtimeState->water.regionPointPreviewOverrides.insert(WaterRegionPreviewKey(layer));
        runtimeState->water.fieldLayers.push_back(std::move(layer));
        runtimeState->water.selectedFieldLayerIndex = runtimeState->water.fieldLayers.size() - 1U;
    }
    auto& layer = runtimeState->water.fieldLayers[runtimeState->water.selectedFieldLayerIndex.value()];
    layer.vertices.push_back(pivot->point);
    layer.hull = invisible_places::water::BuildWaterRegionHull(layer.vertices);
    if (layer.vertices.size() >= 3U) {
        MarkWaterRegionLayerEffectsDirty(runtimeState, layer);
    }
    runtimeState->statusMessage =
        "Added field region vertex " + std::to_string(layer.vertices.size()) + " to " + layer.name + ".";
    runtimeState->errorMessage.clear();
    return true;
}

bool MoveWaterEmitterAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr || !runtimeState->water.movingEmitterIndex.has_value()) {
        return false;
    }

    const auto emitterIndex = runtimeState->water.movingEmitterIndex.value();
    if (emitterIndex >= runtimeState->water.emitters.size()) {
        runtimeState->water.movingEmitterIndex.reset();
        runtimeState->errorMessage = "The selected water source is no longer available to move.";
        runtimeState->statusMessage.clear();
        return false;
    }

    const auto pivot =
        ResolveWaterSourcePlacementPivot(*runtimeState, viewport, screenPoint);
    if (!pivot.has_value()) {
        runtimeState->errorMessage =
            "No CPU-ready canonical analysis surface was available for moving "
            "the water source.";
        runtimeState->statusMessage.clear();
        return false;
    }

    auto& emitter = runtimeState->water.emitters[emitterIndex];
    emitter.position = pivot->point;
    emitter.confidence =
        std::max(emitter.confidence, pivot->matchedSurface ? 0.85F : 0.55F);
    runtimeState->water.selectedEmitterIndex = emitterIndex;
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    MarkWaterPathDirty(runtimeState, emitter.id);
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = emitter.position;
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->statusMessage =
        "Moved water source " + emitter.name + "; path bake required.";
    runtimeState->errorMessage.clear();
    return true;
}

std::uint32_t NextDynamicMeshAttractorId(const WaterDynamicMeshFlowSettings& settings) {
    std::uint32_t nextId = 1U;
    for (const auto& attractor : settings.attractors) {
        nextId = std::max(nextId, attractor.id + 1U);
    }
    return nextId;
}

bool PlaceDynamicMeshAttractorAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }

    const auto meshPoint =
        ProjectScreenPointToDynamicMeshSurfaceForPlacement(runtimeState, viewport, screenPoint, "mesh attractor");
    if (!meshPoint.has_value()) {
        return false;
    }

    auto& settings = runtimeState->water.dynamicMeshFlowSettings;
    WaterDynamicMeshAttractor attractor;
    attractor.id = NextDynamicMeshAttractorId(settings);
    attractor.name = "Attractor " + std::to_string(attractor.id);
    attractor.position = meshPoint.value();
    attractor.enabled = true;
    settings.attractors.push_back(std::move(attractor));
    runtimeState->water.selectedDynamicMeshAttractorIndex = settings.attractors.size() - 1U;
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = meshPoint.value();
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->statusMessage = "Placed dynamic mesh attractor on the mesh surface.";
    runtimeState->errorMessage.clear();
    return true;
}

bool MoveDynamicMeshAttractorAtScreenPoint(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr || !runtimeState->water.movingDynamicMeshAttractorIndex.has_value()) {
        return false;
    }
    auto& settings = runtimeState->water.dynamicMeshFlowSettings;
    const auto attractorIndex = runtimeState->water.movingDynamicMeshAttractorIndex.value();
    if (attractorIndex >= settings.attractors.size()) {
        runtimeState->water.movingDynamicMeshAttractorIndex.reset();
        runtimeState->errorMessage = "The selected dynamic mesh attractor is no longer available to move.";
        runtimeState->statusMessage.clear();
        return false;
    }

    const auto meshPoint =
        ProjectScreenPointToDynamicMeshSurfaceForPlacement(runtimeState, viewport, screenPoint, "mesh attractor");
    if (!meshPoint.has_value()) {
        return false;
    }

    auto& attractor = settings.attractors[attractorIndex];
    attractor.position = meshPoint.value();
    attractor.enabled = true;
    runtimeState->water.selectedDynamicMeshAttractorIndex = attractorIndex;
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    runtimeState->pivotOverlay.visible = true;
    runtimeState->pivotOverlay.pivot = meshPoint.value();
    runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
    runtimeState->statusMessage = "Moved dynamic mesh attractor " + attractor.name + ".";
    runtimeState->errorMessage.clear();
    return true;
}

void SuggestWaterEmittersForActiveLayer(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage = "Canonical analysis sources are still loading or unavailable; source suggestions are disabled.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto& session = runtimeState->sessions[supportIndex.value()];
    if (session.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(
        runtimeState,
        session,
        defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water source suggestions.";
        runtimeState->statusMessage.clear();
        return;
    }

    const auto firstId = NextWaterEmitterId(*runtimeState);
    auto suggestions = invisible_places::water::SuggestWaterEmitters(
        *supportCloud,
        runtimeState->water.emitters,
        defaultSourceSettings.path,
        firstId,
        runtimeState->water.maxAutoSuggestions);
    if (suggestions.empty()) {
        runtimeState->statusMessage = "No conservative water source candidates were found.";
        runtimeState->errorMessage.clear();
        return;
    }

    runtimeState->water.nextEmitterId = firstId + static_cast<std::uint32_t>(suggestions.size());
    runtimeState->water.emitters.insert(
        runtimeState->water.emitters.end(),
        std::make_move_iterator(suggestions.begin()),
        std::make_move_iterator(suggestions.end()));
    for (std::uint32_t emitterId = firstId; emitterId < runtimeState->water.nextEmitterId; ++emitterId) {
        MarkWaterPathDirty(runtimeState, emitterId);
    }
    runtimeState->statusMessage =
        "Suggested " + FormatPointCount(runtimeState->water.nextEmitterId - firstId) +
        " conservative water sources; path bake required.";
    runtimeState->errorMessage.clear();
}

void PropagateWaterEmittersToActiveLayer(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage = "Canonical analysis sources are still loading or unavailable; emitter propagation is disabled.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto& targetSession = runtimeState->sessions[supportIndex.value()];
    if (targetSession.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(
        runtimeState,
        targetSession,
        defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water source snapping.";
        runtimeState->statusMessage.clear();
        return;
    }

    std::vector<WaterEmitter> propagated;
    std::vector<std::uint32_t> propagatedEmitterIds;
    for (const auto& emitter : runtimeState->water.emitters) {
        if (emitter.status == WaterEmitterStatus::Disabled ||
            emitter.origin == WaterEmitterOrigin::Propagated) {
            continue;
        }
        const auto& pathSettings =
            invisible_places::water::ResolveWaterSourceSettings(
                emitter,
                runtimeState->water.emitters,
                defaultSourceSettings).path;
        const auto snapped = invisible_places::water::SnapEmitterToCloud(
            *supportCloud,
            emitter.position,
            pathSettings);
        if (!snapped.has_value()) {
            continue;
        }

        WaterEmitter clone = emitter;
        clone.id = NextWaterEmitterId(*runtimeState) + static_cast<std::uint32_t>(propagated.size());
        clone.name = emitter.name + " snapped";
        clone.position = snapped.value();
        clone.origin = WaterEmitterOrigin::Propagated;
        clone.status = WaterEmitterStatus::Accepted;
        clone.parentId = emitter.id;
        clone.radius = std::max(pathSettings.supportVoxelSize * 3.0F, emitter.radius * 0.45F);
        clone.confidence = std::min(0.95F, emitter.confidence);
        propagatedEmitterIds.push_back(clone.id);
        propagated.push_back(std::move(clone));
    }

    if (propagated.empty()) {
        runtimeState->statusMessage = "No emitters were propagated to the active scale.";
        runtimeState->errorMessage.clear();
        return;
    }

    runtimeState->water.nextEmitterId =
        NextWaterEmitterId(*runtimeState) + static_cast<std::uint32_t>(propagated.size());
    runtimeState->water.emitters.insert(
        runtimeState->water.emitters.end(),
        std::make_move_iterator(propagated.begin()),
        std::make_move_iterator(propagated.end()));
    for (const auto emitterId : propagatedEmitterIds) {
        MarkWaterPathDirty(runtimeState, emitterId);
    }
    runtimeState->statusMessage = "Snapped accepted emitters to the active support scene; path bake required.";
    runtimeState->errorMessage.clear();
}

ProjectDocument BuildProjectDocument(const PreviewRuntimeState& runtimeState) {
    ProjectDocument document;
    document.projectName = runtimeState.persistence.projectName;
    const auto projectWindowSize =
        ProjectLiveViewWindowSize(runtimeState.projectSettings);
    document.liveViewWindowWidth =
        static_cast<std::uint32_t>(projectWindowSize.width);
    document.liveViewWindowHeight =
        static_cast<std::uint32_t>(projectWindowSize.height);
    document.lockLiveViewWindowSize =
        runtimeState.projectSettings.lockLiveViewWindowSize;
    document.backgroundColor = runtimeState.projectSettings.backgroundColor;
    document.eyeDomeLightingEnabled = runtimeState.projectSettings.eyeDomeLightingEnabled;
    document.proResAlphaPreviewEnabled = runtimeState.projectSettings.proResAlphaPreviewEnabled;
    document.eyeDomeLightingThickness = runtimeState.projectSettings.eyeDomeLightingThickness;
    document.constantUpdateView = runtimeState.projectSettings.constantUpdateView;
    document.liveVisualEffects = runtimeState.projectSettings.liveVisualEffects;
    document.previewPerformanceMode = runtimeState.projectSettings.previewPerformanceMode;
    document.loadAllScalarFields = runtimeState.projectSettings.loadAllScalarFields;
    document.scalarFieldBudgetGigabytes =
        runtimeState.projectSettings.scalarFieldBudgetGigabytes;
    document.sidePanelPinned = runtimeState.sidePanel.pinned;
    document.showLidarTab = runtimeState.showLidarTab;
    document.showGsplatTab = runtimeState.showGsplatTab;
    document.orbitControlMode = runtimeState.cameraInteraction.orbitControlMode;
    document.autoLowerGsplatQualityWhileNavigating =
        runtimeState.projectSettings.autoLowerGsplatQualityWhileNavigating;
    document.pointCloudPreviewLodMode = PointCloudPreviewLodMode::FullResolution;
    document.interactivePointCap = runtimeState.projectSettings.interactivePointCap;
    document.pointCloudRendererMode = runtimeState.projectSettings.pointCloudRendererMode;
    document.cameraState = runtimeState.camera.CaptureState();
    document.cameraShots = runtimeState.cameraShots;
    for (auto& shot : document.cameraShots) {
        CanonicalizeAssociatedLayerPathsForSceneGroups(runtimeState, &shot.associatedLayerPaths);
    }
    document.cameraPathShotIndices = runtimeState.cameraPanel.pathShotIndices;
    document.cameraPathDurationFrames = runtimeState.cameraPanel.pathDurationFrames;
    document.lastAnimationPath = runtimeState.animationPanel.currentFilePath;
    if (runtimeState.animationPanel.currentPath.has_value() &&
        !runtimeState.animationPanel.currentFilePath.empty()) {
        document.activeAnimationPath =
            runtimeState.animationPanel.currentFilePath;
        document.activeAnimationPosition = std::clamp(
            runtimeState.animationPanel.scrubAmount,
            0.0F,
            1.0F);
    }
    document.hasSavedAnimationRegistry = true;
    for (std::size_t index = 0; index < runtimeState.animationPanel.availableFiles.size(); ++index) {
        auto associatedLayerPaths =
            AnimationRegistryAssociationPaths(runtimeState.animationPanel, index);
        CanonicalizeAssociatedLayerPathsForSceneGroups(runtimeState, &associatedLayerPaths);
        const auto* registryPath = RegistryAnimationPath(
            runtimeState,
            index);
        document.savedAnimations.push_back(
            {.filePath = runtimeState.animationPanel.availableFiles[index],
             .associatedLayerPaths = std::move(associatedLayerPaths),
             .velocityBlendLink =
                 registryPath != nullptr
                     ? registryPath->velocityBlendLink
                     : std::nullopt});
    }
    document.renderJobSettings = RenderSettingsFromExportPreset(
        ViewedExportPreset(runtimeState),
        runtimeState.renderSettings.outputDirectory);
    document.exportPresets = runtimeState.animationPanel.exportPresets;
    document.selectedExportPresetName = runtimeState.animationPanel.selectedExportPresetName;
    document.tempExportPreset = runtimeState.animationPanel.editedExportPreset;
    document.pointVisuals.reserve(runtimeState.pointVisualLibrary.pointVisuals.size());
    for (const auto& visual : runtimeState.pointVisualLibrary.pointVisuals) {
        ProjectLayerDocument::PointVisual visualDocument;
        visualDocument.name = NormalizePointVisualName(visual.name);
        visualDocument.style = visual.style;
        ClearPointCloudStyleShoreline(&visualDocument.style);
        document.pointVisuals.push_back(std::move(visualDocument));
    }
    if (document.pointVisuals.empty()) {
        if (const auto sessionIt = std::find_if(
                runtimeState.sessions.begin(),
                runtimeState.sessions.end(),
                [](const PreviewLayerSession& session) {
                    return IsProjectPointVisualSession(session);
                });
            sessionIt != runtimeState.sessions.end()) {
            auto style = sessionIt->pointStyle;
            ClearPointCloudStyleShoreline(&style);
            document.pointVisuals.push_back(
                {.name = std::string{kDefaultPointVisualName}, .style = style});
        }
    }
    document.selectedPointVisualName =
        runtimeState.pointVisualLibrary.selectedPointVisualName.empty()
            ? std::string{kDefaultPointVisualName}
            : NormalizePointVisualName(runtimeState.pointVisualLibrary.selectedPointVisualName);
    if (document.pointVisuals.empty()) {
        document.pointVisuals.push_back({.name = std::string{kDefaultPointVisualName}, .style = PointCloudStyleState{}});
        document.selectedPointVisualName = std::string{kDefaultPointVisualName};
    }
    document.sceneVisualStates.reserve(runtimeState.pointVisualLibrary.sceneVisualStates.size());
    for (const auto& state : runtimeState.pointVisualLibrary.sceneVisualStates) {
        if (state.sceneGroupName.empty()) {
            continue;
        }
        invisible_places::serialization::ScenePointVisualStateDocument stateDocument;
        stateDocument.sceneGroupName = state.sceneGroupName;
        stateDocument.visual.name = NormalizePointVisualName(state.visual.name);
        stateDocument.visual.style = state.visual.style;
        ClearPointCloudStyleShoreline(&stateDocument.visual.style);
        document.sceneVisualStates.push_back(std::move(stateDocument));
    }
    document.gsplatVisualStyle = runtimeState.projectSettings.gsplatVisualStyle;
    document.waterEmitters = runtimeState.water.emitters;
    document.waterManualFlowPaths = runtimeState.water.manualFlowPaths;
    document.waterSeepageNodes = runtimeState.water.seepageNodes;
    document.waterShorelineDefaultSettings.reset();
    document.waterShorelineProfiles =
        runtimeState.water.shorelineProfiles;
    document.selectedWaterShorelineProfileName.clear();
    document.waterShorelineInstances = runtimeState.water.shorelineInstances;
    document.nextWaterShorelineInstanceId =
        runtimeState.water.nextShorelineInstanceId;
    document.waterSeepageDefaultNodeSettings =
        runtimeState.water.defaultSeepageNodeSettings;
    document.waterSeepageNodeSettingsProfiles =
        WithoutPresetSeepageNodeSettingsProfiles(
            runtimeState.water.seepageNodeSettingsProfiles);
    document.waterSeepageDefaultLook = runtimeState.water.defaultSeepageLook;
    document.waterSeepageLookProfiles = WithoutPresetSeepageLookProfiles(
        runtimeState.water.seepageLookProfiles);
    document.waterSeepageResponseProfiles = WithoutPresetSeepageResponseProfiles(
        runtimeState.water.seepageResponseProfiles);
    document.waterScenarios = runtimeState.water.seepageScenarios;
    document.selectedWaterScenarioId = runtimeState.water.selectedSeepageScenarioId;
    document.waterTimingRuns = runtimeState.water.timingRuns;
    document.waterTimingRunSequence = runtimeState.water.nextTimingRunSequence;
    document.waterFeatureTimingRuns =
        runtimeState.water.featureTimingRunsByScenario;
    document.waterKeyedSettingsProfiles =
        runtimeState.water.keyedSettingsProfiles;
    document.waterFeatureTimingRunSequence =
        runtimeState.water.nextFeatureTimingRunSequence;
    document.timingTakes = runtimeState.water.timingTakes;
    document.selectedTimingTakeId =
        invisible_places::timing::NormalizeTimingTakeId(
            runtimeState.water.selectedTimingTakeId);
    document.timingTakeStates =
        runtimeState.water.timingTakeSceneStates;
    document.timingColourisePalettes =
        runtimeState.water.savedTimingColourisePalettes;
    document.timingScalarBoundsStores =
        runtimeState.water.timingScalarBoundsStores;
    document.timingTakeSequence =
        runtimeState.water.nextTimingTakeSequence;
    document.timingColourisePaletteSequence =
        runtimeState.water.nextTimingColourisePaletteSequence;
    document.tempWaterScenario = runtimeState.water.editedScenario;
    document.waterRippleLayers = runtimeState.water.rippleLayers;
    document.waterFieldLayers = runtimeState.water.fieldLayers;
    document.waterFlowTrailSettings = runtimeState.water.flowTrailSettings;
    document.waterShowFlowTrails = runtimeState.water.showFlowTrails;
    document.waterFieldSettings = runtimeState.water.fieldSettings;
    document.waterFieldTrailSettings = runtimeState.water.fieldTrailSettings;
    document.waterDynamicMeshFlowSettings = runtimeState.water.dynamicMeshFlowSettings;
    document.waterRainSettings = runtimeState.water.collisionRainSettings;
    document.waterRainVisualSettings = runtimeState.water.rainVisual;
    document.activeWaterSceneGroupName =
        runtimeState.water.authoritativeWaterSurfaceSceneGroupName.empty()
            ? runtimeState.water.activeWaterSurfaceSceneGroupName
            : runtimeState.water.authoritativeWaterSurfaceSceneGroupName;
    {
        invisible_places::serialization::WaterSceneStateDocument waterSceneState;
        waterSceneState.sceneGroupName =
            document.activeWaterSceneGroupName.empty()
                ? std::string{"Default"}
                : document.activeWaterSceneGroupName;
        if (document.activeWaterSceneGroupName.empty()) {
            const auto supportIndex =
                ResolveWaterRuntimeSessionIndex(runtimeState);
            if (supportIndex.has_value() &&
                supportIndex.value() < runtimeState.sessions.size()) {
                const auto sceneKey = ProjectVisualSceneKey(
                    runtimeState.sessions[supportIndex.value()]);
                if (!sceneKey.empty()) {
                    waterSceneState.sceneGroupName = sceneKey;
                    document.activeWaterSceneGroupName = sceneKey;
                }
            }
        }
        waterSceneState.emitters = runtimeState.water.emitters;
        waterSceneState.manualFlowPaths = runtimeState.water.manualFlowPaths;
        waterSceneState.seepageNodes = runtimeState.water.seepageNodes;
        waterSceneState.rippleLayers = runtimeState.water.rippleLayers;
        waterSceneState.fieldLayers = runtimeState.water.fieldLayers;
        waterSceneState.pathCache = CurrentWaterPathCacheForDocument(runtimeState);
        waterSceneState.rippleRuntimeCaches = CurrentWaterRippleRuntimeCachesForDocument(runtimeState);
        waterSceneState.dynamicMeshPath = runtimeState.water.dynamicMeshFlowSettings.meshPath;
        document.waterSceneStates.push_back(std::move(waterSceneState));
    }
    document.waterSourceSettings = runtimeState.water.defaultSourceSettings;
    document.tempWaterSourceSettings = runtimeState.water.tempDefaultSourceSettings;
    document.waterTrailGeometry = runtimeState.water.defaultTrailGeometry;
    document.waterAnimationTrailSettings = runtimeState.water.defaultAnimationTrailSettings;
    document.tempWaterAnimationTrailSettings = runtimeState.water.tempDefaultAnimationTrailSettings;
    document.waterAnimationTrailProfiles.clear();
    document.waterAnimationTrailProfiles.reserve(runtimeState.water.animationTrailProfiles.size());
    for (const auto& profile : runtimeState.water.animationTrailProfiles) {
        document.waterAnimationTrailProfiles.push_back({
            .name = NormalizeWaterAnimationTrailProfileName(profile.name),
            .settings = profile.settings,
        });
    }
    document.selectedWaterPathProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedPathProfileName);
    document.selectedWaterLaneProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedLaneProfileName);
    document.selectedWaterTrailProfileName =
        NormalizeWaterProfileName(runtimeState.water.selectedTrailProfileName);
    document.tempWaterPathProfileSettings = runtimeState.water.editedPathProfileSettings;
    document.tempWaterLaneProfileSettings = runtimeState.water.editedLaneProfileSettings;
    document.waterPathProfiles.reserve(runtimeState.water.pathProfiles.size());
    for (const auto& profile : runtimeState.water.pathProfiles) {
        document.waterPathProfiles.push_back(MakeWaterPathProfileDocument(profile));
    }
    document.waterLaneProfiles.reserve(runtimeState.water.laneProfiles.size());
    for (const auto& profile : runtimeState.water.laneProfiles) {
        document.waterLaneProfiles.push_back(MakeWaterLaneProfileDocument(profile));
    }
    document.waterTrailProfiles.reserve(runtimeState.water.trailProfiles.size());
    for (const auto& profile : runtimeState.water.trailProfiles) {
        document.waterTrailProfiles.push_back(MakeWaterTrailProfileDocument(profile));
    }
    if (runtimeState.water.editedTrailProfile.has_value()) {
        document.tempWaterTrailProfile =
            MakeWaterTrailProfileDocument(runtimeState.water.editedTrailProfile.value());
    }
    if (runtimeState.water.editedDynamicMeshTrailProfile.has_value()) {
        document.tempWaterDynamicMeshTrailProfile =
            MakeWaterTrailProfileDocument(
                runtimeState.water.editedDynamicMeshTrailProfile.value());
    }
    document.waterCausticLookSettings = runtimeState.water.defaultCausticLookSettings;
    document.tempWaterCausticLookSettings = runtimeState.water.tempDefaultCausticLookSettings;
    document.waterPointVisualStyle = runtimeState.water.defaultPointVisualStyle;
    document.tempWaterPointVisualStyle = runtimeState.water.tempDefaultPointVisualStyle;
    auto appendWaterProjectVisual = [&document](std::string_view name, const PointCloudStyleState& style) {
        const auto normalized = NormalizePointVisualName(name);
        if (!IsWaterProjectCustomVisualName(normalized)) {
            return;
        }
        const auto existing = std::find_if(
            document.waterPointVisuals.begin(),
            document.waterPointVisuals.end(),
            [&normalized](const ProjectLayerDocument::PointVisual& visual) {
                return NormalizePointVisualName(visual.name) == normalized;
            });
        if (existing != document.waterPointVisuals.end()) {
            return;
        }

        ProjectLayerDocument::PointVisual visual;
        visual.name = normalized;
        visual.style = MakeWaterTrailExportStyle(style);
        document.waterPointVisuals.push_back(std::move(visual));
    };
    for (const auto& visual : runtimeState.water.pointVisuals) {
        appendWaterProjectVisual(visual.name, visual.style);
    }
    document.selectedWaterPointVisualName =
        runtimeState.water.selectedPointVisualName.empty()
            ? std::string{"Water Flow_preset"}
            : NormalizePointVisualName(runtimeState.water.selectedPointVisualName);
    if (document.selectedWaterPointVisualName.empty() ||
        document.selectedWaterPointVisualName == std::string{kDefaultPointVisualName}) {
        document.selectedWaterPointVisualName = "Water Flow_preset";
    } else if (IsEditedPointVisualName(document.selectedWaterPointVisualName)) {
        document.selectedWaterPointVisualName = BasePointVisualName(document.selectedWaterPointVisualName);
    }
    document.waterSettings.path = runtimeState.water.defaultSourceSettings.path;
    document.waterSettings.trail.particleJitter =
        runtimeState.water.defaultSourceSettings.trailShape.particleJitter;
    document.waterSettings.trail.splineAnchorSpacing =
        runtimeState.water.defaultSourceSettings.trailShape.splineAnchorSpacing;
    document.waterSettings.trail.particleDensity =
        runtimeState.water.defaultAnimationTrailSettings.particleDensity;
    document.waterSettings.trail.particleSpeed =
        runtimeState.water.defaultAnimationTrailSettings.particleSpeed;
    document.waterSettings.visual.colorVariation =
        runtimeState.water.defaultAnimationTrailSettings.colorVariation;
    if (runtimeState.water.tempDefaultSourceSettings.has_value() ||
        runtimeState.water.tempDefaultAnimationTrailSettings.has_value()) {
        auto tempBundle = document.waterSettings;
        if (runtimeState.water.tempDefaultSourceSettings.has_value()) {
            tempBundle.path = runtimeState.water.tempDefaultSourceSettings->path;
            tempBundle.trail.particleJitter =
                runtimeState.water.tempDefaultSourceSettings->trailShape.particleJitter;
            tempBundle.trail.splineAnchorSpacing =
                runtimeState.water.tempDefaultSourceSettings->trailShape.splineAnchorSpacing;
        }
        if (runtimeState.water.tempDefaultAnimationTrailSettings.has_value()) {
            tempBundle.trail.particleDensity =
                runtimeState.water.tempDefaultAnimationTrailSettings->particleDensity;
            tempBundle.trail.particleSpeed =
                runtimeState.water.tempDefaultAnimationTrailSettings->particleSpeed;
            tempBundle.visual.colorVariation =
                runtimeState.water.tempDefaultAnimationTrailSettings->colorVariation;
        }
        document.tempWaterSettings = tempBundle;
    }
    document.waterBakeSettings = runtimeState.water.defaultSourceSettings.path;
    document.waterRenderSettings = document.waterSettings;
    document.waterPathCache = CurrentWaterPathCacheForDocument(runtimeState);
    document.waterRippleRuntimeCaches = CurrentWaterRippleRuntimeCachesForDocument(runtimeState);

    if (runtimeState.selectedSessionIndex.has_value()) {
        const auto& selectedSession =
            runtimeState.sessions[runtimeState.selectedSessionIndex.value()];
        document.selectedLayerPath = selectedSession.sourcePath;
        document.activeSceneGroupName = selectedSession.sceneGroupName;
    }

    document.scenePointCloudGroups.reserve(runtimeState.pointCloudScenes.size());
    for (const auto& scene : runtimeState.pointCloudScenes) {
        invisible_places::serialization::ScenePointCloudGroupDocument groupDocument;
        groupDocument.sceneGroupName = scene.sceneGroupName;
        groupDocument.displaySpacingMeters =
            scene.committedDisplaySpacingMicrometres.has_value()
                ? static_cast<float>(scene.committedDisplaySpacingMicrometres.value()) / 1'000'000.0F
                : 0.0F;
        groupDocument.displayLoaded = scene.displayLoaded;
        groupDocument.displayVisible = scene.displayVisible;
        groupDocument.waterSurfaceCache = scene.waterSurfaceCache;
        for (std::size_t roleIndex = 0;
             roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
             ++roleIndex) {
            const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
            invisible_places::serialization::ScenePointCloudRoleSourceDocument roleDocument;
            roleDocument.sceneRole = std::string{invisible_places::scene::ScenePointCloudRoleName(role)};
            if (scene.analysisSessionIndices[roleIndex].has_value()) {
                roleDocument.analysisSourcePath = runtimeState.sessions[
                    scene.analysisSessionIndices[roleIndex].value()].sourcePath;
            }
            if (scene.committedDisplaySessionIndices[roleIndex].has_value()) {
                roleDocument.displaySourcePath = runtimeState.sessions[
                    scene.committedDisplaySessionIndices[roleIndex].value()].sourcePath;
            }
            groupDocument.roleSources.push_back(std::move(roleDocument));
        }
        document.scenePointCloudGroups.push_back(std::move(groupDocument));
    }

    document.layers.reserve(runtimeState.sessions.size());
    for (const auto& session : runtimeState.sessions) {
        if (IsGeneratedWaterOverlaySession(session)) {
            continue;
        }

        ProjectLayerDocument layerDocument;
        layerDocument.kind = session.kind == LayerKind::GaussianSplat
                                 ? invisible_places::serialization::SerializedLayerKind::GaussianSplat
                                 : invisible_places::serialization::SerializedLayerKind::PointCloud;
        layerDocument.sourcePath = session.sourcePath;
        layerDocument.sceneGroupName = session.sceneGroupName;
        layerDocument.sceneRole = session.sceneRole;
        layerDocument.inferredPointSpacingMeters = session.inferredPointSpacingMeters;
        layerDocument.pointSpacingMeters = EffectivePointSpacingMeters(session);
        layerDocument.pointSpacingManualOverride = session.pointSpacingManualOverride;
        layerDocument.scenePrimaryRole = session.scenePrimaryRole;
        layerDocument.selectedSceneVariantPath = session.selectedSceneVariantPath;
        layerDocument.loaded = session.loaded;
        layerDocument.visible = session.visible;
        if (const auto* scene = FindScenePointCloudRuntime(runtimeState, session); scene != nullptr) {
            const auto role = invisible_places::scene::ParseScenePointCloudRole(session.sceneRole);
            if (role.has_value()) {
                const auto roleIndex = invisible_places::scene::ScenePointCloudRoleIndex(role.value());
                if (scene->analysisSessionIndices[roleIndex].has_value()) {
                    layerDocument.selectedSceneVariantPath = runtimeState.sessions[
                        scene->analysisSessionIndices[roleIndex].value()].sourcePath;
                }
            }
            layerDocument.loaded = scene->displayLoaded && session.committedDisplaySource;
            layerDocument.visible = layerDocument.loaded && scene->displayVisible;
        }
        if (session.kind == LayerKind::PointCloud) {
            layerDocument.pointBudgetActivePoints =
                session.kind == LayerKind::PointCloud ? session.totalPrimitives : session.pointBudget.activePoints;
        }
        document.layers.push_back(std::move(layerDocument));
    }

    return document;
}

std::optional<std::size_t> FindSessionIndexBySourcePath(
    const PreviewRuntimeState& runtimeState,
    const std::filesystem::path& sourcePath) {
    for (std::size_t index = 0; index < runtimeState.sessions.size(); ++index) {
        if (PathsReferToSameLocation(
                runtimeState.sessions[index].sourcePath,
                sourcePath)) {
            return index;
        }
    }

    return std::nullopt;
}

std::optional<std::size_t> FindSessionIndexForSceneGroup(
    const PreviewRuntimeState& runtimeState,
    std::string_view sceneGroupName) {
    if (sceneGroupName.empty()) {
        return std::nullopt;
    }

    const auto sceneIt = std::find_if(
        runtimeState.pointCloudScenes.begin(),
        runtimeState.pointCloudScenes.end(),
        [&](const ScenePointCloudRuntime& scene) {
            return scene.sceneGroupName == sceneGroupName;
        });
    if (sceneIt != runtimeState.pointCloudScenes.end()) {
        for (const auto sessionIndex :
             sceneIt->committedDisplaySessionIndices) {
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState.sessions.size()) {
                return sessionIndex;
            }
        }
        for (const auto sessionIndex : sceneIt->analysisSessionIndices) {
            if (sessionIndex.has_value() &&
                sessionIndex.value() < runtimeState.sessions.size()) {
                return sessionIndex;
            }
        }
    }

    const auto sessionIt = std::find_if(
        runtimeState.sessions.begin(),
        runtimeState.sessions.end(),
        [&](const PreviewLayerSession& session) {
            return session.sceneGroupName == sceneGroupName &&
                   !IsGeneratedWaterOverlaySession(session);
        });
    return sessionIt == runtimeState.sessions.end()
               ? std::nullopt
               : std::optional<std::size_t>{
                     static_cast<std::size_t>(
                         std::distance(
                             runtimeState.sessions.begin(),
                             sessionIt))};
}

void StartQueuedLayerLoadIfIdle(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        runtimeState->pendingLoad.has_value() ||
        runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
        runtimeState->water.waterSurfaceCachePreprocessPending ||
        runtimeState->persistence.queuedLoads.empty()) {
        return;
    }

    const auto nextLoad = runtimeState->persistence.queuedLoads.front();
    runtimeState->persistence.queuedLoads.erase(runtimeState->persistence.queuedLoads.begin());
    BeginLayerLoad(
        nextLoad.sessionIndex,
        runtimeState,
        nextLoad.purpose,
        nextLoad.sceneSwitchGeneration);
}

const SceneDisplayBundleRuntime* FinestSceneDisplayBundle(
    const ScenePointCloudRuntime& scene) {
    if (scene.displayBundles.empty()) {
        return nullptr;
    }
    return &*std::min_element(
        scene.displayBundles.begin(),
        scene.displayBundles.end(),
        [](const SceneDisplayBundleRuntime& left, const SceneDisplayBundleRuntime& right) {
            if (left.spacingMicrometres != right.spacingMicrometres) {
                return left.spacingMicrometres < right.spacingMicrometres;
            }
            return left.totalPointCount > right.totalPointCount;
        });
}

std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
SceneFullDensityExportSessionIndices(const ScenePointCloudRuntime& scene) {
    std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
        indices{};
    if (const auto* finestBundle = FinestSceneDisplayBundle(scene); finestBundle != nullptr) {
        for (std::size_t roleIndex = 0; roleIndex < finestBundle->sessionIndices.size(); ++roleIndex) {
            indices[roleIndex] = finestBundle->sessionIndices[roleIndex];
        }
        return indices;
    }
    return scene.analysisSessionIndices;
}

bool SceneFullDensityExportUsesSession(
    const ScenePointCloudRuntime& scene,
    std::size_t sessionIndex) {
    const auto exportIndices = SceneFullDensityExportSessionIndices(scene);
    return std::any_of(
        exportIndices.begin(),
        exportIndices.end(),
        [&](const std::optional<std::size_t>& candidate) {
            return candidate.has_value() && candidate.value() == sessionIndex;
        });
}

bool IsExportPointCloudSourceCandidate(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (sessionIndex >= runtimeState.sessions.size()) {
        return false;
    }

    const auto& session = runtimeState.sessions[sessionIndex];
    if (session.kind != LayerKind::PointCloud ||
        IsInactiveLegacyWaterOverlaySession(session)) {
        return false;
    }
    if (!IsSceneGroupedPointCloud(session)) {
        return IsRenderablePointCloudSource(runtimeState, session);
    }

    const auto* scene = FindScenePointCloudRuntime(runtimeState, session);
    if (scene == nullptr || !scene->displayLoaded || !scene->displayVisible) {
        return false;
    }

    // Final exports ignore the live density switch. The viewport can stay on a
    // coarse bundle, while output renders the finest complete scene bundle.
    return SceneFullDensityExportUsesSession(*scene, sessionIndex);
}

bool IsExportPointCloudSourceReady(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (!IsExportPointCloudSourceCandidate(runtimeState, sessionIndex)) {
        return false;
    }
    const auto& session = runtimeState.sessions[sessionIndex];
    return session.loaded &&
           session.gpuResident &&
           session.offlinePointCloud != nullptr;
}

bool IsGpuAnimationExportPointCloudSourceReady(
    const PreviewRuntimeState& runtimeState,
    std::size_t sessionIndex) {
    if (IsExportPointCloudSourceReady(runtimeState, sessionIndex)) {
        return true;
    }
    if (!IsExportPointCloudSourceCandidate(runtimeState, sessionIndex) ||
        sessionIndex >= runtimeState.sessions.size()) {
        return false;
    }
    const auto& session = runtimeState.sessions[sessionIndex];
    return runtimeState.water.dynamicMeshFlowGpuSessionIndex == sessionIndex &&
           session.dynamicMeshFlowGpuPreview &&
           session.loaded &&
           session.gpuResident &&
           session.totalPrimitives > 0U;
}

bool EnsureFullDensityExportSourcesReady(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (runtimeState->water.flowTrailBuildJob.worker.joinable() ||
        runtimeState->water.flowTrailBuildJob.pendingCapture) {
        runtimeState->statusMessage =
            "Finishing the current Flow trail update before export.";
        runtimeState->errorMessage.clear();
        return false;
    }

    for (std::size_t sessionIndex = 0U;
         sessionIndex < runtimeState->sessions.size();
         ++sessionIndex) {
        const auto& session = runtimeState->sessions[sessionIndex];
        if (!session.loaded || !session.waterFlowGpuPreview) {
            continue;
        }
        const auto diagnostics = viewport->WaterFlowGpuSourceState(sessionIndex);
        const auto requestedRevision = std::max(
            diagnostics.requestedRevision,
            session.waterFlowGpuRevision);
        if (diagnostics.pending || requestedRevision == 0U ||
            diagnostics.completedRevision < requestedRevision) {
            runtimeState->statusMessage =
                "Finishing GPU Flow source " +
                std::to_string(session.waterFlowSourceId.value_or(0U)) +
                " before export (revision " +
                std::to_string(diagnostics.completedRevision) + " / " +
                std::to_string(requestedRevision) + ").";
            runtimeState->errorMessage.clear();
            return false;
        }
    }

    const bool needsFlowCpuSnapshot = std::any_of(
        runtimeState->sessions.begin(),
        runtimeState->sessions.end(),
        [](const PreviewLayerSession& session) {
            return session.loaded && session.waterFlowGpuPreview &&
                   (session.offlinePointCloud == nullptr ||
                    session.waterFlowCpuSnapshotRevision < session.waterFlowGpuRevision);
        });
    if (needsFlowCpuSnapshot) {
        if (!QueueWaterFlowCpuExportSnapshot(runtimeState)) {
            runtimeState->errorMessage =
                "The settled GPU Flow output could not queue its CPU export snapshot.";
            runtimeState->statusMessage.clear();
            return false;
        }
        runtimeState->statusMessage =
            "Preparing deterministic CPU Flow snapshots for offline export.";
        runtimeState->errorMessage.clear();
        return false;
    }

    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->statusMessage =
            "Preparing full-density export point clouds; wait for the current layer load to finish.";
        runtimeState->errorMessage.clear();
        return false;
    }

    bool queuedAny = false;
    std::size_t missingSourceCount = 0U;
    for (const auto& scene : runtimeState->pointCloudScenes) {
        if (!scene.displayLoaded || !scene.displayVisible) {
            continue;
        }
        const auto exportIndices = SceneFullDensityExportSessionIndices(scene);
        for (const auto sessionIndex : exportIndices) {
            if (!sessionIndex.has_value() || sessionIndex.value() >= runtimeState->sessions.size()) {
                ++missingSourceCount;
                continue;
            }

            const auto index = sessionIndex.value();
            auto& session = runtimeState->sessions[index];
            if (session.loaded && session.gpuResident && session.offlinePointCloud != nullptr) {
                continue;
            }
            QueueLayerLoad(runtimeState, index, PointCloudLoadPurpose::ExportGpu);
            queuedAny = true;
        }
    }

    if (missingSourceCount > 0U) {
        runtimeState->errorMessage =
            "The full-density export bundle is incomplete for one or more visible scenes.";
        runtimeState->statusMessage.clear();
        return false;
    }

    if (queuedAny) {
        StartQueuedLayerLoadIfIdle(runtimeState);
        runtimeState->statusMessage =
            "Preparing full-density export point clouds; start the export again when loading finishes.";
        runtimeState->errorMessage.clear();
        return false;
    }

    // Every export source is loaded; now every scalar field its authored
    // state references must be resident, so the frozen export renders with
    // the same field data the preview resolves.
    for (const auto& scene : runtimeState->pointCloudScenes) {
        if (!scene.displayLoaded || !scene.displayVisible) {
            continue;
        }
        for (const auto sessionIndex : SceneFullDensityExportSessionIndices(scene)) {
            if (!sessionIndex.has_value() ||
                sessionIndex.value() >= runtimeState->sessions.size()) {
                continue;
            }
            const auto missing = SessionMissingRequiredScalarFieldName(
                *runtimeState,
                runtimeState->sessions[sessionIndex.value()]);
            if (!missing.has_value()) {
                continue;
            }
            if (!runtimeState->pendingScalarFieldLoad.has_value()) {
                StartScalarFieldLoad(
                    runtimeState,
                    sessionIndex.value(),
                    missing.value());
            }
            runtimeState->statusMessage =
                "Loading scalar field '" + missing.value() +
                "' for export; start the export again when loading finishes.";
            runtimeState->errorMessage.clear();
            return false;
        }
    }
    return true;
}

struct ExportSourceReleaseSummary {
    std::size_t gpuSessionCount = 0U;
    std::size_t cpuSessionCount = 0U;
    std::size_t retainedAnalysisCpuSessionCount = 0U;
    std::string warning;
};

ExportSourceReleaseSummary ReleaseExportOnlyPointCloudSources(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    ExportSourceReleaseSummary summary;
    if (runtimeState == nullptr || viewport == nullptr) {
        return summary;
    }

    // Finest-density scene roles can be loaded and uploaded solely for an
    // export while the viewport continues to show a coarser committed bundle.
    // Reuse them throughout one batch, then retire only sessions with no live
    // display owner. Analysis sources keep their CPU payload because Shoreline,
    // Seepage, Rain, and Flow may still use it; their export-only GPU copy is
    // safe to release. The shared WaterSurfaceCache is independent and remains
    // warm.
    std::vector<std::size_t> releaseIndices;
    for (const auto& scene : runtimeState->pointCloudScenes) {
        for (const auto sessionIndex :
             SceneFullDensityExportSessionIndices(scene)) {
            if (!sessionIndex.has_value() ||
                sessionIndex.value() >= runtimeState->sessions.size() ||
                std::find(
                    releaseIndices.begin(),
                    releaseIndices.end(),
                    sessionIndex.value()) != releaseIndices.end()) {
                continue;
            }
            const auto& session =
                runtimeState->sessions[sessionIndex.value()];
            if (session.committedDisplaySource ||
                session.pendingDisplaySource) {
                continue;
            }
            const bool hasExportOnlyGpuCopy =
                session.gpuResident || session.loaded;
            const bool hasUnownedCpuCopy =
                session.cpuResident && !session.analysisSource;
            if (hasExportOnlyGpuCopy || hasUnownedCpuCopy) {
                releaseIndices.push_back(sessionIndex.value());
            }
        }
    }
    if (releaseIndices.empty()) {
        return summary;
    }

    const bool hasGpuResources = std::any_of(
        releaseIndices.begin(),
        releaseIndices.end(),
        [&](std::size_t index) {
            return runtimeState->sessions[index].gpuResident ||
                   runtimeState->sessions[index].loaded;
        });
    std::optional<PointCloudMutationBatchScope> mutationBatch;
    try {
        // Removing all role buffers under one resource mutation avoids a
        // separate device settle for ROCK, SAND, and VEG.
        if (hasGpuResources) {
            mutationBatch.emplace(viewport);
        }
        for (const auto index : releaseIndices) {
            auto& session = runtimeState->sessions[index];
            const bool hadGpuResources =
                session.gpuResident || session.loaded;
            const bool hadCpuResources = session.cpuResident;
            const bool releaseCpuResources = !session.analysisSource;
            UnloadLayerByIndex(
                runtimeState,
                viewport,
                index,
                releaseCpuResources);
            if (hadGpuResources &&
                !session.gpuResident && !session.loaded) {
                ++summary.gpuSessionCount;
            }
            if (hadCpuResources && releaseCpuResources &&
                !session.cpuResident) {
                ++summary.cpuSessionCount;
            } else if (hadCpuResources && !releaseCpuResources &&
                       session.cpuResident) {
                ++summary.retainedAnalysisCpuSessionCount;
            }
        }
        if (mutationBatch.has_value()) {
            mutationBatch->Finish();
        }
        if (summary.gpuSessionCount > 0U) {
            runtimeState->previewRenderStateSignatureValid = false;
        }
        std::cout
            << "Released export-only point-cloud residency: "
            << summary.gpuSessionCount << " GPU session(s), "
            << summary.cpuSessionCount << " unowned CPU session(s); retained "
            << summary.retainedAnalysisCpuSessionCount
            << " analysis CPU session(s)." << std::endl;
    } catch (const std::exception& error) {
        summary.warning =
            "Could not fully release export-only point-cloud resources: " +
            std::string{error.what()};
    }
    return summary;
}

void StopBackgroundWorkForShutdown(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }

    runtimeState->persistence.queuedLoads.clear();
    if (runtimeState->offlineRenderJob.active) {
        std::cout << "Requesting animation export shutdown..." << std::endl;
        runtimeState->offlineRenderJob.cancelRequested = true;
        RequestAnimationExportWriterCancellation(&runtimeState->offlineRenderJob);
        if (runtimeState->offlineRenderJob.worker.joinable()) {
            runtimeState->offlineRenderJob.worker = std::jthread{};
        }
    }
    runtimeState->exportPowerAssertion.Reset();
    if (runtimeState->water.regionPointPreviewJob.worker.joinable()) {
        runtimeState->water.regionPointPreviewJob.worker.request_stop();
        runtimeState->water.regionPointPreviewJob.worker = std::jthread{};
    }
    if (runtimeState->water.flowTrailBuildJob.worker.joinable()) {
        runtimeState->water.flowTrailBuildJob.worker.request_stop();
        runtimeState->water.flowTrailBuildJob.worker = std::jthread{};
    }
    runtimeState->water.flowTrailBuildJob.pendingCapture = false;
    CancelWaterSurfaceCacheWarmup(&runtimeState->water);
    auto& histogramJob =
        runtimeState->timingColouriseHistogram;
    histogramJob.pendingBatch.reset();
    if (histogramJob.worker.joinable()) {
        histogramJob.worker.request_stop();
        histogramJob.worker = std::jthread{};
    }
    histogramJob.shared.reset();
    histogramJob.activeBatchId.clear();
    if (runtimeState->animationVelocityPreviewJob.worker.joinable()) {
        runtimeState->animationVelocityPreviewJob.worker.request_stop();
        runtimeState->animationVelocityPreviewJob.worker = std::jthread{};
    }
    runtimeState->animationVelocityPreviewJob.shared.reset();
    if (runtimeState->animationStrongAlignmentJob.worker.joinable()) {
        runtimeState->animationStrongAlignmentJob.worker.request_stop();
        runtimeState->animationStrongAlignmentJob.worker = std::jthread{};
    }
    runtimeState->animationStrongAlignmentJob.shared.reset();
    if (runtimeState->animationMatchingFrameGhostJob.worker.joinable()) {
        runtimeState->animationMatchingFrameGhostJob.worker.request_stop();
        runtimeState->animationMatchingFrameGhostJob.worker = std::jthread{};
    }
    runtimeState->animationMatchingFrameGhostJob.shared.reset();
    runtimeState->animationMatchingFrameGhostJob.sourceCache.reset();

    if (!runtimeState->pendingLoad.has_value()) {
        return;
    }

    std::cout << "Waiting for background layer load to finish before shutdown..." << std::endl;
    runtimeState->pendingLoad->backgroundThread.request_stop();
    runtimeState->pendingLoad.reset();
}

const invisible_places::serialization::ScenePointCloudRoleSourceDocument*
FindSceneRoleSourceDocument(
    const invisible_places::serialization::ScenePointCloudGroupDocument& groupDocument,
    invisible_places::scene::ScenePointCloudRole role) {
    const auto roleName = invisible_places::scene::ScenePointCloudRoleName(role);
    const auto it = std::find_if(
        groupDocument.roleSources.begin(),
        groupDocument.roleSources.end(),
        [&](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
            return NormalizeSceneRoleName(source.sceneRole) == NormalizeSceneRoleName(roleName);
        });
    return it == groupDocument.roleSources.end() ? nullptr : &*it;
}

void ReleaseScenePointCloudResidency(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || viewport == nullptr || scene == nullptr) {
        return;
    }
    const auto sceneFolderKey = NormalizePathKey(scene->sourceFolder);
    for (std::size_t index = 0; index < runtimeState->sessions.size(); ++index) {
        auto& session = runtimeState->sessions[index];
        if (!IsSceneGroupedPointCloud(session) ||
            NormalizePathKey(session.sourcePath.parent_path()) != sceneFolderKey) {
            continue;
        }
        session.committedDisplaySource = false;
        session.pendingDisplaySource = false;
        if (session.gpuResident || session.cpuResident) {
            UnloadLayerByIndex(runtimeState, viewport, index, true);
        }
    }
    std::erase_if(
        runtimeState->persistence.queuedLoads,
        [&](const QueuedLayerLoad& load) {
            return load.sessionIndex < runtimeState->sessions.size() &&
                   IsSceneGroupedPointCloud(runtimeState->sessions[load.sessionIndex]) &&
                   NormalizePathKey(
                       runtimeState->sessions[load.sessionIndex].sourcePath.parent_path()) == sceneFolderKey;
        });
    scene->displayLoaded = false;
    scene->pendingDisplaySessionIndices = {};
    scene->pendingDisplaySpacingMicrometres.reset();
    scene->pendingMixedDisplay = false;
    scene->stagedReadyCount = 0U;

    runtimeState->water.activeSupportSessionIndex.reset();
    runtimeState->water.combinedSupportCloud.reset();
    runtimeState->water.combinedSupportSignature.clear();
    runtimeState->water.trailSurfaceIndex.reset();
    runtimeState->water.trailSurfaceIndexSupportSignature.clear();
    runtimeState->water.trailSurfaceIndexSupportPath.clear();
}

bool ApplyScenePointCloudGroupDocuments(
    const ProjectDocument& document,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    bool requestedAnyDisplay = false;
    for (auto& scene : runtimeState->pointCloudScenes) {
        const auto groupIt = std::find_if(
            document.scenePointCloudGroups.begin(),
            document.scenePointCloudGroups.end(),
            [&](const invisible_places::serialization::ScenePointCloudGroupDocument& group) {
                if (group.sceneGroupName != scene.sceneGroupName) {
                    return false;
                }
                const bool hasFolderQualifiedPath = std::any_of(
                    group.roleSources.begin(),
                    group.roleSources.end(),
                    [&](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
                        return (!source.analysisSourcePath.empty() &&
                                PathsReferToSameLocation(
                                    source.analysisSourcePath.parent_path(),
                                    scene.sourceFolder)) ||
                               (!source.displaySourcePath.empty() &&
                                PathsReferToSameLocation(
                                    source.displaySourcePath.parent_path(),
                                    scene.sourceFolder));
                    });
                const bool hasAnySourcePath = std::any_of(
                    group.roleSources.begin(),
                    group.roleSources.end(),
                    [](const invisible_places::serialization::ScenePointCloudRoleSourceDocument& source) {
                        return !source.analysisSourcePath.empty() || !source.displaySourcePath.empty();
                    });
                return hasFolderQualifiedPath || !hasAnySourcePath;
            });
        if (groupIt == document.scenePointCloudGroups.end()) {
            ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
            continue;
        }

        for (auto& session : runtimeState->sessions) {
            if (IsSceneGroupedPointCloud(session) &&
                PathsReferToSameLocation(
                    session.sourcePath.parent_path(),
                    scene.sourceFolder)) {
                session.analysisSource = false;
            }
        }
        for (std::size_t roleIndex = 0;
             roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
             ++roleIndex) {
            const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
            const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
            auto analysisIndex = scene.analysisSessionIndices[roleIndex];
            if (roleDocument != nullptr && !roleDocument->analysisSourcePath.empty()) {
                const auto savedIndex = SessionIndexForSourcePath(
                    runtimeState->sessions,
                    roleDocument->analysisSourcePath);
                if (savedIndex.has_value() &&
                    PathsReferToSameLocation(
                        runtimeState->sessions[savedIndex.value()].sourcePath.parent_path(),
                        scene.sourceFolder)) {
                    analysisIndex = savedIndex;
                } else {
                    scene.switchError = "Saved analysis source is missing; using the canonical scene source where available.";
                }
            }
            scene.analysisSessionIndices[roleIndex] = analysisIndex;
            if (analysisIndex.has_value()) {
                auto& analysisSession = runtimeState->sessions[analysisIndex.value()];
                analysisSession.analysisSource = true;
                for (auto& session : runtimeState->sessions) {
                    if (IsSceneGroupedPointCloud(session) &&
                        PathsReferToSameLocation(
                            session.sourcePath.parent_path(),
                            scene.sourceFolder) &&
                        NormalizeSceneRoleName(session.sceneRole) ==
                            NormalizeSceneRoleName(analysisSession.sceneRole)) {
                        session.selectedSceneVariantPath = analysisSession.sourcePath;
                    }
                }
            }
        }

        scene.displayVisible = groupIt->displayVisible;
        scene.waterSurfaceCache = groupIt->waterSurfaceCache;
        scene.waterSurfaceCacheStatus = InitialWaterSurfaceCacheStatus(
            *runtimeState,
            scene);
        const bool shouldLoadDisplay = groupIt->displayLoaded;

        const SceneDisplayBundleRuntime* desiredBundle = nullptr;
        const auto savedSpacing = invisible_places::scene::QuantizePointSpacingMicrometres(
            groupIt->displaySpacingMeters);
        if (savedSpacing.has_value()) {
            desiredBundle = FindSceneDisplayBundle(scene, savedSpacing.value());
        }
        if (desiredBundle == nullptr) {
            for (const auto& bundle : scene.displayBundles) {
                bool pathsMatch = true;
                for (std::size_t roleIndex = 0;
                     roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                     ++roleIndex) {
                    const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
                    const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
                    pathsMatch &= roleDocument != nullptr &&
                                  !roleDocument->displaySourcePath.empty() &&
                                  PathsReferToSameLocation(
                                      roleDocument->displaySourcePath,
                                      runtimeState->sessions[bundle.sessionIndices[roleIndex]].sourcePath);
                }
                if (pathsMatch) {
                    desiredBundle = &bundle;
                    break;
                }
            }
        }
        if (desiredBundle == nullptr && !scene.displayBundles.empty()) {
            desiredBundle = &*std::min_element(
                scene.displayBundles.begin(),
                scene.displayBundles.end(),
                [&](const SceneDisplayBundleRuntime& left, const SceneDisplayBundleRuntime& right) {
                    if (!savedSpacing.has_value()) {
                        return left.spacingMicrometres < right.spacingMicrometres;
                    }
                    const auto leftDistance = left.spacingMicrometres > savedSpacing.value()
                                                  ? left.spacingMicrometres - savedSpacing.value()
                                                  : savedSpacing.value() - left.spacingMicrometres;
                    const auto rightDistance = right.spacingMicrometres > savedSpacing.value()
                                                   ? right.spacingMicrometres - savedSpacing.value()
                                                   : savedSpacing.value() - right.spacingMicrometres;
                    return leftDistance != rightDistance
                               ? leftDistance < rightDistance
                               : left.spacingMicrometres < right.spacingMicrometres;
                });
            scene.switchError = "Saved display density is unavailable; selected the nearest complete bundle.";
        }

        if (desiredBundle == nullptr) {
            std::array<std::optional<std::size_t>, invisible_places::scene::kScenePointCloudRoleCount>
                mixedDisplayIndices{};
            for (std::size_t roleIndex = 0;
                 roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                 ++roleIndex) {
                const auto role = static_cast<invisible_places::scene::ScenePointCloudRole>(roleIndex);
                const auto* roleDocument = FindSceneRoleSourceDocument(*groupIt, role);
                if (roleDocument != nullptr && !roleDocument->displaySourcePath.empty()) {
                    mixedDisplayIndices[roleIndex] = SessionIndexForSourcePath(
                        runtimeState->sessions,
                        roleDocument->displaySourcePath);
                }
                if (!mixedDisplayIndices[roleIndex].has_value()) {
                    mixedDisplayIndices[roleIndex] = scene.analysisSessionIndices[roleIndex];
                }
            }
            scene.mixedDisplay = true;
            scene.switchError = "No complete ROCK/SAND/VEG display bundle is available; the saved mixed set is not switchable.";
            if (!shouldLoadDisplay) {
                ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
                scene.committedDisplaySessionIndices = mixedDisplayIndices;
                scene.committedDisplaySpacingMicrometres.reset();
                scene.mixedDisplay = true;
                continue;
            }
            requestedAnyDisplay |= RequestSceneMixedDisplayLoad(
                runtimeState,
                viewport,
                &scene,
                mixedDisplayIndices);
            continue;
        }

        if (!shouldLoadDisplay) {
            ReleaseScenePointCloudResidency(runtimeState, viewport, &scene);
            for (std::size_t roleIndex = 0;
                 roleIndex < invisible_places::scene::kScenePointCloudRoleCount;
                 ++roleIndex) {
                scene.committedDisplaySessionIndices[roleIndex] =
                    desiredBundle->sessionIndices[roleIndex];
            }
            scene.committedDisplaySpacingMicrometres = desiredBundle->spacingMicrometres;
            scene.mixedDisplay = false;
            continue;
        }

        requestedAnyDisplay |= RequestSceneDisplaySwitch(
            runtimeState,
            viewport,
            &scene,
            desiredBundle->spacingMicrometres);
    }
    return requestedAnyDisplay;
}

bool ApplyProjectDocumentToRuntime(
    const ProjectDocument& document,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }

    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->statusMessage = "Please wait for the current layer to finish loading before loading a project.";
        return false;
    }

    // Project application is a full context switch. Clear the previous
    // animation before water/profile state is synchronized, then restore the
    // persisted animation only after its project-owned libraries are ready.
    runtimeState->animationPlayback.active = false;
    runtimeState->animationPanel.currentPath.reset();
    runtimeState->animationPanel.currentFilePath.clear();
    runtimeState->animationPanel.currentPathUsesEdited = false;
    runtimeState->animationPanel.selectedFileUsesEdited = false;
    runtimeState->animationPanel.selectedFileIndex.reset();
    runtimeState->animationPanel.selectedKeyIndex.reset();
    runtimeState->animationPanel.scrubAmount = 0.0F;
    runtimeState->animationPanel.timelineViewRange = {};
    runtimeState->animationPanel.timelineViewDrag.reset();
    runtimeState->animationPanel.dirty = false;
    if (runtimeState->animationMatchingFrameGhostJob.worker.joinable()) {
        runtimeState->animationMatchingFrameGhostJob.worker.request_stop();
        runtimeState->animationMatchingFrameGhostJob.worker =
            std::jthread{};
    }
    runtimeState->animationMatchingFrameGhostJob.shared.reset();
    runtimeState->animationMatchingFrameGhostJob.sourceCache.reset();
    viewport->RemovePointCloud(kAnimationMatchingFrameGhostLayerId);
    runtimeState->animationPanel.matchingFrameGhost = {};
    runtimeState->animationPanel.requestedMatchingFrameGhostCapture.reset();
    runtimeState->animationPanel.requestedMatchingFrameGhostClear = false;

    CancelWaterFlowTrailBuildJob(&runtimeState->water);
    runtimeState->water.flowTrailSourceRequests.clear();
    runtimeState->water.flowTrailSourceArtifacts.clear();

    runtimeState->projectSettings.backgroundColor = document.backgroundColor;
    runtimeState->projectSettings.liveViewWindowWidth =
        static_cast<int>(std::min<std::uint32_t>(
            document.liveViewWindowWidth,
            static_cast<std::uint32_t>(
                kMaximumLiveViewWindowDimension)));
    runtimeState->projectSettings.liveViewWindowHeight =
        static_cast<int>(std::min<std::uint32_t>(
            document.liveViewWindowHeight,
            static_cast<std::uint32_t>(
                kMaximumLiveViewWindowDimension)));
    const auto projectWindowSize =
        ProjectLiveViewWindowSize(runtimeState->projectSettings);
    runtimeState->projectSettings.liveViewWindowWidth =
        projectWindowSize.width;
    runtimeState->projectSettings.liveViewWindowHeight =
        projectWindowSize.height;
    runtimeState->projectSettings.lockLiveViewWindowSize =
        document.lockLiveViewWindowSize;
    runtimeState->pendingLiveViewWindowSize.reset();
    if (runtimeState->projectSettings.lockLiveViewWindowSize) {
        runtimeState->pendingLiveViewWindowSize = projectWindowSize;
    }
    runtimeState->projectSettings.eyeDomeLightingEnabled = document.eyeDomeLightingEnabled;
    runtimeState->projectSettings.proResAlphaPreviewEnabled = document.proResAlphaPreviewEnabled;
    runtimeState->projectSettings.eyeDomeLightingThickness =
        std::clamp(document.eyeDomeLightingThickness, 1.0F, 24.0F);
    runtimeState->projectSettings.constantUpdateView = document.constantUpdateView;
    runtimeState->projectSettings.liveVisualEffects = document.liveVisualEffects;
    runtimeState->projectSettings.previewPerformanceMode = document.previewPerformanceMode;
    runtimeState->projectSettings.loadAllScalarFields = document.loadAllScalarFields;
    runtimeState->projectSettings.scalarFieldBudgetGigabytes =
        std::max(0.0F, document.scalarFieldBudgetGigabytes);
    runtimeState->sidePanel.pinned = document.sidePanelPinned;
    runtimeState->showLidarTab = document.showLidarTab;
    runtimeState->showGsplatTab = document.showGsplatTab;
    runtimeState->cameraInteraction.orbitControlMode = document.orbitControlMode;
    runtimeState->cameraInteraction.trackballOrbitActive = false;
    runtimeState->projectSettings.autoLowerGsplatQualityWhileNavigating =
        document.autoLowerGsplatQualityWhileNavigating;
    runtimeState->projectSettings.gsplatVisualStyle = document.gsplatVisualStyle;
    runtimeState->pointVisualLibrary.pointVisuals.clear();
    runtimeState->pointVisualLibrary.pointVisuals.reserve(document.pointVisuals.size());
    for (const auto& visualDocument : document.pointVisuals) {
        runtimeState->pointVisualLibrary.pointVisuals.push_back({
            .name = NormalizePointVisualName(visualDocument.name),
            .style = visualDocument.style,
        });
    }
    runtimeState->pointVisualLibrary.selectedPointVisualName =
        NormalizePointVisualName(document.selectedPointVisualName);
    runtimeState->pointVisualLibrary.pointVisualNameBuffer =
        BasePointVisualName(runtimeState->pointVisualLibrary.selectedPointVisualName);
    runtimeState->pointVisualLibrary.sceneVisualStates.clear();
    runtimeState->pointVisualLibrary.sceneVisualStates.reserve(document.sceneVisualStates.size());
    for (const auto& stateDocument : document.sceneVisualStates) {
        if (stateDocument.sceneGroupName.empty()) {
            continue;
        }
        runtimeState->pointVisualLibrary.sceneVisualStates.push_back({
            .sceneGroupName = stateDocument.sceneGroupName,
            .visual = {
                .name = NormalizePointVisualName(stateDocument.visual.name),
                .style = stateDocument.visual.style,
            },
        });
    }
    EnsureProjectPointVisuals(runtimeState);
    runtimeState->projectSettings.pointCloudPreviewLodMode = PointCloudPreviewLodMode::FullResolution;
    runtimeState->projectSettings.interactivePointCap = document.interactivePointCap;
    runtimeState->projectSettings.pointCloudRendererMode = document.pointCloudRendererMode;
    auto renderSettings = document.renderJobSettings;
    if (renderSettings.outputDirectory.empty() && !runtimeState->renderSettings.outputDirectory.empty()) {
        renderSettings.outputDirectory = runtimeState->renderSettings.outputDirectory;
    }
    runtimeState->renderSettings = renderSettings;
    runtimeState->animationPanel.exportPresets = document.exportPresets;
    runtimeState->animationPanel.selectedExportPresetName =
        document.selectedExportPresetName.empty()
            ? std::string{invisible_places::output::kMp4PresetName}
            : document.selectedExportPresetName;
    runtimeState->animationPanel.editedExportPreset = document.tempExportPreset;
    runtimeState->animationPanel.exportPresetNameBuffer =
        invisible_places::output::BaseExportPresetName(
            runtimeState->animationPanel.selectedExportPresetName);
    EnsureExportPresets(runtimeState);
    ApplyActiveExportPresetToRenderSettings(runtimeState);
    runtimeState->water.emitters = document.waterEmitters;
    runtimeState->water.manualFlowPaths = document.waterManualFlowPaths;
    runtimeState->water.seepageNodes = document.waterSeepageNodes;
    std::optional<PointCloudShorelineWaveSettings>
        legacyPrimaryShoreline;
    if (const auto selectedStyle = ProjectPointVisualStyleByName(
            runtimeState->pointVisualLibrary,
            runtimeState->pointVisualLibrary.selectedPointVisualName);
        selectedStyle.has_value()) {
        const auto settings =
            invisible_places::renderer::pointcloud::
                ExtractPointCloudShorelineWaveSettings(
                    selectedStyle.value());
        const bool legacyOwnership =
            document.sourceSchemaVersion <
            invisible_places::serialization::
                kWaterOwnedShorelineProjectSchemaVersion;
        if (legacyOwnership && settings.enabled) {
            legacyPrimaryShoreline = settings;
        }
    }
    runtimeState->water.shorelineProfiles =
        document.waterShorelineProfiles;
    runtimeState->water.shorelineInstances = document.waterShorelineInstances;
    runtimeState->water.nextShorelineInstanceId = std::max(
        document.nextWaterShorelineInstanceId,
        NextAvailableShorelineInstanceId(
            runtimeState->water.shorelineInstances));
    runtimeState->water.selectedShorelineInstanceIndex.reset();
    runtimeState->water.selectedShorelineProfileName =
        NormalizeWaterShorelineProfileName(
            document.selectedWaterShorelineProfileName);
    NormalizeWaterShorelineState(
        &runtimeState->water,
        legacyPrimaryShoreline);
    ClearWaterShorelineFromSavedVisuals(runtimeState);
    runtimeState->water.defaultSeepageNodeSettings =
        document.waterSeepageDefaultNodeSettings;
    runtimeState->water.seepageNodeSettingsProfiles =
        document.waterSeepageNodeSettingsProfiles;
    runtimeState->water.defaultSeepageLook = document.waterSeepageDefaultLook;
    runtimeState->water.seepageLookProfiles = document.waterSeepageLookProfiles;
    runtimeState->water.seepageResponseProfiles =
        document.waterSeepageResponseProfiles;
    MigrateLegacyWaterSeepageLooks(
        &runtimeState->water,
        !document.waterSeepageResponseProfiles.empty());
    MigrateLegacyWaterSeepageNodeSettings(&runtimeState->water);
    SeedWaterSeepageProfilePresets(&runtimeState->water);
    runtimeState->water.seepageScenarios = document.waterScenarios.empty()
        ? invisible_places::water::DefaultWaterScenarioDefinitions()
        : document.waterScenarios;
    runtimeState->water.selectedSeepageScenarioId = document.selectedWaterScenarioId;
    runtimeState->water.timingRuns = document.waterTimingRuns;
    runtimeState->water.nextTimingRunSequence = document.waterTimingRunSequence;
    runtimeState->water.featureTimingRunsByScenario =
        document.waterFeatureTimingRuns;
    runtimeState->water.keyedSettingsProfiles =
        document.waterKeyedSettingsProfiles;
    runtimeState->water.nextFeatureTimingRunSequence =
        document.waterFeatureTimingRunSequence;
    // After nodes, profiles, and keyed tracks are all loaded so orphan drops
    // and owner-rename syncs can rewrite every reference kind.
    ReconcileWaterSeepageObjectProfiles(&runtimeState->water);
    runtimeState->water.timingTakes = document.timingTakes;
    runtimeState->water.selectedTimingTakeId =
        invisible_places::timing::NormalizeTimingTakeId(
            document.selectedTimingTakeId);
    runtimeState->water.timingTakeSceneStates =
        document.timingTakeStates;
    runtimeState->water.savedTimingColourisePalettes =
        document.timingColourisePalettes;
    runtimeState->water.timingScalarBoundsStores =
        document.timingScalarBoundsStores;
    runtimeState->water.nextTimingTakeSequence =
        document.timingTakeSequence;
    runtimeState->water.nextTimingColourisePaletteSequence =
        document.timingColourisePaletteSequence;
    runtimeState->water.editedScenario = document.tempWaterScenario;
    if (runtimeState->water.editedScenario.has_value() &&
        FindWaterScenarioDefinition(
            runtimeState->water,
            runtimeState->water.editedScenario->id) == nullptr) {
        runtimeState->water.editedScenario.reset();
    }
    runtimeState->timingsPanel = TimingsPanelState{};
    RecompileWaterTimingTracksForAnimation(runtimeState);
    runtimeState->water.rippleLayers = document.waterRippleLayers;
    runtimeState->water.fieldLayers = document.waterFieldLayers;
    runtimeState->water.flowTrailSettings = document.waterFlowTrailSettings;
    runtimeState->water.showFlowTrails = document.waterShowFlowTrails;
    runtimeState->water.defaultTrailGeometry = document.waterTrailGeometry;
    runtimeState->water.fieldSettings = document.waterFieldSettings;
    runtimeState->water.fieldTrailSettings = document.waterFieldTrailSettings;
    runtimeState->water.dynamicMeshFlowSettings =
        invisible_places::water::SanitizeWaterDynamicMeshFlowSettings(
            document.waterDynamicMeshFlowSettings);
    runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
        NormalizeWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.dynamicMeshFlowSettings.particlePresetName = std::string{
        invisible_places::water::NormalizeWaterDynamicMeshParticlePresetName(
            runtimeState->water.dynamicMeshFlowSettings.particlePresetName)};
    runtimeState->water.dynamicMeshTrailProfileNameBuffer =
        BaseWaterProfileName(runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    // Schema-45 Mesh Flow has no authored attractor/source interaction.
    // Loading a project also clears any legacy in-memory placement state so
    // ordinary Flow emitters remain the only source markers handled by the
    // reachable viewport UI.
    runtimeState->water.selectedDynamicMeshAttractorIndex.reset();
    runtimeState->water.movingDynamicMeshAttractorIndex.reset();
    runtimeState->water.dynamicMeshAttractorPlacementArmed = false;
    runtimeState->water.activeWaterSurfaceSceneGroupName =
        document.activeWaterSceneGroupName;
    runtimeState->water.authoritativeWaterSurfaceSceneGroupName =
        document.activeWaterSceneGroupName;
    runtimeState->water.dynamicMeshFlowGpuSessionIndex.reset();
    runtimeState->water.dynamicMeshFlowLastUpdateSeconds = 0.0F;
    runtimeState->water.dynamicMeshFlowResetRequested = true;
    runtimeState->water.dynamicMeshFlowAllocationRevision = 0U;
    runtimeState->water.dynamicMeshFlowParameterRevision = 0U;
    runtimeState->water.dynamicMeshFlowDescriptorGeneration = 0U;
    runtimeState->water.dynamicMeshFlowDispatchCount = 0U;
    runtimeState->water.dynamicMeshFlowSharedGroundUploadRevision = 0U;
    runtimeState->water.dynamicMeshFlowContactEventCount = 0U;
    runtimeState->water.dynamicMeshSurfaceCache.reset();
    runtimeState->water.dynamicMeshSurfaceCachePath.clear();
    runtimeState->water.dynamicMeshSurfaceCacheSignature.clear();
    runtimeState->water.collisionRainSettings = document.waterRainSettings;
    runtimeState->water.rainVisual = document.waterRainVisualSettings;
    runtimeState->water.flowOverlay = {};
    runtimeState->water.flowTrailOverlay = {};
    runtimeState->water.fieldTrailOverlay = {};
    runtimeState->water.rippleEffectOverlay = {};
    runtimeState->water.fieldSurfaceEffectOverlay = {};
    runtimeState->water.fieldCache = {};
    if (kRippleWaterRuntimeEnabled) {
        runtimeState->water.rippleRuntimeCaches =
            document.waterRippleRuntimeCaches;
    } else {
        runtimeState->water.rippleRuntimeCaches.clear();
    }
    runtimeState->water.fieldCacheRevision = 0U;
    runtimeState->water.regionPointPreviews.clear();
    runtimeState->water.regionPointPreviewOverrides.clear();
    runtimeState->water.regionPointPreviewPendingKeys.clear();
    runtimeState->water.regionEffectsDirtyKeys.clear();
    runtimeState->water.rippleEffectsDirty = std::any_of(
        runtimeState->water.rippleLayers.begin(),
        runtimeState->water.rippleLayers.end(),
        [](const WaterEffectLayer& layer) { return layer.vertices.size() >= 3U; });
    runtimeState->water.fieldEffectsDirty = std::any_of(
        runtimeState->water.fieldLayers.begin(),
        runtimeState->water.fieldLayers.end(),
        [](const WaterEffectLayer& layer) { return layer.vertices.size() >= 3U; });
    for (const auto& layer : runtimeState->water.rippleLayers) {
        if (WaterRegionLayerClosed(layer)) {
            runtimeState->water.regionEffectsDirtyKeys.insert(WaterRegionPreviewKey(layer));
        }
    }
    for (const auto& layer : runtimeState->water.fieldLayers) {
        if (WaterRegionLayerClosed(layer)) {
            runtimeState->water.regionEffectsDirtyKeys.insert(WaterRegionPreviewKey(layer));
        }
    }
    runtimeState->water.defaultSourceSettings = document.waterSourceSettings;
    runtimeState->water.tempDefaultSourceSettings = document.tempWaterSourceSettings;
    runtimeState->water.defaultAnimationTrailSettings = document.waterAnimationTrailSettings;
    runtimeState->water.tempDefaultAnimationTrailSettings = document.tempWaterAnimationTrailSettings;
    runtimeState->water.animationTrailProfiles.clear();
    runtimeState->water.animationTrailProfiles.reserve(document.waterAnimationTrailProfiles.size());
    for (const auto& profile : document.waterAnimationTrailProfiles) {
        runtimeState->water.animationTrailProfiles.push_back({
            .name = NormalizeWaterAnimationTrailProfileName(profile.name),
            .settings = profile.settings,
        });
    }
    EnsureWaterAnimationTrailProfiles(&runtimeState->water);
    runtimeState->water.defaultCausticLookSettings = document.waterCausticLookSettings;
    runtimeState->water.tempDefaultCausticLookSettings = document.tempWaterCausticLookSettings;
    runtimeState->water.defaultPointVisualStyle = document.waterPointVisualStyle;
    runtimeState->water.tempDefaultPointVisualStyle = document.tempWaterPointVisualStyle;
    runtimeState->water.pathProfiles.clear();
    runtimeState->water.pathProfiles.reserve(document.waterPathProfiles.size());
    for (const auto& profile : document.waterPathProfiles) {
        runtimeState->water.pathProfiles.push_back(MakeWaterPathProfileState(profile));
    }
    runtimeState->water.laneProfiles.clear();
    runtimeState->water.laneProfiles.reserve(document.waterLaneProfiles.size());
    for (const auto& profile : document.waterLaneProfiles) {
        runtimeState->water.laneProfiles.push_back(MakeWaterLaneProfileState(profile));
    }
    runtimeState->water.trailProfiles.clear();
    runtimeState->water.trailProfiles.reserve(document.waterTrailProfiles.size());
    for (const auto& profile : document.waterTrailProfiles) {
        runtimeState->water.trailProfiles.push_back(MakeWaterTrailProfileState(profile));
    }
    runtimeState->water.selectedPathProfileName = document.selectedWaterPathProfileName;
    runtimeState->water.selectedLaneProfileName = document.selectedWaterLaneProfileName;
    runtimeState->water.selectedTrailProfileName = document.selectedWaterTrailProfileName;
    runtimeState->water.editedPathProfileSettings = document.tempWaterPathProfileSettings;
    runtimeState->water.editedLaneProfileSettings = document.tempWaterLaneProfileSettings;
    runtimeState->water.editedTrailProfile =
        document.tempWaterTrailProfile.has_value()
            ? std::optional<SavedWaterTrailProfileState>{
                  MakeWaterTrailProfileState(document.tempWaterTrailProfile.value())}
            : std::nullopt;
    runtimeState->water.editedDynamicMeshTrailProfile =
        document.tempWaterDynamicMeshTrailProfile.has_value()
            ? std::optional<SavedWaterTrailProfileState>{
                  MakeWaterTrailProfileState(
                      document.tempWaterDynamicMeshTrailProfile.value())}
            : std::nullopt;
    if (runtimeState->water.editedDynamicMeshTrailProfile.has_value()) {
        runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
            NormalizeWaterProfileName(
                runtimeState->water.editedDynamicMeshTrailProfile->name);
    } else if (IsEditedWaterProfileName(
                   runtimeState->water.dynamicMeshFlowSettings
                       .trailProfileName)) {
        // Older project files could retain an `_edited` assignment without
        // the shadow's geometry/style. Resolve that dangling reference to its
        // saved base profile instead of leaking a prior project's edit.
        runtimeState->water.dynamicMeshFlowSettings.trailProfileName =
            UneditedWaterProfileName(
                runtimeState->water.dynamicMeshFlowSettings
                    .trailProfileName);
    }
    runtimeState->water.dynamicMeshTrailProfileNameBuffer =
        BaseWaterProfileName(
            runtimeState->water.dynamicMeshFlowSettings.trailProfileName);
    runtimeState->water.pointVisuals.clear();
    for (const auto& visualDocument : document.waterPointVisuals) {
        const auto normalized = NormalizePointVisualName(visualDocument.name);
        if (!IsWaterProjectCustomVisualName(normalized)) {
            continue;
        }
        AppendWaterPointVisualIfMissing(
            &runtimeState->water.pointVisuals,
            normalized,
            visualDocument.style);
    }
    bool importedLegacyWaterPointVisual = false;
    if (document.schemaVersion < 23U && document.waterPointVisuals.empty()) {
        if (document.tempWaterPointVisualStyle.has_value()) {
            ImportLegacyWaterPointVisualStyle(
                runtimeState,
                document.tempWaterPointVisualStyle.value());
        } else {
            ImportLegacyWaterPointVisualStyle(runtimeState, document.waterPointVisualStyle);
        }
        importedLegacyWaterPointVisual = true;
    }
    if (document.waterTrailProfiles.empty()) {
        ImportLegacyWaterVisualsAsTrailProfiles(runtimeState);
        if (document.schemaVersion < 25U &&
            !document.selectedWaterPointVisualName.empty()) {
            runtimeState->water.selectedTrailProfileName =
                NormalizeWaterProfileName(document.selectedWaterPointVisualName);
        }
        if (!runtimeState->water.editedTrailProfile.has_value() &&
            document.tempWaterPointVisualStyle.has_value()) {
            runtimeState->water.editedTrailProfile = MakeWaterTrailProfile(
                EditedWaterProfileName(runtimeState->water.selectedTrailProfileName),
                runtimeState->water.defaultTrailGeometry,
                document.tempWaterPointVisualStyle.value());
        }
    }
    MigrateLegacyWaterEmitterProfiles(&runtimeState->water);
    EnsureWaterProfiles(runtimeState);
    runtimeState->water.selectedPointVisualName =
        document.selectedWaterPointVisualName.empty()
            ? std::string{"Water Flow_preset"}
            : NormalizePointVisualName(document.selectedWaterPointVisualName);
    if (importedLegacyWaterPointVisual &&
        runtimeState->water.selectedPointVisualName == "Water Flow_preset" &&
        FindWaterProjectVisualIndex(runtimeState->water.pointVisuals, "Water Flow").has_value()) {
        runtimeState->water.selectedPointVisualName = "Water Flow";
    }
    if (document.schemaVersion < 23U) {
        const auto rawSelected = runtimeState->water.selectedPointVisualName;
        const auto legacySelected = NormalizeWaterPointVisualName(rawSelected);
        if (legacySelected != rawSelected &&
            !FindWaterProjectVisualIndex(runtimeState->water.pointVisuals, rawSelected).has_value()) {
            runtimeState->water.selectedPointVisualName = legacySelected;
        }
    }
    const bool selectedIsPreset =
        MakeProtectedWaterPointVisualStyle(*runtimeState, runtimeState->water.selectedPointVisualName).has_value();
    if (!selectedIsPreset &&
        !FindWaterProjectVisualIndex(
             runtimeState->water.pointVisuals,
             runtimeState->water.selectedPointVisualName)
             .has_value()) {
        runtimeState->water.selectedPointVisualName = "Water Flow_preset";
    }
    runtimeState->water.pointVisualNameBuffer = BasePointVisualName(runtimeState->water.selectedPointVisualName);
    runtimeState->water.nextEmitterId = NextWaterEmitterId(*runtimeState);
    runtimeState->water.nextSeepageNodeId = NextWaterSeepageNodeId(*runtimeState);
    runtimeState->water.nextRippleLayerId = NextWaterRippleLayerId(*runtimeState);
    runtimeState->water.selectedEmitterIndex.reset();
    runtimeState->water.selectedManualFlowPathIndex.reset();
    runtimeState->water.manualFlowPathEditor = {};
    ClearWaterSeepageSelection(&runtimeState->water);
    runtimeState->water.movingSeepageNodeIndex.reset();
    runtimeState->water.seepagePlacementArmed = false;
    runtimeState->water.seepageTopologyFingerprints.clear();
    runtimeState->water.seepageAttachmentSemanticKeys.clear();
    runtimeState->water.seepageParamsFingerprints.clear();
    runtimeState->water.seepageRuntimeGrids.clear();
    runtimeState->water.seepageSupportJob = {};
    runtimeState->water.seepageSupportSelections.clear();
    runtimeState->water.seepageSupportNodeFingerprints.clear();
    runtimeState->water.seepagePendingSupportSelections.clear();
    runtimeState->water.seepagePendingSupportNodeFingerprints.clear();
    runtimeState->water.seepageSupportFailedKeys.clear();
    runtimeState->water.seepageRuntimeGuideKeys.clear();
    runtimeState->water.seepageSurfaceGuides.clear();
    runtimeState->water.seepageSurfaceGuideFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideNodeFingerprints.clear();
    runtimeState->water.seepageSurfaceGuideWarning.clear();
    runtimeState->water.seepageSupportWarning.clear();
    runtimeState->water.selectedRippleLayerIndex.reset();
    runtimeState->water.placementArmed = false;
    runtimeState->water.pathAttractorPlacementArmed = false;
    runtimeState->water.rippleRegionPlacementArmed = false;
    runtimeState->water.movingEmitterIndex.reset();
    SyncWaterAnimationTrailProfileFromCurrentAnimation(runtimeState);
    if (document.waterPathCache.has_value() && !document.waterPathCache->branches.empty()) {
        runtimeState->water.pathCache = document.waterPathCache.value();
        runtimeState->water.pathCacheLoaded = true;
        runtimeState->water.pathCacheStale = runtimeState->water.pathCache.stale;
        runtimeState->water.pathDirty = runtimeState->water.pathCacheStale;
        runtimeState->water.dirtyEmitterIds.clear();
        runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    } else {
        runtimeState->water.pathCache = {};
        runtimeState->water.pathCacheLoaded = false;
        runtimeState->water.pathCacheStale = false;
        runtimeState->water.pathAnchors = {};
        if (runtimeState->water.emitters.empty()) {
            runtimeState->water.pathDirty = false;
            runtimeState->water.dirtyEmitterIds.clear();
        } else {
            MarkWaterPathDirty(runtimeState);
        }
    }
    ValidateWaterSourceSettingLinks(runtimeState);
    runtimeState->cameraShots = document.cameraShots;
    EnsureRuntimeCameraShotIds(runtimeState);
    runtimeState->cameraPanel.draftShotName = NextCameraShotName(*runtimeState);
    runtimeState->cameraPanel.selectedShotIndex.reset();
    runtimeState->cameraPanel.renamingShotIndex.reset();
    runtimeState->cameraPanel.pendingLinkedShotDeleteIndex.reset();
    runtimeState->cameraPanel.multiEditAllowedCameraIds.clear();
    runtimeState->cameraPanel.shotRenameBuffer.clear();
    runtimeState->cameraPanel.focusShotRename = false;
    runtimeState->cameraPanel.pathShotIndices = document.cameraPathShotIndices;
    runtimeState->cameraPanel.selectedPathItemIndex.reset();
    runtimeState->cameraPanel.pathDurationFrames =
        std::max<std::uint32_t>(1U, document.cameraPathDurationFrames);
    runtimeState->animationPanel.availableFiles.clear();
    runtimeState->animationPanel.availableFileAssociatedLayerPaths.clear();
    runtimeState->animationPanel.availableFileLoadedPaths.clear();
    runtimeState->animationPanel.availableFileEditedPaths.clear();
    runtimeState->animationPanel.availableFileLoopEditPairIds.clear();
    runtimeState->animationPanel.availableFileDirtyFlags.clear();
    runtimeState->animationPanel.brokenVelocityLinkPathKeys.clear();
    runtimeState->animationPanel.projectVelocityLinksDirty = false;
    runtimeState->animationPanel.selectedExportFiles.clear();
    if (document.hasSavedAnimationRegistry) {
        for (const auto& animation : document.savedAnimations) {
            AddAnimationFileToRegistry(
                &runtimeState->animationPanel,
                animation.filePath,
                animation.associatedLayerPaths);
        }
        runtimeState->animationPanel.animationRegistryInitialized = true;
    } else {
        runtimeState->animationPanel.animationRegistryInitialized = false;
        RefreshAnimationFileList(&runtimeState->animationPanel, AnimationDirectory(*runtimeState));
    }
    ValidateProjectAnimationVelocityLinks(document, runtimeState);
    runtimeState->animationPanel.renamingFileIndex.reset();
    runtimeState->animationPanel.fileRenameBuffer.clear();
    runtimeState->animationPanel.focusFileRename = false;
    runtimeState->animationPanel.currentPathUsesEdited = false;
    runtimeState->animationPanel.selectedFileUsesEdited = false;
    if (runtimeState->cameraPanel.pathShotIndices.empty() &&
        document.schemaVersion < 9U &&
        !runtimeState->cameraShots.empty()) {
        runtimeState->cameraPanel.pathShotIndices.reserve(runtimeState->cameraShots.size());
        for (std::size_t index = 0; index < runtimeState->cameraShots.size(); ++index) {
            runtimeState->cameraPanel.pathShotIndices.push_back(index);
        }
        std::uint32_t legacyDurationFrames = 0U;
        for (std::size_t index = 1; index < runtimeState->cameraShots.size(); ++index) {
            legacyDurationFrames += std::max<std::uint32_t>(1U, runtimeState->cameraShots[index].durationFrames);
        }
        runtimeState->cameraPanel.pathDurationFrames = std::max<std::uint32_t>(1U, legacyDurationFrames);
    }
    runtimeState->cameraPlayback.active = false;
    if (!runtimeState->cameraShots.empty()) {
        runtimeState->cameraPanel.selectedShotIndex = 0;
    }
    EnsureCameraShotSelections(&runtimeState->cameraPanel, runtimeState->cameraShots.size());
    runtimeState->persistence.queuedLoads.clear();
    const bool hasProjectCamera = document.cameraState.has_value();
    bool requestedLoadedLayer = false;

    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        auto& session = runtimeState->sessions[sessionIndex];
        const auto layerIt = std::find_if(
            document.layers.begin(),
            document.layers.end(),
            [&session](const ProjectLayerDocument& layerDocument) {
                return PathsReferToSameLocation(
                    layerDocument.sourcePath,
                    session.sourcePath);
            });

        if (layerIt == document.layers.end()) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex);
            continue;
        }

        if (session.kind == LayerKind::PointCloud) {
            if (!layerIt->sceneGroupName.empty()) {
                session.sceneGroupName = layerIt->sceneGroupName;
            }
            if (!layerIt->sceneRole.empty()) {
                session.sceneRole = layerIt->sceneRole;
            }
            if (layerIt->inferredPointSpacingMeters > 0.0F) {
                session.inferredPointSpacingMeters = layerIt->inferredPointSpacingMeters;
            }
            if (layerIt->pointSpacingMeters > 0.0F) {
                session.pointSpacingMeters = layerIt->pointSpacingMeters;
            }
            session.pointSpacingManualOverride = layerIt->pointSpacingManualOverride;
            session.scenePrimaryRole = layerIt->scenePrimaryRole;
            if (!layerIt->selectedSceneVariantPath.empty()) {
                session.selectedSceneVariantPath = layerIt->selectedSceneVariantPath;
            }
        }

        if (session.kind == LayerKind::PointCloud) {
            if (IsGeneratedWaterFlowOverlaySession(session)) {
                session.pointVisuals.clear();
                for (const auto& visualDocument : layerIt->pointVisuals) {
                    session.pointVisuals.push_back({
                        .name = NormalizePointVisualName(visualDocument.name),
                        .style = visualDocument.style,
                    });
                }
                session.selectedPointVisualName = NormalizePointVisualName(layerIt->selectedPointVisualName);
                if (layerIt->pointStyle.has_value()) {
                    session.pointStyle = layerIt->pointStyle.value();
                }
                EnsurePointVisuals(&session);
                SeedWaterFlowBuiltInVisuals(runtimeState, &session);
            } else {
                session.selectedPointVisualName =
                    runtimeState->pointVisualLibrary.selectedPointVisualName;
                session.pointVisualNameBuffer =
                    BaseNameFromProjectPointVisualName(
                        runtimeState->pointVisualLibrary,
                        session.selectedPointVisualName);
                ApplyProjectPointVisualToSession(runtimeState, &session);
            }
        } else if (session.kind == LayerKind::GaussianSplat) {
            ApplyProjectGsplatVisualStyleToSession(*runtimeState, &session);
        }

        if (session.kind == LayerKind::PointCloud) {
            session.pointBudget = MakePreviewPointBudgetState(session, session.totalPrimitives);
            ClearPreviewLodSampleCache(&session);
            if (session.loaded) {
                viewport->UpdatePointBudget(sessionIndex, {});
            }
        }

        SanitizePointCloudStyle(&session);
        if (session.kind == LayerKind::PointCloud && !IsProjectPointVisualSession(session)) {
            EnsurePointVisuals(&session);
            UpsertPointVisual(&session, session.selectedPointVisualName, session.pointStyle);
        }

        if (IsSceneGroupedPointCloud(session)) {
            // The v33 scene group record controls grouped residency/visibility.
            // Legacy layer flags remain compatibility mirrors only.
            continue;
        }

        requestedLoadedLayer |= layerIt->loaded;
        if (!layerIt->loaded) {
            UnloadLayerByIndex(runtimeState, viewport, sessionIndex);
            continue;
        }

        session.visible = layerIt->visible;
        if (!session.loaded) {
            QueueLayerLoad(runtimeState, sessionIndex, PointCloudLoadPurpose::Interactive);
        }
    }

    CanonicalizeRuntimeSceneAssociations(runtimeState);
    requestedLoadedLayer |= ApplyScenePointCloudGroupDocuments(
        document,
        runtimeState,
        viewport);

    const auto selectedLayerIndex =
        document.selectedLayerPath.empty()
            ? std::nullopt
            : FindSessionIndexBySourcePath(
                  *runtimeState,
                  document.selectedLayerPath);
    runtimeState->selectedSessionIndex = selectedLayerIndex;
    // Prefer the precise saved layer when it still belongs to the active
    // scene. The stable group identity repairs selection after a density or
    // source-file replacement makes that path obsolete.
    if (!document.activeSceneGroupName.empty() &&
        (!runtimeState->selectedSessionIndex.has_value() ||
         runtimeState->sessions[
             runtimeState->selectedSessionIndex.value()]
                 .sceneGroupName != document.activeSceneGroupName)) {
        if (const auto activeSceneIndex =
                FindSessionIndexForSceneGroup(
                    *runtimeState,
                    document.activeSceneGroupName);
            activeSceneIndex.has_value()) {
            runtimeState->selectedSessionIndex = activeSceneIndex;
        }
    }

    if (runtimeState->selectedSessionIndex.has_value()) {
        const auto selectedIndex = runtimeState->selectedSessionIndex.value();
        if (runtimeState->sessions[selectedIndex].loaded && !hasProjectCamera) {
            FocusSessionLayer(runtimeState, *viewport, selectedIndex);
        }
    }

    if (hasProjectCamera) {
        runtimeState->camera.ApplyState(document.cameraState.value());
        SyncPivotOverlayToCamera(runtimeState);
    }
    runtimeState->preserveProjectCameraOnNextLayerActivation =
        hasProjectCamera && requestedLoadedLayer && VisibleLayerCount(*runtimeState) == 0;
    std::size_t restoredRippleMemberships = 0U;
    std::size_t restoredRippleRegions = 0U;
    const auto restoredRippleSessions = RestoreWaterRippleRuntimeCachesForLoadedSessions(
        runtimeState,
        viewport,
        &restoredRippleMemberships,
        &restoredRippleRegions);
    bool restoredActiveAnimation = false;
    std::string activeAnimationRestoreError;
    if (!document.activeAnimationPath.empty()) {
        if (LoadAnimationPathFromFile(
                runtimeState,
                document.activeAnimationPath)) {
            restoredActiveAnimation = true;
            runtimeState->animationPanel.scrubAmount =
                std::clamp(
                    document.activeAnimationPosition,
                    0.0F,
                    1.0F);
            ApplyAnimationScrub(runtimeState);
            runtimeState->animationPanel.selectedFileIndex =
                FindAnimationRegistryIndex(
                    runtimeState->animationPanel,
                    document.activeAnimationPath);
            if (requestedLoadedLayer &&
                VisibleLayerCount(*runtimeState) == 0) {
                runtimeState->preserveProjectCameraOnNextLayerActivation =
                    true;
            }
        } else {
            activeAnimationRestoreError =
                runtimeState->errorMessage.empty()
                    ? "The saved active animation could not be loaded."
                    : runtimeState->errorMessage;
            runtimeState->animationPanel.currentPath.reset();
            runtimeState->animationPanel.currentFilePath.clear();
            runtimeState->animationPanel.currentPathUsesEdited = false;
            runtimeState->animationPanel.selectedFileUsesEdited = false;
            runtimeState->animationPanel.selectedFileIndex.reset();
            runtimeState->animationPanel.selectedKeyIndex.reset();
        }
    }
    runtimeState->statusMessage =
        "Loaded project with " + FormatPointCount(document.layers.size()) + " layer settings.";
    if (restoredRippleSessions > 0U) {
        runtimeState->statusMessage +=
            " Restored cached Ripple membership: " + FormatPointCount(restoredRippleMemberships) +
            " points across " + FormatPointCount(restoredRippleRegions) + " params.";
    }
    if (restoredActiveAnimation) {
        runtimeState->statusMessage +=
            " Restored active animation " +
            document.activeAnimationPath.filename().string() + ".";
    }
    runtimeState->persistence.projectName = document.projectName;
    if (activeAnimationRestoreError.empty()) {
        runtimeState->errorMessage.clear();
    } else {
        runtimeState->errorMessage =
            "The project loaded, but its active animation did not: " +
            activeAnimationRestoreError;
    }
    return true;
}

std::filesystem::path ProjectRenderSetupDirectory(
    const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{
        runtimeState.persistence.projectFilePath};
    const auto projectDirectory = projectPath.empty()
                                      ? std::filesystem::path{"Saved"}
                                      : projectPath.parent_path();
    return projectDirectory / "render_setups";
}

std::filesystem::path ProjectRenderSetupHistoryIndexPath(
    const PreviewRuntimeState& runtimeState) {
    return ProjectRenderSetupDirectory(runtimeState) / "history.json";
}

std::string RenderSetupProjectIdentity(
    const PreviewRuntimeState& runtimeState) {
    const std::filesystem::path projectPath{
        runtimeState.persistence.projectFilePath};
    if (!projectPath.empty()) {
        std::error_code canonicalError;
        const auto canonical =
            std::filesystem::weakly_canonical(
                projectPath,
                canonicalError);
        return (canonicalError ? projectPath.lexically_normal()
                               : canonical)
            .generic_string();
    }
    return runtimeState.persistence.projectName;
}

PreservedAnimationRuntimeState CaptureAnimationRuntimeState(
    const PreviewRuntimeState& runtimeState) {
    PreservedAnimationRuntimeState state{
        .path = runtimeState.animationPanel.currentPath,
        .filePath = runtimeState.animationPanel.currentFilePath,
        .selectedFileIndex =
            runtimeState.animationPanel.selectedFileIndex,
        .currentPathUsesEdited =
            runtimeState.animationPanel.currentPathUsesEdited,
        .selectedFileUsesEdited =
            runtimeState.animationPanel.selectedFileUsesEdited,
        .scrubAmount = std::clamp(
            runtimeState.animationPanel.scrubAmount,
            0.0F,
            1.0F),
        .timelineViewRange =
            invisible_places::timing::SanitizeTimelineViewRange(
                runtimeState.animationPanel.timelineViewRange),
        .dirty = runtimeState.animationPanel.dirty,
    };
    const auto& panel = runtimeState.animationPanel;
    const auto editCount = std::min(
        panel.availableFiles.size(),
        panel.availableFileEditedPaths.size());
    state.edits.reserve(editCount);
    for (std::size_t index = 0U; index < editCount; ++index) {
        if (!panel.availableFileEditedPaths[index].has_value()) {
            continue;
        }
        state.edits.push_back({
            .filePath = panel.availableFiles[index],
            .path = panel.availableFileEditedPaths[index].value(),
            .loopPairId = index < panel.availableFileLoopEditPairIds.size()
                              ? panel.availableFileLoopEditPairIds[index]
                              : std::string{},
        });
    }
    if (panel.dirty && panel.currentPath.has_value() &&
        !panel.currentFilePath.empty()) {
        const std::filesystem::path currentFilePath{
            panel.currentFilePath};
        const auto currentEdit = std::find_if(
            state.edits.begin(),
            state.edits.end(),
            [&](const PreservedAnimationEdit& edit) {
                return edit.filePath.lexically_normal() ==
                       currentFilePath.lexically_normal();
            });
        if (currentEdit != state.edits.end()) {
            currentEdit->path = panel.currentPath.value();
        } else {
            std::string loopPairId;
            if (const auto currentIndex = FindAnimationRegistryIndex(
                    panel,
                    currentFilePath);
                currentIndex.has_value() &&
                currentIndex.value() <
                    panel.availableFileLoopEditPairIds.size()) {
                loopPairId = panel.availableFileLoopEditPairIds[
                    currentIndex.value()];
            }
            state.edits.push_back({
                .filePath = currentFilePath,
                .path = panel.currentPath.value(),
                .loopPairId = std::move(loopPairId),
            });
        }
    }
    return state;
}

void RestoreAnimationRuntimeState(
    PreviewRuntimeState* runtimeState,
    PreservedAnimationRuntimeState state) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& panel = runtimeState->animationPanel;
    panel.currentPath = std::move(state.path);
    panel.currentFilePath = std::move(state.filePath);
    panel.selectedFileIndex = state.selectedFileIndex;
    panel.currentPathUsesEdited =
        state.currentPathUsesEdited || state.dirty;
    panel.selectedFileUsesEdited =
        state.selectedFileUsesEdited || state.dirty;
    EnsureAnimationAssociationStorage(&panel);
    for (auto& edit : state.edits) {
        auto registryIndex = FindAnimationRegistryIndex(
            panel,
            edit.filePath);
        if (!registryIndex.has_value()) {
            AddAnimationFileToRegistry(
                &panel,
                edit.filePath,
                edit.path.associatedLayerPaths);
            registryIndex = FindAnimationRegistryIndex(
                panel,
                edit.filePath);
        }
        if (!registryIndex.has_value()) {
            continue;
        }
        EnsureAnimationAssociationStorage(&panel);
        panel.availableFileEditedPaths[registryIndex.value()] =
            std::move(edit.path);
        panel.availableFileLoopEditPairIds[registryIndex.value()] =
            std::move(edit.loopPairId);
        panel.availableFileDirtyFlags[registryIndex.value()] = true;
    }
    panel.selectedKeyIndex.reset();
    panel.selectedWaterKeyIndex.reset();
    panel.selectedSeepageNodeKeyIndex.reset();
    panel.scrubAmount = std::clamp(state.scrubAmount, 0.0F, 1.0F);
    panel.timelineViewRange =
        invisible_places::timing::SanitizeTimelineViewRange(
            state.timelineViewRange);
    panel.timelineViewDrag.reset();
    panel.dirty = state.dirty;
    panel.preparedPathCache = {};
    panel.motionStatsCache = {};
    panel.perceivedFlowCache = {};
    runtimeState->animationPlayback.active = false;
    if (panel.currentPath.has_value()) {
        ApplyAnimationScrub(runtimeState);
    }
}

invisible_places::serialization::WaterSourcesDocument
CaptureRenderSetupAuthoredWater(
    const ProjectDocument& project) {
    invisible_places::serialization::WaterSourcesDocument water;
    water.emitters = project.waterEmitters;
    water.manualFlowPaths = project.waterManualFlowPaths;
    water.seepageNodes = project.waterSeepageNodes;
    water.shorelineDefaultSettings.reset();
    water.shorelineProfiles = project.waterShorelineProfiles;
    water.selectedShorelineProfileName.clear();
    water.shorelineInstances = project.waterShorelineInstances;
    water.nextShorelineInstanceId = std::max(
        project.nextWaterShorelineInstanceId,
        NextAvailableShorelineInstanceId(water.shorelineInstances));
    water.seepageDefaultNodeSettings =
        project.waterSeepageDefaultNodeSettings;
    water.seepageNodeSettingsProfiles =
        project.waterSeepageNodeSettingsProfiles;
    water.seepageDefaultLook = project.waterSeepageDefaultLook;
    water.seepageLookProfiles = project.waterSeepageLookProfiles;
    water.seepageResponseProfiles =
        project.waterSeepageResponseProfiles;
    water.rippleLayers = project.waterRippleLayers;
    water.fieldLayers = project.waterFieldLayers;
    water.sourceSettings = project.waterSourceSettings;
    water.tempSourceSettings = project.tempWaterSourceSettings;
    water.causticLookSettings = project.waterCausticLookSettings;
    water.tempCausticLookSettings =
        project.tempWaterCausticLookSettings;
    water.settings = project.waterSettings;
    water.tempSettings = project.tempWaterSettings;
    water.pathProfiles = project.waterPathProfiles;
    water.laneProfiles = project.waterLaneProfiles;
    water.trailProfiles = project.waterTrailProfiles;
    water.keyedSettingsProfiles =
        project.waterKeyedSettingsProfiles;
    water.selectedPathProfileName =
        project.selectedWaterPathProfileName;
    water.selectedLaneProfileName =
        project.selectedWaterLaneProfileName;
    water.selectedTrailProfileName =
        project.selectedWaterTrailProfileName;
    water.tempPathProfileSettings =
        project.tempWaterPathProfileSettings;
    water.tempLaneProfileSettings =
        project.tempWaterLaneProfileSettings;
    water.tempTrailProfile = project.tempWaterTrailProfile;
    water.bakeSettings = project.waterBakeSettings;
    water.renderSettings = project.waterRenderSettings;
    water.flowTrailSettings = project.waterFlowTrailSettings;
    water.showFlowTrails = project.waterShowFlowTrails;
    water.trailGeometry = project.waterTrailGeometry;
    water.fieldSettings = project.waterFieldSettings;
    water.fieldTrailSettings = project.waterFieldTrailSettings;
    water.dynamicMeshFlowSettings =
        project.waterDynamicMeshFlowSettings;
    water.rainSettings = project.waterRainSettings;
    water.rainVisualSettings = project.waterRainVisualSettings;
    // Render setups deliberately reference immutable terrain inputs and never
    // carry generated path/ripple cache payloads.
    water.pathCache.reset();
    water.rippleRuntimeCaches.clear();
    return water;
}

