        liveChanged |= ImGui::SliderFloat("Downhill Pull", &settings.downhillWeight, 0.0F, 3.0F, "%.2f");
        liveChanged |= ImGui::SliderFloat("Inertia", &settings.inertia, 0.0F, 0.98F, "%.2f");
