void DrawTimingColourisePaletteEditor(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    using invisible_places::timing::TimingColourisePalette;
    using invisible_places::timing::TimingColourisePaletteDefinition;
    using invisible_places::timing::TimingColourisePaletteKeyModel;
    using invisible_places::timing::TimingColourisePaletteSourceKind;
    using invisible_places::timing::TimingColouriseAmountOverrideMode;
    using invisible_places::timing::TimingColouriseEffectParameter;
    using invisible_places::timing::TimingColourisePaletteStopParameter;
    using invisible_places::timing::
        TimingColourisePaletteStopParameterKey;
    using invisible_places::water::WaterScenarioInterpolation;

    auto& timings = runtimeState->timingsPanel;
    auto& water = runtimeState->water;
    const float position = std::clamp(
        runtimeState->animationPanel.scrubAmount,
        0.0F,
        1.0F);
    const auto stopIndexById =
        [](const TimingColourisePalette& palette,
           std::string_view stopId)
            -> std::optional<std::size_t> {
        const auto found = std::find_if(
            palette.stops.begin(),
            palette.stops.end(),
            [&](const auto& stop) { return stop.id == stopId; });
        return found == palette.stops.end()
                   ? std::nullopt
                   : std::optional<std::size_t>{
                         static_cast<std::size_t>(
                             std::distance(
                                 palette.stops.begin(),
                                 found))};
    };
    const auto markPaletteBaseEdited = [&]() {
        if (effect->paletteSourceKind ==
            TimingColourisePaletteSourceKind::Preset) {
            (void)invisible_places::timing::
                UpsertTimingColouriseLocalPaletteEdit(
                    effect,
                    effect->basePalette);
            return;
        }
        effect->paletteEdited = true;
    };
    const auto findSavedPalette =
        [&](std::string_view id)
            -> TimingColourisePaletteDefinition* {
        const auto found = std::find_if(
            water.savedTimingColourisePalettes.begin(),
            water.savedTimingColourisePalettes.end(),
            [&](const auto& palette) {
                return palette.id == id;
            });
        return found ==
                       water.savedTimingColourisePalettes.end()
                   ? nullptr
                   : &*found;
    };
    const auto paletteDisplayName = [&]() {
        std::string name =
            effect->paletteSourceName.empty()
                ? std::string{"Custom"}
                : effect->paletteSourceName;
        if (effect->paletteEdited) {
            name += "_edited";
        }
        return name;
    };

    bool hasPaletteKeys =
        TimingColouriseEffectHasPaletteKeys(*effect);
    const bool paletteSourceLocked =
        hasPaletteKeys ||
        (effect->paletteEdited &&
         effect->paletteSourceKind !=
             TimingColourisePaletteSourceKind::Preset);
    const auto presets =
        invisible_places::timing::
            BuiltInTimingColourisePalettePresets();
    const auto findPreset =
        [&](std::string_view id)
            -> const TimingColourisePaletteDefinition* {
            const auto found = std::find_if(
                presets.begin(),
                presets.end(),
                [&](const auto& preset) {
                    return preset.id == id;
                });
            return found != presets.end() ? &*found : nullptr;
        };
    const auto resetPaletteInteraction = [&]() {
        timings.selectedColourisePaletteStopIndex = 0U;
        timings.draggingColourisePaletteStop = false;
        timings.draggingColourisePaletteStopAmount = false;
        timings.colourisePaletteDrag.reset();
        timings.colourisePalettePicker.reset();
        timings.requestedColourisePalettePickerStopIndex.reset();
        runtimeState->previewRenderStateSignatureValid = false;
    };
    const auto compactButtonWidth = [](const char* label) {
        return ImGui::CalcTextSize(label).x +
               ImGui::GetStyle().FramePadding.x * 2.0F;
    };
    const auto* currentPreset =
        effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Preset
            ? findPreset(effect->paletteSourceId)
            : nullptr;
    const auto* currentLocalEdit =
        currentPreset != nullptr
            ? invisible_places::timing::
                  FindTimingColouriseLocalPaletteEdit(
                      *effect,
                      currentPreset->id)
            : nullptr;

    ImGui::AlignTextToFramePadding();
    ImGui::TextDisabled("Preset");
    ImGui::SameLine();
    const float presetActionWidth =
        currentLocalEdit != nullptr
            ? compactButtonWidth("X") + 2.0F
            : 0.0F;
    ImGui::SetNextItemWidth(
        std::max(
            40.0F,
            ImGui::GetContentRegionAvail().x -
                presetActionWidth));
    const std::string presetPreview =
        effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Preset
            ? paletteDisplayName()
            : "Choose preset...";
    ImGui::BeginDisabled(paletteSourceLocked);
    if (ImGui::BeginCombo(
            "##TimingColourisePresetPalette",
            presetPreview.c_str())) {
        for (const auto& preset : presets) {
            const bool originalSelected =
                effect->paletteSourceKind ==
                    TimingColourisePaletteSourceKind::Preset &&
                effect->paletteSourceId == preset.id &&
                !effect->paletteEdited;
            if (DrawTimingPaletteComboEntry(
                    preset,
                    originalSelected) &&
                invisible_places::timing::
                    ActivateTimingColouriseOriginalPreset(
                        effect,
                        preset)) {
                resetPaletteInteraction();
            }
            const auto* localEdit = invisible_places::timing::
                FindTimingColouriseLocalPaletteEdit(
                    *effect,
                    preset.id);
            if (localEdit == nullptr) {
                continue;
            }
            TimingColourisePaletteDefinition editedDefinition{
                .id = preset.id + "-effect-local-edit",
                .name = localEdit->presetName + "_edited",
                .palette = localEdit->palette,
            };
            const bool localEditSelected =
                effect->paletteSourceKind ==
                    TimingColourisePaletteSourceKind::Preset &&
                effect->paletteSourceId == preset.id &&
                effect->paletteEdited;
            ImGui::Indent(10.0F);
            if (DrawTimingPaletteComboEntry(
                    editedDefinition,
                    localEditSelected) &&
                invisible_places::timing::
                    ActivateTimingColouriseLocalPaletteEdit(
                        effect,
                        preset.id)) {
                resetPaletteInteraction();
            }
            ImGui::Unindent(10.0F);
        }
        ImGui::EndCombo();
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        hasPaletteKeys
            ? "Palette source changes are locked while this effect has keyed palette versions."
        : paletteSourceLocked
            ? "Save the active _edited palette before changing its source."
            : "Choose a built-in original or one of this effect's private _edited versions. Editing an original creates its private version; switching does not discard either version.");
    const auto* activePreset =
        effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Preset
            ? findPreset(effect->paletteSourceId)
            : nullptr;
    const auto* activeLocalEdit =
        activePreset != nullptr
            ? invisible_places::timing::
                  FindTimingColouriseLocalPaletteEdit(
                      *effect,
                      activePreset->id)
            : nullptr;
    const bool canDiscardLocalEdit =
        activePreset != nullptr && activeLocalEdit != nullptr &&
        !hasPaletteKeys;
    if (activeLocalEdit != nullptr) {
        ImGui::SameLine(0.0F, 2.0F);
        ImGui::BeginDisabled(!canDiscardLocalEdit);
        if (ImGui::SmallButton("X##DiscardLocalPaletteEdit") &&
            activePreset != nullptr &&
            invisible_places::timing::
                DiscardTimingColouriseLocalPaletteEdit(
                    effect,
                    *activePreset)) {
            resetPaletteInteraction();
            runtimeState->statusMessage =
                "Discarded " + activePreset->name +
                "_edited and restored the built-in preset.";
            runtimeState->errorMessage.clear();
        }
        ImGui::EndDisabled();
        DrawTimingControlTooltip(
            canDiscardLocalEdit
                ? "Discard this effect's private _edited preset and restore the built-in original."
                : "Palette keys lock this private edit. Remove its palette keys before discarding it.");
    }

    ImGui::AlignTextToFramePadding();
    ImGui::TextDisabled("Saved");
    ImGui::SameLine();
    const std::string savedPreview =
        effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Saved
            ? paletteDisplayName()
            : "Choose saved palette...";
    const float savedActionWidth =
        compactButtonWidth("+") + compactButtonWidth("Save") +
        compactButtonWidth("X") + 6.0F;
    ImGui::SetNextItemWidth(std::max(
        40.0F,
        ImGui::GetContentRegionAvail().x -
            savedActionWidth));
    ImGui::BeginDisabled(paletteSourceLocked);
    if (ImGui::BeginCombo(
            "##TimingColouriseSavedPalette",
            savedPreview.c_str())) {
        for (const auto& saved :
             water.savedTimingColourisePalettes) {
            const bool selected =
                effect->paletteSourceKind ==
                    TimingColourisePaletteSourceKind::Saved &&
                effect->paletteSourceId == saved.id;
            if (DrawTimingPaletteComboEntry(
                    saved,
                    selected)) {
                ApplyTimingColourisePaletteSource(
                    effect,
                    TimingColourisePaletteSourceKind::Saved,
                    saved);
                timings.selectedColourisePaletteStopIndex = 0U;
                timings.draggingColourisePaletteStop = false;
                timings.draggingColourisePaletteStopAmount = false;
                runtimeState
                    ->previewRenderStateSignatureValid = false;
            }
        }
        if (water.savedTimingColourisePalettes.empty()) {
            ImGui::TextDisabled(
                "No saved palettes in this project.");
        }
        ImGui::EndCombo();
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        hasPaletteKeys
            ? "Palette source changes are locked while this effect has keyed palette versions."
        : paletteSourceLocked
            ? "Save the active _edited palette before choosing another palette if you want to keep the changes."
            : "Copy a saved project palette into this Colourise effect.");

    ImGui::SameLine();
    if (ImGui::SmallButton("+")) {
        const bool promotesLocalPresetEdit =
            effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Preset &&
            effect->paletteEdited &&
            invisible_places::timing::
                    FindTimingColouriseLocalPaletteEdit(
                        *effect,
                        effect->paletteSourceId) != nullptr;
        timings.paletteNameBuffer =
            effect->paletteSourceName.empty()
                ? "Palette " +
                      std::to_string(
                          water.savedTimingColourisePalettes
                                  .size() +
                              1U)
            : promotesLocalPresetEdit
                ? effect->paletteSourceName
                : effect->paletteSourceName + " Copy";
        ImGui::OpenPopup(
            "Save New Colourise Palette");
    }
    DrawTimingControlTooltip(
        effect->paletteSourceKind ==
                    TimingColourisePaletteSourceKind::Preset &&
                effect->paletteEdited
            ? "Promote the active private _edited preset to a shared saved project palette. Other private preset edits on this effect remain available."
            : "Save this palette under a new editable project name. Effect-local keys remain attached.");

    ImGui::SameLine(0.0F, 2.0F);
    auto* selectedSavedPalette =
        effect->paletteSourceKind ==
                TimingColourisePaletteSourceKind::Saved
            ? findSavedPalette(effect->paletteSourceId)
            : nullptr;
    const bool canSaveEdited =
        selectedSavedPalette != nullptr &&
        effect->paletteEdited;
    ImGui::BeginDisabled(!canSaveEdited);
    if (ImGui::SmallButton("Save") &&
        selectedSavedPalette != nullptr) {
        selectedSavedPalette->palette =
            invisible_places::timing::
                SanitizeTimingColourisePalette(
                    effect->basePalette);
        effect->paletteEdited = false;
        runtimeState->statusMessage =
            "Saved palette " +
            selectedSavedPalette->name + ".";
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        canSaveEdited
            ? "Overwrite the saved palette with this _edited base and return to its saved name."
            : "Edit a saved palette before overwriting it.");

    ImGui::SameLine(0.0F, 2.0F);
    const bool savedPaletteHasKeyedUse =
        selectedSavedPalette != nullptr &&
        TimingColouriseSavedPaletteHasKeyedUse(
            water,
            selectedSavedPalette->id);
    const bool hadSelectedSavedPalette =
        selectedSavedPalette != nullptr;
    ImGui::BeginDisabled(
        selectedSavedPalette == nullptr ||
        savedPaletteHasKeyedUse);
    if (ImGui::SmallButton("X") &&
        selectedSavedPalette != nullptr) {
        const std::string deletedId =
            selectedSavedPalette->id;
        const std::string deletedName =
            selectedSavedPalette->name;
        DetachTimingColouriseSavedPaletteSource(
            &water,
            deletedId);
        std::erase_if(
            water.savedTimingColourisePalettes,
            [&](const auto& candidate) {
                return candidate.id == deletedId;
            });
        selectedSavedPalette = nullptr;
        runtimeState->statusMessage =
            "Deleted saved palette " + deletedName + ".";
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        !hadSelectedSavedPalette
            ? "Select a saved palette before deleting it."
        : savedPaletteHasKeyedUse
            ? "This saved palette is used by keyed Colourise versions and cannot be deleted."
            : "Delete this saved palette. Unkeyed effects keep independent custom snapshots.");

    if (ImGui::BeginPopupModal(
            "Save New Colourise Palette",
            nullptr,
            ImGuiWindowFlags_AlwaysAutoResize)) {
        ImGui::TextUnformatted(
            "Save an editable project palette");
        ImGui::SetNextItemWidth(280.0F);
        InputTextString(
            "Name",
            &timings.paletteNameBuffer);
        const std::string newName =
            TrimText(timings.paletteNameBuffer);
        const std::string normalizedNewName =
            LowercaseAsciiCopy(newName);
        const bool duplicateName =
            std::any_of(
                water.savedTimingColourisePalettes.begin(),
                water.savedTimingColourisePalettes.end(),
                [&](const auto& saved) {
                    return LowercaseAsciiCopy(
                               TrimText(saved.name)) ==
                           normalizedNewName;
                });
        if (duplicateName) {
            ImGui::TextDisabled(
                "A saved palette already uses this name.");
        }
        ImGui::BeginDisabled(
            newName.empty() || duplicateName);
        const bool saveNew =
            ImGui::Button("Save New");
        ImGui::EndDisabled();
        ImGui::SameLine();
        const bool cancelNew =
            ImGui::Button("Cancel");
        if (saveNew && !newName.empty() &&
            !duplicateName) {
            const std::string savedId =
                invisible_places::timing::
                    AllocateTimingColourisePaletteId(
                        water.savedTimingColourisePalettes,
                        &water
                             .nextTimingColourisePaletteSequence);
            const bool promotesLocalPresetEdit =
                effect->paletteSourceKind ==
                    TimingColourisePaletteSourceKind::Preset &&
                effect->paletteEdited &&
                invisible_places::timing::
                        FindTimingColouriseLocalPaletteEdit(
                            *effect,
                            effect->paletteSourceId) != nullptr;
            bool saved = false;
            if (promotesLocalPresetEdit) {
                const std::string presetId =
                    effect->paletteSourceId;
                if (auto promoted = invisible_places::timing::
                        PromoteTimingColouriseLocalPaletteEdit(
                            effect,
                            presetId,
                            savedId,
                            newName);
                    promoted.has_value()) {
                    water.savedTimingColourisePalettes.push_back(
                        invisible_places::timing::
                            SanitizeTimingColourisePaletteDefinition(
                                std::move(promoted.value())));
                    saved = true;
                }
            } else {
                TimingColourisePaletteDefinition definition{
                    .id = savedId,
                    .name = newName,
                    .palette = effect->basePalette,
                };
                water.savedTimingColourisePalettes.push_back(
                    invisible_places::timing::
                        SanitizeTimingColourisePaletteDefinition(
                            std::move(definition)));
                ApplyTimingColourisePaletteSource(
                    effect,
                    TimingColourisePaletteSourceKind::Saved,
                    water.savedTimingColourisePalettes.back(),
                    true);
                saved = true;
            }
            if (saved) {
                resetPaletteInteraction();
                timings.paletteNameBuffer.clear();
                runtimeState->statusMessage =
                    "Saved palette " + newName +
                    " and assigned it to this Colourise effect.";
                runtimeState->errorMessage.clear();
                ImGui::CloseCurrentPopup();
            } else {
                runtimeState->errorMessage =
                    "The private palette edit could not be promoted.";
                runtimeState->statusMessage.clear();
            }
        } else if (cancelNew) {
            timings.paletteNameBuffer.clear();
            ImGui::CloseCurrentPopup();
        }
        ImGui::EndPopup();
    }

    hasPaletteKeys =
        TimingColouriseEffectHasPaletteKeys(*effect);
    const bool legacyModel =
        effect->paletteKeyModel ==
        TimingColourisePaletteKeyModel::LegacySnapshots;
    const bool presetSource =
        effect->paletteSourceKind ==
        TimingColourisePaletteSourceKind::Preset;

    auto legacyExactKey = std::find_if(
        effect->paletteKeys.begin(),
        effect->paletteKeys.end(),
        [&](const auto& key) {
            return std::abs(key.position - position) <=
                   invisible_places::timing::
                       kTimingColouriseKeyTolerance;
        });
    TimingColourisePalette* legacyEditable = nullptr;
    const auto evaluateRawPaletteLut = [&]() {
        auto rawEffect = *effect;
        rawEffect.colouriseAmountOverrideMode =
            TimingColouriseAmountOverrideMode::Maximum;
        rawEffect.colouriseAmountOverride = 1.0F;
        rawEffect.palettePhaseOffset = 0.0F;
        rawEffect.effectParameterKeys.clear();
        return invisible_places::timing::
            EvaluateTimingColourisePaletteLut(
                rawEffect,
                position);
    };
    auto rawEvaluatedLut = evaluateRawPaletteLut();
    auto evaluatedLut =
        invisible_places::timing::
            EvaluateTimingColourisePaletteLut(
                *effect,
                position);
    TimingColourisePalette workingPalette;
    if (legacyModel) {
        if (effect->paletteKeys.empty()) {
            legacyEditable = &effect->basePalette;
        } else if (
            legacyExactKey != effect->paletteKeys.end()) {
            legacyEditable = &legacyExactKey->palette;
        }
        workingPalette =
            legacyEditable != nullptr
                ? invisible_places::timing::
                      SanitizeTimingColourisePalette(
                          *legacyEditable)
                : MaterializeTimingPaletteFromLut(
                      rawEvaluatedLut);
    } else {
        workingPalette =
            invisible_places::timing::
                EvaluateTimingColourisePalette(
                    *effect,
                    position);
    }

    if (!timings.selectedColourisePaletteStopIndex
             .has_value() ||
        timings.selectedColourisePaletteStopIndex.value() >=
            workingPalette.stops.size()) {
        timings.selectedColourisePaletteStopIndex = 0U;
    }

    auto paletteKeyPositions =
        invisible_places::timing::
            TimingColourisePaletteKeyPositions(*effect);
    const auto drawKeyedPaletteVersionsCombo = [&]() {
      if (!paletteKeyPositions.empty()) {
        std::string keyedPreview =
            std::to_string(paletteKeyPositions.size()) +
            (paletteKeyPositions.size() == 1U
                 ? " keyed version"
                 : " keyed versions");
        for (std::size_t index = 0U;
             index < paletteKeyPositions.size();
             ++index) {
            if (std::abs(
                    paletteKeyPositions[index] -
                    position) <=
                invisible_places::timing::
                    kTimingColouriseKeyTolerance) {
                keyedPreview =
                    invisible_places::timing::
                        TimingColourisePaletteKeyStateName(
                            paletteDisplayName(),
                            index);
                break;
            }
        }
        if (ImGui::BeginCombo(
                "Keyed Palettes",
                keyedPreview.c_str())) {
            for (std::size_t index = 0U;
                 index < paletteKeyPositions.size();
                 ++index) {
                const float keyPosition =
                    paletteKeyPositions[index];
                TimingColourisePaletteDefinition keyed;
                keyed.id =
                    effect->id + "-palette-key-" +
                    std::to_string(index);
                keyed.name =
                    invisible_places::timing::
                        TimingColourisePaletteKeyStateName(
                            paletteDisplayName(),
                            index);
                keyed.palette =
                    legacyModel
                        ? MaterializeTimingPaletteFromLut(
                              invisible_places::timing::
                                  EvaluateTimingColourisePaletteLut(
                                      *effect,
                                      keyPosition))
                        : invisible_places::timing::
                              EvaluateTimingColourisePalette(
                                  *effect,
                                  keyPosition);
                const bool selected =
                    std::abs(keyPosition - position) <=
                    invisible_places::timing::
                        kTimingColouriseKeyTolerance;
                if (DrawTimingPaletteComboEntry(
                        keyed,
                        selected)) {
                    runtimeState->animationPanel.scrubAmount =
                        keyPosition;
                    ApplyAnimationScrub(runtimeState);
                }
            }
            ImGui::EndCombo();
        }
        DrawTimingControlTooltip(
            "These _RunNN versions belong only to this Colourise effect. Their numbers follow key order automatically.");
      } else {
        ImGui::TextDisabled(
            "No keyed palette versions for this Colourise effect.");
      }
    };

    const auto drawFlipPaletteButton = [&]() {
    const bool canFlipPalette =
        invisible_places::timing::
            CanReverseTimingColourisePaletteAtPosition(
                *effect,
                position);
    ImGui::BeginDisabled(!canFlipPalette);
    if (ImGui::Button("Flip Palette")) {
        StopAnimationPlayback(runtimeState);
        const auto selectedStopId =
            timings.selectedColourisePaletteStopIndex
                    .has_value() &&
                    timings.selectedColourisePaletteStopIndex
                            .value() <
                        workingPalette.stops.size()
                ? workingPalette
                      .stops[timings
                                 .selectedColourisePaletteStopIndex
                                 .value()]
                      .id
                : std::string{};
        if (invisible_places::timing::
                ReverseTimingColourisePaletteAtPosition(
                    effect,
                    position)) {
            hasPaletteKeys =
                TimingColouriseEffectHasPaletteKeys(*effect);
            rawEvaluatedLut = evaluateRawPaletteLut();
            evaluatedLut =
                invisible_places::timing::
                    EvaluateTimingColourisePaletteLut(
                        *effect,
                        position);
            if (legacyModel) {
                legacyExactKey = std::find_if(
                    effect->paletteKeys.begin(),
                    effect->paletteKeys.end(),
                    [&](const auto& key) {
                        return std::abs(
                                   key.position - position) <=
                               invisible_places::timing::
                                   kTimingColouriseKeyTolerance;
                    });
                if (effect->paletteKeys.empty()) {
                    legacyEditable = &effect->basePalette;
                } else if (
                    legacyExactKey !=
                    effect->paletteKeys.end()) {
                    legacyEditable =
                        &legacyExactKey->palette;
                } else {
                    legacyEditable = nullptr;
                }
                workingPalette =
                    legacyEditable != nullptr
                        ? invisible_places::timing::
                              SanitizeTimingColourisePalette(
                                  *legacyEditable)
                        : MaterializeTimingPaletteFromLut(
                              rawEvaluatedLut);
            } else {
                workingPalette =
                    invisible_places::timing::
                        EvaluateTimingColourisePalette(
                            *effect,
                            position);
            }
            paletteKeyPositions =
                invisible_places::timing::
                    TimingColourisePaletteKeyPositions(
                        *effect);
            if (!selectedStopId.empty()) {
                timings.selectedColourisePaletteStopIndex =
                    stopIndexById(
                        workingPalette,
                        selectedStopId);
            }
            runtimeState->statusMessage =
                hasPaletteKeys
                    ? "Flipped the palette at animation position " +
                          FormatFixed(position, 4) + "."
                    : "Flipped the palette left to right.";
            runtimeState->previewRenderStateSignatureValid =
                false;
        }
    }
    ImGui::EndDisabled();
    const char* flipPaletteTooltip = nullptr;
    if (!canFlipPalette) {
        flipPaletteTooltip =
            "Move onto a legacy palette key before flipping it.";
    } else if (
        legacyModel && presetSource &&
        effect->paletteEdited) {
        flipPaletteTooltip =
            "Reverse this effect's private _edited preset snapshot left "
            "to right. The private version remains selected.";
    } else if (legacyModel && presetSource) {
        flipPaletteTooltip =
            "Reverse this whole legacy palette snapshot left to right. "
            "An unkeyed preset remains a preset; once snapshot keys "
            "exist, move onto the exact key to flip it.";
    } else if (legacyModel) {
        flipPaletteTooltip =
            "Reverse this whole legacy palette snapshot left to right. "
            "An unkeyed saved or custom base becomes _edited; once "
            "snapshot keys exist, move onto the exact key to flip it.";
    } else if (hasPaletteKeys) {
        flipPaletteTooltip =
            "Reverse the palette left to right by keying every stop "
            "Position here. Position keys use the normal timeline "
            "interpolation and first/last-key hold behaviour.";
    } else if (presetSource && effect->paletteEdited) {
        flipPaletteTooltip =
            "Reverse this effect's private _edited preset left to right. "
            "The private version remains selected.";
    } else if (presetSource) {
        flipPaletteTooltip =
            "Reverse this built-in preset left to right without marking "
            "it _edited. Use + to save the flipped version as a project "
            "palette.";
    } else {
        flipPaletteTooltip =
            "Reverse the palette left to right. The saved or custom base "
            "becomes _edited.";
    }
    DrawTimingControlTooltip(flipPaletteTooltip);
    };

    const float evaluatedPhase = invisible_places::timing::
        EvaluateTimingColouriseEffectParameter(
            *effect,
            TimingColouriseEffectParameter::PalettePhase,
            position);
    const float evaluatedAmountOverride = invisible_places::timing::
        EvaluateTimingColouriseEffectParameter(
            *effect,
            TimingColouriseEffectParameter::AmountOverride,
            position);

    const bool canEditStops =
        !legacyModel || legacyEditable != nullptr;
    const bool canEditTopology =
        canEditStops && !hasPaletteKeys;
    // Shared by the Colour Stop popup's Remove button and the Delete key.
    // Refusals stay silent here; the popup's disabled-button tooltip
    // explains the topology gates.
    const auto removePaletteStop =
        [&](const std::string& stopId,
            std::size_t stopIndex) -> bool {
        if (legacyModel || hasPaletteKeys ||
            !invisible_places::timing::
                CanRemoveTimingColourisePaletteStop(
                    *effect,
                    stopId)) {
            return false;
        }
        if (!invisible_places::timing::
                RemoveTimingColourisePaletteStop(
                    effect,
                    stopId)) {
            return false;
        }
        markPaletteBaseEdited();
        timings.selectedColourisePaletteStopIndex =
            std::min<std::size_t>(
                stopIndex,
                effect->basePalette.stops.size() - 1U);
        timings.draggingColourisePaletteStop = false;
        runtimeState->previewRenderStateSignatureValid = false;
        return true;
    };
    const auto isDraggingPaletteStop = [&]() {
        return timings.draggingColourisePaletteStop ||
               timings.draggingColourisePaletteStopAmount;
    };
    if (isDraggingPaletteStop() &&
        timings.colourisePaletteDrag.has_value() &&
        timings.colourisePaletteDrag->effectId ==
            effect->id) {
        if (const auto selectedById =
                stopIndexById(
                    workingPalette,
                    timings.colourisePaletteDrag->stopId);
            selectedById.has_value()) {
            timings.selectedColourisePaletteStopIndex =
                selectedById;
        } else {
            timings.draggingColourisePaletteStop = false;
            timings.draggingColourisePaletteStopAmount = false;
            timings.colourisePaletteDrag.reset();
        }
    } else if (!isDraggingPaletteStop()) {
        timings.colourisePaletteDrag.reset();
    }
    const auto paletteBeforePreview = workingPalette;
    const bool wasDraggingPaletteStop =
        isDraggingPaletteStop();
    const bool previewChanged =
        DrawTimingPalettePreview(
            evaluatedLut,
            rawEvaluatedLut,
            evaluatedPhase,
            effect->colouriseAmountOverrideMode,
            evaluatedAmountOverride,
            &workingPalette,
            &timings.selectedColourisePaletteStopIndex,
            &timings.draggingColourisePaletteStop,
            &timings.draggingColourisePaletteStopAmount,
            &timings
                 .requestedColourisePalettePickerStopIndex,
            canEditStops,
            canEditTopology,
            "##TimingColourisePalettePreview");
    bool effectControlsChanged = false;
    if (ImGui::BeginTable(
            "##TimingColouriseEffectControls",
            2,
            ImGuiTableFlags_SizingStretchSame |
                ImGuiTableFlags_NoSavedSettings)) {
        ImGui::TableNextColumn();
        effectControlsChanged =
            DrawTimingColouriseEffectParameterEditor(
                runtimeState,
                effect,
                TimingColouriseEffectParameter::AmountOverride);
        ImGui::TableNextColumn();
        effectControlsChanged =
            DrawTimingColouriseEffectParameterEditor(
                runtimeState,
                effect,
                TimingColouriseEffectParameter::PalettePhase,
                drawFlipPaletteButton) ||
            effectControlsChanged;
        ImGui::EndTable();
    }
    const auto amountKeyPositions = invisible_places::timing::
        TimingColouriseEffectParameterKeyPositions(
            *effect,
            TimingColouriseEffectParameter::AmountOverride);
    const auto phaseKeyPositions = invisible_places::timing::
        TimingColouriseEffectParameterKeyPositions(
            *effect,
            TimingColouriseEffectParameter::PalettePhase);
    const std::array effectParameterLanes{
        TimingColouriseKeyLaneSeries{
            .label = "Colourise Amount",
            .track = TimingColouriseKeyTrack::EffectParameter,
            .effectParameter =
                TimingColouriseEffectParameter::AmountOverride,
            .positions = std::span<const float>{amountKeyPositions},
            .colour = IM_COL32(120, 205, 172, 255),
        },
        TimingColouriseKeyLaneSeries{
            .label = "Colour Phase",
            .track = TimingColouriseKeyTrack::EffectParameter,
            .effectParameter =
                TimingColouriseEffectParameter::PalettePhase,
            .positions = std::span<const float>{phaseKeyPositions},
            .colour = IM_COL32(238, 174, 72, 255),
        },
    };
    ImGui::TextDisabled("Value over animation position");
    DrawTimingControlTooltip(
        "Colourise Amount uses its own visible value range. Colour Phase uses a fixed -1 to +1 turn range and draws integer-shifted copies of its accumulated curve so every wrap remains visible. Drag the matching coloured markers on the horizontal axis to retime keys.");
    DrawTimingKeyLaneGroup(
        "##TimingColouriseEffectParameterKeyLane",
        runtimeState,
        effect,
        effectParameterLanes);
    if (effectControlsChanged) {
        evaluatedLut = invisible_places::timing::
            EvaluateTimingColourisePaletteLut(*effect, position);
        runtimeState->previewRenderStateSignatureValid = false;
    }
    drawKeyedPaletteVersionsCombo();
    if (isDraggingPaletteStop()) {
        StopAnimationPlayback(runtimeState);
        if (!wasDraggingPaletteStop ||
            !timings.colourisePaletteDrag.has_value() ||
            timings.colourisePaletteDrag->effectId !=
                effect->id) {
            const auto selectedIndex =
                timings.selectedColourisePaletteStopIndex;
            if (selectedIndex.has_value() &&
                selectedIndex.value() <
                    workingPalette.stops.size()) {
                timings.colourisePaletteDrag =
                    TimingsPanelState::
                        ColourisePaletteStopAuthoringState{
                            .effectId = effect->id,
                            .stopId =
                                workingPalette
                                    .stops[selectedIndex.value()]
                                    .id,
                            .animationPosition = position,
                        };
            }
        }
    }
    const float previewKeyPosition =
        timings.colourisePaletteDrag.has_value() &&
                timings.colourisePaletteDrag->effectId ==
                    effect->id
            ? timings.colourisePaletteDrag
                  ->animationPosition
            : position;
    if (previewChanged) {
        StopAnimationPlayback(runtimeState);
        if (legacyModel && legacyEditable != nullptr) {
            *legacyEditable =
                invisible_places::timing::
                    SanitizeTimingColourisePalette(
                        workingPalette);
            if (effect->paletteKeys.empty()) {
                markPaletteBaseEdited();
            }
        } else if (!legacyModel &&
                   !hasPaletteKeys) {
            effect->basePalette =
                invisible_places::timing::
                    SanitizeTimingColourisePalette(
                        workingPalette);
            workingPalette = effect->basePalette;
            markPaletteBaseEdited();
        } else if (!legacyModel) {
            for (const auto& stop :
                 workingPalette.stops) {
                const auto beforeIndex =
                    stopIndexById(
                        paletteBeforePreview,
                        stop.id);
                if (!beforeIndex.has_value()) {
                    continue;
                }
                const auto& before = paletteBeforePreview
                    .stops[beforeIndex.value()];
                const bool positionChanged =
                    std::abs(before.position - stop.position) >
                    std::numeric_limits<float>::epsilon();
                const bool amountChanged =
                    std::abs(
                        before.colouriseAmount -
                        stop.colouriseAmount) >
                    std::numeric_limits<float>::epsilon();
                if (positionChanged) {
                    (void)invisible_places::timing::
                        AddOrUpdateTimingColourisePaletteStopScalarKey(
                            effect,
                            stop.id,
                            TimingColourisePaletteStopParameter::
                                Position,
                            previewKeyPosition,
                            stop.position,
                            WaterScenarioInterpolation::Smooth);
                }
                if (!amountChanged) {
                    continue;
                }
                const bool amountTrackArmed = std::any_of(
                    effect->paletteStopParameterKeys.begin(),
                    effect->paletteStopParameterKeys.end(),
                    [&](const auto& key) {
                        return key.stopId == stop.id &&
                               key.parameter ==
                                   TimingColourisePaletteStopParameter::
                                       ColouriseAmount;
                    });
                if (amountTrackArmed) {
                    (void)invisible_places::timing::
                        AddOrUpdateTimingColourisePaletteStopScalarKey(
                            effect,
                            stop.id,
                            TimingColourisePaletteStopParameter::
                                ColouriseAmount,
                            previewKeyPosition,
                            stop.colouriseAmount,
                            WaterScenarioInterpolation::Smooth);
                    continue;
                }
                const auto baseIndex = stopIndexById(
                    effect->basePalette,
                    stop.id);
                if (baseIndex.has_value()) {
                    effect->basePalette
                        .stops[baseIndex.value()]
                        .colouriseAmount = stop.colouriseAmount;
                    markPaletteBaseEdited();
                }
            }
        }
        runtimeState->previewRenderStateSignatureValid =
            false;
    }
    if (!isDraggingPaletteStop()) {
        timings.colourisePaletteDrag.reset();
    }

    if (timings
            .requestedColourisePalettePickerStopIndex
            .has_value()) {
        StopAnimationPlayback(runtimeState);
        const auto selectedIndex =
            std::min(
                timings
                    .requestedColourisePalettePickerStopIndex
                    .value(),
                workingPalette.stops.size() - 1U);
        timings.selectedColourisePaletteStopIndex =
            selectedIndex;
        timings.colourisePalettePicker =
            TimingsPanelState::
                ColourisePaletteStopAuthoringState{
                    .effectId = effect->id,
                    .stopId =
                        workingPalette
                            .stops[selectedIndex]
                            .id,
                    .animationPosition = position,
                };
        timings
            .requestedColourisePalettePickerStopIndex
            .reset();
        ImGui::OpenPopup("Colour Stop");
    }

    const auto findParameterKeyAt =
        [&](std::string_view stopId,
            TimingColourisePaletteStopParameter parameter,
            float keyPosition)
            -> TimingColourisePaletteStopParameterKey* {
        const auto found = std::find_if(
            effect->paletteStopParameterKeys.begin(),
            effect->paletteStopParameterKeys.end(),
            [&](const auto& key) {
                return key.stopId == stopId &&
                       key.parameter == parameter &&
                       std::abs(key.position - keyPosition) <=
                           invisible_places::timing::
                               kTimingColouriseKeyTolerance;
            });
        return found ==
                       effect->paletteStopParameterKeys.end()
                   ? nullptr
                   : &*found;
    };
    const auto interpolationForAt =
        [&](std::string_view stopId,
            TimingColourisePaletteStopParameter parameter,
            float keyPosition) {
        const auto* key =
            findParameterKeyAt(
                stopId,
                parameter,
                keyPosition);
        return key != nullptr
                   ? key->interpolation
                   : WaterScenarioInterpolation::Smooth;
    };

    float pickerPosition = position;
    const bool pickerMatches =
        timings.colourisePalettePicker.has_value() &&
        timings.colourisePalettePicker->effectId ==
            effect->id;
    if (pickerMatches) {
        pickerPosition =
            timings.colourisePalettePicker
                ->animationPosition;
        if (const auto selectedById =
                stopIndexById(
                    workingPalette,
                    timings.colourisePalettePicker->stopId);
            selectedById.has_value()) {
            timings.selectedColourisePaletteStopIndex =
                selectedById;
        }
    }

    if (ImGui::BeginPopup("Colour Stop")) {
        StopAnimationPlayback(runtimeState);
        if (!canEditStops ||
            !timings.selectedColourisePaletteStopIndex
                 .has_value() ||
            timings.selectedColourisePaletteStopIndex.value() >=
                workingPalette.stops.size()) {
            ImGui::TextDisabled(
                "Select an editable colour stop. Evaluated legacy palettes are read-only between snapshot keys.");
        } else {
            const std::size_t selectedIndex =
                timings
                    .selectedColourisePaletteStopIndex
                    .value();
            const auto originalStop =
                workingPalette.stops[selectedIndex];
            auto editedStop = originalStop;
            ImGui::Text(
                "Colour Stop %zu of %zu",
                selectedIndex + 1U,
                workingPalette.stops.size());
            const bool colourChanged =
                ImGui::ColorPicker3(
                    "##TimingColourStopPicker",
                    editedStop.colour.data());
            if (!legacyModel) {
                ImGui::SameLine();
                const bool colourExact =
                    findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            Colour,
                        pickerPosition) != nullptr;
                if (ImGui::SmallButton("+##KeyColour")) {
                    (void)invisible_places::timing::
                        AddOrUpdateTimingColourisePaletteStopColourKey(
                            effect,
                            originalStop.id,
                            pickerPosition,
                            editedStop.colour,
                            interpolationForAt(
                                originalStop.id,
                                TimingColourisePaletteStopParameter::
                                    Colour,
                                pickerPosition));
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
                DrawTimingControlTooltip(
                    colourExact
                        ? "Update Colour Key: update only this stop's colour key at the captured animation position."
                        : "Key Colour: key only this stop's colour at the captured animation position.");
            }

            ImGui::TextDisabled("Position");
            ImGui::SameLine();
            ImGui::SetNextItemWidth(92.0F);
            const bool positionChanged =
                ImGui::InputFloat(
                    "##TimingColourStopPosition",
                    &editedStop.position,
                    0.0F,
                    0.0F,
                    "%.4f");
            if (!legacyModel) {
                ImGui::SameLine(0.0F, 2.0F);
                const bool positionExact =
                    findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            Position,
                        pickerPosition) != nullptr;
                if (ImGui::SmallButton("+##KeyPosition")) {
                    (void)invisible_places::timing::
                        AddOrUpdateTimingColourisePaletteStopScalarKey(
                            effect,
                            originalStop.id,
                            TimingColourisePaletteStopParameter::
                                Position,
                            pickerPosition,
                            std::clamp(
                                editedStop.position,
                                0.0F,
                                1.0F),
                            interpolationForAt(
                                originalStop.id,
                                TimingColourisePaletteStopParameter::
                                    Position,
                                pickerPosition));
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
                DrawTimingControlTooltip(
                    positionExact
                        ? "Update Position Key: update only this stop's gradient-position key at the captured animation position."
                        : "Key Position: key only this stop's gradient position at the captured animation position.");
            }
            ImGui::SameLine();
            ImGui::TextDisabled("Amount");
            ImGui::SameLine();
            ImGui::SetNextItemWidth(92.0F);
            const bool amountChanged =
                ImGui::InputFloat(
                    "##TimingColourStopAmount",
                    &editedStop.colouriseAmount,
                    0.0F,
                    0.0F,
                    "%.3f");
            if (!legacyModel) {
                ImGui::SameLine(0.0F, 2.0F);
                const bool amountExact =
                    findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            ColouriseAmount,
                        pickerPosition) != nullptr;
                if (ImGui::SmallButton("+##KeyAmount")) {
                    (void)invisible_places::timing::
                        AddOrUpdateTimingColourisePaletteStopScalarKey(
                            effect,
                            originalStop.id,
                            TimingColourisePaletteStopParameter::
                                ColouriseAmount,
                            pickerPosition,
                            std::clamp(
                                editedStop.colouriseAmount,
                                0.0F,
                                1.0F),
                            interpolationForAt(
                                originalStop.id,
                                TimingColourisePaletteStopParameter::
                                    ColouriseAmount,
                                pickerPosition));
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
                DrawTimingControlTooltip(
                    amountExact
                        ? "Update Amount Key: update only this stop's Colourise Amount key at the captured animation position."
                        : "Key Amount: key only this stop's Colourise Amount at the captured animation position.");
            }
            editedStop.position =
                std::clamp(
                    editedStop.position,
                    0.0F,
                    1.0F);
            editedStop.colouriseAmount =
                std::clamp(
                    editedStop.colouriseAmount,
                    0.0F,
                    1.0F);

            if (colourChanged || positionChanged ||
                amountChanged) {
                timings.selectedColourisePaletteStopIndex =
                    ReplaceTimingColourisePaletteStop(
                        &workingPalette,
                        selectedIndex,
                        editedStop);
                if (legacyModel &&
                    legacyEditable != nullptr) {
                    *legacyEditable =
                        invisible_places::timing::
                            SanitizeTimingColourisePalette(
                                workingPalette);
                    if (effect->paletteKeys.empty()) {
                        markPaletteBaseEdited();
                    }
                } else if (
                    !legacyModel &&
                    !hasPaletteKeys) {
                    effect->basePalette =
                        invisible_places::timing::
                            SanitizeTimingColourisePalette(
                                workingPalette);
                    workingPalette =
                        effect->basePalette;
                    markPaletteBaseEdited();
                } else if (!legacyModel) {
                    if (colourChanged) {
                        (void)invisible_places::timing::
                            AddOrUpdateTimingColourisePaletteStopColourKey(
                                effect,
                                originalStop.id,
                                pickerPosition,
                                editedStop.colour,
                                interpolationForAt(
                                    originalStop.id,
                                    TimingColourisePaletteStopParameter::
                                        Colour,
                                    pickerPosition));
                    }
                    if (positionChanged) {
                        (void)invisible_places::timing::
                            AddOrUpdateTimingColourisePaletteStopScalarKey(
                                effect,
                                originalStop.id,
                                TimingColourisePaletteStopParameter::
                                    Position,
                                pickerPosition,
                                editedStop.position,
                                interpolationForAt(
                                    originalStop.id,
                                    TimingColourisePaletteStopParameter::
                                        Position,
                                    pickerPosition));
                    }
                    if (amountChanged) {
                        const bool amountTrackArmed = std::any_of(
                            effect->paletteStopParameterKeys.begin(),
                            effect->paletteStopParameterKeys.end(),
                            [&](const auto& key) {
                                return key.stopId == originalStop.id &&
                                       key.parameter ==
                                           TimingColourisePaletteStopParameter::
                                               ColouriseAmount;
                            });
                        if (amountTrackArmed) {
                            (void)invisible_places::timing::
                                AddOrUpdateTimingColourisePaletteStopScalarKey(
                                    effect,
                                    originalStop.id,
                                    TimingColourisePaletteStopParameter::
                                        ColouriseAmount,
                                    pickerPosition,
                                    editedStop.colouriseAmount,
                                    WaterScenarioInterpolation::Smooth);
                        } else if (const auto baseIndex =
                                       stopIndexById(
                                           effect->basePalette,
                                           originalStop.id);
                                   baseIndex.has_value()) {
                            effect->basePalette
                                .stops[baseIndex.value()]
                                .colouriseAmount =
                                editedStop.colouriseAmount;
                            markPaletteBaseEdited();
                        }
                    }
                }
                runtimeState
                    ->previewRenderStateSignatureValid = false;
            }

            if (!legacyModel) {
                if (auto* key = findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            Colour,
                        pickerPosition);
                    key != nullptr &&
                    DrawTimingInterpolationCombo(
                        "Colour Interpolation",
                        &key->interpolation)) {
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
                if (auto* key = findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            Position,
                        pickerPosition);
                    key != nullptr &&
                    DrawTimingInterpolationCombo(
                        "Position Interpolation",
                        &key->interpolation)) {
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
                if (auto* key = findParameterKeyAt(
                        originalStop.id,
                        TimingColourisePaletteStopParameter::
                            ColouriseAmount,
                        pickerPosition);
                    key != nullptr &&
                    DrawTimingInterpolationCombo(
                        "Amount Interpolation",
                        &key->interpolation)) {
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
            }

            const bool canRemoveStop =
                !legacyModel && !hasPaletteKeys &&
                invisible_places::timing::
                    CanRemoveTimingColourisePaletteStop(
                        *effect,
                        originalStop.id);
            ImGui::BeginDisabled(!canRemoveStop);
            if (ImGui::Button("X  Remove Stop") &&
                removePaletteStop(
                    originalStop.id,
                    selectedIndex)) {
                ImGui::CloseCurrentPopup();
            }
            ImGui::EndDisabled();
            DrawTimingControlTooltip(
                canRemoveStop
                    ? "Delete this colour marker. The Delete key also removes the selected stop."
                    : "A stop cannot be removed while palette keys depend on its topology.");
        }
        ImGui::EndPopup();
    }
    if (pickerMatches &&
        !ImGui::IsPopupOpen("Colour Stop")) {
        timings.colourisePalettePicker.reset();
    }

    if (timings.selectedColourisePaletteStopIndex
            .has_value() &&
        timings.selectedColourisePaletteStopIndex.value() <
            workingPalette.stops.size()) {
        const auto& selected =
            workingPalette.stops[
                timings
                    .selectedColourisePaletteStopIndex
                    .value()];
        ImGui::TextDisabled(
            "Stop %zu/%zu   position %.4f   amount %.3f   (double-click marker to edit)",
            timings
                    .selectedColourisePaletteStopIndex
                    .value() +
                1U,
            workingPalette.stops.size(),
            selected.position,
            selected.colouriseAmount);
    }

    DrawTimingKeyLane(
        "##TimingPaletteKeyLane",
        runtimeState,
        effect,
        TimingColouriseKeyTrack::Palette,
        std::nullopt,
        std::nullopt,
        paletteKeyPositions,
        IM_COL32(222, 134, 190, 255));
    const bool exact =
        invisible_places::timing::
            TimingColourisePaletteKeyCountAtPosition(
                *effect,
                position) > 0U;
    if (legacyModel) {
        if (ImGui::SmallButton("+##SetPaletteKey")) {
            invisible_places::timing::
                AddOrUpdateTimingColourisePaletteKey(
                    effect,
                    position,
                    workingPalette,
                    legacyExactKey !=
                            effect->paletteKeys.end()
                        ? legacyExactKey->interpolation
                        : WaterScenarioInterpolation::
                              Smooth);
            runtimeState
                ->previewRenderStateSignatureValid = false;
        }
        DrawTimingControlTooltip(
            exact
                ? "Update Palette Key: legacy projects retain whole-palette snapshot keys exactly. New saved palettes use independent stop-property keys."
                : "Set Palette Key: legacy projects retain whole-palette snapshot keys exactly. New saved palettes use independent stop-property keys.");
    } else {
        const auto selectedIndex =
            timings.selectedColourisePaletteStopIndex
                .value_or(0U);
        const bool canKeySelected =
            selectedIndex < workingPalette.stops.size();
        ImGui::BeginDisabled(!canKeySelected);
        if (ImGui::SmallButton("+##KeySelectedStop")) {
            const auto& stop =
                workingPalette.stops[selectedIndex];
            (void)invisible_places::timing::
                AddOrUpdateTimingColourisePaletteStopScalarKey(
                    effect,
                    stop.id,
                    TimingColourisePaletteStopParameter::
                        Position,
                    position,
                    stop.position,
                    interpolationForAt(
                        stop.id,
                        TimingColourisePaletteStopParameter::
                            Position,
                        position));
            (void)invisible_places::timing::
                AddOrUpdateTimingColourisePaletteStopColourKey(
                    effect,
                    stop.id,
                    position,
                    stop.colour,
                    interpolationForAt(
                        stop.id,
                        TimingColourisePaletteStopParameter::
                            Colour,
                        position));
            (void)invisible_places::timing::
                AddOrUpdateTimingColourisePaletteStopScalarKey(
                    effect,
                    stop.id,
                    TimingColourisePaletteStopParameter::
                        ColouriseAmount,
                    position,
                    stop.colouriseAmount,
                    interpolationForAt(
                        stop.id,
                        TimingColourisePaletteStopParameter::
                            ColouriseAmount,
                        position));
            runtimeState
                ->previewRenderStateSignatureValid = false;
        }
        ImGui::EndDisabled();
        DrawTimingControlTooltip(
            exact
                ? "Update Selected Stop Keys: key all three properties of the selected stop here. Editing an already-keyed palette writes only the property that changed."
                : "Key Selected Stop: key all three properties of the selected stop here. Editing an already-keyed palette writes only the property that changed.");
    }
    ImGui::SameLine(0.0F, 2.0F);
    DrawTimingColouriseTrackButtons(
        runtimeState,
        effect,
        true);

    if (legacyModel) {
        legacyExactKey = std::find_if(
            effect->paletteKeys.begin(),
            effect->paletteKeys.end(),
            [&](const auto& key) {
                return std::abs(
                           key.position - position) <=
                       invisible_places::timing::
                           kTimingColouriseKeyTolerance;
            });
        if (legacyExactKey !=
            effect->paletteKeys.end()) {
            if (DrawTimingInterpolationCombo(
                    "Palette Interpolation",
                    &legacyExactKey->interpolation)) {
                runtimeState
                    ->previewRenderStateSignatureValid = false;
            }
        }
    }

    // Delete removes the selected stop through the exact gates the Colour
    // Stop popup's Remove button uses; refusals stay silent because those
    // gates' tooltips explain the topology locks elsewhere.
    if (timings.selectedColourisePaletteStopIndex.has_value() &&
        timings.selectedColourisePaletteStopIndex.value() <
            workingPalette.stops.size() &&
        ImGui::IsKeyPressed(ImGuiKey_Delete, false) &&
        ImGui::IsWindowFocused(
            ImGuiFocusedFlags_RootAndChildWindows) &&
        !ImGui::GetIO().WantTextInput &&
        !ImGui::IsAnyItemActive() &&
        !ImGui::IsPopupOpen(
            nullptr,
            ImGuiPopupFlags_AnyPopup)) {
        const auto stopIndex =
            timings.selectedColourisePaletteStopIndex.value();
        (void)removePaletteStop(
            workingPalette.stops[stopIndex].id,
            stopIndex);
    }
}

std::optional<std::array<std::size_t, 3>>
TimingColouriseSessionIndicesForScene(
    PreviewRuntimeState* runtimeState,
    const ScenePointCloudRuntime* scene) {
    if (runtimeState == nullptr || scene == nullptr) {
        return std::nullopt;
    }
    constexpr std::array roles{
        invisible_places::scene::ScenePointCloudRole::Sand,
        invisible_places::scene::ScenePointCloudRole::Rock,
        invisible_places::scene::ScenePointCloudRole::Vegetation,
    };
    std::array<std::size_t, 3> result{};
    for (std::size_t index = 0U; index < roles.size();
         ++index) {
        const auto roleIndex =
            invisible_places::scene::
                ScenePointCloudRoleIndex(roles[index]);
        const auto sessionIndex =
            scene->committedDisplaySessionIndices[roleIndex];
        if (!sessionIndex.has_value() ||
            sessionIndex.value() >=
                runtimeState->sessions.size()) {
            return std::nullopt;
        }
        result[index] = sessionIndex.value();
    }
    return result;
}

std::optional<std::array<std::size_t, 3>>
ActiveTimingColouriseSessionIndices(
    PreviewRuntimeState* runtimeState) {
    return TimingColouriseSessionIndicesForScene(
        runtimeState,
        ActiveWaterSurfaceScene(runtimeState));
}

std::vector<invisible_places::timing::TimingColouriseFieldFamily>
BuildActiveTimingColouriseFieldCatalog(
    PreviewRuntimeState* runtimeState) {
    const auto indices =
        ActiveTimingColouriseSessionIndices(runtimeState);
    if (!indices.has_value()) {
        return {};
    }
    std::array<
        invisible_places::timing::
            TimingColouriseLayerFieldSet,
        3>
        fields;
    for (std::size_t layer = 0U; layer < 3U;
         ++layer) {
        const auto& session =
            runtimeState->sessions[
                indices.value()[layer]];
        fields[layer].hasNormals = session.hasNormals;
        // The catalog offers every on-disk field, not only the resident
        // subset: choosing an unloaded field streams it in on demand.
        if (!session.availableScalarFields.empty()) {
            fields[layer].scalarFieldNames.reserve(
                session.availableScalarFields.size());
            for (const auto& available :
                 session.availableScalarFields) {
                fields[layer].scalarFieldNames.push_back(
                    available.name);
            }
        } else {
            fields[layer].scalarFieldNames.reserve(
                session.scalarFields.size());
            for (const auto& field : session.scalarFields) {
                fields[layer].scalarFieldNames.push_back(
                    field.name);
            }
        }
    }
    return invisible_places::timing::
        BuildTimingColouriseFieldCatalog(fields);
}

std::optional<std::pair<float, float>>
TimingColouriseSelectorRangeFromStats(
    PreviewRuntimeState* runtimeState,
    const invisible_places::timing::
        TimingColouriseFieldSelector& selector) {
    using invisible_places::timing::
        TimingColouriseFieldSource;
    if (selector.source !=
        TimingColouriseFieldSource::Scalar) {
        return std::pair{-1.0F, 1.0F};
    }
    const auto indices =
        ActiveTimingColouriseSessionIndices(runtimeState);
    if (!indices.has_value()) {
        return std::nullopt;
    }
    float minimum =
        std::numeric_limits<float>::infinity();
    float maximum =
        -std::numeric_limits<float>::infinity();
    bool found = false;
    for (const auto sessionIndex : indices.value()) {
        const auto& fields =
            runtimeState->sessions[sessionIndex]
                .scalarFields;
        const auto field = std::find_if(
            fields.begin(),
            fields.end(),
            [&](const auto& candidate) {
                return candidate.name ==
                       selector.scalarFieldName;
            });
        if (field == fields.end() || !field->valid) {
            return std::nullopt;
        }
        minimum = std::min(minimum, field->minimum);
        maximum = std::max(maximum, field->maximum);
        found = true;
    }
    return found
               ? std::optional{
                     std::pair{minimum, maximum}}
               : std::nullopt;
}

std::optional<std::pair<std::string, std::filesystem::path>>
TimingColouriseHistogramIdentityForScene(
    PreviewRuntimeState* runtimeState,
    const ScenePointCloudRuntime* scene,
    const std::array<std::size_t, 3>& indices,
    const invisible_places::timing::
        TimingColouriseFieldSelector& selector) {
    if (runtimeState == nullptr || scene == nullptr) {
        return std::nullopt;
    }
    invisible_places::timing::
        TimingColouriseHistogramFingerprintInput input;
    input.sceneGroupName = scene->sceneGroupName;
    input.selector = selector;
    input.displaySpacingMicrometres =
        scene->committedDisplaySpacingMicrometres
            .value_or(0U);
    for (std::size_t layer = 0U; layer < 3U;
         ++layer) {
        input.sources[layer] =
            invisible_places::timing::
                InspectTimingColouriseHistogramSource(
                    runtimeState
                        ->sessions[indices[layer]]
                        .sourcePath);
    }
    const auto fingerprint =
        invisible_places::timing::
            BuildTimingColouriseHistogramFingerprint(
                input);
    const auto root =
        !scene->sourceFolder.empty()
            ? scene->sourceFolder
            : std::filesystem::path{
                  runtimeState->persistence
                      .projectFilePath}
                  .parent_path();
    return std::pair{
        fingerprint,
        invisible_places::timing::
            TimingColouriseHistogramCachePath(
                root,
                fingerprint)};
}

std::optional<std::pair<std::string, std::filesystem::path>>
TimingColouriseHistogramIdentity(
    PreviewRuntimeState* runtimeState,
    const invisible_places::timing::
        TimingColouriseFieldSelector& selector) {
    const auto indices =
        ActiveTimingColouriseSessionIndices(runtimeState);
    auto* scene = ActiveWaterSurfaceScene(runtimeState);
    if (!indices.has_value() || scene == nullptr) {
        return std::nullopt;
    }
    return TimingColouriseHistogramIdentityForScene(
        runtimeState,
        scene,
        indices.value(),
        selector);
}

std::optional<TimingColouriseHistogramBatch>
BuildTimingColouriseHistogramBatch(
    PreviewRuntimeState* runtimeState,
    const ScenePointCloudRuntime* scene,
    const std::optional<
        invisible_places::timing::TimingColouriseFieldSelector>&
        prioritySelector = std::nullopt) {
    const auto indices =
        TimingColouriseSessionIndicesForScene(
            runtimeState,
            scene);
    if (runtimeState == nullptr || scene == nullptr ||
        !indices.has_value()) {
        return std::nullopt;
    }

    TimingColouriseHistogramBatch batch;
    std::array<
        invisible_places::timing::
            TimingColouriseLayerFieldSet,
        invisible_places::timing::
            kTimingColouriseAuthoredLayerCount>
        fieldSets;
    for (std::size_t layer = 0U;
         layer < batch.resident.size();
         ++layer) {
        const auto& session =
            runtimeState->sessions[
                indices.value()[layer]];
        if (!session.cpuResident ||
            session.offlinePointCloud == nullptr) {
            return std::nullopt;
        }
        batch.resident[layer] =
            session.offlinePointCloud;
        batch.paths[layer] = session.sourcePath;
        fieldSets[layer] =
            invisible_places::timing::
                TimingColouriseLayerFieldSetFromCloud(
                    *session.offlinePointCloud);
    }

    std::vector<
        invisible_places::timing::
            TimingColouriseFieldSelector>
        selectors;
    if (prioritySelector.has_value()) {
        selectors.push_back(prioritySelector.value());
    }
    const auto catalog =
        invisible_places::timing::
            BuildTimingColouriseFieldCatalog(fieldSets);
    for (const auto& family : catalog) {
        for (const auto& variant : family.variants) {
            if (std::find(
                    selectors.begin(),
                    selectors.end(),
                    variant.selector) ==
                selectors.end()) {
                selectors.push_back(variant.selector);
            }
        }
    }
    if (selectors.empty()) {
        return std::nullopt;
    }

    invisible_places::timing::
        TimingColouriseHistogramFingerprintInput bundleInput;
    bundleInput.sceneGroupName = scene->sceneGroupName;
    bundleInput.selector.source =
        invisible_places::timing::
            TimingColouriseFieldSource::NormalX;
    bundleInput.displaySpacingMicrometres =
        scene->committedDisplaySpacingMicrometres
            .value_or(0U);
    for (std::size_t layer = 0U;
         layer < batch.paths.size();
         ++layer) {
        bundleInput.sources[layer] =
            invisible_places::timing::
                InspectTimingColouriseHistogramSource(
                    batch.paths[layer]);
    }
    batch.id =
        invisible_places::timing::
            BuildTimingColouriseHistogramFingerprint(
                bundleInput);
    batch.tasks.reserve(selectors.size());
    for (const auto& selector : selectors) {
        const auto identity =
            TimingColouriseHistogramIdentityForScene(
                runtimeState,
                scene,
                indices.value(),
                selector);
        if (!identity.has_value()) {
            continue;
        }
        batch.tasks.push_back({
            .selector = selector,
            .signature = identity->first,
            .cachePath = identity->second,
        });
    }
    return batch.tasks.empty()
               ? std::nullopt
               : std::optional{
                     std::move(batch)};
}

void StartTimingColouriseHistogramBatch(
    PreviewRuntimeState* runtimeState,
    TimingColouriseHistogramBatch batch) {
    if (runtimeState == nullptr ||
        batch.tasks.empty()) {
        return;
    }
    auto shared = std::make_shared<
        TimingColouriseHistogramJobShared>();
    for (const auto& task : batch.tasks) {
        shared->pendingSignatures.insert(
            task.signature);
    }

    auto& job =
        runtimeState->timingColouriseHistogram;
    job.shared = shared;
    job.activeBatchId = batch.id;
    job.worker = std::jthread{
        [shared,
         batch = std::move(batch)](
            std::stop_token stopToken) mutable {
            const auto publish =
                [&](TimingColouriseHistogramJobResult result) {
                    std::scoped_lock lock(shared->mutex);
                    shared->pendingSignatures.erase(
                        result.signature);
                    if (shared->prioritySignature ==
                        result.signature) {
                        shared->prioritySignature.clear();
                    }
                    shared->results.push_back(
                        std::move(result));
                };
            const auto finish = [&]() {
                std::scoped_lock lock(shared->mutex);
                shared->pendingSignatures.clear();
                shared->completed = true;
            };
            const auto makeOutput =
                [](const TimingColouriseHistogramTask& task,
                   invisible_places::timing::
                       TimingColouriseHistogram histogram) {
                    auto displayBins = invisible_places::timing::
                        BuildTimingColouriseHistogramDisplayBins(
                            histogram);
                    return TimingColouriseHistogram{
                        .signature = task.signature,
                        .selector = task.selector,
                        .data = std::move(histogram),
                        .displayBins = std::move(displayBins),
                    };
                };

            std::vector<TimingColouriseHistogramTask>
                missing;
            missing.reserve(batch.tasks.size());
            for (const auto& task : batch.tasks) {
                if (stopToken.stop_requested()) {
                    finish();
                    return;
                }
                std::string cacheError;
                auto cached =
                    invisible_places::timing::
                        LoadTimingColouriseHistogramCache(
                            task.cachePath,
                            task.signature,
                            &cacheError);
                if (cached.has_value()) {
                    TimingColouriseHistogramJobResult result;
                    result.signature = task.signature;
                    result.histogram =
                        makeOutput(
                            task,
                            std::move(cached.value()));
                    publish(std::move(result));
                } else {
                    missing.push_back(task);
                }
            }

            invisible_places::timing::
                TimingColouriseHistogramSourceBundle sources{};
            for (std::size_t layer = 0U;
                 layer < sources.size();
                 ++layer) {
                sources[layer] = {
                    .residentCloud =
                        batch.resident[layer].get(),
                    .sourcePath = batch.paths[layer],
                };
            }
            for (std::size_t taskIndex = 0U;
                 taskIndex < missing.size();
                 ++taskIndex) {
                if (stopToken.stop_requested()) {
                    finish();
                    return;
                }
                {
                    std::scoped_lock lock(shared->mutex);
                    if (!shared->prioritySignature.empty()) {
                        const auto priority =
                            std::find_if(
                                missing.begin() +
                                    static_cast<
                                        std::ptrdiff_t>(
                                        taskIndex),
                                missing.end(),
                                [&](const auto& task) {
                                    return task.signature ==
                                           shared
                                               ->prioritySignature;
                                });
                        if (priority != missing.end()) {
                            std::iter_swap(
                                missing.begin() +
                                    static_cast<
                                        std::ptrdiff_t>(
                                        taskIndex),
                                priority);
                        }
                    }
                }
                const auto& task = missing[taskIndex];
                auto computed =
                    invisible_places::timing::
                        ComputeTimingColouriseHistogramFromSources(
                            sources,
                            task.selector,
                            stopToken);
                if (computed.cancelled) {
                    finish();
                    return;
                }

                TimingColouriseHistogramJobResult result;
                result.signature = task.signature;
                if (computed.success) {
                    (void)invisible_places::timing::
                        SaveTimingColouriseHistogramCache(
                            task.cachePath,
                            task.signature,
                            computed.histogram);
                    result.histogram =
                        makeOutput(
                            task,
                            std::move(computed.histogram));
                } else {
                    result.errorMessage =
                        computed.errorMessage;
                }
                publish(std::move(result));
            }
            finish();
        }};
}

void PollTimingColouriseHistogram(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& job =
        runtimeState->timingColouriseHistogram;
    if (job.shared == nullptr) {
        return;
    }
    std::deque<TimingColouriseHistogramJobResult>
        results;
    bool completed = false;
    {
        std::scoped_lock lock(job.shared->mutex);
        completed = job.shared->completed;
        results.swap(job.shared->results);
    }
    for (auto& result : results) {
        if (result.histogram.has_value()) {
            job.cache.insert_or_assign(
                result.signature,
                std::move(result.histogram.value()));
            job.failures.erase(result.signature);
            if (job.failedSignature ==
                result.signature) {
                job.failedSignature.clear();
                job.failedErrorMessage.clear();
            }
        } else if (!result.errorMessage.empty()) {
            job.failures[result.signature] =
                result.errorMessage;
            if (job.requestedSignature ==
                result.signature) {
                job.failedSignature =
                    result.signature;
                job.failedErrorMessage =
                    result.errorMessage;
                runtimeState->statusMessage =
                    "Colourise histogram unavailable: " +
                    result.errorMessage;
            }
        }
    }
    if (!completed) {
        return;
    }
    if (job.worker.joinable()) {
        // The worker has reported completion, so this retires only an
        // already-finished thread and never joins an active point scan.
        job.worker = std::jthread{};
    }
    job.shared.reset();
    job.activeBatchId.clear();
    if (job.pendingBatch.has_value()) {
        auto pending =
            std::move(job.pendingBatch.value());
        job.pendingBatch.reset();
        StartTimingColouriseHistogramBatch(
            runtimeState,
            std::move(pending));
    }
}

void QueueTimingColouriseHistogramPrewarmForSelector(
    PreviewRuntimeState* runtimeState,
    const ScenePointCloudRuntime& scene,
    const std::optional<
        invisible_places::timing::TimingColouriseFieldSelector>&
        prioritySelector) {
    auto batch =
        BuildTimingColouriseHistogramBatch(
            runtimeState,
            &scene,
            prioritySelector);
    if (!batch.has_value()) {
        return;
    }
    auto& job =
        runtimeState->timingColouriseHistogram;
    if (job.shared != nullptr &&
        job.activeBatchId == batch->id) {
        if (prioritySelector.has_value()) {
            const auto priorityTask =
                std::find_if(
                    batch->tasks.begin(),
                    batch->tasks.end(),
                    [&](const auto& task) {
                        return task.selector ==
                               prioritySelector.value();
                    });
            if (priorityTask != batch->tasks.end()) {
                std::scoped_lock lock(
                    job.shared->mutex);
                if (job.shared->pendingSignatures.contains(
                        priorityTask->signature)) {
                    job.shared->prioritySignature =
                        priorityTask->signature;
                } else if (!job.cache.contains(
                               priorityTask->signature) &&
                           !job.failures.contains(
                               priorityTask->signature)) {
                    job.pendingBatch =
                        std::move(batch.value());
                }
            }
        }
        return;
    }
    if (job.worker.joinable()) {
        job.worker.request_stop();
        job.pendingBatch =
            std::move(batch.value());
        return;
    }
    StartTimingColouriseHistogramBatch(
        runtimeState,
        std::move(batch.value()));
}

void QueueTimingColouriseHistogramPrewarm(
    PreviewRuntimeState* runtimeState,
    const ScenePointCloudRuntime& scene) {
    if (runtimeState == nullptr) {
        return;
    }
    PollTimingColouriseHistogram(runtimeState);
    QueueTimingColouriseHistogramPrewarmForSelector(
        runtimeState,
        scene,
        std::nullopt);
}

const TimingColouriseHistogram* EnsureTimingColouriseHistogram(
    PreviewRuntimeState* runtimeState,
    const invisible_places::timing::
        TimingColouriseFieldSelector& selector) {
    if (runtimeState == nullptr) {
        return nullptr;
    }
    PollTimingColouriseHistogram(runtimeState);
    const auto identity =
        TimingColouriseHistogramIdentity(
            runtimeState,
            selector);
    if (!identity.has_value()) {
        return nullptr;
    }
    auto& job =
        runtimeState->timingColouriseHistogram;
    const auto cached =
        job.cache.find(identity->first);
    if (cached != job.cache.end()) {
        return &cached->second;
    }
    job.requestedSignature = identity->first;
    if (job.failedSignature !=
        identity->first) {
        job.failedSignature.clear();
        job.failedErrorMessage.clear();
    }
    if (const auto failed =
            job.failures.find(identity->first);
        failed != job.failures.end()) {
        job.failedSignature = identity->first;
        job.failedErrorMessage = failed->second;
        return nullptr;
    }
    if (job.shared != nullptr) {
        std::scoped_lock lock(job.shared->mutex);
        if (job.shared->pendingSignatures.contains(
                identity->first)) {
            job.shared->prioritySignature =
                identity->first;
            return nullptr;
        }
    }
    if (job.pendingBatch.has_value() &&
        std::any_of(
            job.pendingBatch->tasks.begin(),
            job.pendingBatch->tasks.end(),
            [&](const auto& task) {
                return task.signature ==
                       identity->first;
            })) {
        return nullptr;
    }
    const auto* scene =
        ActiveWaterSurfaceScene(runtimeState);
    if (scene == nullptr) {
        return nullptr;
    }
    QueueTimingColouriseHistogramPrewarmForSelector(
        runtimeState,
        *scene,
        selector);
    if (job.shared != nullptr) {
        std::scoped_lock lock(job.shared->mutex);
        if (job.shared->pendingSignatures.contains(
                identity->first)) {
            job.shared->prioritySignature =
                identity->first;
        }
    }
    return nullptr;
}

const char* TimingColouriseBoundsParameterLabel(
    invisible_places::timing::TimingColouriseBoundsParameter parameter) {
    using invisible_places::timing::TimingColouriseBoundsParameter;
    switch (parameter) {
        case TimingColouriseBoundsParameter::Lower:
            return "Lower";
        case TimingColouriseBoundsParameter::Upper:
            return "Upper";
        case TimingColouriseBoundsParameter::Centre:
            return "Centre";
        case TimingColouriseBoundsParameter::Spread:
            return "Spacing";
        case TimingColouriseBoundsParameter::EdgeFade:
            return "Fade";
    }
    return "Bound";
}

bool TimingColouriseBoundsParameterHasKeys(
    const invisible_places::timing::TimingColouriseEffect& effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter) {
    return std::any_of(
        effect.boundsParameterKeys.begin(),
        effect.boundsParameterKeys.end(),
        [&](const auto& key) {
            return key.parameter == parameter;
        });
}

bool TimingColouriseBoundsParameterEditableAt(
    invisible_places::timing::TimingColouriseEffect* effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter,
    float /*position*/) {
    if (effect == nullptr ||
        !invisible_places::timing::
            TimingColouriseBoundsParameterIsAllowed(
                effect->boundsKeyMode,
                parameter)) {
        return false;
    }
    return true;
}

void SetTimingColouriseBaseBoundsParameter(
    invisible_places::timing::TimingColouriseEffect* effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter,
    float value) {
    using invisible_places::timing::TimingColouriseBoundsKeyMode;
    using invisible_places::timing::TimingColouriseBoundsParameter;
    if (effect == nullptr || !std::isfinite(value)) {
        return;
    }
    auto bounds =
        invisible_places::timing::SanitizeTimingColouriseBounds(
            effect->baseBounds);
    const float spread = bounds.upper - bounds.lower;
    const float centre = std::midpoint(bounds.lower, bounds.upper);
    switch (parameter) {
        case TimingColouriseBoundsParameter::Lower:
            if (effect->boundsKeyMode ==
                TimingColouriseBoundsKeyMode::LowerSpread) {
                bounds.lower = value;
                bounds.upper = value + spread;
            } else {
                bounds.lower = std::min(value, bounds.upper);
            }
            break;
        case TimingColouriseBoundsParameter::Upper:
            if (effect->boundsKeyMode ==
                TimingColouriseBoundsKeyMode::UpperSpread) {
                bounds.upper = value;
                bounds.lower = value - spread;
            } else {
                bounds.upper = std::max(value, bounds.lower);
            }
            break;
        case TimingColouriseBoundsParameter::Centre:
            bounds.lower = value - spread * 0.5F;
            bounds.upper = value + spread * 0.5F;
            break;
        case TimingColouriseBoundsParameter::Spread: {
            const float sanitizedSpread = std::max(0.0F, value);
            switch (effect->boundsKeyMode) {
                case TimingColouriseBoundsKeyMode::LowerSpread:
                    bounds.upper =
                        bounds.lower + sanitizedSpread;
                    break;
                case TimingColouriseBoundsKeyMode::UpperSpread:
                    bounds.lower =
                        bounds.upper - sanitizedSpread;
                    break;
                case TimingColouriseBoundsKeyMode::CentreSpread:
                case TimingColouriseBoundsKeyMode::LowerUpper:
                default:
                    bounds.lower =
                        centre - sanitizedSpread * 0.5F;
                    bounds.upper =
                        centre + sanitizedSpread * 0.5F;
                    break;
            }
            break;
        }
        case TimingColouriseBoundsParameter::EdgeFade:
            bounds.edgeFade =
                std::clamp(value, -0.5F, 0.5F);
            break;
    }
    effect->baseBounds =
        invisible_places::timing::SanitizeTimingColouriseBounds(
            bounds);
}

bool SetTimingColouriseBoundsParameterAt(
    std::vector<invisible_places::timing::TimingScalarBoundsStore>* stores,
    invisible_places::timing::TimingColouriseEffect* effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter,
    float position,
    float value) {
    using invisible_places::timing::TimingColouriseBoundsParameter;
    if (!TimingColouriseBoundsParameterEditableAt(
            effect,
            parameter,
            position) ||
        !std::isfinite(value)) {
        return false;
    }
    const auto evaluated =
        invisible_places::timing::EvaluateTimingColouriseBounds(
            *effect,
            position);
    switch (parameter) {
        case TimingColouriseBoundsParameter::Lower:
            if (effect->boundsKeyMode ==
                invisible_places::timing::
                    TimingColouriseBoundsKeyMode::LowerUpper) {
                value = std::min(value, evaluated.upper);
            }
            break;
        case TimingColouriseBoundsParameter::Upper:
            if (effect->boundsKeyMode ==
                invisible_places::timing::
                    TimingColouriseBoundsKeyMode::LowerUpper) {
                value = std::max(value, evaluated.lower);
            }
            break;
        case TimingColouriseBoundsParameter::Spread:
            value = std::max(0.0F, value);
            break;
        case TimingColouriseBoundsParameter::EdgeFade:
            value = std::clamp(value, -0.5F, 0.5F);
            break;
        case TimingColouriseBoundsParameter::Centre:
            break;
    }
    const bool armed =
        !effect->boundsKeys.empty() ||
        TimingColouriseBoundsParameterHasKeys(
            *effect,
            parameter);
    if (armed) {
        auto interpolation = TimingScalarTrackInterpolationAt(
            effect->boundsParameterKeys,
            [&](const auto& key) {
                return key.parameter == parameter;
            },
            position);
        if (!TimingColouriseBoundsParameterHasKeys(
                *effect,
                parameter) &&
            !effect->boundsKeys.empty()) {
            interpolation = TimingScalarTrackInterpolationAt(
                effect->boundsKeys,
                [](const auto&) { return true; },
                position);
        }
        if (!invisible_places::timing::
                AddOrUpdateTimingColouriseBoundsParameterKey(
                    effect,
                    parameter,
                    position,
                    value,
                    interpolation)) {
            return false;
        }
        // A keyed bounds is a local edit: it detaches this feature from
        // the shared Global bounds without republishing them.
        effect->boundsEdited = true;
    } else {
        SetTimingColouriseBaseBoundsParameter(
            effect,
            parameter,
            value);
        invisible_places::timing::RecordTimingScalarBoundsEdit(
            stores,
            effect);
    }
    return true;
}

bool TimingColouriseHistogramHandleEditableAt(
    invisible_places::timing::TimingColouriseEffect* effect,
    TimingColouriseHistogramHandle handle,
    float position) {
    if (effect == nullptr ||
        handle == TimingColouriseHistogramHandle::None) {
        return false;
    }
    if (handle == TimingColouriseHistogramHandle::LowerFade ||
        handle == TimingColouriseHistogramHandle::UpperFade) {
        return TimingColouriseBoundsParameterEditableAt(
            effect,
            invisible_places::timing::
                TimingColouriseBoundsParameter::EdgeFade,
            position);
    }
    const auto parameters = invisible_places::timing::
        TimingColouriseBoundsParametersForMode(
            effect->boundsKeyMode);
    return std::all_of(
        parameters.begin(),
        parameters.end(),
        [&](const auto parameter) {
            return TimingColouriseBoundsParameterEditableAt(
                effect,
                parameter,
                position);
        });
}

float TimingColouriseHistogramHandleValue(
    const invisible_places::timing::TimingColouriseBounds& bounds,
    TimingColouriseHistogramHandle handle) {
    const float centre =
        std::midpoint(bounds.lower, bounds.upper);
    const float span = bounds.upper - bounds.lower;
    switch (handle) {
        case TimingColouriseHistogramHandle::Lower:
        case TimingColouriseHistogramHandle::LowerSpread:
            return bounds.lower;
        case TimingColouriseHistogramHandle::Upper:
        case TimingColouriseHistogramHandle::UpperSpread:
            return bounds.upper;
        case TimingColouriseHistogramHandle::LowerFade:
            return bounds.lower + span * bounds.edgeFade;
        case TimingColouriseHistogramHandle::UpperFade:
            return bounds.upper - span * bounds.edgeFade;
        case TimingColouriseHistogramHandle::Centre:
        case TimingColouriseHistogramHandle::None:
        default:
            return centre;
    }
}

bool ApplyTimingColouriseHistogramBounds(
    std::vector<invisible_places::timing::TimingScalarBoundsStore>* stores,
    invisible_places::timing::TimingColouriseEffect* effect,
    TimingColouriseHistogramHandle handle,
    float position,
    float targetValue,
    float rangeMinimum,
    float rangeMaximum) {
    if (!TimingColouriseHistogramHandleEditableAt(
            effect,
            handle,
            position) ||
        !std::isfinite(rangeMinimum) ||
        !std::isfinite(rangeMaximum) ||
        rangeMaximum <= rangeMinimum) {
        return false;
    }
    const auto bounds =
        invisible_places::timing::EvaluateTimingColouriseBounds(
            *effect,
            position);
    const float span = bounds.upper - bounds.lower;
    if (handle == TimingColouriseHistogramHandle::LowerFade ||
        handle == TimingColouriseHistogramHandle::UpperFade) {
        if (span <= std::numeric_limits<float>::epsilon()) {
            return false;
        }
        const float fade =
            handle == TimingColouriseHistogramHandle::LowerFade
                ? (targetValue - bounds.lower) / span
                : (bounds.upper - targetValue) / span;
        return SetTimingColouriseBoundsParameterAt(
            stores,
            effect,
            invisible_places::timing::
                TimingColouriseBoundsParameter::EdgeFade,
            position,
            std::clamp(fade, -0.5F, 0.5F));
    }

    auto desired = bounds;
    targetValue = std::clamp(
        targetValue,
        rangeMinimum,
        rangeMaximum);
    const float centre =
        std::midpoint(bounds.lower, bounds.upper);
    switch (handle) {
        case TimingColouriseHistogramHandle::Lower:
            desired.lower = std::min(targetValue, bounds.upper);
            break;
        case TimingColouriseHistogramHandle::Upper:
            desired.upper = std::max(targetValue, bounds.lower);
            break;
        case TimingColouriseHistogramHandle::Centre: {
            const float maximumShiftRight =
                rangeMaximum - bounds.upper;
            const float maximumShiftLeft =
                rangeMinimum - bounds.lower;
            const float requestedShift =
                targetValue - centre;
            const float shift =
                maximumShiftLeft <= maximumShiftRight
                    ? std::clamp(
                          requestedShift,
                          maximumShiftLeft,
                          maximumShiftRight)
                    : requestedShift;
            desired.lower += shift;
            desired.upper += shift;
            break;
        }
        case TimingColouriseHistogramHandle::LowerSpread:
        case TimingColouriseHistogramHandle::UpperSpread: {
            const float maximumHalfSpan = std::max(
                0.0F,
                std::min(
                    centre - rangeMinimum,
                    rangeMaximum - centre));
            const float halfSpan = std::clamp(
                std::abs(targetValue - centre),
                0.0F,
                maximumHalfSpan);
            desired.lower = centre - halfSpan;
            desired.upper = centre + halfSpan;
            break;
        }
        case TimingColouriseHistogramHandle::LowerFade:
        case TimingColouriseHistogramHandle::UpperFade:
        case TimingColouriseHistogramHandle::None:
            return false;
    }

    const auto parameters = invisible_places::timing::
        TimingColouriseBoundsParametersForMode(
            effect->boundsKeyMode);
    bool changed = false;
    for (const auto parameter : parameters) {
        const float currentValue = invisible_places::timing::
            TimingColouriseBoundsParameterValue(
                bounds,
                parameter);
        const float desiredValue = invisible_places::timing::
            TimingColouriseBoundsParameterValue(
                desired,
                parameter);
        if (std::abs(currentValue - desiredValue) >
            std::numeric_limits<float>::epsilon()) {
            changed |= SetTimingColouriseBoundsParameterAt(
                stores,
                effect,
                parameter,
                position,
                desiredValue);
        }
    }
    return changed;
}

void DrawTimingColouriseHistogram(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect,
    const TimingColouriseHistogram* histogram,
    invisible_places::timing::TimingColouriseHistogramAxisMode
        requestedAxisMode) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    if (histogram == nullptr) {
        const auto& job =
            runtimeState->timingColouriseHistogram;
        if (!job.failedErrorMessage.empty()) {
            ImGui::TextWrapped(
                "Histogram unavailable: %s",
                job.failedErrorMessage.c_str());
        } else {
            ImGui::TextDisabled(
                "Computing high-resolution SAND / ROCK / VEG histogram...");
        }
        return;
    }
    const float position = std::clamp(
        runtimeState->animationPanel.scrubAmount,
        0.0F,
        1.0F);
    const ImVec2 size{
        std::max(160.0F, ImGui::GetContentRegionAvail().x),
        92.0F};
    ImGui::InvisibleButton(
        "##TimingColouriseHistogram",
        size,
        ImGuiButtonFlags_MouseButtonLeft);
    const auto minimum = ImGui::GetItemRectMin();
    const auto maximum = ImGui::GetItemRectMax();
    auto* drawList = ImGui::GetWindowDrawList();
    const auto& histogramData = histogram->data;
    const auto& histogramDisplayBins =
        histogram->displayBins.size() ==
                histogramData.bins.size()
            ? histogram->displayBins
            : histogramData.bins;
    const auto axis =
        invisible_places::timing::
            BuildTimingColouriseHistogramAxis(
                histogramData,
                requestedAxisMode);
    const float width = maximum.x - minimum.x;
    const float height = maximum.y - minimum.y;
    // The persistent histogram is deliberately much finer than the graph.
    // Merge only source bins that occupy less than one screen pixel. A bin
    // widened by Distribution Spread is therefore drawn independently, while
    // the long low-density tails remain inexpensive to display.
    constexpr float kMinimumDisplayBucketWidth = 1.0F;
    const auto forEachDisplayBucket =
        [&](auto&& visit) {
            std::uint64_t displayBucketTotal = 0U;
            std::size_t displayBucketBinCount = 0U;
            float displayBucketX0 = minimum.x;
            const auto flushDisplayBucket =
                [&](float requestedX1) {
                    if (displayBucketBinCount == 0U) {
                        return;
                    }
                    const auto averageCount =
                        displayBucketTotal /
                        static_cast<std::uint64_t>(
                            displayBucketBinCount);
                    const float x1 = std::min(
                        maximum.x,
                        std::max(
                            requestedX1,
                            displayBucketX0 + 1.0F));
                    visit(
                        displayBucketX0,
                        x1,
                        averageCount);
                    displayBucketTotal = 0U;
                    displayBucketBinCount = 0U;
                    displayBucketX0 = requestedX1;
                };
            float binX0 = minimum.x;
            for (std::size_t index = 0U;
                 index < histogramData.bins.size();
                 ++index) {
                const float rawX1 = std::lerp(
                    histogramData.minimum,
                    histogramData.maximum,
                    static_cast<float>(index + 1U) /
                        static_cast<float>(
                            histogramData.bins.size()));
                const float binX1 =
                    minimum.x + width * axis.RawToUnit(rawX1);
                const float sourceBinWidth = binX1 - binX0;
                if (displayBucketBinCount > 0U &&
                    sourceBinWidth >=
                        kMinimumDisplayBucketWidth) {
                    flushDisplayBucket(binX0);
                }
                if (displayBucketBinCount == 0U) {
                    displayBucketX0 = binX0;
                }
                displayBucketTotal +=
                    histogramDisplayBins[index];
                ++displayBucketBinCount;
                const bool bucketIsVisible =
                    binX1 - displayBucketX0 >=
                    kMinimumDisplayBucketWidth;
                if (sourceBinWidth >=
                        kMinimumDisplayBucketWidth ||
                    bucketIsVisible ||
                    index + 1U ==
                        histogramData.bins.size()) {
                    flushDisplayBucket(binX1);
                }
                binX0 = binX1;
            }
        };

    // Normalize after the high-resolution bins have been merged for this
    // horizontal axis. Normalizing against an unmerged one-bin spike would
    // then averaging that spike into a pixel bucket, flattening every visible
    // bar. Each axis keeps its own displayed minimum at zero and maximum at
    // full graph height; Distribution Spread still changes only x spacing.
    std::uint64_t minimumDisplayCount =
        std::numeric_limits<std::uint64_t>::max();
    std::uint64_t maximumDisplayCount = 0U;
    bool hasDisplayBuckets = false;
    forEachDisplayBucket(
        [&](float, float, std::uint64_t averageCount) {
            minimumDisplayCount =
                std::min(minimumDisplayCount, averageCount);
            maximumDisplayCount =
                std::max(maximumDisplayCount, averageCount);
            hasDisplayBuckets = true;
        });
    if (!hasDisplayBuckets) {
        minimumDisplayCount = 0U;
    }
    forEachDisplayBucket(
        [&](float x0, float x1, std::uint64_t averageCount) {
            const float amount =
                invisible_places::timing::
                    TimingColouriseHistogramDisplayHeight(
                        averageCount,
                        minimumDisplayCount,
                        maximumDisplayCount);
            drawList->AddRectFilled(
                ImVec2{x0, maximum.y - amount * height},
                ImVec2{x1, maximum.y},
                IM_COL32(118, 156, 184, 210));
        });
    drawList->AddRect(
        minimum,
        maximum,
        ImGui::GetColorU32(ImGuiCol_Border));
    if (axis.UsesDistributionSpread() &&
        histogramData.minimum < 0.0F &&
        histogramData.maximum > 0.0F) {
        const float zeroX =
            minimum.x + width * axis.zeroUnit;
        drawList->AddLine(
            ImVec2{zeroX, minimum.y},
            ImVec2{zeroX, maximum.y},
            ImGui::GetColorU32(ImGuiCol_TextDisabled),
            1.0F);
    }
    const auto evaluated =
        invisible_places::timing::
            EvaluateTimingColouriseBounds(
                *effect,
                position);
    const auto xForRaw = [&](float value) {
        return minimum.x + width * axis.RawToUnit(value);
    };
    const ImU32 lowerColour =
        IM_COL32(255, 190, 74, 255);
    const ImU32 upperColour =
        IM_COL32(242, 104, 96, 255);
    const ImU32 fadeColour =
        IM_COL32(116, 190, 120, 255);
    const auto drawBound = [&](float value, ImU32 colour) {
        const float x = xForRaw(value);
        drawList->AddLine(
            ImVec2{x, minimum.y},
            ImVec2{x, maximum.y},
            colour,
            2.0F);
        drawList->AddTriangleFilled(
            ImVec2{x - 5.0F, minimum.y},
            ImVec2{x + 5.0F, minimum.y},
            ImVec2{x, minimum.y + 7.0F},
            colour);
        return x;
    };
    const float lowerX =
        drawBound(evaluated.lower, lowerColour);
    const float upperX =
        drawBound(evaluated.upper, upperColour);
    const float rawCentre =
        std::midpoint(evaluated.lower, evaluated.upper);
    const float centreX = xForRaw(rawCentre);
    const float railY =
        minimum.y + std::clamp(height * 0.56F, 24.0F, height - 12.0F);
    const float fadeY = maximum.y - 8.0F;
    const float rawSpan = evaluated.upper - evaluated.lower;
    const float lowerFadeValue =
        evaluated.lower + rawSpan * evaluated.edgeFade;
    const float upperFadeValue =
        evaluated.upper - rawSpan * evaluated.edgeFade;
    const float lowerFadeX = xForRaw(lowerFadeValue);
    const float upperFadeX = xForRaw(upperFadeValue);
    const bool histogramRangeEditable =
        std::isfinite(histogramData.minimum) &&
        std::isfinite(histogramData.maximum) &&
        histogramData.maximum > histogramData.minimum;
    const auto handleInsideHistogramRange =
        [&](TimingColouriseHistogramHandle handle) {
            // RawToUnit deliberately pins out-of-range values to an edge.
            // Keep those visible handles interactive so they can be pulled
            // back into range, and so signed fade handles can cross outward.
            return histogramRangeEditable &&
                   handle != TimingColouriseHistogramHandle::None;
        };
    const bool centreEditable =
        handleInsideHistogramRange(
            TimingColouriseHistogramHandle::Centre) &&
        TimingColouriseHistogramHandleEditableAt(
            effect,
            TimingColouriseHistogramHandle::Centre,
            position);
    drawList->AddLine(
        ImVec2{lowerX, railY},
        ImVec2{upperX, railY},
        centreEditable
            ? ImGui::GetColorU32(ImGuiCol_SliderGrab)
            : ImGui::GetColorU32(ImGuiCol_TextDisabled),
        2.0F);
    const auto drawSpreadHandle =
        [&](float x, ImU32 colour) {
            drawList->AddCircleFilled(
                ImVec2{x, railY},
                4.5F,
                colour);
            drawList->AddCircle(
                ImVec2{x, railY},
                6.0F,
                ImGui::GetColorU32(ImGuiCol_Border),
                0,
                1.0F);
        };
    drawSpreadHandle(lowerX, lowerColour);
    drawSpreadHandle(upperX, upperColour);
    drawList->AddCircleFilled(
        ImVec2{centreX, railY},
        5.0F,
        centreEditable
            ? ImGui::GetColorU32(ImGuiCol_SliderGrabActive)
            : ImGui::GetColorU32(ImGuiCol_TextDisabled));
    drawList->AddCircle(
        ImVec2{centreX, railY},
        6.5F,
        ImGui::GetColorU32(ImGuiCol_Border),
        0,
        1.0F);

    const auto drawFadeHandle =
        [&](float boundX, float handleX) {
            drawList->AddLine(
                ImVec2{boundX, fadeY},
                ImVec2{handleX, fadeY},
                fadeColour,
                1.5F);
            drawList->AddLine(
                ImVec2{handleX, fadeY - 4.0F},
                ImVec2{handleX, fadeY + 4.0F},
                fadeColour,
                2.0F);
        };
    drawFadeHandle(lowerX, lowerFadeX);
    drawFadeHandle(upperX, upperFadeX);

    const std::string helpMarkText =
        std::string{
            "Bounds histogram\n"
            "Drag the upper part of either vertical line to move that bound.\n"
            "Drag the centre rail to translate the interval. Drag either rail circle to resize symmetrically.\n"
            "The sideways T handles set signed Fade: inward is positive, outward is negative.\n"} +
        (axis.UsesDistributionSpread()
             ? "Distribution Spread uses the cached high-resolution distribution for graph spacing and drag sensitivity; the vertical density shape stays in raw-value space and authored values remain raw."
             : "Histogram heights show the finite full-scene scalar distribution using a fixed raw-value density window.");
    const bool watermarkHovered = DrawTimingCornerHelpMark(
        drawList,
        minimum,
        maximum,
        helpMarkText.c_str());

    const auto mouse = ImGui::GetIO().MousePos;
    const float mouseUnit =
        (mouse.x - minimum.x) /
            std::max(1.0F, width);
    const float mouseValue =
        mouseUnit < 0.0F
            ? histogramData.minimum +
                  mouseUnit *
                      (histogramData.maximum - histogramData.minimum)
        : mouseUnit > 1.0F
            ? histogramData.maximum +
                  (mouseUnit - 1.0F) *
                      (histogramData.maximum - histogramData.minimum)
            : axis.UnitToRaw(mouseUnit);
    TimingColouriseHistogramHandle hoveredHandle =
        TimingColouriseHistogramHandle::None;
    if (ImGui::IsItemHovered() && !watermarkHovered) {
        const float lowerFadeDistance = std::hypot(
            mouse.x - lowerFadeX,
            mouse.y - fadeY);
        const float upperFadeDistance = std::hypot(
            mouse.x - upperFadeX,
            mouse.y - fadeY);
        const float centreDistance = std::hypot(
            mouse.x - centreX,
            mouse.y - railY);
        const float lowerSpreadDistance = std::hypot(
            mouse.x - lowerX,
            mouse.y - railY);
        const float upperSpreadDistance = std::hypot(
            mouse.x - upperX,
            mouse.y - railY);
        if (std::min(lowerFadeDistance, upperFadeDistance) <= 9.0F) {
            hoveredHandle =
                lowerFadeDistance <= upperFadeDistance
                    ? TimingColouriseHistogramHandle::LowerFade
                    : TimingColouriseHistogramHandle::UpperFade;
        } else if (centreDistance <= 10.0F &&
            handleInsideHistogramRange(
                TimingColouriseHistogramHandle::Centre)) {
            hoveredHandle =
                TimingColouriseHistogramHandle::Centre;
        } else if (
            std::min(
                lowerSpreadDistance,
                upperSpreadDistance) <= 9.0F) {
            hoveredHandle =
                lowerSpreadDistance <= upperSpreadDistance
                    ? TimingColouriseHistogramHandle::LowerSpread
                    : TimingColouriseHistogramHandle::UpperSpread;
        } else if (mouse.y < railY - 9.0F &&
                   std::min(
                       std::abs(mouse.x - lowerX),
                       std::abs(mouse.x - upperX)) <= 9.0F) {
            hoveredHandle =
                std::abs(mouse.x - lowerX) <=
                        std::abs(mouse.x - upperX)
                    ? TimingColouriseHistogramHandle::Lower
                    : TimingColouriseHistogramHandle::Upper;
        } else if (
            std::abs(mouse.y - railY) <= 12.0F &&
            mouse.x >= std::min(lowerX, upperX) &&
            mouse.x <= std::max(lowerX, upperX)) {
            hoveredHandle =
                TimingColouriseHistogramHandle::Centre;
        }
    }
    if (hoveredHandle != TimingColouriseHistogramHandle::None &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left) &&
        handleInsideHistogramRange(hoveredHandle) &&
        TimingColouriseHistogramHandleEditableAt(
            effect,
            hoveredHandle,
            position)) {
        runtimeState->timingsPanel.activeHistogramHandle =
            hoveredHandle;
        runtimeState->timingsPanel.histogramHandleGrabOffset =
            mouseValue -
            TimingColouriseHistogramHandleValue(
                evaluated,
                hoveredHandle);
    }
    if (runtimeState->timingsPanel.activeHistogramHandle !=
            TimingColouriseHistogramHandle::None &&
        ImGui::IsItemActive() &&
        ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        if (ApplyTimingColouriseHistogramBounds(
                &runtimeState->water.timingScalarBoundsStores,
                effect,
                runtimeState->timingsPanel
                    .activeHistogramHandle,
                position,
                mouseValue - runtimeState->timingsPanel
                                 .histogramHandleGrabOffset,
                histogramData.minimum,
                histogramData.maximum)) {
            runtimeState->previewRenderStateSignatureValid =
                false;
        }
    }
    if (!ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        runtimeState->timingsPanel.activeHistogramHandle =
            TimingColouriseHistogramHandle::None;
        runtimeState->timingsPanel.histogramHandleGrabOffset =
            0.0F;
    }
    if (hoveredHandle !=
        TimingColouriseHistogramHandle::None) {
        ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);
    }
    const bool spreadAxis =
        axis.UsesDistributionSpread();
    ImGui::TextDisabled(
        "%s",
        spreadAxis
            ? axis.shape ==
                      invisible_places::timing::
                          TimingColouriseHistogramAxisShape::
                              Centred
                  ? "-1"
                  : "0"
            : FormatFixed(
                  histogramData.minimum,
                  5)
                  .c_str());
    ImGui::SameLine();
    const std::string boundsText =
        (spreadAxis ? "raw [" : "[") +
        FormatFixed(evaluated.lower, 4) +
        ", " + FormatFixed(evaluated.upper, 4) +
        "]";
    const float boundsWidth =
        ImGui::CalcTextSize(boundsText.c_str()).x;
    ImGui::SetCursorPosX(
        std::max(
            ImGui::GetCursorPosX(),
            (ImGui::GetWindowContentRegionMax().x -
             boundsWidth) *
                0.5F));
    ImGui::TextDisabled(
        "%s",
        boundsText.c_str());
    ImGui::SameLine();
    const std::string maximumText =
        spreadAxis
            ? "1"
            : FormatFixed(histogramData.maximum, 5);
    ImGui::SetCursorPosX(
        std::max(
            ImGui::GetCursorPosX(),
            ImGui::GetWindowContentRegionMax().x -
                ImGui::CalcTextSize(
                    maximumText.c_str())
                    .x));
    ImGui::TextDisabled(
        "%s",
        maximumText.c_str());
}

void DrawTimingColouriseBoundsParameterTrackButtons(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    ImGui::PushStyleVar(
        ImGuiStyleVar_FramePadding,
        ImVec2{2.0F, 1.0F});
    const float position = std::clamp(
        runtimeState->animationPanel.scrubAmount,
        0.0F,
        1.0F);
    const auto previous =
        invisible_places::timing::
            PreviousTimingColouriseBoundsParameterKeyPosition(
                *effect,
                parameter,
                position);
    const auto next =
        invisible_places::timing::
            NextTimingColouriseBoundsParameterKeyPosition(
                *effect,
                parameter,
                position);
    const auto currentCount =
        invisible_places::timing::
            TimingColouriseBoundsParameterKeyCountAtPosition(
                *effect,
                parameter,
                position);
    const bool allowed = invisible_places::timing::
        TimingColouriseBoundsParameterIsAllowed(
            effect->boundsKeyMode,
            parameter);
    const float evaluatedValue = invisible_places::timing::
        TimingColouriseBoundsParameterValue(
            invisible_places::timing::
                EvaluateTimingColouriseBounds(
                    *effect,
                    position),
            parameter);
    auto interpolation = TimingScalarTrackInterpolationAt(
        effect->boundsParameterKeys,
        [&](const auto& key) { return key.parameter == parameter; },
        position);
    if (!TimingColouriseBoundsParameterHasKeys(
            *effect,
            parameter) &&
        !effect->boundsKeys.empty()) {
        interpolation = TimingScalarTrackInterpolationAt(
            effect->boundsKeys,
            [](const auto&) { return true; },
            position);
    }
    ImGui::BeginDisabled(!allowed);
    if (ImGui::SmallButton("+") &&
        invisible_places::timing::
            AddOrUpdateTimingColouriseBoundsParameterKey(
                effect,
                parameter,
                position,
                evaluatedValue,
                interpolation)) {
        // A keyed bounds is a local edit that detaches this feature from
        // the shared Global bounds.
        effect->boundsEdited = true;
        runtimeState->previewRenderStateSignatureValid = false;
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        allowed
            ? "Add a key here using this setting's Curve style. Further edits automatically key the current animation position."
            : "This setting is view-only for the selected Bounds Keying mode.");
    ImGui::SameLine(0.0F, 2.0F);
    ImGui::BeginDisabled(!previous.has_value());
    if (ImGui::SmallButton("<")) {
        runtimeState->animationPanel.scrubAmount =
            previous.value();
        ApplyAnimationScrub(runtimeState);
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        previous.has_value()
            ? "Go to the previous key for this Bounds parameter."
            : "This Bounds parameter has no earlier key.");
    ImGui::SameLine(0.0F, 2.0F);
    ImGui::BeginDisabled(!next.has_value());
    if (ImGui::SmallButton(">")) {
        runtimeState->animationPanel.scrubAmount = next.value();
        ApplyAnimationScrub(runtimeState);
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        next.has_value()
            ? "Go to the next key for this Bounds parameter."
            : "This Bounds parameter has no later key.");
    ImGui::SameLine(0.0F, 2.0F);
    ImGui::BeginDisabled(currentCount == 0U);
    if (ImGui::SmallButton("X")) {
        (void)invisible_places::timing::
            RemoveTimingColouriseBoundsParameterKeysAtPosition(
                effect,
                parameter,
                position);
        runtimeState->previewRenderStateSignatureValid = false;
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        currentCount > 0U
            ? "Delete this Bounds parameter key at the current animation position."
            : "Move onto a key for this Bounds parameter before deleting it.");
    const bool hasKeys = TimingColouriseBoundsParameterHasKeys(
        *effect,
        parameter);
    if (hasKeys) {
        ImGui::SetNextItemWidth(
            std::max(48.0F, ImGui::GetContentRegionAvail().x));
        if (DrawTimingScalarTrackInterpolationCombo(
                "##CurveStyle",
                &effect->boundsParameterKeys,
                [&](const auto& key) {
                    return key.parameter == parameter;
                })) {
            runtimeState->previewRenderStateSignatureValid = false;
        }
    }
    ImGui::PopStyleVar();
}

void DrawTimingColouriseBoundsParameterEditor(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect,
    invisible_places::timing::TimingColouriseBoundsParameter parameter) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    const float position = std::clamp(
        runtimeState->animationPanel.scrubAmount,
        0.0F,
        1.0F);
    const auto evaluatedBounds =
        invisible_places::timing::EvaluateTimingColouriseBounds(
            *effect,
            position);
    const float evaluatedValue =
        invisible_places::timing::TimingColouriseBoundsParameterValue(
            evaluatedBounds,
            parameter);
    const bool editable =
        TimingColouriseBoundsParameterEditableAt(
            effect,
            parameter,
            position);
    const bool keyed =
        TimingColouriseBoundsParameterHasKeys(
            *effect,
            parameter);
    const bool percentage =
        parameter ==
        invisible_places::timing::
            TimingColouriseBoundsParameter::EdgeFade;
    float draft =
        percentage ? evaluatedValue * 100.0F : evaluatedValue;
    ImGui::PushID(static_cast<int>(parameter));
    ImGui::SetNextItemWidth(
        std::max(24.0F, ImGui::GetContentRegionAvail().x));
    ImGui::PushStyleVar(
        ImGuiStyleVar_FrameBorderSize,
        0.0F);
    ImGui::PushStyleVar(
        ImGuiStyleVar_FramePadding,
        ImVec2{1.0F, 2.0F});
    ImGui::PushStyleColor(
        ImGuiCol_FrameBg,
        IM_COL32(0, 0, 0, 0));
    ImGui::PushStyleColor(
        ImGuiCol_FrameBgHovered,
        IM_COL32(90, 90, 90, 18));
    ImGui::PushStyleColor(
        ImGuiCol_FrameBgActive,
        IM_COL32(90, 90, 90, 28));
    if (keyed) {
        ImGui::PushStyleColor(
            ImGuiCol_Text,
            kWaterKeyedSettingColour);
    }
    ImGui::BeginDisabled(!editable);
    const bool changed = ImGui::InputFloat(
        "##Value",
        &draft,
        0.0F,
        0.0F,
        percentage ? "%+.1f%%" : "%.6g",
        ImGuiInputTextFlags_None);
    ImGui::EndDisabled();
    if (keyed) {
        ImGui::PopStyleColor();
    }
    ImGui::PopStyleColor(3);
    ImGui::PopStyleVar(2);
    if (changed && editable &&
        SetTimingColouriseBoundsParameterAt(
            &runtimeState->water.timingScalarBoundsStores,
            effect,
            parameter,
            position,
            percentage ? draft * 0.01F : draft)) {
        runtimeState->previewRenderStateSignatureValid = false;
    }
    if (percentage) {
        DrawTimingControlTooltip(
            editable
                ? "Signed fade as a percentage of spacing: positive fades inward, negative fades outward."
                : "Fade is view-only in this Bounds Keying mode.");
    } else {
        DrawTimingControlTooltip(
            editable
                ? keyed
                      ? "This setting is armed. Editing at a new animation position automatically adds a key using its Curve style."
                  : !effect->boundsKeys.empty()
                      ? "This value comes from legacy Bounds keys. Editing promotes this setting to an independent scalar key track."
                      : "Click the value to edit its base, or press + to arm automatic keying."
                : "This value is resolved from the selected Bounds Keying mode and is view-only.");
    }

    DrawTimingColouriseBoundsParameterTrackButtons(
        runtimeState,
        effect,
        parameter);
    ImGui::PopID();
}

void DrawTimingColouriseBoundsEditor(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect,
    bool drawKeyMode = true,
    bool drawParameters = true) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    using invisible_places::timing::TimingColouriseBoundsKeyMode;
    using invisible_places::timing::TimingColouriseBoundsParameter;
    if (drawKeyMode) {
    struct ModeChoice {
        TimingColouriseBoundsKeyMode mode;
        const char* label;
        const char* explanation;
    };
    constexpr std::array modeChoices{
        ModeChoice{
            TimingColouriseBoundsKeyMode::LowerUpper,
            "Lower + Upper",
            "Key either endpoint independently."},
        ModeChoice{
            TimingColouriseBoundsKeyMode::CentreSpread,
            "Centre + Spacing",
            "Key the interval centre and total spacing."},
        ModeChoice{
            TimingColouriseBoundsKeyMode::LowerSpread,
            "Lower + Spacing",
            "Anchor the lower endpoint and key its spacing to the upper endpoint."},
        ModeChoice{
            TimingColouriseBoundsKeyMode::UpperSpread,
            "Upper + Spacing",
            "Anchor the upper endpoint and key its spacing to the lower endpoint."},
    };
    const auto currentChoice = std::find_if(
        modeChoices.begin(),
        modeChoices.end(),
        [&](const auto& choice) {
            return choice.mode == effect->boundsKeyMode;
        });
    const char* currentLabel =
        currentChoice != modeChoices.end()
            ? currentChoice->label
            : modeChoices.front().label;
    if (ImGui::BeginCombo("Bounds Keying", currentLabel)) {
        for (const auto& choice : modeChoices) {
            const bool compatible = std::all_of(
                effect->boundsParameterKeys.begin(),
                effect->boundsParameterKeys.end(),
                [&](const auto& key) {
                    return invisible_places::timing::
                        TimingColouriseBoundsParameterIsAllowed(
                            choice.mode,
                            key.parameter);
                });
            ImGui::BeginDisabled(!compatible);
            const bool selected =
                effect->boundsKeyMode == choice.mode;
            if (ImGui::Selectable(
                    choice.label,
                    selected) &&
                compatible &&
                invisible_places::timing::
                    SetTimingColouriseBoundsKeyMode(
                        effect,
                        choice.mode)) {
                runtimeState->timingsPanel
                    .activeHistogramHandle =
                    TimingColouriseHistogramHandle::None;
                runtimeState->previewRenderStateSignatureValid =
                    false;
            }
            ImGui::EndDisabled();
            DrawTimingControlTooltip(
                compatible
                    ? choice.explanation
                    : "This mode conflicts with an existing Bounds parameter track. Delete that track's keys before changing mode.");
            if (selected) {
                ImGui::SetItemDefaultFocus();
            }
        }
        ImGui::EndCombo();
    }
    DrawTimingLabelTooltip(
        "Choose the only two interval coordinates that this effect can key. Incompatible combinations are unavailable for the whole Timing Take.");
    }

    if (!drawParameters) {
        return;
    }

    if (!effect->boundsKeys.empty()) {
        ImGui::TextDisabled(
            "Legacy Bounds snapshot keys remain active as a fallback. New keys below override their individual coordinates.");
    }
    constexpr std::array parameters{
        TimingColouriseBoundsParameter::Lower,
        TimingColouriseBoundsParameter::Upper,
        TimingColouriseBoundsParameter::Centre,
        TimingColouriseBoundsParameter::Spread,
        TimingColouriseBoundsParameter::EdgeFade,
    };
    constexpr std::array<ImU32, parameters.size()> laneColours{
        IM_COL32(255, 190, 74, 255),
        IM_COL32(242, 104, 96, 255),
        IM_COL32(100, 176, 232, 255),
        IM_COL32(190, 132, 224, 255),
        IM_COL32(148, 214, 132, 255),
    };
    if (ImGui::BeginTable(
            "##BoundsParameters",
            static_cast<int>(parameters.size()),
            ImGuiTableFlags_SizingStretchSame)) {
        ImGui::TableNextRow();
        for (std::size_t index = 0U;
             index < parameters.size();
             ++index) {
            ImGui::TableSetColumnIndex(
                static_cast<int>(index));
            const auto parameter = parameters[index];
            const bool allowed = invisible_places::timing::
                TimingColouriseBoundsParameterIsAllowed(
                    effect->boundsKeyMode,
                    parameter);
            const bool keyed =
                TimingColouriseBoundsParameterHasKeys(
                    *effect,
                    parameter);
            if (!allowed) {
                ImGui::TextDisabled(
                    "%s",
                    TimingColouriseBoundsParameterLabel(
                        parameter));
            } else {
                if (keyed) {
                    ImGui::PushStyleColor(
                        ImGuiCol_Text,
                        kWaterKeyedSettingColour);
                }
                ImGui::TextUnformatted(
                    TimingColouriseBoundsParameterLabel(
                        parameter));
                if (keyed) {
                    ImGui::PopStyleColor();
                }
            }
        }
        ImGui::TableNextRow();
        for (std::size_t index = 0U;
             index < parameters.size();
             ++index) {
            ImGui::TableSetColumnIndex(
                static_cast<int>(index));
            DrawTimingColouriseBoundsParameterEditor(
                runtimeState,
                effect,
                parameters[index]);
        }
        ImGui::EndTable();
    }
    std::array<std::vector<float>, parameters.size()>
        boundsKeyPositions;
    for (const auto& key : effect->boundsParameterKeys) {
        const auto parameter = std::find(
            parameters.begin(),
            parameters.end(),
            key.parameter);
        if (parameter != parameters.end()) {
            boundsKeyPositions[static_cast<std::size_t>(
                std::distance(parameters.begin(), parameter))]
                .push_back(key.position);
        }
    }
    std::array<TimingColouriseKeyLaneSeries, parameters.size()>
        boundsLanes{};
    for (std::size_t index = 0U;
         index < parameters.size();
         ++index) {
        boundsLanes[index] = TimingColouriseKeyLaneSeries{
            .label = TimingColouriseBoundsParameterLabel(
                parameters[index]),
            .track = TimingColouriseKeyTrack::Bounds,
            .boundsParameter = parameters[index],
            .positions =
                std::span<const float>{boundsKeyPositions[index]},
            .colour = laneColours[index],
        };
    }
    ImGui::TextDisabled("Value over animation position");
    DrawTimingControlTooltip(
        "Allowed Bounds settings are drawn as coloured evaluated curves, each scaled over its own visible value range. Key dots are visual; drag matching coloured markers on the horizontal axis to retime keys.");
    DrawTimingKeyLaneGroup(
        "##TimingColouriseBoundsParameterKeyLane",
        runtimeState,
        effect,
        boundsLanes);
}

struct TimingColouriseActivationConcurrencySpan {
    float start = 0.0F;
    float end = 0.0F;
    // Renderer slots consumed by every feature active in this span. A
    // feature with both the colourise and emissive aspect enabled costs two
    // of the renderer's slots.
    std::size_t count = 0U;
};

// Renderer slots one Visual Feature consumes while active: one per enabled
// output aspect.
std::size_t TimingEffectRendererSlotCost(
    const invisible_places::timing::TimingColouriseEffect& effect) {
    return (effect.colouriseEnabled ? 1U : 0U) +
           (effect.emissiveEnabled ? 1U : 0U);
}

std::vector<TimingColouriseActivationConcurrencySpan>
BuildTimingColouriseActivationConcurrencySpans(
    std::span<const invisible_places::timing::TimingColouriseEffect>
        effects) {
    std::vector<float> boundaries{0.0F, 1.0F};
    boundaries.reserve(2U + effects.size() * 2U);
    for (const auto& effect : effects) {
        if (!effect.enabled) {
            continue;
        }
        const auto range = invisible_places::timing::
            SanitizeTimingColouriseActivationRange(
                effect.activationRange);
        boundaries.push_back(range.start);
        boundaries.push_back(range.end);
    }
    std::stable_sort(boundaries.begin(), boundaries.end());
    boundaries.erase(
        std::unique(
            boundaries.begin(),
            boundaries.end(),
            [](float left, float right) {
                return std::abs(left - right) <=
                       invisible_places::timing::
                           kTimingColouriseKeyTolerance;
            }),
        boundaries.end());

    std::vector<TimingColouriseActivationConcurrencySpan> spans;
    for (std::size_t index = 0U;
         index + 1U < boundaries.size();
         ++index) {
        const float start = boundaries[index];
        const float end = boundaries[index + 1U];
        if (end - start <=
            invisible_places::timing::
                kTimingColouriseKeyTolerance) {
            continue;
        }
        const float sample = std::midpoint(start, end);
        const std::size_t count = std::accumulate(
            effects.begin(),
            effects.end(),
            std::size_t{0U},
            [&](std::size_t slots, const auto& effect) {
                return invisible_places::timing::
                           TimingColouriseEffectIsActiveAt(
                               effect,
                               sample)
                           ? slots +
                                 TimingEffectRendererSlotCost(
                                     effect)
                           : slots;
            });
        if (count <= invisible_places::timing::
                         kTimingColouriseSoftActiveEffectLimit) {
            continue;
        }
        if (!spans.empty() && spans.back().count == count &&
            std::abs(spans.back().end - start) <=
                invisible_places::timing::
                    kTimingColouriseKeyTolerance) {
            spans.back().end = end;
        } else {
            spans.push_back({
                .start = start,
                .end = end,
                .count = count,
            });
        }
    }

    // Activation windows are inclusive at both ends. Sample every exact
    // boundary as well as the open spans above so adjacent ranges (and
    // single-frame ranges where start == end) cannot hide a concurrency spike
    // at the shared animation position.
    for (const float boundary : boundaries) {
        const std::size_t count = std::accumulate(
            effects.begin(),
            effects.end(),
            std::size_t{0U},
            [&](std::size_t slots, const auto& effect) {
                return invisible_places::timing::
                           TimingColouriseEffectIsActiveAt(
                               effect,
                               boundary)
                           ? slots +
                                 TimingEffectRendererSlotCost(
                                     effect)
                           : slots;
            });
        if (count > invisible_places::timing::
                        kTimingColouriseSoftActiveEffectLimit) {
            spans.push_back({
                .start = boundary,
                .end = boundary,
                .count = count,
            });
        }
    }
    return spans;
}

void DrawTimingColouriseTimelineZoomToggle(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& timings = runtimeState->timingsPanel;
    bool activeRangeView =
        timings.colouriseTimelineView ==
        TimingColouriseTimelineView::ActiveRange;
    if (ImGui::Checkbox(
            "Zoom setting lanes to active range",
            &activeRangeView)) {
        timings.colouriseTimelineView =
            activeRangeView
                ? TimingColouriseTimelineView::ActiveRange
                : TimingColouriseTimelineView::FullAnimation;
        timings.colouriseLocalKeyDrag.reset();
    }
    DrawTimingControlTooltip(
        activeRangeView
            ? "The selected feature's setting lanes are expanded to its active interval. Switch off to see every key across 0..1."
            : "Setting lanes show the full 0..1 animation. Keys outside the selected feature's active interval remain editable but are dimmed.");
}

void DrawTimingColouriseActivationOverview(
    PreviewRuntimeState* runtimeState,
    std::vector<invisible_places::timing::TimingColouriseEffect>*
        effects) {
    if (runtimeState == nullptr || effects == nullptr) {
        return;
    }
    auto& timings = runtimeState->timingsPanel;
    if (effects->empty()) {
        timings.colouriseActivationDrag.reset();
        ImGui::TextDisabled(
            "Add a Visual Feature to author an active range.");
        return;
    }

    const auto concurrency =
        BuildTimingColouriseActivationConcurrencySpans(*effects);
    const std::size_t rendererCapacity =
        invisible_places::renderer::pointcloud::
            kTimingColouriseMaxEffects;
    const auto selectEffect = [&](std::size_t index) {
        timings.selectedColouriseEffectIndex = index;
        timings.selectedColourisePaletteStopIndex =
            TimingEffectIsEmissive((*effects)[index])
                ? std::nullopt
                : std::optional<std::size_t>{0U};
        timings.draggingColourisePaletteStop = false;
        timings.draggingColourisePaletteStopAmount = false;
        timings.colourisePaletteDrag.reset();
        timings.requestedColourisePalettePickerStopIndex.reset();
        timings.colourisePalettePicker.reset();
        timings.activeHistogramHandle =
            TimingColouriseHistogramHandle::None;
        timings.colouriseLocalKeyDrag.reset();
        timings.colouriseLocalKeyPositionEdit.reset();
        runtimeState->animationPanel
            .timingColouriseKeyPositionEdit.reset();
        timings.colouriseEffectRenameBuffer =
            (*effects)[index].name;
    };
    const auto fieldCatalog =
        BuildActiveTimingColouriseFieldCatalog(runtimeState);
    const auto fieldWatermarkLabel =
        [&](const invisible_places::timing::
                TimingColouriseEffect& effect) -> std::string {
        for (const auto& family : fieldCatalog) {
            for (const auto& variant : family.variants) {
                if (variant.selector == effect.field) {
                    return family.name + " · " + variant.name;
                }
            }
        }
        switch (effect.field.source) {
            case invisible_places::timing::
                TimingColouriseFieldSource::NormalX:
                return "Normal X";
            case invisible_places::timing::
                TimingColouriseFieldSource::NormalY:
                return "Normal Y";
            case invisible_places::timing::
                TimingColouriseFieldSource::NormalZ:
                return "Normal Z";
            case invisible_places::timing::
                TimingColouriseFieldSource::Scalar:
                break;
        }
        return effect.field.scalarFieldName;
    };

    constexpr ImGuiTableFlags kTableFlags =
        ImGuiTableFlags_SizingStretchProp |
        ImGuiTableFlags_BordersInnerV |
        ImGuiTableFlags_RowBg;
    if (ImGui::BeginTable(
            "##TimingColouriseActivationOverview",
            2,
            kTableFlags)) {
        ImGui::TableSetupColumn(
            "Visual Feature",
            ImGuiTableColumnFlags_WidthFixed,
            180.0F);
        ImGui::TableSetupColumn(
            "Active range  0 ............................. 1",
            ImGuiTableColumnFlags_WidthStretch);
        ImGui::TableNextRow(ImGuiTableRowFlags_Headers);
        ImGui::TableSetColumnIndex(0);
        ImGui::TableHeader("Visual Feature");
        ImGui::TableSetColumnIndex(1);
        ImGui::TableHeader(
            "Active range  0 ............................. 1");
        DrawTimingCornerHelpMark(
            ImGui::GetWindowDrawList(),
            ImGui::GetItemRectMin(),
            ImGui::GetItemRectMax(),
            "Visual Features timeline\n"
            "Click a feature name to select it, double-click to turn it on "
            "or off, or drag it to change its layer priority.\n"
            "Drag either endpoint of a row's filled interval, or drag the "
            "filled body to translate it. Keys keep their global animation "
            "positions.\n"
            "Red overlays mark ranges where the active features need more "
            "renderer slots than recommended. A feature with colourise and "
            "emissive output uses two of the eight slots.");

        // This timeline is the single Visual Feature list: its names own
        // selection, enable toggles, and renderer-priority reordering.
        bool dragEffectStillPresent = false;
        std::optional<std::pair<std::size_t, std::size_t>>
            requestedReorder;
        for (std::size_t index = 0U;
             index < effects->size();
             ++index) {
            auto& effect = (*effects)[index];
            auto range = invisible_places::timing::
                SanitizeTimingColouriseActivationRange(
                    effect.activationRange);
            ImGui::PushID(effect.id.c_str());
            ImGui::TableNextRow(
                ImGuiTableRowFlags_None,
                24.0F);
            ImGui::TableSetColumnIndex(0);
            const bool effectWasEnabled = effect.enabled;
            if (!effectWasEnabled) {
                ImGui::PushStyleColor(
                    ImGuiCol_Text,
                    ImGui::GetStyleColorVec4(
                        ImGuiCol_TextDisabled));
            }
            const std::string rowLabel =
                std::string{"["} +
                TimingEffectAspectBadge(effect) + "] " +
                effect.name;
            const bool selected = ImGui::Selectable(
                rowLabel.c_str(),
                timings.selectedColouriseEffectIndex ==
                    index);
            const bool toggleEnabled =
                ImGui::IsItemHovered() &&
                ImGui::IsMouseDoubleClicked(
                    ImGuiMouseButton_Left);
            if (selected) {
                selectEffect(index);
            }
            if (toggleEnabled) {
                effect.enabled = !effect.enabled;
                runtimeState->previewRenderStateSignatureValid =
                    false;
            }
            if (!effectWasEnabled) {
                ImGui::PopStyleColor();
            }
            if (ImGui::BeginDragDropSource()) {
                const auto payloadIndex = index;
                ImGui::SetDragDropPayload(
                    "TIMING_COLOURISE_EFFECT_ITEM",
                    &payloadIndex,
                    sizeof(payloadIndex));
                ImGui::Text(
                    "[%s] %s",
                    TimingEffectAspectBadge(effect),
                    effect.name.c_str());
                ImGui::EndDragDropSource();
            }
            if (ImGui::BeginDragDropTarget()) {
                if (const auto* payload =
                        ImGui::AcceptDragDropPayload(
                            "TIMING_COLOURISE_EFFECT_ITEM");
                    payload != nullptr &&
                    payload->DataSize ==
                        sizeof(std::size_t)) {
                    requestedReorder = std::pair{
                        *static_cast<const std::size_t*>(
                            payload->Data),
                        index};
                }
                ImGui::EndDragDropTarget();
            }
            DrawTimingControlTooltip(
                effect.enabled
                    ? "Click to select, double-click to turn off, or drag to change layer priority. The top feature has highest priority."
                    : "Click to select, double-click to turn on, or drag to change layer priority. The top feature has highest priority.");

            ImGui::TableSetColumnIndex(1);
            const ImVec2 laneSize{
                std::max(
                    80.0F,
                    ImGui::GetContentRegionAvail().x),
                20.0F};
            ImGui::InvisibleButton(
                "##ActivationRange",
                laneSize,
                ImGuiButtonFlags_MouseButtonLeft);
            const ImVec2 itemMinimum =
                ImGui::GetItemRectMin();
            const ImVec2 itemMaximum =
                ImGui::GetItemRectMax();
            constexpr float kHandleInset = 5.0F;
            const float trackMinimumX =
                itemMinimum.x + kHandleInset;
            const float trackMaximumX =
                itemMaximum.x - kHandleInset;
            const float trackWidth = std::max(
                1.0F,
                trackMaximumX - trackMinimumX);
            const float centreY =
                std::midpoint(
                    itemMinimum.y,
                    itemMaximum.y);
            const auto xForPosition = [&](float position) {
                return trackMinimumX +
                       trackWidth * std::clamp(
                                        position,
                                        0.0F,
                                        1.0F);
            };
            const auto positionForX = [&](float x) {
                return std::clamp(
                    (x - trackMinimumX) / trackWidth,
                    0.0F,
                    1.0F);
            };
            const auto mouse = ImGui::GetIO().MousePos;
            const float startX =
                xForPosition(range.start);
            const float endX =
                xForPosition(range.end);
            constexpr float kHandleHitRadius = 7.0F;
            const float startDistance =
                std::abs(mouse.x - startX);
            const float endDistance =
                std::abs(mouse.x - endX);
            std::optional<TimingColouriseActivationDragPart>
                hoveredPart;
            if (ImGui::IsItemHovered()) {
                if (startDistance <= kHandleHitRadius &&
                    endDistance <= kHandleHitRadius) {
                    hoveredPart =
                        mouse.y < centreY
                            ? TimingColouriseActivationDragPart::Start
                            : TimingColouriseActivationDragPart::End;
                } else if (
                    startDistance <= kHandleHitRadius) {
                    hoveredPart =
                        TimingColouriseActivationDragPart::Start;
                } else if (
                    endDistance <= kHandleHitRadius) {
                    hoveredPart =
                        TimingColouriseActivationDragPart::End;
                } else if (
                    mouse.x >= startX && mouse.x <= endX) {
                    hoveredPart =
                        TimingColouriseActivationDragPart::Body;
                }
            }
            if (ImGui::IsItemHovered() &&
                ImGui::IsMouseClicked(
                    ImGuiMouseButton_Left)) {
                selectEffect(index);
                if (hoveredPart.has_value()) {
                    StopAnimationPlayback(runtimeState);
                    timings.colouriseActivationDrag =
                        TimingColouriseActivationDragState{
                            .effectId = effect.id,
                            .part = hoveredPart.value(),
                            .mouseStartX = mouse.x,
                            .originalStart = range.start,
                            .originalEnd = range.end,
                        };
                }
            }

            if (timings.colouriseActivationDrag.has_value() &&
                timings.colouriseActivationDrag->effectId ==
                    effect.id) {
                dragEffectStillPresent = true;
                if (ImGui::IsItemActive() &&
                    ImGui::IsMouseDown(
                        ImGuiMouseButton_Left)) {
                    const auto& drag =
                        timings.colouriseActivationDrag.value();
                    const float delta =
                        (mouse.x - drag.mouseStartX) /
                        trackWidth;
                    auto updated = range;
                    switch (drag.part) {
                        case TimingColouriseActivationDragPart::Start:
                            updated.start = std::clamp(
                                drag.originalStart + delta,
                                0.0F,
                                drag.originalEnd);
                            updated.end = drag.originalEnd;
                            break;
                        case TimingColouriseActivationDragPart::End:
                            updated.start = drag.originalStart;
                            updated.end = std::clamp(
                                drag.originalEnd + delta,
                                drag.originalStart,
                                1.0F);
                            break;
                        case TimingColouriseActivationDragPart::Body: {
                            const float length =
                                drag.originalEnd -
                                drag.originalStart;
                            updated.start = std::clamp(
                                drag.originalStart + delta,
                                0.0F,
                                std::max(0.0F, 1.0F - length));
                            updated.end =
                                updated.start + length;
                            break;
                        }
                    }
                    updated = invisible_places::timing::
                        SanitizeTimingColouriseActivationRange(
                            updated);
                    if (updated.start !=
                            effect.activationRange.start ||
                        updated.end !=
                            effect.activationRange.end) {
                        effect.activationRange = updated;
                        range = updated;
                        runtimeState
                            ->previewRenderStateSignatureValid =
                            false;
                    }
                }
            }

            auto* drawList =
                ImGui::GetWindowDrawList();
            const ImU32 frameColour =
                ImGui::GetColorU32(ImGuiCol_FrameBg);
            const ImU32 borderColour =
                ImGui::GetColorU32(
                    timings.selectedColouriseEffectIndex == index
                        ? ImGuiCol_SliderGrabActive
                        : ImGuiCol_Border);
            drawList->AddRectFilled(
                itemMinimum,
                itemMaximum,
                frameColour,
                3.0F);
            drawList->AddRect(
                itemMinimum,
                itemMaximum,
                borderColour,
                3.0F);
            // Low-alpha scalar-field watermark behind the activation fill
            // so every row identifies its bound field at a glance.
            if (const std::string fieldLabel =
                    fieldWatermarkLabel(effect);
                !fieldLabel.empty()) {
                drawList->PushClipRect(
                    itemMinimum,
                    itemMaximum,
                    true);
                drawList->AddText(
                    ImVec2{
                        itemMinimum.x + 6.0F,
                        std::midpoint(
                            itemMinimum.y,
                            itemMaximum.y) -
                            ImGui::GetTextLineHeight() * 0.5F},
                    ImGui::GetColorU32(
                        ImGuiCol_TextDisabled,
                        0.35F),
                    fieldLabel.c_str());
                drawList->PopClipRect();
            }
            const ImU32 rangeColour = ImGui::GetColorU32(
                effect.enabled
                    ? ImVec4{0.26F, 0.55F, 0.78F, 0.58F}
                    : ImVec4{0.42F, 0.42F, 0.42F, 0.24F});
            drawList->AddRectFilled(
                ImVec2{
                    xForPosition(range.start),
                    itemMinimum.y + 3.0F},
                ImVec2{
                    xForPosition(range.end),
                    itemMaximum.y - 3.0F},
                rangeColour,
                2.0F);

            const auto rangeContains =
                [&](float position) {
                    return position >= range.start &&
                           position <= range.end;
                };
            const TimingColouriseActivationConcurrencySpan*
                hoveredConcurrency = nullptr;
            if (effect.enabled) {
                for (const auto& span : concurrency) {
                    const bool boundaryOnly =
                        std::abs(span.end - span.start) <=
                        invisible_places::timing::
                            kTimingColouriseKeyTolerance;
                    const float sample =
                        boundaryOnly
                            ? span.start
                            : std::midpoint(span.start, span.end);
                    if (!rangeContains(sample)) {
                        continue;
                    }
                    const bool beyondCapacity =
                        span.count > rendererCapacity;
                    const ImU32 concurrencyColour =
                        beyondCapacity
                            ? IM_COL32(230, 58, 52, 196)
                            : IM_COL32(222, 82, 72, 112);
                    if (boundaryOnly) {
                        const float boundaryX =
                            xForPosition(span.start);
                        drawList->AddLine(
                            ImVec2{
                                boundaryX,
                                itemMinimum.y + 2.0F},
                            ImVec2{
                                boundaryX,
                                itemMaximum.y - 2.0F},
                            concurrencyColour,
                            beyondCapacity ? 4.0F : 3.0F);
                    } else {
                        drawList->AddRectFilled(
                            ImVec2{
                                xForPosition(span.start),
                                itemMinimum.y + 3.0F},
                            ImVec2{
                                xForPosition(span.end),
                                itemMaximum.y - 3.0F},
                            concurrencyColour,
                            1.5F);
                    }
                    if (ImGui::IsItemHovered() &&
                        (boundaryOnly
                             ? std::abs(
                                   mouse.x -
                                   xForPosition(span.start)) <= 4.0F
                             : mouse.x >=
                                       xForPosition(span.start) &&
                                   mouse.x <=
                                       xForPosition(span.end))) {
                        hoveredConcurrency = &span;
                    }
                }
            }

            const ImU32 handleColour =
                ImGui::GetColorU32(
                    effect.enabled
                        ? ImGuiCol_SliderGrabActive
                        : ImGuiCol_TextDisabled);
            const float drawnStartX =
                xForPosition(range.start);
            const float drawnEndX =
                xForPosition(range.end);
            drawList->AddLine(
                ImVec2{drawnStartX, itemMinimum.y + 2.0F},
                ImVec2{drawnStartX, itemMaximum.y - 2.0F},
                handleColour,
                2.0F);
            drawList->AddLine(
                ImVec2{drawnEndX, itemMinimum.y + 2.0F},
                ImVec2{drawnEndX, itemMaximum.y - 2.0F},
                handleColour,
                2.0F);
            drawList->AddCircleFilled(
                ImVec2{drawnStartX, centreY - 3.0F},
                3.0F,
                handleColour);
            drawList->AddCircleFilled(
                ImVec2{drawnEndX, centreY + 3.0F},
                3.0F,
                handleColour);
            const float scrubX = xForPosition(
                runtimeState->animationPanel.scrubAmount);
            drawList->AddLine(
                ImVec2{scrubX, itemMinimum.y + 1.0F},
                ImVec2{scrubX, itemMaximum.y - 1.0F},
                ImGui::GetColorU32(
                    rangeContains(
                        runtimeState->animationPanel.scrubAmount)
                        ? ImGuiCol_Text
                        : ImGuiCol_TextDisabled),
                1.0F);

            if (hoveredConcurrency != nullptr) {
                std::string activeNames;
                const bool boundaryOnly =
                    std::abs(
                        hoveredConcurrency->end -
                        hoveredConcurrency->start) <=
                    invisible_places::timing::
                        kTimingColouriseKeyTolerance;
                const float sample =
                    boundaryOnly
                        ? hoveredConcurrency->start
                        : std::midpoint(
                              hoveredConcurrency->start,
                              hoveredConcurrency->end);
                for (const auto& candidate : *effects) {
                    if (!invisible_places::timing::
                            TimingColouriseEffectIsActiveAt(
                                candidate,
                                sample)) {
                        continue;
                    }
                    if (!activeNames.empty()) {
                        activeNames += ", ";
                    }
                    activeNames +=
                        std::string{"["} +
                        TimingEffectAspectBadge(candidate) + "] " +
                        candidate.name;
                }
                if (hoveredConcurrency->count >
                    rendererCapacity) {
                    if (boundaryOnly) {
                        ImGui::SetTooltip(
                            "Active features need %zu renderer slots at boundary %.4f. Only the highest-priority features fitting the %zu-slot budget render here; lower list items are omitted.\n%s",
                            hoveredConcurrency->count,
                            hoveredConcurrency->start,
                            rendererCapacity,
                            activeNames.c_str());
                    } else {
                        ImGui::SetTooltip(
                            "Active features need %zu renderer slots from %.4f to %.4f. Only the highest-priority features fitting the %zu-slot budget render here; lower list items are omitted.\n%s",
                            hoveredConcurrency->count,
                            hoveredConcurrency->start,
                            hoveredConcurrency->end,
                            rendererCapacity,
                            activeNames.c_str());
                    }
                } else {
                    if (boundaryOnly) {
                        ImGui::SetTooltip(
                            "Active features need %zu renderer slots at boundary %.4f. This exceeds the recommended responsive budget of %zu.\n%s",
                            hoveredConcurrency->count,
                            hoveredConcurrency->start,
                            invisible_places::timing::
                                kTimingColouriseSoftActiveEffectLimit,
                            activeNames.c_str());
                    } else {
                        ImGui::SetTooltip(
                            "Active features need %zu renderer slots from %.4f to %.4f. This exceeds the recommended responsive budget of %zu.\n%s",
                            hoveredConcurrency->count,
                            hoveredConcurrency->start,
                            hoveredConcurrency->end,
                            invisible_places::timing::
                                kTimingColouriseSoftActiveEffectLimit,
                            activeNames.c_str());
                    }
                }
            } else if (ImGui::IsItemHovered()) {
                const float durationSeconds =
                    runtimeState->animationPanel.currentPath.has_value()
                        ? std::max(
                              0.0F,
                              AnimationDurationSeconds(
                                  runtimeState->animationPanel
                                      .currentPath.value()))
                        : 0.0F;
                ImGui::SetTooltip(
                    "%s active %.4f–%.4f (%.2f–%.2f s)",
                    effect.name.c_str(),
                    range.start,
                    range.end,
                    range.start * durationSeconds,
                    range.end * durationSeconds);
            }
            if (hoveredPart.has_value()) {
                ImGui::SetMouseCursor(
                    ImGuiMouseCursor_ResizeEW);
            }
            ImGui::PopID();
        }
        if (timings.colouriseActivationDrag.has_value() &&
            !dragEffectStillPresent) {
            timings.colouriseActivationDrag.reset();
        }
        ImGui::EndTable();

        if (requestedReorder.has_value()) {
            const auto [sourceIndex, destinationIndex] =
                requestedReorder.value();
            std::optional<std::string> selectedEffectId;
            if (timings.selectedColouriseEffectIndex.has_value() &&
                timings.selectedColouriseEffectIndex.value() <
                    effects->size()) {
                selectedEffectId =
                    (*effects)[timings.selectedColouriseEffectIndex
                                   .value()]
                        .id;
            }
            if (invisible_places::timing::
                    MoveTimingColouriseEffect(
                        effects,
                        sourceIndex,
                        destinationIndex)) {
                if (selectedEffectId.has_value()) {
                    const auto selectedEffect = std::find_if(
                        effects->begin(),
                        effects->end(),
                        [&](const auto& candidate) {
                            return candidate.id ==
                                   selectedEffectId.value();
                        });
                    timings.selectedColouriseEffectIndex =
                        selectedEffect != effects->end()
                            ? std::optional<std::size_t>{
                                  static_cast<std::size_t>(
                                      std::distance(
                                          effects->begin(),
                                          selectedEffect))}
                            : std::nullopt;
                }
                runtimeState->previewRenderStateSignatureValid =
                    false;
            }
        }
    }
    if (!ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        timings.colouriseActivationDrag.reset();
    }

    std::size_t maximumConcurrency = 0U;
    for (const auto& span : concurrency) {
        maximumConcurrency =
            std::max(maximumConcurrency, span.count);
    }
    if (maximumConcurrency > rendererCapacity) {
        ImGui::TextColored(
            ImVec4{0.92F, 0.25F, 0.22F, 1.0F},
            "Overlapping features need %zu renderer slots; only the top features within the %zu-slot budget render in the strong-red area or boundary marker.",
            maximumConcurrency,
            rendererCapacity);
    } else if (
        maximumConcurrency > invisible_places::timing::
                                 kTimingColouriseSoftActiveEffectLimit) {
        ImGui::TextColored(
            ImVec4{0.78F, 0.34F, 0.30F, 1.0F},
            "Overlapping features need %zu renderer slots in the softly marked ranges or boundary markers (recommended: %zu).",
            maximumConcurrency,
            invisible_places::timing::
                kTimingColouriseSoftActiveEffectLimit);
    }
}

void DrawTimingColouriseSection(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr ||
        !BeginPanelSection("Visual Features")) {
        return;
    }
    auto& water = runtimeState->water;
    auto& timings = runtimeState->timingsPanel;
    const auto takeId =
        ActiveWaterTimingScenarioId(*runtimeState);
    auto& state = EnsureScenarioFeatureRuns(
        &water,
        takeId);
    auto& effects = state.colouriseEffects;
    // Features without a local bounds edit follow the newest shared Global
    // bounds for their scalar field once per frame.
    for (auto& candidate : effects) {
        if (invisible_places::timing::
                RefreshTimingColouriseBoundsFromGlobal(
                    &candidate,
                    water.timingScalarBoundsStores)) {
            runtimeState->previewRenderStateSignatureValid =
                false;
        }
    }
    const auto selectEffect = [&](std::size_t index) {
        if (index >= effects.size()) {
            return;
        }
        timings.selectedColouriseEffectIndex = index;
        timings.selectedColourisePaletteStopIndex =
            TimingEffectIsEmissive(effects[index])
                ? std::nullopt
                : std::optional<std::size_t>{0U};
        timings.draggingColourisePaletteStop = false;
        timings.draggingColourisePaletteStopAmount = false;
        timings.colourisePaletteDrag.reset();
        timings.requestedColourisePalettePickerStopIndex.reset();
        timings.colourisePalettePicker.reset();
        timings.activeHistogramHandle =
            TimingColouriseHistogramHandle::None;
        timings.colouriseLocalKeyDrag.reset();
        timings.colouriseLocalKeyPositionEdit.reset();
        runtimeState->animationPanel
            .timingColouriseKeyPositionEdit.reset();
        timings.colouriseEffectRenameBuffer = effects[index].name;
    };
    if (timings.selectedColouriseEffectIndex.has_value() &&
        timings.selectedColouriseEffectIndex.value() >=
            effects.size()) {
        timings.selectedColouriseEffectIndex.reset();
        timings.selectedColourisePaletteStopIndex.reset();
        timings.draggingColourisePaletteStop = false;
        timings.draggingColourisePaletteStopAmount = false;
        runtimeState->previewRenderStateSignatureValid =
            false;
    }
    DrawTimingColouriseActivationOverview(
        runtimeState,
        &effects);
    if (ImGui::Button("Add")) {
        invisible_places::timing::TimingColouriseEffect effect;
        effect.id = invisible_places::timing::
            AllocateTimingColouriseEffectId(
                effects,
                &state.colouriseEffectSequence);
        const auto defaultName = [&](std::size_t ordinal) {
            return std::string{"Visual Feature "} +
                   (ordinal < 10U
                        ? std::string{"0"}
                        : std::string{}) +
                   std::to_string(ordinal);
        };
        std::size_t ordinal = 1U;
        while (std::any_of(
            effects.begin(),
            effects.end(),
            [&](const auto& candidate) {
                return candidate.name == defaultName(ordinal);
            })) {
            ++ordinal;
        }
        effect.name = defaultName(ordinal);
        effects.push_back(
            invisible_places::timing::
                SanitizeTimingColouriseEffect(
                    std::move(effect)));
        selectEffect(effects.size() - 1U);
        runtimeState->previewRenderStateSignatureValid = false;
    }
    DrawTimingControlTooltip(
        "Add a Visual Feature: one scalar-field selection that can drive colourise, emissive shading, or both. Keep concurrent active ranges at five or fewer when possible.");
    ImGui::SameLine();
    const bool hasSelection =
        timings.selectedColouriseEffectIndex.has_value();
    ImGui::BeginDisabled(!hasSelection);
    if (ImGui::Button("Duplicate") && hasSelection) {
        auto duplicate =
            effects[timings.selectedColouriseEffectIndex.value()];
        duplicate.id =
            invisible_places::timing::
                AllocateTimingColouriseEffectId(
                    effects,
                    &state.colouriseEffectSequence);
        duplicate.name += " Copy";
        const auto insertAt =
            timings.selectedColouriseEffectIndex.value() + 1U;
        effects.insert(
            effects.begin() +
                static_cast<std::ptrdiff_t>(insertAt),
            std::move(duplicate));
        selectEffect(insertAt);
        runtimeState->previewRenderStateSignatureValid =
            false;
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        !hasSelection
            ? "Select a Visual Feature to duplicate it."
            : "Duplicate the selected Visual Feature, including its keys.");
    ImGui::SameLine();
    ImGui::BeginDisabled(!hasSelection);
    if (ImGui::Button("Delete") && hasSelection) {
        effects.erase(
            effects.begin() +
            static_cast<std::ptrdiff_t>(
                timings.selectedColouriseEffectIndex
                    .value()));
        if (effects.empty()) {
            timings.selectedColouriseEffectIndex.reset();
            timings.selectedColourisePaletteStopIndex.reset();
            timings.colourisePaletteDrag.reset();
            timings.colouriseLocalKeyDrag.reset();
            timings.colouriseLocalKeyPositionEdit.reset();
        } else {
            selectEffect(std::min(
                timings.selectedColouriseEffectIndex.value(),
                effects.size() - 1U));
        }
        runtimeState->previewRenderStateSignatureValid =
            false;
    }
    ImGui::EndDisabled();
    DrawTimingControlTooltip(
        hasSelection
            ? "Delete the selected Visual Feature and all of its setting and Bounds keys."
            : "Select a Visual Feature to delete it.");

    if (!timings.selectedColouriseEffectIndex.has_value()) {
        ImGui::TextDisabled(
            "Add or select a Visual Feature to edit its controls, scalar field, and animated Bounds.");
        EndPanelSection();
        return;
    }
    auto& effect =
        effects[timings.selectedColouriseEffectIndex.value()];
    InputTextString(
        "Name",
        &effect.name);
    DrawTimingLabelTooltip(
        "Rename this Visual Feature. Its output aspects are toggled in the Emissive and Colourise sections below.");
    DrawTimingColouriseTimelineZoomToggle(runtimeState);
    ImGui::SeparatorText("Scalar Field and Bounds");
    auto catalog =
        BuildActiveTimingColouriseFieldCatalog(
            runtimeState);
    if (effect.emissiveEnabled) {
        for (auto& family : catalog) {
            std::erase_if(
                family.variants,
                [](const auto& variant) {
                    return variant.selector.source !=
                           invisible_places::timing::
                               TimingColouriseFieldSource::Scalar;
                });
        }
        std::erase_if(
            catalog,
            [](const auto& family) {
                return family.variants.empty();
            });
    }
    if (catalog.empty()) {
        ImGui::TextDisabled(
            "Load a committed SAND / ROCK / VEG scene bundle to choose fields and compute a histogram.");
        DrawTimingColouriseBoundsEditor(
            runtimeState,
            &effect);
    } else {
        // Remembered per-family variant, else the family's Combined
        // variant, else its first variant.
        const auto defaultVariantIndex =
            [&](const invisible_places::timing::
                    TimingColouriseFieldFamily& family)
                -> std::size_t {
                if (const auto remembered =
                        timings.lastColouriseVariantByFamily
                            .find(family.id);
                    remembered !=
                    timings.lastColouriseVariantByFamily
                        .end()) {
                    for (std::size_t index = 0U;
                         index < family.variants.size();
                         ++index) {
                        if (family.variants[index].id ==
                            remembered->second) {
                            return index;
                        }
                    }
                }
                for (std::size_t index = 0U;
                     index < family.variants.size();
                     ++index) {
                    if (LowercaseAsciiCopy(
                            family.variants[index].name) ==
                        "combined") {
                        return index;
                    }
                }
                return 0U;
            };
        // Field switches never lose Bounds authoring: the current
        // selector's state is stashed, the new selector restores its
        // remembered state, and first visits adopt the shared Global
        // bounds or the field's full stats range.
        const auto applyFieldSelection =
            [&](const invisible_places::timing::
                    TimingColouriseFieldSelector& selector) {
                if (selector == effect.field) {
                    return;
                }
                auto fallbackBounds = effect.baseBounds;
                if (const auto range =
                        TimingColouriseSelectorRangeFromStats(
                            runtimeState,
                            selector);
                    range.has_value()) {
                    fallbackBounds = {
                        .lower = range->first,
                        .upper = range->second,
                        .edgeFade = 0.10F,
                    };
                }
                invisible_places::timing::
                    ApplyTimingColouriseFieldSelection(
                        &effect,
                        selector,
                        fallbackBounds,
                        invisible_places::timing::
                            FindTimingScalarBoundsStore(
                                std::as_const(
                                    water
                                        .timingScalarBoundsStores),
                                selector));
                runtimeState->previewRenderStateSignatureValid =
                    false;
            };
        std::size_t familyIndex = 0U;
        std::size_t variantIndex = 0U;
        bool foundSelector = false;
        for (std::size_t family = 0U;
             family < catalog.size();
             ++family) {
            for (std::size_t variant = 0U;
                 variant < catalog[family].variants.size();
                 ++variant) {
                if (catalog[family]
                        .variants[variant]
                        .selector == effect.field) {
                    familyIndex = family;
                    variantIndex = variant;
                    foundSelector = true;
                    break;
                }
            }
            if (foundSelector) {
                break;
            }
        }
        const bool unsetScalarSelector =
            effect.field.source ==
                invisible_places::timing::
                    TimingColouriseFieldSource::Scalar &&
            effect.field.scalarFieldName.empty();
        const bool emissiveNonScalarSelector =
            effect.emissiveEnabled &&
            effect.field.source !=
                invisible_places::timing::
                    TimingColouriseFieldSource::Scalar;
        if (!foundSelector &&
            (unsetScalarSelector ||
             emissiveNonScalarSelector) &&
            !catalog.front().variants.empty()) {
            const auto defaultIndex =
                defaultVariantIndex(catalog.front());
            applyFieldSelection(
                catalog.front()
                    .variants[defaultIndex]
                    .selector);
            familyIndex = 0U;
            variantIndex = defaultIndex;
            foundSelector = true;
        } else if (!foundSelector) {
            std::string missingName;
            switch (effect.field.source) {
                case invisible_places::timing::
                    TimingColouriseFieldSource::NormalX:
                    missingName = "Normal X";
                    break;
                case invisible_places::timing::
                    TimingColouriseFieldSource::NormalY:
                    missingName = "Normal Y";
                    break;
                case invisible_places::timing::
                    TimingColouriseFieldSource::NormalZ:
                    missingName = "Normal Z";
                    break;
                case invisible_places::timing::
                    TimingColouriseFieldSource::Scalar:
                    missingName = effect.field.scalarFieldName;
                    break;
            }
            catalog.push_back(
                {.id = "__missing__",
                 .name = "Missing: " + missingName,
                 .variants = {
                     {.id = "__missing__",
                      .name = missingName,
                      .selector = effect.field}}});
            familyIndex = catalog.size() - 1U;
            variantIndex = 0U;
        }
        if (ImGui::BeginCombo(
                "Scalar Family",
                catalog[familyIndex].name.c_str())) {
            for (std::size_t index = 0U;
                 index < catalog.size();
                 ++index) {
                const bool selected =
                    index == familyIndex;
                if (ImGui::Selectable(
                        catalog[index].name.c_str(),
                        selected) &&
                    !catalog[index].variants.empty()) {
                    const auto defaultIndex =
                        defaultVariantIndex(catalog[index]);
                    applyFieldSelection(
                        catalog[index]
                            .variants[defaultIndex]
                            .selector);
                    familyIndex = index;
                    variantIndex = defaultIndex;
                }
                if (selected) {
                    ImGui::SetItemDefaultFocus();
                }
            }
            ImGui::EndCombo();
        }
        DrawTimingLabelTooltip(
            "Choose a scalar family shared by committed SAND, ROCK, and VEG. Related scale and vector components are grouped. Switching fields keeps every field's Bounds authoring remembered.");
        const auto& variants =
            catalog[familyIndex].variants;
        variantIndex = std::min(
            variantIndex,
            variants.size() - 1U);
        if (ImGui::BeginCombo(
                "Variant",
                variants[variantIndex].name.c_str())) {
            for (std::size_t index = 0U;
                 index < variants.size();
                 ++index) {
                const bool selected =
                    variants[index].selector ==
                    effect.field;
                if (ImGui::Selectable(
                        variants[index].name.c_str(),
                        selected)) {
                    applyFieldSelection(
                        variants[index].selector);
                    timings.lastColouriseVariantByFamily
                        [catalog[familyIndex].id] =
                        variants[index].id;
                    variantIndex = index;
                }
                if (selected) {
                    ImGui::SetItemDefaultFocus();
                }
            }
            ImGui::EndCombo();
        }
        DrawTimingLabelTooltip(
            "Choose Fine, Medium, Broad, Combined, X, Y, Z, Magnitude, or the available single variant. The chosen variant is remembered per family.");
        auto& boundsStores = water.timingScalarBoundsStores;
        const auto* boundsStore =
            invisible_places::timing::
                FindTimingScalarBoundsStore(
                    std::as_const(boundsStores),
                    effect.field);
        if (ImGui::BeginCombo(
                "Bounds Profile",
                effect.boundsEdited ? "Edited" : "Global")) {
            if (effect.boundsEdited) {
                if (ImGui::Selectable("Edited", true)) {
                    // The live local edit is already active.
                }
                DrawTimingControlTooltip(
                    "This feature's Bounds are a local edit detached from the shared Global bounds for this scalar field.");
            }
            ImGui::BeginDisabled(boundsStore == nullptr);
            if (ImGui::Selectable(
                    "Global",
                    !effect.boundsEdited) &&
                boundsStore != nullptr) {
                effect.baseBounds =
                    boundsStore->globalBounds;
                effect.boundsEdited = false;
                effect.boundsAdoptedGlobalRevision =
                    boundsStore->revision;
                runtimeState
                    ->previewRenderStateSignatureValid =
                    false;
            }
            ImGui::EndDisabled();
            DrawTimingControlTooltip(
                boundsStore == nullptr
                    ? "No feature has published Global bounds for this scalar field yet. Editing any feature's Bounds creates them."
                    : "Adopt and follow the latest edited bounds shared by every feature bound to this scalar field.");
            if (boundsStore != nullptr) {
                for (const auto& profile :
                     boundsStore->profiles) {
                    if (ImGui::Selectable(
                            profile.name.c_str(),
                            false)) {
                        effect.baseBounds =
                            invisible_places::timing::
                                SanitizeTimingColouriseBounds(
                                    profile.bounds);
                        effect.boundsEdited = true;
                        runtimeState
                            ->previewRenderStateSignatureValid =
                            false;
                    }
                    DrawTimingControlTooltip(
                        "Copy this saved bounds state into this feature as a deliberate detached edit. It does not follow later Global changes.");
                }
            }
            ImGui::EndCombo();
        }
        DrawTimingLabelTooltip(
            "Bounds provenance for this scalar field. Global follows the latest edit shared across features, Edited is this feature's detached local state, and named profiles are saved states to reapply.");
        ImGui::SameLine();
        if (ImGui::SmallButton("+##SaveBoundsProfile")) {
            timings.boundsProfileNameBuffer =
                "Bounds " +
                std::to_string(
                    (boundsStore != nullptr
                         ? boundsStore->profiles.size()
                         : 0U) +
                    1U);
            ImGui::OpenPopup("Save Bounds Profile");
        }
        DrawTimingControlTooltip(
            "Save the current Bounds as a named profile for this scalar field so any feature can reapply them.");
        if (ImGui::BeginPopup("Save Bounds Profile")) {
            ImGui::SetNextItemWidth(220.0F);
            InputTextString(
                "Name",
                &timings.boundsProfileNameBuffer);
            const std::string profileName =
                TrimText(timings.boundsProfileNameBuffer);
            const auto equalsIgnoreCase = [](const std::string& value,
                                             const char* reserved) {
                return value.size() == std::strlen(reserved) &&
                       std::equal(
                           value.begin(),
                           value.end(),
                           reserved,
                           [](char a, char b) {
                               return std::tolower(
                                          static_cast<unsigned char>(a)) ==
                                      std::tolower(
                                          static_cast<unsigned char>(b));
                           });
            };
            const bool reservedName =
                equalsIgnoreCase(profileName, "Global") ||
                equalsIgnoreCase(profileName, "Edited");
            if (reservedName) {
                ImGui::TextDisabled(
                    "Global and Edited are built-in states.");
            }
            ImGui::BeginDisabled(profileName.empty() || reservedName);
            if (ImGui::Button("Save") &&
                !profileName.empty() && !reservedName) {
                auto* store =
                    invisible_places::timing::
                        FindTimingScalarBoundsStore(
                            &boundsStores,
                            effect.field);
                if (store == nullptr) {
                    boundsStores.push_back(
                        invisible_places::timing::
                            TimingScalarBoundsStore{
                                .selector = effect.field});
                    store = &boundsStores.back();
                }
                const auto existing = std::find_if(
                    store->profiles.begin(),
                    store->profiles.end(),
                    [&](const auto& candidate) {
                        return candidate.name ==
                               profileName;
                    });
                if (existing != store->profiles.end()) {
                    existing->bounds = effect.baseBounds;
                } else {
                    store->profiles.push_back(
                        {.name = profileName,
                         .bounds = effect.baseBounds});
                }
                runtimeState->statusMessage =
                    "Saved bounds profile " + profileName +
                    ".";
                timings.boundsProfileNameBuffer.clear();
                ImGui::CloseCurrentPopup();
            }
            ImGui::EndDisabled();
            DrawTimingControlTooltip(
                "Save the current Bounds under this name. An existing profile with the same name is replaced.");
            ImGui::EndPopup();
        }
        const auto* histogram =
            EnsureTimingColouriseHistogram(
                runtimeState,
                effect.field);
        const bool spreadAvailable =
            histogram != nullptr &&
            std::isfinite(histogram->data.minimum) &&
            std::isfinite(histogram->data.maximum) &&
            histogram->data.maximum > histogram->data.minimum;
        bool useDistributionSpread =
            histogram != nullptr &&
            timings.spreadColouriseHistogramSignatures.contains(
                histogram->signature);
        ImGui::BeginDisabled(!spreadAvailable);
        if (ImGui::BeginCombo(
                "Histogram Axis",
                useDistributionSpread
                    ? "Distribution Spread"
                    : "Raw Values")) {
            if (ImGui::Selectable(
                    "Raw Values",
                    !useDistributionSpread)) {
                timings.spreadColouriseHistogramSignatures
                    .erase(histogram->signature);
                useDistributionSpread = false;
                timings.activeHistogramHandle =
                    TimingColouriseHistogramHandle::None;
            }
            if (ImGui::Selectable(
                    "Distribution Spread",
                    useDistributionSpread)) {
                timings.spreadColouriseHistogramSignatures
                    .insert(histogram->signature);
                useDistributionSpread = true;
                timings.activeHistogramHandle =
                    TimingColouriseHistogramHandle::None;
            }
            ImGui::EndCombo();
        }
        ImGui::EndDisabled();
        DrawTimingLabelTooltip(
            spreadAvailable
                ? "Raw Values uses the scalar's linear range. Distribution Spread uses the cached 16,384-bin distribution to reveal concentrated detail and give it more mouse resolution. It changes only this editing graph; Bounds keys, rendering, and export stay in raw scalar units."
                : "The editing axis becomes available when this finite, non-constant histogram is ready.");
        DrawTimingColouriseHistogram(
            runtimeState,
            &effect,
            histogram,
            useDistributionSpread
                ? invisible_places::timing::
                      TimingColouriseHistogramAxisMode::
                          DistributionSpread
                : invisible_places::timing::
                      TimingColouriseHistogramAxisMode::Raw);
        DrawTimingColouriseBoundsEditor(
            runtimeState,
            &effect);
    }
    ImGui::SeparatorText("Emissive");
    {
        const bool scalarSource =
            effect.field.source ==
            invisible_places::timing::
                TimingColouriseFieldSource::Scalar;
        const bool onlyEnabledAspect =
            effect.emissiveEnabled &&
            !effect.colouriseEnabled;
        ImGui::BeginDisabled(
            !scalarSource || onlyEnabledAspect);
        bool emissiveEnabled = effect.emissiveEnabled;
        if (ImGui::Checkbox(
                "Emissive##Aspect",
                &emissiveEnabled)) {
            effect.emissiveEnabled = emissiveEnabled;
            effect = invisible_places::timing::
                SanitizeTimingColouriseEffect(effect);
            runtimeState->previewRenderStateSignatureValid =
                false;
        }
        ImGui::EndDisabled();
        DrawTimingControlTooltip(
            !scalarSource
                ? "Emissive output needs a Scalar field source. Normal components cannot drive emission."
            : onlyEnabledAspect
                ? "A Visual Feature needs at least one output aspect."
            : effect.emissiveEnabled
                ? "Disable this feature's emissive output. Its Emissive Level track stays stored but dormant."
                : "Add field-masked emissive output to this feature. A feature with both aspects uses two of the eight renderer slots while active.");
        if (effect.emissiveEnabled) {
            DrawTimingEmissiveLevelEditor(
                runtimeState,
                &effect);
        }
    }
    ImGui::SeparatorText("Colourise");
    {
        const bool onlyEnabledAspect =
            effect.colouriseEnabled &&
            !effect.emissiveEnabled;
        ImGui::BeginDisabled(onlyEnabledAspect);
        bool colouriseEnabled = effect.colouriseEnabled;
        if (ImGui::Checkbox(
                "Colourise##Aspect",
                &colouriseEnabled)) {
            effect.colouriseEnabled = colouriseEnabled;
            effect = invisible_places::timing::
                SanitizeTimingColouriseEffect(effect);
            runtimeState->previewRenderStateSignatureValid =
                false;
        }
        ImGui::EndDisabled();
        DrawTimingControlTooltip(
            onlyEnabledAspect
                ? "A Visual Feature needs at least one output aspect."
            : effect.colouriseEnabled
                ? "Disable this feature's colourise output. Its palette, stops, and keys stay stored but dormant."
                : "Add palette colourise output to this feature. A feature with both aspects uses two of the eight renderer slots while active.");
        if (effect.colouriseEnabled) {
            DrawTimingColourisePaletteEditor(
                runtimeState,
                &effect);
        }
    }
    EndPanelSection();
}

void DrawAuthoredTimingsPanel(
    PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }
    auto& water = runtimeState->water;
    auto& panel = runtimeState->animationPanel;
    auto& timings = runtimeState->timingsPanel;
    if (water.timingTakes.empty() ||
        invisible_places::timing::FindTimingTakeDefinition(
            water.timingTakes,
            invisible_places::timing::kAuthoredTimingTakeId) ==
            nullptr) {
        water.timingTakes.insert(
            water.timingTakes.begin(),
            invisible_places::timing::
                AuthoredTimingTakeDefinition());
    }
    water.selectedTimingTakeId =
        invisible_places::timing::NormalizeTimingTakeId(
            water.selectedTimingTakeId);
    if (invisible_places::timing::FindTimingTakeDefinition(
            water.timingTakes,
            water.selectedTimingTakeId) == nullptr) {
        water.selectedTimingTakeId =
            std::string{
                invisible_places::timing::
                    kAuthoredTimingTakeId};
    }
    auto* animationPath =
        panel.currentPath.has_value()
            ? &panel.currentPath.value()
            : nullptr;
    const auto animationRegistryIndex =
        panel.currentFilePath.empty()
            ? std::nullopt
            : FindAnimationRegistryIndex(
                  panel,
                  std::filesystem::path{panel.currentFilePath});
    const bool readOnlySavedComparison =
        animationRegistryIndex.has_value() &&
        !panel.currentPathUsesEdited &&
        RegistryAnimationHasEditedVersion(
            panel,
            animationRegistryIndex.value());
    std::string selectedTakeId =
        animationPath != nullptr
            ? invisible_places::timing::NormalizeTimingTakeId(
                  animationPath->selectedTimingTakeId)
            : water.selectedTimingTakeId;
    auto* selectedTake =
        invisible_places::timing::FindTimingTakeDefinition(
            &water.timingTakes,
            selectedTakeId);
    if (selectedTake == nullptr) {
        selectedTakeId =
            std::string{
                invisible_places::timing::
                    kAuthoredTimingTakeId};
        water.selectedTimingTakeId = selectedTakeId;
        if (animationPath != nullptr && !readOnlySavedComparison) {
            animationPath->selectedTimingTakeId =
                selectedTakeId;
            panel.dirty = true;
        }
        selectedTake =
            invisible_places::timing::FindTimingTakeDefinition(
                &water.timingTakes,
                selectedTakeId);
    }

    if (BeginPanelSection("Linked Animation")) {
        if (animationPath == nullptr) {
            ImGui::TextDisabled(
                "Load an animation to link a reusable Timing Take. Takes can still be authored below.");
        } else {
            ImGui::Text(
                "%s  (%u frames, %.1f s)",
                animationPath->name.c_str(),
                animationPath->durationFrames,
                std::max(
                    0.0F,
                    AnimationDurationSeconds(
                        *animationPath)));
        }
        if (readOnlySavedComparison) {
            ImGui::TextDisabled(
                "The saved animation is a read-only comparison. Load "
                "_Edited before changing its Timing Take link.");
        }
        ImGui::BeginDisabled(readOnlySavedComparison);
        const char* takePreview =
            selectedTake != nullptr
                ? selectedTake->name.c_str()
                : "Authored Timing";
        if (ImGui::BeginCombo(
                "Timing Take",
                takePreview)) {
            for (const auto& take : water.timingTakes) {
                const bool selected =
                    take.id == selectedTakeId;
                if (ImGui::Selectable(
                        take.name.c_str(),
                        selected)) {
                    water.selectedTimingTakeId = take.id;
                    if (animationPath != nullptr) {
                        animationPath->selectedTimingTakeId =
                            take.id;
                        panel.dirty = true;
                    }
                    timings.selectedFeatureRunIndex.reset();
                    timings.selectedColouriseEffectIndex.reset();
                    timings.selectedColourisePaletteStopIndex.reset();
                    runtimeState->previewRenderStateSignatureValid =
                        false;
                    selectedTakeId = take.id;
                    selectedTake =
                        invisible_places::timing::
                            FindTimingTakeDefinition(
                                &water.timingTakes,
                                take.id);
                }
                if (selected) {
                    ImGui::SetItemDefaultFocus();
                }
            }
            ImGui::EndCombo();
        }
        DrawTimingControlTooltip(
            "Choose the reusable Timing Take linked to this animation. A take starts from authored water and changes only explicit keys.");

        if (ImGui::Button("New")) {
            invisible_places::timing::TimingTakeDefinition take;
            take.id =
                invisible_places::timing::
                    AllocateTimingTakeId(
                        water.timingTakes,
                        &water.nextTimingTakeSequence);
            take.name =
                "Timing Take " +
                std::to_string(
                    water.timingTakes.size());
            water.timingTakes.push_back(take);
            water.selectedTimingTakeId = take.id;
            if (animationPath != nullptr) {
                animationPath->selectedTimingTakeId =
                    take.id;
                panel.dirty = true;
            }
            selectedTakeId = take.id;
            selectedTake =
                &water.timingTakes.back();
        }
        DrawTimingControlTooltip(
            "Create an empty Timing Take that inherits every authored water setting.");
        ImGui::SameLine();
        if (ImGui::Button("Duplicate") &&
            selectedTake != nullptr) {
            auto copy = *selectedTake;
            copy.id =
                invisible_places::timing::
                    AllocateTimingTakeId(
                        water.timingTakes,
                        &water.nextTimingTakeSequence);
            copy.name += " Copy";
            const std::string sourceId = selectedTakeId;
            water.timingTakes.push_back(copy);
            std::vector<
                invisible_places::timing::
                    TimingTakeSceneState>
                copiedStates;
            for (const auto& state :
                 water.timingTakeSceneStates) {
                if (state.takeId == sourceId) {
                    auto duplicated = state;
                    duplicated.takeId = copy.id;
                    copiedStates.push_back(
                        std::move(duplicated));
                }
            }
            water.timingTakeSceneStates.insert(
                water.timingTakeSceneStates.end(),
                std::make_move_iterator(
                    copiedStates.begin()),
                std::make_move_iterator(
                    copiedStates.end()));
            water.selectedTimingTakeId = copy.id;
            if (animationPath != nullptr) {
                animationPath->selectedTimingTakeId =
                    copy.id;
                panel.dirty = true;
            }
            selectedTakeId = copy.id;
            selectedTake =
                &water.timingTakes.back();
        }
        DrawTimingControlTooltip(
            "Duplicate the selected take across all of its scene-specific runs and Colourise / Emissive effects.");
        ImGui::SameLine();
        const bool authoredTake =
            selectedTakeId ==
            invisible_places::timing::
                kAuthoredTimingTakeId;
        ImGui::BeginDisabled(
            authoredTake ||
            selectedTake == nullptr);
        if (ImGui::Button("Delete") &&
            selectedTake != nullptr) {
            std::erase_if(
                water.timingTakes,
                [&](const auto& candidate) {
                    return candidate.id ==
                           selectedTakeId;
                });
            std::erase_if(
                water.timingTakeSceneStates,
                [&](const auto& state) {
                    return state.takeId ==
                           selectedTakeId;
                });
            water.selectedTimingTakeId =
                std::string{
                    invisible_places::timing::
                        kAuthoredTimingTakeId};
            if (animationPath != nullptr) {
                animationPath->selectedTimingTakeId =
                    water.selectedTimingTakeId;
                panel.dirty = true;
            }
            selectedTakeId =
                water.selectedTimingTakeId;
            selectedTake =
                invisible_places::timing::
                    FindTimingTakeDefinition(
                        &water.timingTakes,
                        selectedTakeId);
            timings.selectedFeatureRunIndex.reset();
            timings.selectedColouriseEffectIndex.reset();
        }
        ImGui::EndDisabled();
        DrawTimingControlTooltip(
            authoredTake
                ? "Authored Timing is reserved and cannot be deleted."
                : "Delete this Timing Take and every scene-specific run and scalar effect it owns.");
        if (selectedTake != nullptr) {
            ImGui::BeginDisabled(authoredTake);
            InputTextString(
                "Take Name",
                &selectedTake->name);
            ImGui::EndDisabled();
            DrawTimingControlTooltip(
                authoredTake
                    ? "The reserved Authored Timing take keeps its fixed name."
                    : "Rename the selected Timing Take.");
        }
        ImGui::EndDisabled();
        EndPanelSection();
    }

    DrawWaterFeatureRunsSection(runtimeState);
    DrawTimingColouriseSection(runtimeState);

    if (BeginPanelSection("Save")) {
        if (panel.currentPath.has_value() &&
            ImGui::Button("Save Animation##Timings")) {
            RequestSaveChangesDialog(
                runtimeState,
                SaveChangesRequest::Animation);
        }
        DrawTimingControlTooltip(
            "Save the animation camera path and its Timing Take selection. Runs, Colourise / Emissive effects, and saved palettes are stored with the project.");
        if (panel.dirty) {
            ImGui::SameLine();
            ImGui::TextDisabled("_Edited");
        }
        EndPanelSection();
    }
    SyncCurrentAnimationToRegistry(runtimeState);
}

// Key markers for one feature's setting tracks under the global bar. One
// colour per setting. The two-stage double-click gesture prevents an
// accidental time edit: first jump the global position to the marker, then
// double-click it again to open the normalized-position editor.
void DrawWaterKeyMarkerStrip(
    PreviewRuntimeState* runtimeState,
    const invisible_places::water::WaterFeatureTimingRun& run,
    const invisible_places::water::WaterFeatureTimeline& timeline,
    ImVec2 barMin,
    ImVec2 barMax) {
    // One palette with the Timings-tab run graphs so a setting keeps its
    // colour between the top bar and the run timeline.
    const auto& kSettingColours = kWaterKeyedSettingColours;
    const float barWidth = std::max(1.0F, barMax.x - barMin.x);
    constexpr float kStripHeight = 9.0F;
    ImGui::SetCursorScreenPos(ImVec2{barMin.x, barMax.y + 2.0F});
    ImGui::InvisibleButton(
        "##WaterKeyMarkerStrip",
        ImVec2{barWidth, kStripHeight});
    const bool hovered = ImGui::IsItemHovered();
    const float mouseX = ImGui::GetIO().MousePos.x;
    auto* drawList = ImGui::GetWindowDrawList();
    const float stripTop = barMax.y + 2.0F;

    struct NearestKey {
        float distance = 1.0e9F;
        float position = 0.0F;
        std::size_t settingIndex = 0U;
        std::size_t keyNumber = 0U;
        float value = 0.0F;
    };
    NearestKey nearest;
    for (std::size_t settingIndex = 0U;
         settingIndex < timeline.settings.size();
         ++settingIndex) {
        const auto& setting = timeline.settings[settingIndex];
        if (!setting.active) {
            continue;
        }
        auto ordered = setting.keys;
        std::stable_sort(
            ordered.begin(),
            ordered.end(),
            [](const auto& left, const auto& right) {
                return left.position < right.position;
            });
        const auto colour =
            kSettingColours[settingIndex % kSettingColours.size()];
        for (std::size_t keyIndex = 0U; keyIndex < ordered.size();
             ++keyIndex) {
            const auto& key = ordered[keyIndex];
            const float x = barMin.x + barWidth * key.position;
            drawList->AddRectFilled(
                ImVec2{x - 1.5F, stripTop},
                ImVec2{x + 1.5F, stripTop + kStripHeight},
                colour);
            if (hovered) {
                const float distance = std::abs(mouseX - x);
                if (distance < nearest.distance) {
                    nearest = {
                        .distance = distance,
                        .position = key.position,
                        .settingIndex = settingIndex,
                        .keyNumber = keyIndex + 1U,
                        .value = key.value,
                    };
                }
            }
        }
    }
    if (hovered && nearest.distance <= 6.0F) {
        const auto& setting = timeline.settings[nearest.settingIndex];
        const auto* info = invisible_places::water::FindWaterKeyableSetting(
            timeline.feature.kind,
            setting.settingId);
        const char* settingLabel =
            !setting.label.empty()
                ? setting.label.c_str()
                : info != nullptr
                      ? info->label
                      : setting.settingId.c_str();
        const float durationSeconds =
            runtimeState->animationPanel.currentPath.has_value()
                ? std::max(
                      0.0F,
                      AnimationDurationSeconds(
                          runtimeState->animationPanel.currentPath.value()))
                : 0.0F;
        const bool positionIsOnKey =
            std::abs(
                runtimeState->animationPanel.scrubAmount -
                nearest.position) <= 1.0e-4F;
        ImGui::SetTooltip(
            positionIsOnKey
                ? "%s %zu — %s = %.3f at %.2f s (double-click to edit position)"
                : "%s %zu — %s = %.3f at %.2f s (double-click to jump)",
            run.name.c_str(),
            nearest.keyNumber,
            settingLabel,
            nearest.value,
            nearest.position * durationSeconds);
        if (ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
            if (positionIsOnKey) {
                runtimeState->animationPanel.waterKeyPositionEdit =
                    WaterKeyPositionEditState{
                        .runId = run.id,
                        .feature = timeline.feature,
                        .settingId = setting.settingId,
                        .sourcePosition = nearest.position,
                        .draftPosition = nearest.position,
                        .requestKeyboardFocus = true,
                    };
                ImGui::OpenPopup("Edit Water Key Position");
            } else {
                runtimeState->animationPanel.scrubAmount =
                    nearest.position;
                ApplyAnimationScrub(runtimeState);
            }
        }
    }

    bool closeEditor = false;
    if (ImGui::BeginPopup("Edit Water Key Position")) {
        auto& edit =
            runtimeState->animationPanel.waterKeyPositionEdit;
        if (!edit.has_value() || edit->runId != run.id ||
            edit->feature != timeline.feature) {
            ImGui::CloseCurrentPopup();
            closeEditor = true;
        } else {
            const auto settingIt = std::find_if(
                timeline.settings.begin(),
                timeline.settings.end(),
                [&](const auto& candidate) {
                    return candidate.settingId == edit->settingId;
                });
            const auto* settingInfo =
                invisible_places::water::FindWaterKeyableSetting(
                    timeline.feature.kind,
                    edit->settingId);
            ImGui::TextUnformatted(
                settingIt != timeline.settings.end() &&
                        !settingIt->label.empty()
                    ? settingIt->label.c_str()
                    : settingInfo != nullptr
                          ? settingInfo->label
                          : edit->settingId.c_str());
            ImGui::TextDisabled("Enter a normalized position from 0 to 1.");
            ImGui::SetNextItemWidth(180.0F);
            if (edit->requestKeyboardFocus) {
                ImGui::SetKeyboardFocusHere();
                edit->requestKeyboardFocus = false;
            }
            // InputScalar deliberately rejects EnterReturnsTrue in this
            // ImGui version. Submission stays explicit through Apply while
            // the numeric field remains fully keyboard-editable.
            ImGui::InputFloat(
                "##WaterKeyNormalizedPosition",
                &edit->draftPosition,
                0.001F,
                0.01F,
                "%.4f",
                ImGuiInputTextFlags_None);
            bool applyRequested = false;
            const bool validPosition =
                std::isfinite(edit->draftPosition) &&
                edit->draftPosition >= 0.0F &&
                edit->draftPosition <= 1.0F;
            constexpr float kKeyTolerance = 1.0e-4F;
            const bool destinationOccupied =
                settingIt != timeline.settings.end() &&
                std::any_of(
                    settingIt->keys.begin(),
                    settingIt->keys.end(),
                    [&](const auto& candidate) {
                        return std::abs(
                                   candidate.position -
                                   edit->sourcePosition) >
                                   kKeyTolerance &&
                               std::abs(
                                   candidate.position -
                                   edit->draftPosition) <=
                                   kKeyTolerance;
                    });
            if (!validPosition) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "Position must be between 0 and 1.");
            } else if (destinationOccupied) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "That setting already has a key at this position.");
            } else if (!edit->errorMessage.empty()) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "%s",
                    edit->errorMessage.c_str());
            }

            ImGui::BeginDisabled(
                !validPosition || destinationOccupied ||
                settingIt == timeline.settings.end());
            applyRequested |= ImGui::Button("Apply");
            ImGui::EndDisabled();
            ImGui::SameLine();
            if (ImGui::Button("Cancel")) {
                ImGui::CloseCurrentPopup();
                closeEditor = true;
            }

            if (applyRequested && validPosition &&
                !destinationOccupied &&
                settingIt != timeline.settings.end()) {
                auto& water = runtimeState->water;
                const auto scenarioId =
                    ActiveWaterTimingScenarioId(*runtimeState);
                auto* mutableTrack =
                    FindMutableWaterSettingTrack(
                        &water,
                        scenarioId,
                        edit->feature,
                        edit->settingId);
                if (invisible_places::water::MoveWaterSettingKey(
                        mutableTrack,
                        edit->sourcePosition,
                        edit->draftPosition)) {
                    runtimeState->animationPanel.scrubAmount =
                        edit->draftPosition;
                    ApplyAnimationScrub(runtimeState);
                    InvalidateWaterSeepageParams(&water);
                    runtimeState->previewRenderStateSignatureValid =
                        false;
                    runtimeState->statusMessage =
                        "Moved water key to position " +
                        FormatFixed(edit->draftPosition, 4) + ".";
                    runtimeState->errorMessage.clear();
                    ImGui::CloseCurrentPopup();
                    closeEditor = true;
                } else {
                    edit->errorMessage =
                        "The key could not be moved; it may have changed.";
                }
            }
        }
        ImGui::EndPopup();
    }
    if (closeEditor ||
        !ImGui::IsPopupOpen("Edit Water Key Position")) {
        runtimeState->animationPanel.waterKeyPositionEdit.reset();
    }
}

void DrawTimingColouriseGlobalMarkerLanes(
    PreviewRuntimeState* runtimeState,
    invisible_places::timing::TimingColouriseEffect* effect,
    ImVec2 barMin,
    ImVec2 barMax) {
    if (runtimeState == nullptr || effect == nullptr) {
        return;
    }
    struct Lane {
        const char* id;
        const char* label;
        TimingColouriseKeyTrack track;
        ImU32 colour;
        std::vector<float> positions;
    };
    const bool emissive = TimingEffectIsEmissive(*effect);
    Lane bounds{
        .id = "##GlobalTimingBoundsLane",
        .label = "Bounds",
        .track = TimingColouriseKeyTrack::Bounds,
        .colour = IM_COL32(102, 187, 227, 255),
    };
    Lane controls{
        .id = "##GlobalTimingColouriseControlsLane",
        .label = emissive ? "Emissive Level" : "Controls",
        .track = TimingColouriseKeyTrack::EffectParameter,
        .colour = IM_COL32(238, 174, 72, 255),
    };
    const auto appendParameterPositions =
        [&](invisible_places::timing::TimingColouriseEffectParameter
                parameter) {
            auto positions = invisible_places::timing::
                TimingColouriseEffectParameterKeyPositions(
                    *effect,
                    parameter);
            controls.positions.insert(
                controls.positions.end(),
                positions.begin(),
                positions.end());
        };
    if (emissive) {
        appendParameterPositions(
            invisible_places::timing::
                TimingColouriseEffectParameter::EmissiveLevel);
    } else {
        appendParameterPositions(
            invisible_places::timing::
                TimingColouriseEffectParameter::AmountOverride);
        appendParameterPositions(
            invisible_places::timing::
                TimingColouriseEffectParameter::PalettePhase);
    }
    for (const auto& key : effect->boundsKeys) {
        bounds.positions.push_back(key.position);
    }
    for (const auto& key : effect->boundsParameterKeys) {
        bounds.positions.push_back(key.position);
    }
    const auto sortUniquePositions = [](std::vector<float>* positions) {
        std::stable_sort(positions->begin(), positions->end());
        positions->erase(
            std::unique(
                positions->begin(),
                positions->end(),
                [](float left, float right) {
                    return std::abs(left - right) <=
                           invisible_places::timing::
                               kTimingColouriseKeyTolerance;
                }),
            positions->end());
    };
    sortUniquePositions(&bounds.positions);
    sortUniquePositions(&controls.positions);
    std::vector<Lane> lanes;
    lanes.reserve(emissive ? 2U : 3U);
    if (!emissive) {
        Lane palette{
            .id = "##GlobalTimingPaletteLane",
            .label = "Palette",
            .track = TimingColouriseKeyTrack::Palette,
            .colour = IM_COL32(222, 134, 190, 255),
            .positions = invisible_places::timing::
                TimingColourisePaletteKeyPositions(*effect),
        };
        lanes.push_back(std::move(palette));
    }
    lanes.push_back(std::move(controls));
    lanes.push_back(std::move(bounds));
    const float width = std::max(1.0F, barMax.x - barMin.x);
    const auto activation = invisible_places::timing::
        SanitizeTimingColouriseActivationRange(
            effect->activationRange);
    constexpr float kLaneHeight = 9.0F;
    constexpr float kLaneGap = 2.0F;
    const float mouseX = ImGui::GetIO().MousePos.x;
    for (std::size_t laneIndex = 0U;
         laneIndex < lanes.size();
         ++laneIndex) {
        auto& lane = lanes[laneIndex];
        const float top =
            barMax.y + kLaneGap +
            static_cast<float>(laneIndex) *
                (kLaneHeight + kLaneGap);
        ImGui::SetCursorScreenPos(
            ImVec2{barMin.x, top});
        ImGui::InvisibleButton(
            lane.id,
            ImVec2{width, kLaneHeight});
        const bool hovered = ImGui::IsItemHovered();
        auto* drawList = ImGui::GetWindowDrawList();
        const float activationStartX =
            barMin.x + width * activation.start;
        const float activationEndX =
            barMin.x + width * activation.end;
        drawList->AddRectFilled(
            ImVec2{activationStartX, top + 2.0F},
            ImVec2{activationEndX, top + kLaneHeight - 1.0F},
            effect->enabled
                ? IM_COL32(88, 158, 208, 42)
                : IM_COL32(128, 128, 128, 24),
            1.0F);
        for (const float boundaryX :
             {activationStartX, activationEndX}) {
            drawList->AddLine(
                ImVec2{boundaryX, top + 1.0F},
                ImVec2{boundaryX, top + kLaneHeight - 1.0F},
                effect->enabled
                    ? IM_COL32(110, 178, 220, 110)
                    : IM_COL32(128, 128, 128, 66),
                1.0F);
        }
        drawList->AddText(
            ImVec2{barMin.x + 3.0F, top - 1.0F},
            ImGui::GetColorU32(ImGuiCol_TextDisabled),
            lane.label);
        float nearestDistance =
            std::numeric_limits<float>::max();
        float nearestPosition = 0.0F;
        for (const float keyPosition : lane.positions) {
            const float x =
                barMin.x +
                width *
                    std::clamp(keyPosition, 0.0F, 1.0F);
            auto markerColour = lane.colour;
            if (!invisible_places::timing::
                    TimingColouriseActivationRangeContains(
                        activation,
                        keyPosition)) {
                auto dimmed =
                    ImGui::ColorConvertU32ToFloat4(
                        markerColour);
                dimmed.w *= 0.32F;
                markerColour =
                    ImGui::ColorConvertFloat4ToU32(
                        dimmed);
            }
            drawList->AddRectFilled(
                ImVec2{x - 1.75F, top},
                ImVec2{x + 1.75F, top + kLaneHeight},
                markerColour);
            const float distance =
                std::abs(mouseX - x);
            if (distance < nearestDistance) {
                nearestDistance = distance;
                nearestPosition = keyPosition;
            }
        }
        if (hovered && nearestDistance <= 6.0F) {
            const bool onKey =
                std::abs(
                    runtimeState->animationPanel.scrubAmount -
                    nearestPosition) <=
                invisible_places::timing::
                    kTimingColouriseKeyTolerance;
            ImGui::SetTooltip(
                onKey
                    ? "%s key at %.4f (double-click to edit position)"
                    : "%s key at %.4f (double-click to jump)",
                lane.label,
                nearestPosition);
            if (ImGui::IsMouseDoubleClicked(
                    ImGuiMouseButton_Left)) {
                if (onKey) {
                    runtimeState->animationPanel
                        .timingColouriseKeyPositionEdit =
                        TimingColouriseKeyPositionEditState{
                            .effectId = effect->id,
                            .track = lane.track,
                            .sourcePosition =
                                nearestPosition,
                            .draftPosition =
                                nearestPosition,
                            .requestKeyboardFocus =
                                true,
                        };
                    ImGui::OpenPopup(
                        "Edit Effect Key Position");
                } else {
                    runtimeState->animationPanel.scrubAmount =
                        nearestPosition;
                    ApplyAnimationScrub(runtimeState);
                }
            }
        } else if (hovered) {
            const float startDistance =
                std::abs(mouseX - activationStartX);
            const float endDistance =
                std::abs(mouseX - activationEndX);
            if (std::min(startDistance, endDistance) <=
                5.0F) {
                ImGui::SetTooltip(
                    "%s activation boundary at %.4f (derived, not a key). Edit it in the Activation overview.",
                    startDistance <= endDistance
                        ? "Start"
                        : "End",
                    startDistance <= endDistance
                        ? activation.start
                        : activation.end);
            }
        }
    }

    bool closeEditor = false;
    if (ImGui::BeginPopup(
            "Edit Effect Key Position")) {
        auto& edit = runtimeState->animationPanel
                         .timingColouriseKeyPositionEdit;
        if (!edit.has_value() ||
            edit->effectId != effect->id) {
            ImGui::CloseCurrentPopup();
            closeEditor = true;
        } else {
            ImGui::TextUnformatted(
                edit->track ==
                        TimingColouriseKeyTrack::Palette
                    ? "Palette key"
                : edit->track ==
                          TimingColouriseKeyTrack::EffectParameter
                    ? emissive
                          ? "Emissive Level key"
                          : "Colourise control key"
                    : "Bounds key");
            ImGui::TextDisabled(
                "Enter a normalized position from 0 to 1.");
            ImGui::SetNextItemWidth(180.0F);
            if (edit->requestKeyboardFocus) {
                ImGui::SetKeyboardFocusHere();
                edit->requestKeyboardFocus = false;
            }
            // InputFloat routes through InputScalar in this ImGui version,
            // where EnterReturnsTrue is explicitly unsupported.
            ImGui::InputFloat(
                "##EffectKeyNormalizedPosition",
                &edit->draftPosition,
                0.001F,
                0.01F,
                "%.4f",
                ImGuiInputTextFlags_None);
            const bool valid =
                std::isfinite(edit->draftPosition) &&
                edit->draftPosition >= 0.0F &&
                edit->draftPosition <= 1.0F;
            const auto occupied =
                [&](float position) {
                    if (edit->track ==
                        TimingColouriseKeyTrack::Palette) {
                        return !invisible_places::timing::
                                    CanMoveTimingColourisePaletteKeysAtPosition(
                                        *effect,
                                        edit->sourcePosition,
                                        position);
                    }
                    if (edit->track ==
                        TimingColouriseKeyTrack::EffectParameter) {
                        if (emissive) {
                            if (std::abs(
                                    position -
                                    edit->sourcePosition) <=
                                invisible_places::timing::
                                    kTimingColouriseKeyTolerance) {
                                return false;
                            }
                            return invisible_places::timing::
                                       TimingColouriseEffectParameterKeyCountAtPosition(
                                           *effect,
                                           invisible_places::timing::
                                               TimingColouriseEffectParameter::EmissiveLevel,
                                           position) > 0U;
                        }
                        return !invisible_places::timing::
                                    CanMoveTimingColouriseEffectParameterKeysAtPosition(
                                        *effect,
                                        edit->sourcePosition,
                                        position);
                    }
                    return std::abs(
                               position -
                               edit->sourcePosition) >
                               invisible_places::timing::
                                   kTimingColouriseKeyTolerance &&
                           invisible_places::timing::
                               TimingColouriseBoundsKeyCountAtPosition(
                                   *effect,
                                   position) > 0U;
                };
            const bool destinationOccupied =
                valid && occupied(edit->draftPosition);
            if (!valid) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "Position must be between 0 and 1.");
            } else if (destinationOccupied) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "This track already has a key there.");
            } else if (!edit->errorMessage.empty()) {
                ImGui::TextColored(
                    ImVec4{1.0F, 0.45F, 0.35F, 1.0F},
                    "%s",
                    edit->errorMessage.c_str());
            }
            ImGui::BeginDisabled(
                !valid || destinationOccupied);
            const bool apply =
                ImGui::Button("Apply");
            ImGui::EndDisabled();
            ImGui::SameLine();
            if (ImGui::Button("Cancel")) {
                ImGui::CloseCurrentPopup();
                closeEditor = true;
            }
            if (apply && valid &&
                !destinationOccupied) {
                const bool moved =
                    edit->track ==
                            TimingColouriseKeyTrack::Palette
                        ? invisible_places::timing::
                              MoveTimingColourisePaletteKey(
                                  effect,
                                  edit->sourcePosition,
                                  edit->draftPosition)
                    : edit->track ==
                              TimingColouriseKeyTrack::EffectParameter
                        ? emissive
                              ? invisible_places::timing::
                                    MoveTimingColouriseEffectParameterKey(
                                        effect,
                                        invisible_places::timing::
                                            TimingColouriseEffectParameter::EmissiveLevel,
                                        edit->sourcePosition,
                                        edit->draftPosition)
                              : invisible_places::timing::
                                    MoveTimingColouriseEffectParameterKeys(
                                        effect,
                                        edit->sourcePosition,
                                        edit->draftPosition)
                        : invisible_places::timing::
                              MoveTimingColouriseBoundsKey(
                                  effect,
                                  edit->sourcePosition,
                                  edit->draftPosition);
                if (moved) {
                    runtimeState->animationPanel.scrubAmount =
                        edit->draftPosition;
                    ApplyAnimationScrub(runtimeState);
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                    ImGui::CloseCurrentPopup();
                    closeEditor = true;
                } else {
                    edit->errorMessage =
                        "The key could not be moved; it may have changed.";
                }
            }
        }
        ImGui::EndPopup();
    }
    if (closeEditor ||
        !ImGui::IsPopupOpen(
            "Edit Effect Key Position")) {
        runtimeState->animationPanel
            .timingColouriseKeyPositionEdit.reset();
    }
}

std::vector<float> TimingEffectRelevantKeyPositions(
    const invisible_places::timing::TimingColouriseEffect& effect) {
    std::vector<float> positions;
    const auto append = [&](std::span<const float> source) {
        positions.insert(
            positions.end(),
            source.begin(),
            source.end());
    };
    // Aspects are independent: a combined feature contributes both its
    // emissive and colourise key tracks to the transport bar.
    if (effect.emissiveEnabled) {
        const auto emissivePositions = invisible_places::timing::
            TimingColouriseEffectParameterKeyPositions(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::EmissiveLevel);
        append(emissivePositions);
    }
    if (effect.colouriseEnabled) {
        const auto palettePositions = invisible_places::timing::
            TimingColourisePaletteKeyPositions(effect);
        const auto amountPositions = invisible_places::timing::
            TimingColouriseEffectParameterKeyPositions(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::AmountOverride);
        const auto phasePositions = invisible_places::timing::
            TimingColouriseEffectParameterKeyPositions(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::PalettePhase);
        append(palettePositions);
        append(amountPositions);
        append(phasePositions);
    }
    for (const auto& key : effect.boundsKeys) {
        positions.push_back(key.position);
    }
    for (const auto& key : effect.boundsParameterKeys) {
        positions.push_back(key.position);
    }
    std::stable_sort(positions.begin(), positions.end());
    positions.erase(
        std::unique(
            positions.begin(),
            positions.end(),
            [](float left, float right) {
                return std::abs(left - right) <=
                       invisible_places::timing::
                           kTimingColouriseKeyTolerance;
            }),
        positions.end());
    return positions;
}

std::size_t TimingEffectRelevantKeyCountAtPosition(
    const invisible_places::timing::TimingColouriseEffect& effect,
    float position) {
    std::size_t count = invisible_places::timing::
        TimingColouriseBoundsKeyCountAtPosition(
            effect,
            position);
    if (effect.emissiveEnabled) {
        count += invisible_places::timing::
            TimingColouriseEffectParameterKeyCountAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::EmissiveLevel,
                position);
    }
    if (effect.colouriseEnabled) {
        count += invisible_places::timing::
            TimingColourisePaletteKeyCountAtPosition(
                effect,
                position);
        count += invisible_places::timing::
            TimingColouriseEffectParameterKeyCountAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::AmountOverride,
                position);
        count += invisible_places::timing::
            TimingColouriseEffectParameterKeyCountAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::PalettePhase,
                position);
    }
    return count;
}

std::size_t RemoveTimingEffectRelevantKeysAtPosition(
    invisible_places::timing::TimingColouriseEffect* effect,
    float position) {
    if (effect == nullptr) {
        return 0U;
    }
    std::size_t removed = invisible_places::timing::
        RemoveTimingColouriseBoundsKeysAtPosition(
            effect,
            position);
    if (effect->emissiveEnabled) {
        removed += invisible_places::timing::
            RemoveTimingColouriseEffectParameterKeysAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::EmissiveLevel,
                position);
    }
    if (effect->colouriseEnabled) {
        removed += invisible_places::timing::
            RemoveTimingColourisePaletteKeysAtPosition(
                effect,
                position);
        removed += invisible_places::timing::
            RemoveTimingColouriseEffectParameterKeysAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::AmountOverride,
                position);
        removed += invisible_places::timing::
            RemoveTimingColouriseEffectParameterKeysAtPosition(
                effect,
                invisible_places::timing::
                    TimingColouriseEffectParameter::PalettePhase,
                position);
    }
    return removed;
}

void DrawAnimationTimelineViewBoundsOverlay(
    invisible_places::timing::TimelineViewRange range,
    ImVec2 barMin,
    ImVec2 barMax) {
    range = invisible_places::timing::SanitizeTimelineViewRange(range);
    if (invisible_places::timing::TimelineViewRangeIsFull(range)) {
        return;
    }
    const float width = std::max(1.0F, barMax.x - barMin.x);
    const float startX = barMin.x + width * range.start;
    const float endX = barMin.x + width * range.end;
    auto* drawList = ImGui::GetWindowDrawList();
    drawList->AddRectFilled(
        barMin,
        ImVec2{startX, barMax.y},
        IM_COL32(0, 0, 0, 76));
    drawList->AddRectFilled(
        ImVec2{endX, barMin.y},
        barMax,
        IM_COL32(0, 0, 0, 76));
    const ImU32 boundaryColour = IM_COL32(245, 185, 82, 225);
    drawList->AddLine(
        ImVec2{startX, barMin.y},
        ImVec2{startX, barMax.y},
        boundaryColour,
        1.5F);
    drawList->AddLine(
        ImVec2{endX, barMin.y},
        ImVec2{endX, barMax.y},
        boundaryColour,
        1.5F);
}

bool DrawAnimationTimelineViewRangeSelector(
    PreviewRuntimeState* runtimeState,
    float durationSeconds) {
    if (runtimeState == nullptr) {
        return false;
    }
    auto& panel = runtimeState->animationPanel;
    panel.timelineViewRange =
        invisible_places::timing::SanitizeTimelineViewRange(
            panel.timelineViewRange);
    bool changed = false;

    ImGui::PushID("AnimationTimelineViewRange");
    const bool fullRange =
        invisible_places::timing::TimelineViewRangeIsFull(
            panel.timelineViewRange);
    const std::string rangeLabel =
        durationSeconds > 0.0F
            ? FormatFixed(
                  panel.timelineViewRange.start * durationSeconds,
                  2) +
                  "s - " +
                  FormatFixed(
                      panel.timelineViewRange.end * durationSeconds,
                      2) +
                  "s"
            : FormatFixed(panel.timelineViewRange.start, 4) +
                  " - " +
                  FormatFixed(panel.timelineViewRange.end, 4);
    ImGui::AlignTextToFramePadding();
    ImGui::TextDisabled(
        "Feature Run View: %s%s",
        fullRange ? "Full animation, " : "",
        rangeLabel.c_str());
    const float fullButtonWidth =
        ImGui::CalcTextSize("Full").x +
        ImGui::GetStyle().FramePadding.x * 2.0F;
    ImGui::SameLine();
    ImGui::SetCursorPosX(std::max(
        ImGui::GetCursorPosX(),
        ImGui::GetWindowContentRegionMax().x - fullButtonWidth));
    ImGui::BeginDisabled(fullRange);
    if (ImGui::SmallButton("Full")) {
        panel.timelineViewRange = {};
        panel.timelineViewDrag.reset();
        changed = true;
    }
    ImGui::EndDisabled();

    constexpr float kSelectorHeight = 14.0F;
    const ImVec2 size{
        std::max(24.0F, ImGui::GetContentRegionAvail().x),
        kSelectorHeight};
    ImGui::InvisibleButton(
        "##FeatureRunViewRange",
        size,
        ImGuiButtonFlags_MouseButtonLeft);
    const ImVec2 minimum = ImGui::GetItemRectMin();
    const ImVec2 maximum = ImGui::GetItemRectMax();
    const float width = std::max(1.0F, maximum.x - minimum.x);
    const float mouseX = ImGui::GetIO().MousePos.x;
    const auto overviewPositionForX = [&](float x) {
        return std::clamp((x - minimum.x) / width, 0.0F, 1.0F);
    };

    if (ImGui::IsItemHovered()) {
        const float startX =
            minimum.x + width * panel.timelineViewRange.start;
        const float endX =
            minimum.x + width * panel.timelineViewRange.end;
        constexpr float kHandleHitRadius = 7.0F;
        if (std::min(
                std::abs(mouseX - startX),
                std::abs(mouseX - endX)) <= kHandleHitRadius) {
            ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);
        } else if (mouseX >= startX && mouseX <= endX) {
            ImGui::SetMouseCursor(ImGuiMouseCursor_Hand);
        }
    }

    if (ImGui::IsItemHovered() &&
        ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left)) {
        if (!fullRange) {
            panel.timelineViewRange = {};
            changed = true;
        }
        panel.timelineViewDrag.reset();
    } else if (ImGui::IsItemActivated()) {
        const float startX =
            minimum.x + width * panel.timelineViewRange.start;
        const float endX =
            minimum.x + width * panel.timelineViewRange.end;
        const float startDistance = std::abs(mouseX - startX);
        const float endDistance = std::abs(mouseX - endX);
        constexpr float kHandleHitRadius = 7.0F;
        AnimationTimelineViewDragPart part =
            AnimationTimelineViewDragPart::Body;
        if (std::min(startDistance, endDistance) <=
            kHandleHitRadius) {
            part = startDistance <= endDistance
                       ? AnimationTimelineViewDragPart::Start
                       : AnimationTimelineViewDragPart::End;
        } else if (mouseX < startX) {
            part = AnimationTimelineViewDragPart::Start;
        } else if (mouseX > endX) {
            part = AnimationTimelineViewDragPart::End;
        }
        panel.timelineViewDrag = AnimationTimelineViewDragState{
            .part = part,
            .mouseStartX = mouseX,
            .originalRange = panel.timelineViewRange,
        };
    }

    if (panel.timelineViewDrag.has_value() &&
        ImGui::IsItemActive() &&
        ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        const auto& drag = panel.timelineViewDrag.value();
        auto candidate = panel.timelineViewRange;
        switch (drag.part) {
            case AnimationTimelineViewDragPart::Start:
                candidate.start = std::clamp(
                    overviewPositionForX(mouseX),
                    0.0F,
                    candidate.end -
                        invisible_places::timing::
                            kMinimumTimelineViewSpan);
                break;
            case AnimationTimelineViewDragPart::End:
                candidate.end = std::clamp(
                    overviewPositionForX(mouseX),
                    candidate.start +
                        invisible_places::timing::
                            kMinimumTimelineViewSpan,
                    1.0F);
                break;
            case AnimationTimelineViewDragPart::Body: {
                const float span =
                    drag.originalRange.end -
                    drag.originalRange.start;
                const float delta =
                    (mouseX - drag.mouseStartX) / width;
                candidate.start = std::clamp(
                    drag.originalRange.start + delta,
                    0.0F,
                    1.0F - span);
                candidate.end = candidate.start + span;
                break;
            }
        }
        candidate =
            invisible_places::timing::SanitizeTimelineViewRange(
                candidate);
        if (std::abs(
                candidate.start -
                panel.timelineViewRange.start) >
                std::numeric_limits<float>::epsilon() ||
            std::abs(
                candidate.end -
                panel.timelineViewRange.end) >
                std::numeric_limits<float>::epsilon()) {
            panel.timelineViewRange = candidate;
            changed = true;
        }
    }
    if (!ImGui::IsMouseDown(ImGuiMouseButton_Left)) {
        panel.timelineViewDrag.reset();
    }

    auto* drawList = ImGui::GetWindowDrawList();
    drawList->AddRectFilled(
        minimum,
        maximum,
        ImGui::GetColorU32(ImGuiCol_FrameBg),
        2.0F);
    const float startX =
        minimum.x + width * panel.timelineViewRange.start;
    const float endX =
        minimum.x + width * panel.timelineViewRange.end;
    ImVec4 fill =
        ImGui::GetStyleColorVec4(ImGuiCol_SliderGrabActive);
    fill.w *= 0.42F;
    drawList->AddRectFilled(
        ImVec2{startX, minimum.y},
        ImVec2{endX, maximum.y},
        ImGui::ColorConvertFloat4ToU32(fill),
        2.0F);
    drawList->AddRect(
        minimum,
        maximum,
        ImGui::GetColorU32(ImGuiCol_Border),
        2.0F);
    const ImU32 handleColour =
        ImGui::GetColorU32(ImGuiCol_SliderGrabActive);
    drawList->AddLine(
        ImVec2{startX, minimum.y},
        ImVec2{startX, maximum.y},
        handleColour,
        2.0F);
    drawList->AddLine(
        ImVec2{endX, minimum.y},
        ImVec2{endX, maximum.y},
        handleColour,
        2.0F);
    const float playheadX =
        minimum.x +
        width * std::clamp(panel.scrubAmount, 0.0F, 1.0F);
    drawList->AddLine(
        ImVec2{playheadX, minimum.y + 2.0F},
        ImVec2{playheadX, maximum.y - 2.0F},
        IM_COL32(18, 18, 18, 230),
        1.0F);

    if (ImGui::IsItemHovered()) {
        ImGui::SetTooltip(
            "Drag either end to zoom Feature Run timelines; drag the highlighted middle to pan.\nDouble-click or press Full to reset. Stored key times, playback, and exports remain unchanged.");
    }
    ImGui::PopID();

    if (changed) {
        runtimeState->timingsPanel.waterRunKeyDrag.reset();
    }
    return changed;
}

// The persistent Animation Position row above the controls tabs: scrubbing
// here always repositions the camera (and every keyed water setting follows
// the frame resolve), and the marker strip below shows the keys of the
// feature the user is focused on in the Water tab.
// Resolves the colour and value frame for one pinned setting the same way
// BuildWaterFeatureGraphSeries does for the split run graphs, so a pinned
// curve keeps the setting's colour from the Timings list and run graphs.
struct PinnedWaterSettingSeries {
    ImU32 colour = IM_COL32_WHITE;
    float minimum = 0.0F;
    float maximum = 1.0F;
    const invisible_places::water::WaterKeyedSettingTrack* track = nullptr;
};

std::optional<PinnedWaterSettingSeries> ResolvePinnedWaterSettingSeries(
    const invisible_places::water::WaterFeatureTimeline& timeline,
    std::string_view settingId) {
    const auto trackFor =
        [&](std::string_view id)
        -> const invisible_places::water::WaterKeyedSettingTrack* {
        for (const auto& setting : timeline.settings) {
            if (setting.settingId == id) {
                return &setting;
            }
        }
        return nullptr;
    };
    std::size_t settingIndex = 0U;
    for (const auto& info :
         invisible_places::water::WaterKeyableSettings(
             timeline.feature.kind)) {
        const auto* track = trackFor(info.id);
        if (!info.showUnauthoredInTimeline && track == nullptr) {
            continue;
        }
        if (settingId == info.id) {
            return PinnedWaterSettingSeries{
                .colour = kWaterKeyedSettingColours[
                    settingIndex % kWaterKeyedSettingColours.size()],
                .minimum = info.minimum,
                .maximum = info.maximum,
                .track = track,
            };
        }
        ++settingIndex;
    }
    for (const auto& setting : timeline.settings) {
        if (invisible_places::water::FindWaterKeyableSetting(
                timeline.feature.kind,
                setting.settingId) != nullptr) {
            continue;
        }
        if (!setting.active || setting.keys.empty()) {
            continue;
        }
        if (setting.settingId == settingId) {
            float minimum = std::numeric_limits<float>::max();
            float maximum = std::numeric_limits<float>::lowest();
            for (const auto& key : setting.keys) {
                minimum = std::min(minimum, key.value);
                maximum = std::max(maximum, key.value);
            }
            const float magnitude =
                std::max(std::abs(minimum), std::abs(maximum));
            if (maximum - minimum <=
                std::max(1.0e-6F, magnitude * 1.0e-6F)) {
                const float padding = std::max(1.0e-3F, magnitude * 0.05F);
                minimum -= padding;
                maximum += padding;
            }
            return PinnedWaterSettingSeries{
                .colour = kWaterKeyedSettingColours[
                    settingIndex % kWaterKeyedSettingColours.size()],
                .minimum = minimum,
                .maximum = maximum,
                .track = &setting,
            };
        }
        ++settingIndex;
    }
    return std::nullopt;
}

// Read-only value curves for settings pinned from the Timings run list,
// drawn over the Global Animation Position bar on every tab. Pure overlay:
// the slider keeps every interaction, and a pin whose feature or keys are
// gone simply draws nothing until they return.
void DrawPinnedWaterSettingOverlays(
    PreviewRuntimeState* runtimeState,
    ImVec2 barMin,
    ImVec2 barMax) {
    const auto& pins =
        runtimeState->timingsPanel.waterPinnedSettingOverlays;
    if (pins.empty()) {
        return;
    }
    const auto scenarioId = ActiveWaterTimingScenarioId(*runtimeState);
    const auto* entry = FindScenarioFeatureRuns(
        runtimeState->water,
        scenarioId);
    if (entry == nullptr) {
        return;
    }
    const float barWidth = std::max(1.0F, barMax.x - barMin.x);
    const float barHeight = std::max(1.0F, barMax.y - barMin.y);
    auto* drawList = ImGui::GetWindowDrawList();
    drawList->PushClipRect(barMin, barMax, true);
    constexpr float kOverlayPad = 2.0F;
    for (const auto& pin : pins) {
        if (pin.scenarioId != scenarioId) {
            continue;
        }
        const auto* run =
            invisible_places::water::FindWaterFeatureRunContaining(
                entry->waterFeatureTimingRuns,
                pin.feature);
        const auto* timeline =
            invisible_places::water::FindWaterFeatureTimeline(
                run,
                pin.feature);
        if (timeline == nullptr) {
            continue;
        }
        const auto series =
            ResolvePinnedWaterSettingSeries(*timeline, pin.settingId);
        if (!series.has_value() || series->track == nullptr ||
            series->track->keys.empty()) {
            continue;
        }
        const float range =
            std::max(1.0e-6F, series->maximum - series->minimum);
        const auto pointAt = [&](float position01) {
            const float value =
                invisible_places::water::EvaluateWaterKeyedSettingTrack(
                    *series->track,
                    position01)
                    .value_or(series->minimum);
            const float normalized = std::clamp(
                (value - series->minimum) / range,
                0.0F,
                1.0F);
            return ImVec2{
                barMin.x + barWidth * position01,
                barMax.y - kOverlayPad -
                    normalized * (barHeight - kOverlayPad * 2.0F)};
        };
        const int sampleCount = std::clamp(
            static_cast<int>(barWidth / 2.0F),
            32,
            256);
        const ImU32 colour =
            (series->colour & 0x00FFFFFFU) | 0xD2000000U;
        ImVec2 previous = pointAt(0.0F);
        for (int sample = 1; sample <= sampleCount; ++sample) {
            const ImVec2 current = pointAt(
                static_cast<float>(sample) /
                static_cast<float>(sampleCount));
            drawList->AddLine(previous, current, colour, 1.5F);
            previous = current;
        }
        for (const auto& key : series->track->keys) {
            drawList->AddCircleFilled(
                pointAt(std::clamp(key.position, 0.0F, 1.0F)),
                2.0F,
                colour);
        }
    }
    drawList->PopClipRect();
}

void DrawGlobalAnimationTimingBar(PreviewRuntimeState* runtimeState) {
    auto& panel = runtimeState->animationPanel;
    if (!panel.currentPath.has_value()) {
        return;
    }
    const bool renderSetupReadOnly =
        RenderSetupAuthoringLocked(runtimeState);
    const float durationSeconds =
        std::max(0.0F, AnimationDurationSeconds(panel.currentPath.value()));
    const std::string timeLabel =
        FormatFixed(panel.scrubAmount * durationSeconds, 1) + "s";
    const bool scrubChanged = DrawRangedFloatControl(
        "GlobalAnimationPosition",
        &panel.scrubAmount,
        {.visualMin = 0.0F,
         .visualMax = 1.0F,
         .format = "%.3f",
         .showLabel = false,
         .scaleDragToWidth = true,
         .hardMin = 0.0F,
         .hardMax = 1.0F});
    const ImVec2 barMin = ImGui::GetItemRectMin();
    const ImVec2 barMax = ImGui::GetItemRectMax();
    if (scrubChanged) {
        ApplyAnimationScrub(runtimeState);
    }

    invisible_places::timing::TimingColouriseEffect*
        colouriseEffect = nullptr;
    if (runtimeState->activeControlsTab ==
            ControlsTab::Timings &&
        runtimeState->timingsPanel
            .selectedColouriseEffectIndex.has_value()) {
        auto* timingState =
            invisible_places::timing::
                FindTimingTakeSceneState(
                    &runtimeState->water
                         .timingTakeSceneStates,
                    ActiveWaterTimingScenarioId(
                        *runtimeState),
                    ActiveWaterTimingSceneGroupName(
                        runtimeState->water));
        const auto selected =
            runtimeState->timingsPanel
                .selectedColouriseEffectIndex.value();
        if (timingState != nullptr &&
            selected <
                timingState->colouriseEffects.size()) {
            colouriseEffect =
                &timingState->colouriseEffects[selected];
            ImGui::BeginDisabled(renderSetupReadOnly);
            DrawTimingColouriseGlobalMarkerLanes(
                runtimeState,
                colouriseEffect,
                barMin,
                barMax);
            ImGui::EndDisabled();
        }
    }
    const auto& feature =
        runtimeState->water.activeKeyingFeature;
    const invisible_places::water::WaterFeatureTimingRun* run = nullptr;
    const invisible_places::water::WaterFeatureTimeline* timeline = nullptr;
    if (colouriseEffect == nullptr &&
        runtimeState->activeControlsTab !=
            ControlsTab::Timings &&
        feature.has_value()) {
        const auto* entry = FindScenarioFeatureRuns(
            runtimeState->water,
            ActiveWaterTimingScenarioId(*runtimeState));
        if (entry != nullptr) {
            run =
                invisible_places::water::FindWaterFeatureRunContaining(
                    entry->waterFeatureTimingRuns,
                    feature.value());
            timeline =
                invisible_places::water::FindWaterFeatureTimeline(
                    run,
                    feature.value());
            if (run != nullptr && timeline != nullptr) {
                ImGui::BeginDisabled(renderSetupReadOnly);
                DrawWaterKeyMarkerStrip(
                    runtimeState,
                    *run,
                    *timeline,
                    barMin,
                    barMax);
                ImGui::EndDisabled();
            }
        }
    }

    DrawAnimationTimelineViewRangeSelector(
        runtimeState,
        durationSeconds);
    DrawAnimationTimelineViewBoundsOverlay(
        panel.timelineViewRange,
        barMin,
        barMax);
    DrawPinnedWaterSettingOverlays(runtimeState, barMin, barMax);

    const float scrubPosition = std::clamp(panel.scrubAmount, 0.0F, 1.0F);
    const auto relevantEffectKeyPositions =
        colouriseEffect != nullptr
            ? TimingEffectRelevantKeyPositions(*colouriseEffect)
            : std::vector<float>{};
    const auto previousEffectKey = [&]() -> std::optional<float> {
        for (auto position = relevantEffectKeyPositions.rbegin();
             position != relevantEffectKeyPositions.rend();
             ++position) {
            if (*position <
                scrubPosition -
                    invisible_places::timing::
                        kTimingColouriseKeyTolerance) {
                return *position;
            }
        }
        return std::nullopt;
    }();
    const auto nextEffectKey = [&]() -> std::optional<float> {
        for (const float position : relevantEffectKeyPositions) {
            if (position >
                scrubPosition +
                    invisible_places::timing::
                        kTimingColouriseKeyTolerance) {
                return position;
            }
        }
        return std::nullopt;
    }();
    const auto previous =
        colouriseEffect != nullptr
            ? previousEffectKey
        : timeline != nullptr
            ? invisible_places::water::PreviousWaterFeatureKeyPosition(
                  *timeline,
                  scrubPosition)
            : std::nullopt;
    const auto next =
        colouriseEffect != nullptr
            ? nextEffectKey
        : timeline != nullptr
            ? invisible_places::water::NextWaterFeatureKeyPosition(
                  *timeline,
                  scrubPosition)
            : std::nullopt;
    const std::size_t currentFeatureKeyCount =
        colouriseEffect != nullptr
            ? TimingEffectRelevantKeyCountAtPosition(
                  *colouriseEffect,
                  scrubPosition)
        : timeline != nullptr
            ? invisible_places::water::
                  WaterFeatureKeyCountAtPosition(
                      *timeline,
                      scrubPosition)
            : 0U;
    const bool hasKeyedSettings =
        colouriseEffect != nullptr
            ? !relevantEffectKeyPositions.empty()
            : timeline != nullptr &&
                  std::any_of(
                      timeline->settings.begin(),
                      timeline->settings.end(),
                      [](const auto& setting) {
                          return setting.active &&
                                 !setting.keys.empty();
                      });
    const std::string featureLabel =
        colouriseEffect != nullptr
            ? colouriseEffect->name
        : feature.has_value()
            ? WaterKeyedFeatureDisplayLabel(*runtimeState, *feature)
            : std::string{};
    const std::string effectKeyDescription =
        colouriseEffect != nullptr &&
                TimingEffectIsEmissive(*colouriseEffect)
            ? "Emissive Level or Bounds"
            : "Palette, Controls, or Bounds";
    const std::string effectTypeLabel =
        colouriseEffect != nullptr ? "Visual Feature" : "effect";
    const auto buttonTooltip = [](const char* text) {
        if (ImGui::IsItemHovered(
                ImGuiHoveredFlags_DelayNormal |
                ImGuiHoveredFlags_AllowWhenDisabled)) {
            ImGui::SetTooltip("%s", text);
        }
    };

    ImGui::PushID("GlobalAnimationTransport");
    if (ImGui::SmallButton("|<")) {
        panel.scrubAmount = 0.0F;
        ApplyAnimationScrub(runtimeState);
    }
    buttonTooltip("Go back to the start of the loaded animation.");

    ImGui::SameLine();
    const bool playbackAvailable = panel.currentPath->keys.size() >= 2U;
    ImGui::BeginDisabled(!playbackAvailable);
    if (ImGui::SmallButton(
            runtimeState->animationPlayback.active ? "Stop" : "Play")) {
        ToggleAnimationPlayback(runtimeState);
    }
    ImGui::EndDisabled();
    buttonTooltip(
        playbackAvailable
            ? (runtimeState->animationPlayback.active
                   ? "Stop animation playback. Shortcut: Space."
                   : "Play the loaded animation from the current position. Shortcut: Space.")
            : "Playback requires a loaded animation with at least two camera keys.");

    const float navigationGap = ImGui::GetStyle().ItemSpacing.x * 3.0F;
    ImGui::SameLine(0.0F, navigationGap);
    ImGui::BeginDisabled(!previous.has_value());
    if (ImGui::SmallButton("<")) {
        panel.scrubAmount = previous.value();
        ApplyAnimationScrub(runtimeState);
    }
    ImGui::EndDisabled();
    const std::string previousTooltip =
        colouriseEffect != nullptr
            ? !hasKeyedSettings
                  ? featureLabel +
                        " has no " + effectKeyDescription + " keys."
                  : !previous.has_value()
                        ? "There is no earlier " + effectTypeLabel + " key for " +
                              featureLabel + "."
                        : "Go to the previous " + effectTypeLabel + " key for " +
                              featureLabel + "."
        : runtimeState->activeControlsTab ==
                  ControlsTab::Timings
            ? "Select a Colourise or Emissive effect in the Timings tab to navigate its setting and Bounds keys."
        : !feature.has_value()
            ? "Select a keyable feature in the Water tab to navigate its settings."
            : !hasKeyedSettings
                  ? featureLabel + " has no keyed settings."
                  : !previous.has_value()
                        ? "There is no earlier keyed setting for " +
                              featureLabel + "."
                        : "Go to the previous keyed setting for " +
                              featureLabel + ".";
    buttonTooltip(previousTooltip.c_str());

    ImGui::SameLine(0.0F, 2.0F);
    ImGui::BeginDisabled(!next.has_value());
    if (ImGui::SmallButton(">")) {
        panel.scrubAmount = next.value();
        ApplyAnimationScrub(runtimeState);
    }
    ImGui::EndDisabled();
    const std::string nextTooltip =
        colouriseEffect != nullptr
            ? !hasKeyedSettings
                  ? featureLabel +
                        " has no " + effectKeyDescription + " keys."
                  : !next.has_value()
                        ? "There is no later " + effectTypeLabel + " key for " +
                              featureLabel + "."
                        : "Go to the next " + effectTypeLabel + " key for " +
                              featureLabel + "."
        : runtimeState->activeControlsTab ==
                  ControlsTab::Timings
            ? "Select a Colourise or Emissive effect in the Timings tab to navigate its setting and Bounds keys."
        : !feature.has_value()
            ? "Select a keyable feature in the Water tab to navigate its settings."
            : !hasKeyedSettings
                  ? featureLabel + " has no keyed settings."
                  : !next.has_value()
                        ? "There is no later keyed setting for " +
                              featureLabel + "."
                        : "Go to the next keyed setting for " +
                              featureLabel + ".";
    buttonTooltip(nextTooltip.c_str());

    ImGui::SameLine(0.0F, 2.0F);
    ImGui::BeginDisabled(
        renderSetupReadOnly || currentFeatureKeyCount == 0U);
    if (ImGui::SmallButton("X")) {
        auto& water = runtimeState->water;
        const std::size_t removed =
            colouriseEffect != nullptr
                ? RemoveTimingEffectRelevantKeysAtPosition(
                      colouriseEffect,
                      scrubPosition)
                : feature.has_value()
                      ? invisible_places::water::
                            RemoveWaterFeatureKeysAtPosition(
                                FindMutableWaterFeatureTimeline(
                                    &water,
                                    ActiveWaterTimingScenarioId(
                                        *runtimeState),
                                    feature.value()),
                                scrubPosition)
                      : 0U;
        if (removed > 0U) {
            ApplyAnimationScrub(runtimeState);
            InvalidateWaterSeepageParams(&water);
            runtimeState->previewRenderStateSignatureValid = false;
            runtimeState->statusMessage =
                removed == 1U
                    ? "Deleted the key at the current position."
                    : "Deleted " + std::to_string(removed) +
                          " keys at the current position.";
            runtimeState->errorMessage.clear();
        }
    }
    ImGui::EndDisabled();
    const std::string deleteTooltip =
        renderSetupReadOnly
            ? "Loaded render setups are read-only. Clear the setup in Export before deleting timing keys."
        : colouriseEffect != nullptr
            ? !hasKeyedSettings
                  ? featureLabel +
                        " has no " + effectKeyDescription + " keys."
                  : currentFeatureKeyCount == 0U
                        ? "Move the animation position onto a " + effectKeyDescription + " key for " +
                              featureLabel + " to delete it."
                        : currentFeatureKeyCount == 1U
                              ? "Delete the setting key for " +
                                    featureLabel +
                                    " at the current animation position."
                              : "Delete all " +
                                    std::to_string(
                                        currentFeatureKeyCount) +
                                    " setting keys for " +
                                    featureLabel +
                                    " at the current animation position."
        : runtimeState->activeControlsTab ==
                  ControlsTab::Timings
            ? "Select a Colourise or Emissive effect in the Timings tab to delete its keys."
        : !feature.has_value()
            ? "Select a keyable feature in the Water tab to delete its keys."
            : !hasKeyedSettings
                  ? featureLabel + " has no keyed settings."
                  : currentFeatureKeyCount == 0U
                        ? "Move the animation position onto a key for " +
                              featureLabel + " to delete it."
                        : currentFeatureKeyCount == 1U
                              ? "Delete the key for " + featureLabel +
                                    " at the current animation position."
                              : "Delete all " +
                                    std::to_string(
                                        currentFeatureKeyCount) +
                                    " keys for " + featureLabel +
                                    " at the current animation position.";
    buttonTooltip(deleteTooltip.c_str());

    ImGui::SameLine();
    const float timeWidth = ImGui::CalcTextSize(timeLabel.c_str()).x;
    const float timeCursorX =
        std::max(
            ImGui::GetCursorPosX(),
            ImGui::GetWindowContentRegionMax().x - timeWidth);
    ImGui::SetCursorPosX(timeCursorX);
    ImGui::TextDisabled("%s", timeLabel.c_str());
    ImGui::PopID();
    ImGui::Spacing();
}

void DrawFocusedWaterRunCombo(
    PreviewRuntimeState* runtimeState) {
    if (!runtimeState->animationPanel.currentPath.has_value()) {
        return;
    }
    auto& water = runtimeState->water;
    const auto& feature = water.activeKeyingFeature;
    const auto scenarioId =
        ActiveWaterTimingScenarioId(*runtimeState);
    const auto* entry =
        FindScenarioFeatureRuns(water, scenarioId);
    const auto* currentRun =
        feature.has_value() && entry != nullptr
            ? invisible_places::water::
                  FindWaterFeatureRunContaining(
                      entry->waterFeatureTimingRuns,
                      feature.value())
            : nullptr;
    const std::string preview =
        !feature.has_value()
            ? "No water feature in focus"
            : scenarioId.empty()
                  ? "No Timing Take"
                  : currentRun != nullptr
                        ? currentRun->name
                        : "Not in a run";

    ImGui::SetNextItemWidth(-FLT_MIN);
    const bool available =
        feature.has_value() && !scenarioId.empty() &&
        entry != nullptr && !entry->waterFeatureTimingRuns.empty();
    const bool renderSetupReadOnly =
        RenderSetupAuthoringLocked(runtimeState);
    ImGui::BeginDisabled(!available || renderSetupReadOnly);
    if (ImGui::BeginCombo(
            "Water Run##FocusedWaterRun",
            preview.c_str())) {
        if (currentRun == nullptr) {
            ImGui::TextDisabled("Not in a run");
            ImGui::Separator();
        }
        for (const auto& run : entry->waterFeatureTimingRuns) {
            const bool selected =
                currentRun != nullptr &&
                currentRun->id == run.id;
            if (ImGui::Selectable(
                    run.name.c_str(),
                    selected)) {
                auto& mutableEntry =
                    EnsureScenarioFeatureRuns(
                        &water,
                        scenarioId);
                if (invisible_places::timing::
                        AssignWaterFeatureToTimingRun(
                            &mutableEntry,
                            feature.value(),
                            run.id)) {
                    const auto featureLabel =
                        WaterKeyedFeatureDisplayLabel(
                            *runtimeState,
                            feature.value());
                    runtimeState->statusMessage =
                        featureLabel + " now belongs to " +
                        run.name + ".";
                    runtimeState->errorMessage.clear();
                    ApplyAnimationScrub(runtimeState);
                    InvalidateWaterSeepageParams(&water);
                    runtimeState
                        ->previewRenderStateSignatureValid =
                        false;
                }
            }
            if (selected) {
                ImGui::SetItemDefaultFocus();
            }
        }
        ImGui::EndCombo();
    }
    ImGui::EndDisabled();
    if (ImGui::IsItemHovered(
            ImGuiHoveredFlags_DelayNormal |
            ImGuiHoveredFlags_AllowWhenDisabled)) {
        if (renderSetupReadOnly) {
            ImGui::SetTooltip(
                "Loaded render setups are read-only. Clear the setup in Export before changing run assignments.");
        } else if (!feature.has_value()) {
            ImGui::SetTooltip(
                "Select a keyable Water feature or source first.");
        } else if (scenarioId.empty()) {
            ImGui::SetTooltip(
                "Choose a Timing Take for the loaded animation first.");
        } else if (
            entry == nullptr ||
            entry->waterFeatureTimingRuns.empty()) {
            ImGui::SetTooltip(
                "Create a feature run in the Timings tab, then assign %s here.",
                WaterKeyedFeatureDisplayLabel(
                    *runtimeState,
                    feature.value())
                    .c_str());
        } else {
            ImGui::SetTooltip(
                "Assign the focused water feature to a run, or move it "
                "between runs while preserving all active and dormant keys.");
        }
    }
    ImGui::Spacing();
}

void DrawControlsWindow(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }

    UpdateActiveRenderSetupPreparation(runtimeState);
    CancelRenderSetupAuthoringInteractions(runtimeState);
    const bool renderSetupReadOnly =
        RenderSetupAuthoringLocked(runtimeState);
    const auto drawReadOnlyNotice = [&]() {
        if (!renderSetupReadOnly) {
            return;
        }
        if (runtimeState->activeRenderSetupOverride.has_value()) {
            ImGui::TextWrapped(
                "Loaded render setup: this authoring tab is read-only. "
                "Clear the setup in Export to edit it.");
        } else {
            ImGui::TextWrapped(
                "A click-time render setup is frozen while full-density "
                "sources prepare. Cancel the pending request in Export to "
                "resume authoring.");
        }
        ImGui::Separator();
    };

    auto& sidePanel = runtimeState->sidePanel;
    sidePanel.revealAmount = 1.0F;
    sidePanel.mode = invisible_places::ui::SidePanelMode::Expanded;
    runtimeState->water.activeRegionFeature = WaterRegionFeature::None;
    runtimeState->water.seepageTabActive = false;

    const ImVec2 controlsSize{540.0F, 780.0F};
    ImGuiWindowClass controlsWindowClass;
    controlsWindowClass.ClassId = 0x49504354U;
    controlsWindowClass.ViewportFlagsOverrideSet = ImGuiViewportFlags_NoAutoMerge;
    controlsWindowClass.ViewportFlagsOverrideClear = ImGuiViewportFlags_NoDecoration;
    ImGui::SetNextWindowClass(&controlsWindowClass);
    ImGui::SetNextWindowPos(DefaultControlsWindowPosition(controlsSize), ImGuiCond_FirstUseEver);
    ImGui::SetNextWindowSize(controlsSize, ImGuiCond_FirstUseEver);
    ImGui::SetNextWindowSizeConstraints(ImVec2{460.0F, 420.0F}, ImVec2{780.0F, FLT_MAX});

    const bool popupOpen =
        ImGui::IsPopupOpen(static_cast<const char*>(nullptr), ImGuiPopupFlags_AnyPopupId);
    constexpr ImGuiWindowFlags flags =
        ImGuiWindowFlags_NoCollapse | ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse;
    ImGui::Begin("Invisible Places Controls", nullptr, flags);

    const auto applyLiveView =
        [&](const char* name,
            const glm::vec3& viewDirection,
            const glm::vec3& screenUpDirection) {
            runtimeState->camera.SetViewDirectionAroundOrbitCenter(
                viewDirection,
                screenUpDirection);
            runtimeState->cameraPlayback.active = false;
            runtimeState->animationPlayback.active = false;
            runtimeState->cameraInteraction.trackballOrbitActive = false;
            runtimeState->cameraInteraction.lastNavigationInputAt =
                std::chrono::steady_clock::now();
            runtimeState->statusMessage =
                std::string{name} +
                " view centred on the current focal point.";
            runtimeState->errorMessage.clear();
        };

    ImGui::PushStyleVar(
        ImGuiStyleVar_FramePadding,
        ImVec2{3.0F, ImGui::GetStyle().FramePadding.y});
    ImGui::PushStyleVar(
        ImGuiStyleVar_CellPadding,
        ImVec2{2.0F, ImGui::GetStyle().CellPadding.y});
    if (ImGui::BeginTable(
            "##LiveViewCameraControls",
            6,
            ImGuiTableFlags_SizingStretchSame |
                ImGuiTableFlags_NoSavedSettings)) {
        ImGui::TableNextRow();
        ImGui::TableSetColumnIndex(0);
        if (ImGui::Button("Top", ImVec2{-FLT_MIN, 0.0F})) {
            applyLiveView(
                "Top",
                glm::vec3{0.0F, 0.0F, -1.0F},
                glm::vec3{1.0F, 0.0F, 0.0F});
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Look along -Z with +X pointing up the screen. Keeps the current focal distance.");
        }

        ImGui::TableSetColumnIndex(1);
        if (ImGui::Button("Front", ImVec2{-FLT_MIN, 0.0F})) {
            applyLiveView(
                "Front",
                glm::vec3{1.0F, 0.0F, 0.0F},
                glm::vec3{0.0F, 0.0F, 1.0F});
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Look along +X with +Z pointing up the screen. Keeps the current focal distance.");
        }

        ImGui::TableSetColumnIndex(2);
        if (ImGui::Button("Left", ImVec2{-FLT_MIN, 0.0F})) {
            applyLiveView(
                "Left",
                glm::vec3{0.0F, -1.0F, 0.0F},
                glm::vec3{0.0F, 0.0F, 1.0F});
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Look along -Y with +Z pointing up the screen. Keeps the current focal distance.");
        }

        ImGui::TableSetColumnIndex(3);
        if (ImGui::Button("Right", ImVec2{-FLT_MIN, 0.0F})) {
            applyLiveView(
                "Right",
                glm::vec3{0.0F, 1.0F, 0.0F},
                glm::vec3{0.0F, 0.0F, 1.0F});
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Look along +Y with +Z pointing up the screen. Keeps the current focal distance.");
        }

        ImGui::TableSetColumnIndex(4);
        if (ImGui::Button("Isometric", ImVec2{-FLT_MIN, 0.0F})) {
            applyLiveView(
                "Isometric",
                glm::normalize(glm::vec3{1.0F, 0.0F, -1.0F}),
                glm::vec3{0.0F, 0.0F, 1.0F});
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Use an elevated Front view aimed down at the current focal point. Keeps the current focal distance.");
        }

        ImGui::TableSetColumnIndex(5);
        const bool parallelProjection =
            runtimeState->camera.ParallelProjection();
        if (parallelProjection) {
            ImGui::PushStyleColor(
                ImGuiCol_Button,
                ImGui::GetStyleColorVec4(ImGuiCol_ButtonActive));
        }
        const bool toggleParallel =
            ImGui::Button("Parallel", ImVec2{-FLT_MIN, 0.0F});
        if (parallelProjection) {
            ImGui::PopStyleColor();
        }
        if (toggleParallel) {
            runtimeState->camera.SetParallelProjection(
                !parallelProjection);
            runtimeState->statusMessage =
                parallelProjection
                    ? "Perspective projection enabled."
                    : "Parallel projection enabled.";
            runtimeState->errorMessage.clear();
        }
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip(
                "Toggle parallel projection. Its scale matches the perspective view at the focal point.");
        }
        ImGui::EndTable();
    }
    ImGui::PopStyleVar(2);

    // Tab hit rectangles are captured below. Resolve this frame's click
    // before drawing the global header, then explicitly select that ImGui tab
    // below. This preserves one-click switching when a transient popup has
    // just closed or an interactive Timings item still owns the active ID.
    // A popup that remains open here (notably a modal confirmation) continues
    // to block tab changes intentionally.
    std::optional<ControlsTab> requestedControlsTab;
    if (!popupOpen &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        constexpr std::array tabValues{
            ControlsTab::Visuals,
            ControlsTab::Water,
            ControlsTab::Camera,
            ControlsTab::Animation,
            ControlsTab::Timings,
            ControlsTab::Export,
            ControlsTab::Project,
            ControlsTab::Lidar,
            ControlsTab::Gsplat,
        };
        const auto mouse = ImGui::GetIO().MousePos;
        for (std::size_t index = 0U;
             index < runtimeState->controlsTabHitRects.size();
             ++index) {
            const auto& rect =
                runtimeState->controlsTabHitRects[index];
            if (rect.z > rect.x && rect.w > rect.y &&
                mouse.x >= rect.x && mouse.x <= rect.z &&
                mouse.y >= rect.y && mouse.y <= rect.w) {
                runtimeState->activeControlsTab =
                    tabValues[index];
                requestedControlsTab = tabValues[index];
                break;
            }
        }
    }
    if (requestedControlsTab.has_value() &&
        requestedControlsTab.value() != ControlsTab::Timings) {
        auto& timings = runtimeState->timingsPanel;
        timings.draggingColourisePaletteStop = false;
        timings.draggingColourisePaletteStopAmount = false;
        timings.colourisePaletteDrag.reset();
        timings.requestedColourisePalettePickerStopIndex.reset();
        timings.colourisePalettePicker.reset();
        timings.activeHistogramHandle =
            TimingColouriseHistogramHandle::None;
        timings.colouriseLocalKeyDrag.reset();
        timings.colouriseLocalKeyPositionEdit.reset();
        timings.colouriseActivationDrag.reset();
    }

    const auto& diagnostics = viewport->Diagnostics();
    const double renderFps =
        diagnostics.averageFrameFps > 0.0 ? diagnostics.averageFrameFps : diagnostics.frameFps;
    const char* previewStatus =
        diagnostics.sceneCacheActive && !diagnostics.sceneRenderedThisFrame ? "cached" : "rendering";
    const std::string fpsLabel =
        "FPS (" + FormatFixed(diagnostics.frameAverageWindowSeconds, 1) + "s): " +
        FormatFixed(renderFps, 1) + "  " + previewStatus;
    if (runtimeState->animationPanel.currentPath.has_value()) {
        ImGui::AlignTextToFramePadding();
        ImGui::TextUnformatted("Global Animation Position");
        ImGui::SameLine();
    }
    const float fpsLabelWidth = ImGui::CalcTextSize(fpsLabel.c_str()).x;
    const float fpsCursorX =
        std::max(ImGui::GetCursorPosX(), ImGui::GetWindowContentRegionMax().x - fpsLabelWidth);
    ImGui::SetCursorPosX(fpsCursorX);
    ImGui::TextDisabled("%s", fpsLabel.c_str());

    DrawGlobalAnimationTimingBar(runtimeState);
    DrawFocusedWaterRunCombo(runtimeState);

    sidePanel.hovered = ImGui::IsWindowHovered(
        ImGuiHoveredFlags_AllowWhenBlockedByActiveItem | ImGuiHoveredFlags_RootAndChildWindows);
    sidePanel.interacting =
        popupOpen || ImGui::IsAnyItemActive() ||
        ImGui::IsWindowFocused(ImGuiFocusedFlags_RootAndChildWindows);

    constexpr ImGuiWindowFlags tabScrollFlags = ImGuiWindowFlags_AlwaysVerticalScrollbar;
    runtimeState->controlsTabHitRects.fill(ImVec4{});
    if (ImGui::BeginTabBar("ScenePanelTabs")) {
        const auto beginControlsTabItem =
            [&](const char* label,
                ControlsTab tab,
                bool* open = nullptr) {
                const ImGuiTabItemFlags tabFlags =
                    requestedControlsTab == tab
                        ? ImGuiTabItemFlags_SetSelected
                        : ImGuiTabItemFlags_None;
                const bool selected =
                    ImGui::BeginTabItem(label, open, tabFlags);
                const auto minimum =
                    ImGui::GetItemRectMin();
                const auto maximum =
                    ImGui::GetItemRectMax();
                runtimeState->controlsTabHitRects[
                    static_cast<std::size_t>(tab)] =
                    ImVec4{
                        minimum.x,
                        minimum.y,
                        maximum.x,
                        maximum.y};
                return selected;
            };
        if (beginControlsTabItem("Visuals", ControlsTab::Visuals)) {
            runtimeState->activeControlsTab = ControlsTab::Visuals;
            if (ImGui::BeginChild("VisualsTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                drawReadOnlyNotice();
                ImGui::BeginDisabled(renderSetupReadOnly);
                DrawVisualsPanel(runtimeState, viewport);
                ImGui::EndDisabled();
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Water", ControlsTab::Water)) {
            runtimeState->activeControlsTab = ControlsTab::Water;
            drawReadOnlyNotice();
            ImGui::BeginDisabled(renderSetupReadOnly);
            DrawWaterPanel(runtimeState, viewport);
            ImGui::EndDisabled();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Camera", ControlsTab::Camera)) {
            runtimeState->activeControlsTab = ControlsTab::Camera;
            if (ImGui::BeginChild("CameraTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                DrawCameraSection(runtimeState, *viewport);
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Animation", ControlsTab::Animation)) {
            runtimeState->activeControlsTab = ControlsTab::Animation;
            if (ImGui::BeginChild("AnimationTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                DrawAnimationSection(runtimeState, *viewport);
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Timings", ControlsTab::Timings)) {
            runtimeState->activeControlsTab = ControlsTab::Timings;
            if (ImGui::BeginChild("TimingsTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                drawReadOnlyNotice();
                ImGui::BeginDisabled(renderSetupReadOnly);
                DrawAuthoredTimingsPanel(runtimeState);
                ImGui::EndDisabled();
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Export", ControlsTab::Export)) {
            runtimeState->activeControlsTab = ControlsTab::Export;
            if (ImGui::BeginChild("ExportTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                DrawExportPanel(runtimeState, viewport);
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (beginControlsTabItem("Project", ControlsTab::Project)) {
            runtimeState->activeControlsTab = ControlsTab::Project;
            if (ImGui::BeginChild("ProjectTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                drawReadOnlyNotice();
                ImGui::BeginDisabled(renderSetupReadOnly);
                DrawProjectPanel(runtimeState, viewport);
                ImGui::EndDisabled();
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (runtimeState->showLidarTab &&
            beginControlsTabItem(
                "Lidar",
                ControlsTab::Lidar,
                &runtimeState->showLidarTab)) {
            runtimeState->activeControlsTab = ControlsTab::Lidar;
            if (ImGui::BeginChild("LidarTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                DrawLidarPanel(runtimeState, viewport);
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (runtimeState->showGsplatTab &&
            beginControlsTabItem(
                "gSplat",
                ControlsTab::Gsplat,
                &runtimeState->showGsplatTab)) {
            runtimeState->activeControlsTab = ControlsTab::Gsplat;
            if (ImGui::BeginChild("GsplatTabScroll", ImVec2{0.0F, 0.0F}, false, tabScrollFlags)) {
                DrawGsplatPanel(runtimeState, viewport);
            }
            ImGui::EndChild();
            ImGui::EndTabItem();
        }
        if (ImGui::TabItemButton("+", ImGuiTabItemFlags_Trailing | ImGuiTabItemFlags_NoTooltip)) {
            ImGui::OpenPopup("ControlsAddTabs");
        }
        if (ImGui::BeginPopup("ControlsAddTabs")) {
            ImGui::MenuItem("Lidar", nullptr, &runtimeState->showLidarTab);
            ImGui::MenuItem("gSplat", nullptr, &runtimeState->showGsplatTab);
            ImGui::Separator();
            ImGui::MenuItem("Debug Window", nullptr, &runtimeState->showDiagnosticsPanel);
            ImGui::EndPopup();
        }
        ImGui::EndTabBar();
    }

    sidePanel.interacting =
        popupOpen || ImGui::IsAnyItemActive() ||
        ImGui::IsWindowFocused(ImGuiFocusedFlags_RootAndChildWindows);
    ImGui::End();
}

// Ctrl+click moves the currently selected viewport entity to the raycast
// point-cloud position. Priority when several selections coexist: Seepage
// node, Flow source, path attractor, then the selected animation key. Returns
// false when nothing is selected — or when the Ctrl+click lands on a Seepage
// marker, whose overlay handles it as a selection toggle — so the click falls
// through to normal input; a failed raycast still claims the click and
// surfaces the error.
bool CtrlClickMoveSelectedViewportEntity(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    ImVec2 screenPoint) {
    if (runtimeState == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    if (!RenderSetupAuthoringLocked(runtimeState) &&
        !water.subtleSelectedAuthoringCues) {
        if (water.seepageTabActive &&
            water.selectedSeepageNodeIndex.has_value() &&
            water.selectedSeepageNodeIndex.value() < water.seepageNodes.size()) {
            // A Ctrl+click that lands on a drawn Seepage marker toggles
            // viewport multi-selection in DrawWaterSeepageOverlay later this
            // frame, so the move must decline it; only clicks away from every
            // marker reposition the primary node. Off the Seepage tab the
            // whole branch stands down with the rest of the node picking.
            const auto matrices =
                runtimeState->camera.Matrices(CurrentAspectRatio(viewport));
            for (std::size_t index = 0;
                 index < water.seepageNodes.size();
                 ++index) {
                const auto& node = water.seepageNodes[index];
                const bool drawn =
                    node.enabledInViewport ||
                    water.selectedSeepageNodeIndices.count(index) > 0U ||
                    water.selectedSeepageNodeIndex.value() == index;
                if (!drawn) {
                    continue;
                }
                const auto projected =
                    ProjectWorldPoint(
                        matrices,
                        viewport,
                        ToGlm(node.position));
                if (projected.has_value() &&
                    ScreenDistance(screenPoint, projected->screen) < 13.0F) {
                    return false;
                }
            }
            water.movingSeepageNodeIndex = water.selectedSeepageNodeIndex;
            MoveWaterSeepageNodeAtScreenPoint(
                runtimeState,
                viewport,
                screenPoint);
            water.movingSeepageNodeIndex.reset();
            return true;
        }
        if (water.selectedEmitterIndex.has_value() &&
            water.selectedEmitterIndex.value() < water.emitters.size()) {
            water.movingEmitterIndex = water.selectedEmitterIndex;
            MoveWaterEmitterAtScreenPoint(runtimeState, viewport, screenPoint);
            water.movingEmitterIndex.reset();
            return true;
        }
        if (water.pathAttractorSelected) {
            PlaceWaterPathAttractorAtScreenPoint(runtimeState, viewport, screenPoint);
            return true;
        }
    }
    auto& panel = runtimeState->animationPanel;
    if (panel.currentPath.has_value() &&
        panel.selectedKeyIndex.has_value() &&
        panel.selectedKeyIndex.value() < panel.currentPath->keys.size() &&
        panel.showSplines) {
        const auto pivot = ResolveSurfacePivot(*runtimeState, viewport, screenPoint);
        if (!pivot.has_value()) {
            runtimeState->errorMessage =
                "No visible surface was found under the pointer to move the "
                "animation key to.";
            runtimeState->statusMessage.clear();
            return true;
        }
        if (MoveLinkedAnimationKeyPoint(
                runtimeState,
                &panel.currentPath.value(),
                panel.selectedKeyIndex.value(),
                panel.editTarget,
                ToGlm(pivot->point))) {
            panel.dirty = true;
            runtimeState->pivotOverlay.visible = true;
            runtimeState->pivotOverlay.pivot = pivot->point;
            runtimeState->pivotOverlay.lastSetAt = std::chrono::steady_clock::now();
            runtimeState->statusMessage =
                panel.editTarget == AnimationEditTarget::Camera
                    ? "Moved the camera key to the clicked surface point."
                    : "Moved the focus key to the clicked surface point.";
            runtimeState->errorMessage.clear();
        }
        return true;
    }
    return false;
}

void UpdateCameraFromInput(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell& viewport) {
    if (VisibleLayerCount(*runtimeState) == 0) {
        runtimeState->cameraInteraction.navigationActive = false;
        runtimeState->cameraInteraction.trackballOrbitActive = false;
        return;
    }

    const auto& io = ImGui::GetIO();
    const bool cloudCompareTrackball =
        runtimeState->cameraInteraction.orbitControlMode ==
        OrbitControlMode::CloudCompareTrackball;
    if (!cloudCompareTrackball || !io.MouseDown[0]) {
        runtimeState->cameraInteraction.trackballOrbitActive = false;
    }
    const bool waterAuthoringAllowed =
        !RenderSetupAuthoringLocked(runtimeState);
    const bool waterGeometryAuthoringAllowed =
        waterAuthoringAllowed &&
        !runtimeState->water.subtleSelectedAuthoringCues;
    bool navigatedThisFrame = false;
    if (runtimeState->animationPanel.drag.active) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (runtimeState->water.regionEditor.consumedViewportInputThisFrame ||
        runtimeState->water.regionEditor.drag.active) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (runtimeState->water.manualFlowPathEditor.consumedViewportInputThisFrame ||
        runtimeState->water.manualFlowPathEditor.drag.kind != ManualFlowPathGizmoDragKind::None ||
        runtimeState->water.manualFlowPathEditor.pointerCapturedUntilRelease) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (runtimeState->water.emitterGizmoDrag.kind != ManualFlowPathGizmoDragKind::None ||
        runtimeState->water.emitterGizmoPointerCaptured ||
        runtimeState->water.seepageGizmoDrag.kind != ManualFlowPathGizmoDragKind::None ||
        runtimeState->water.seepageGizmoPointerCaptured) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    // The emitter/Seepage overlays run later in the frame, so their gizmo
    // hover state is one frame old; treating a press over last frame's
    // handles as consumed keeps orbit and the click dispatch below away from
    // gizmo interactions that begin this frame.
    if ((runtimeState->water.emitterGizmoHoveredLastFrame ||
         runtimeState->water.seepageGizmoHoveredLastFrame) &&
        io.MouseDown[0]) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    const bool mouseButtonDown = io.MouseDown[0] || io.MouseDown[1] || io.MouseDown[2];
    const bool renderViewportHovered = IsMouseOverRenderViewport(viewport);
    if (!mouseButtonDown) {
        runtimeState->cameraInteraction.renderViewportMouseActive = false;
    } else if (renderViewportHovered && !viewport.UiWantsMouseCapture()) {
        runtimeState->cameraInteraction.renderViewportMouseActive = true;
    }

    const bool mouseCanNavigate =
        !viewport.UiWantsMouseCapture() &&
        (renderViewportHovered || runtimeState->cameraInteraction.renderViewportMouseActive);
    if (io.KeyCtrl &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        !runtimeState->water.manualFlowPathEditor.active &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left) &&
        CtrlClickMoveSelectedViewportEntity(runtimeState, viewport, io.MousePos)) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.seepageTabActive &&
        runtimeState->water.movingSeepageNodeIndex.has_value() &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        MoveWaterSeepageNodeAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.seepageTabActive &&
        runtimeState->water.seepagePlacementArmed &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        PlaceWaterSeepageNodeAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.movingEmitterIndex.has_value() &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        MoveWaterEmitterAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.placementArmed &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        PlaceWaterEmitterAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.pathAttractorPlacementArmed &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        PlaceWaterPathAttractorAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.rippleRegionPlacementArmed &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        AddWaterRippleVertexAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (waterGeometryAuthoringAllowed &&
        runtimeState->water.fieldRegionPlacementArmed &&
        renderViewportHovered &&
        !viewport.UiWantsMouseCapture() &&
        ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
        AddWaterFieldVertexAtScreenPoint(runtimeState, viewport, io.MousePos);
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (HandleWaterPathViewInput(runtimeState, &viewport)) {
        runtimeState->cameraInteraction.navigationActive = false;
        return;
    }
    if (mouseCanNavigate) {
        const bool doubleClickedPivot =
            !io.KeyShift && ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left);
        const bool isPanning =
            io.MouseDown[1] || io.MouseDown[2] || (io.KeyShift && io.MouseDown[0]);
        if (cloudCompareTrackball &&
            renderViewportHovered &&
            !doubleClickedPivot &&
            !isPanning &&
            ImGui::IsMouseClicked(ImGuiMouseButton_Left)) {
            RefreshCloudCompareOrbitPivot(runtimeState, viewport);
            runtimeState->cameraInteraction.trackballOrbitActive = true;
        }

        if (renderViewportHovered && io.MouseWheel != 0.0F) {
            runtimeState->camera.Dolly(io.MouseWheel);
            navigatedThisFrame = true;
        }

        const bool mouseMoved = io.MouseDelta.x != 0.0F || io.MouseDelta.y != 0.0F;
        if (doubleClickedPivot) {
            runtimeState->cameraInteraction.trackballOrbitActive = false;
            SetCameraPivotFromScreenPoint(runtimeState, viewport, io.MousePos);
            navigatedThisFrame = true;
        } else if (isPanning && mouseMoved) {
            runtimeState->cameraInteraction.trackballOrbitActive = false;
            const auto viewportSize = CurrentUiViewportSize(viewport);
            runtimeState->camera.Pan(io.MouseDelta.x, io.MouseDelta.y, viewportSize.x, viewportSize.y);
            navigatedThisFrame = true;
        } else if (io.MouseDown[0] && mouseMoved) {
            if (cloudCompareTrackball) {
                runtimeState->cameraInteraction.trackballOrbitActive = true;
                const auto viewportSize = CurrentUiViewportSize(viewport);
                const auto viewportOrigin = CurrentUiViewportOrigin();
                const ImVec2 currentLocal{
                    io.MousePos.x - viewportOrigin.x,
                    io.MousePos.y - viewportOrigin.y,
                };
                const ImVec2 previousLocal{
                    currentLocal.x - io.MouseDelta.x,
                    currentLocal.y - io.MouseDelta.y,
                };
                ImVec2 pivotLocal{
                    viewportSize.x * 0.5F,
                    viewportSize.y * 0.5F,
                };
                const auto matrices =
                    runtimeState->camera.Matrices(CurrentAspectRatio(viewport));
                if (const auto projectedPivot = ProjectWorldPoint(
                        matrices,
                        viewport,
                        runtimeState->camera.OrbitCenter());
                    projectedPivot.has_value()) {
                    pivotLocal = ImVec2{
                        projectedPivot->screen.x - viewportOrigin.x,
                        projectedPivot->screen.y - viewportOrigin.y,
                    };
                }
                runtimeState->camera.OrbitTrackball(
                    previousLocal.x,
                    previousLocal.y,
                    currentLocal.x,
                    currentLocal.y,
                    viewportSize.x,
                    viewportSize.y,
                    pivotLocal.x,
                    pivotLocal.y);
            } else {
                runtimeState->camera.Orbit(io.MouseDelta.x, io.MouseDelta.y);
            }
            navigatedThisFrame = true;
        }
    }

    const bool keyboardCanNavigate = !viewport.UiWantsKeyboardCapture() && IsRenderViewportFocused();
    if (keyboardCanNavigate && ImGui::IsKeyPressed(ImGuiKey_F)) {
        if (runtimeState->selectedSessionIndex.has_value()) {
            FocusSessionLayer(runtimeState, viewport, runtimeState->selectedSessionIndex.value());
            navigatedThisFrame = true;
        }
    }

    if (keyboardCanNavigate && ImGui::IsKeyPressed(ImGuiKey_P)) {
        const ImVec2 mousePosition = io.MousePos;
        SetCameraPivotFromScreenPoint(runtimeState, viewport, mousePosition);
        navigatedThisFrame = true;
    }

    if (keyboardCanNavigate && ImGui::IsKeyPressed(ImGuiKey_V)) {
        runtimeState->pivotOverlay.visible = !runtimeState->pivotOverlay.visible;
        runtimeState->pivotOverlay.pivot = FromGlm(runtimeState->camera.OrbitCenter());
        runtimeState->pivotOverlay.lastSetAt = runtimeState->pivotOverlay.visible
                                                   ? std::chrono::steady_clock::now()
                                                   : std::chrono::steady_clock::time_point{};
        runtimeState->statusMessage = runtimeState->pivotOverlay.visible
                                          ? "Pivot marker pinned on."
                                          : "Pivot marker hidden until camera navigation.";
    }

    const auto now = std::chrono::steady_clock::now();
    if (navigatedThisFrame) {
        runtimeState->cameraInteraction.lastNavigationInputAt = now;
        if (runtimeState->cameraPlayback.active) {
            runtimeState->cameraPlayback.active = false;
        }
        if (runtimeState->animationPlayback.active) {
            runtimeState->animationPlayback.active = false;
        }
    }
    runtimeState->cameraInteraction.navigationActive =
        navigatedThisFrame ||
        (runtimeState->cameraInteraction.lastNavigationInputAt.time_since_epoch().count() != 0 &&
         (now - runtimeState->cameraInteraction.lastNavigationInputAt) <
             std::chrono::milliseconds{180});
}

void UpdatePerformanceInteractionState(
    PreviewRuntimeState* runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport) {
    if (runtimeState == nullptr) {
        return;
    }

    const auto now = std::chrono::steady_clock::now();
    const bool uiInteractionActive =
        runtimeState->sidePanel.hovered ||
        runtimeState->sidePanel.interacting ||
        ImGui::IsAnyItemActive() ||
        viewport.UiWantsMouseCapture() ||
        viewport.UiWantsKeyboardCapture();
    if (uiInteractionActive) {
        runtimeState->performanceInteraction.lastUiInteractionAt = now;
    }

    const bool uiInteractionRecent =
        runtimeState->performanceInteraction.lastUiInteractionAt.time_since_epoch().count() != 0 &&
        (now - runtimeState->performanceInteraction.lastUiInteractionAt) < kPerformanceInteractionHold;
    runtimeState->performanceInteraction.active =
        runtimeState->cameraInteraction.navigationActive || uiInteractionRecent;
}

void PrunePreviewLodSampleCaches(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return;
    }

    for (auto& session : runtimeState->sessions) {
        if (!session.loaded ||
            session.kind != LayerKind::PointCloud ||
            session.offlinePointCloud == nullptr) {
            ClearPreviewLodSampleCache(&session);
            continue;
        }
    }
}

std::uint64_t EffectiveWaterSeepageShaderInvocations(const PreviewRuntimeState& runtimeState) {
    std::uint64_t total = 0U;
    for (const auto& session : runtimeState.sessions) {
        if (!IsRenderablePointCloudSource(runtimeState, session) ||
            !IsAuthoredWaterTerrainSession(session)) {
            continue;
        }
        const auto style = MakeSceneRenderStyle(runtimeState, session, session.pointStyle);
        const std::uint64_t multiplier = style.geometryMode == PointCloudGeometryMode::WorldSurfels ? 6U : 1U;
        const std::uint64_t points = EffectivePointDrawCount(runtimeState, session);
        const std::uint64_t contribution =
            points > std::numeric_limits<std::uint64_t>::max() / multiplier
                ? std::numeric_limits<std::uint64_t>::max()
                : points * multiplier;
        total = contribution > std::numeric_limits<std::uint64_t>::max() - total
                    ? std::numeric_limits<std::uint64_t>::max()
                    : total + contribution;
    }
    return total;
}

std::uint64_t EffectiveExportWaterSeepageShaderInvocations(const PreviewRuntimeState& runtimeState) {
    std::uint64_t total = 0U;
    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState.sessions.size(); ++sessionIndex) {
        const auto& session = runtimeState.sessions[sessionIndex];
        if (!IsExportPointCloudSourceReady(runtimeState, sessionIndex) ||
            !IsAuthoredWaterTerrainSession(session)) {
            continue;
        }
        const auto style = MakeSceneRenderStyle(runtimeState, session, session.pointStyle);
        const std::uint64_t multiplier = style.geometryMode == PointCloudGeometryMode::WorldSurfels ? 6U : 1U;
        const std::uint64_t points = EffectivePointDrawCount(runtimeState, session);
        const std::uint64_t contribution =
            points > std::numeric_limits<std::uint64_t>::max() / multiplier
                ? std::numeric_limits<std::uint64_t>::max()
                : points * multiplier;
        total = contribution > std::numeric_limits<std::uint64_t>::max() - total
                    ? std::numeric_limits<std::uint64_t>::max()
                    : total + contribution;
    }
    return total;
}

bool PollWaterSeepageSupportJob(PreviewRuntimeState* runtimeState) {
    if (runtimeState == nullptr) {
        return false;
    }
    auto& water = runtimeState->water;
    auto shared = water.seepageSupportJob.shared;
    if (shared == nullptr) {
        return false;
    }
    std::string semanticKey;
    std::vector<std::string> nodeFingerprints;
    std::vector<WaterSeepageSupportBuildResult> results;
    std::exception_ptr buildFailure;
    {
        std::scoped_lock lock(shared->mutex);
        if (!shared->completed) {
            return false;
        }
        semanticKey = shared->semanticKey;
        nodeFingerprints = std::move(shared->nodeFingerprints);
        results = std::move(shared->results);
        buildFailure = shared->failure;
    }
    water.seepageSupportJob = {};

    auto& pending = water.seepagePendingSupportSelections[semanticKey];
    auto& pendingFingerprints =
        water.seepagePendingSupportNodeFingerprints[semanticKey];
    std::string failure;
    if (buildFailure != nullptr) {
        // Keep the previously settled descriptor generation bound. The
        // worker publishes exceptions instead of allowing them to escape its
        // std::jthread entry point, which would invoke std::terminate.
        failure = "Connected Seepage support generation failed unexpectedly.";
    }
    std::size_t committedCount = 0U;
    for (std::size_t resultIndex = 0U;
         resultIndex < results.size() && resultIndex < nodeFingerprints.size();
         ++resultIndex) {
        const auto& candidate = results[resultIndex];
        WaterSeepageSupportSelection selection;
        if (!invisible_places::water::CommitWaterSeepageSupportSelection(
                candidate,
                &selection)) {
            if (candidate.surfaceUnavailable &&
                candidate.selection.nodeId != 0U) {
                const auto nodeId = candidate.selection.nodeId;
                std::erase_if(
                    pending,
                    [nodeId](
                        const WaterSeepageSupportSelection& settled) {
                        return settled.nodeId == nodeId;
                    });
                // A valid node with no local cell is a settled empty result for
                // this role. Remember its topology fingerprint so ordinary
                // frames do not retry it; moving the node or changing an
                // authored limit produces a new fingerprint and rebuilds.
                pendingFingerprints[nodeId] =
                    nodeFingerprints[resultIndex];
                ++committedCount;
                continue;
            }
            if (failure.empty()) {
                failure = candidate.errorMessage.empty()
                              ? "Connected Seepage support selection failed."
                              : candidate.errorMessage;
            }
            continue;
        }
        const auto nodeId = selection.nodeId;
        if (const auto existing = std::find_if(
                pending.begin(),
                pending.end(),
                [&](const WaterSeepageSupportSelection& candidateSelection) {
                    return candidateSelection.nodeId == nodeId;
                });
            existing == pending.end()) {
            pending.push_back(std::move(selection));
        } else {
            *existing = std::move(selection);
        }
        pendingFingerprints[nodeId] = nodeFingerprints[resultIndex];
        ++committedCount;
    }
    if (results.size() != nodeFingerprints.size() && failure.empty()) {
        failure = "Connected Seepage support selection was interrupted.";
    }
    if (!failure.empty()) {
        // The descriptor currently bound to the cloud remains untouched. A
        // changed limit/placement produces a new key and retries only that
        // node; discard this incomplete role draft without disturbing the
        // previously settled role grid.
        water.seepageSupportFailedKeys.insert(semanticKey);
        water.seepagePendingSupportSelections.erase(semanticKey);
        water.seepagePendingSupportNodeFingerprints.erase(semanticKey);
        water.seepageSupportWarning = failure;
        return true;
    }
    water.seepageSupportFailedKeys.erase(semanticKey);
    water.seepageSupportBuildRevision += committedCount;
    water.seepageSupportWarning.clear();
    return true;
}

bool EnsureWaterSeepageSupportSelectionQueued(
    PreviewRuntimeState* runtimeState,
    const PreviewLayerSession& session,
    std::string_view semanticKey) {
    if (runtimeState == nullptr || semanticKey.empty()) {
        return false;
    }
    auto& water = runtimeState->water;
    // Failed semantic keys deliberately remain on the last descriptor-bound
    // generation. A topology-authoring change produces a different key and
    // permits a fresh node-local build without polling/rebuilding this one.
    if (water.seepageSupportFailedKeys.contains(std::string{semanticKey})) {
        return false;
    }
    const auto existing = water.seepageSupportSelections.find(std::string{semanticKey});
    if (existing != water.seepageSupportSelections.end()) {
        return true;
    }
    if (water.waterSurfaceCache == nullptr ||
        water.waterSurfaceCache->flowSurfaceSurfels.empty()) {
        return false;
    }

    const auto role = NormalizeWaterSeepageRoleName(session.sceneRole);
    auto nodes = WaterSeepageNodesForRole(water.seepageNodes, role);
    if (nodes.empty()) {
        water.seepageSupportSelections.emplace(
            std::string{semanticKey},
            std::vector<WaterSeepageSupportSelection>{});
        water.seepageSupportNodeFingerprints.emplace(
            std::string{semanticKey},
            std::unordered_map<std::uint32_t, std::string>{});
        return true;
    }

    const std::string semanticKeyString{semanticKey};
    auto pendingIt = water.seepagePendingSupportSelections.find(semanticKeyString);
    if (pendingIt == water.seepagePendingSupportSelections.end()) {
        std::vector<WaterSeepageSupportSelection> reusable;
        std::unordered_map<std::uint32_t, std::string> reusableFingerprints;
        reusable.reserve(nodes.size());
        reusableFingerprints.reserve(nodes.size());
        for (const auto& node : nodes) {
            const auto nodeFingerprint = WaterSeepageSupportNodeFingerprint(
                semanticKey,
                node,
                role);
            const WaterSeepageSupportSelection* reusedSelection = nullptr;
            for (const auto& [candidateSemanticKey, candidateFingerprints] :
                 water.seepageSupportNodeFingerprints) {
                const auto fingerprintIt = candidateFingerprints.find(node.id);
                if (fingerprintIt == candidateFingerprints.end() ||
                    fingerprintIt->second != nodeFingerprint) {
                    continue;
                }
                const auto selectionsIt =
                    water.seepageSupportSelections.find(candidateSemanticKey);
                if (selectionsIt == water.seepageSupportSelections.end()) {
                    continue;
                }
                const auto selectionIt = std::find_if(
                    selectionsIt->second.begin(),
                    selectionsIt->second.end(),
                    [&](const WaterSeepageSupportSelection& selection) {
                        return selection.nodeId == node.id &&
                               NormalizeWaterSeepageRoleName(selection.targetSceneRole) == role;
                    });
                if (selectionIt != selectionsIt->second.end()) {
                    reusedSelection = &*selectionIt;
                    break;
                }
            }
            if (reusedSelection != nullptr) {
                reusable.push_back(*reusedSelection);
                reusableFingerprints[node.id] = nodeFingerprint;
            }
        }
        pendingIt = water.seepagePendingSupportSelections.emplace(
            semanticKeyString,
            std::move(reusable)).first;
        water.seepagePendingSupportNodeFingerprints.emplace(
            semanticKeyString,
            std::move(reusableFingerprints));
    }

    auto& pendingFingerprints =
        water.seepagePendingSupportNodeFingerprints[semanticKeyString];
    std::vector<WaterSeepageNode> missingNodes;
    std::vector<std::string> missingFingerprints;
    for (const auto& node : nodes) {
        const auto nodeFingerprint = WaterSeepageSupportNodeFingerprint(
            semanticKey,
            node,
            role);
        const auto fingerprintIt = pendingFingerprints.find(node.id);
        if (fingerprintIt != pendingFingerprints.end() &&
            fingerprintIt->second == nodeFingerprint) {
            continue;
        }
        missingNodes.push_back(node);
        missingFingerprints.push_back(nodeFingerprint);
    }
    if (missingNodes.empty()) {
        water.seepageSupportSelections[semanticKeyString] =
            std::move(pendingIt->second);
        water.seepageSupportNodeFingerprints[semanticKeyString] =
            std::move(pendingFingerprints);
        water.seepagePendingSupportSelections.erase(semanticKeyString);
        water.seepagePendingSupportNodeFingerprints.erase(semanticKeyString);
        water.seepageRuntimeGrids.erase(semanticKeyString);
        water.seepageSupportWarning.clear();
        return true;
    }
    if (water.seepageSupportJob.worker.joinable()) {
        return false;
    }

    auto shared = std::make_shared<WaterSeepageSupportJobShared>();
    shared->semanticKey = semanticKeyString;
    shared->nodeFingerprints = missingFingerprints;
    const auto cache = std::shared_ptr<const WaterSurfaceCache>{water.waterSurfaceCache};
    water.seepageSupportJob.shared = shared;
    water.seepageSupportJob.semanticKey = semanticKeyString;
    water.seepageSupportJob.worker = std::jthread(
        [shared, cache, nodes = std::move(missingNodes), role](std::stop_token stopToken) mutable {
            std::vector<WaterSeepageSupportBuildResult> results;
            std::exception_ptr failure;
            try {
                invisible_places::water::WaterSeepageSupportBuildOptions options;
                options.stopToken = &stopToken;
                results =
                    invisible_places::water::BuildWaterSeepageSupportSelections(
                        nodes,
                        role,
                        *cache,
                        options,
                        3U);
            } catch (...) {
                // This outer boundary also contains failures that occur while
                // allocating the result vector or starting the bounded inner
                // workers, before a per-node candidate exists.
                failure = std::current_exception();
            }
            std::scoped_lock lock(shared->mutex);
            shared->results = std::move(results);
            shared->failure = failure;
            shared->completed = true;
        });
    return false;
}

void EnsureWaterSeepageRuntimeUpToDate(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    const WaterFrameState* frameState = nullptr) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    PollWaterSeepageSupportJob(runtimeState);
    if (const auto* activeScene = ActiveWaterSurfaceScene(runtimeState);
        activeScene != nullptr && !activeScene->waterSurfaceSources.empty() &&
        (runtimeState->water.waterSurfaceCache == nullptr ||
         runtimeState->water.waterSurfaceSceneGroupName != activeScene->sceneGroupName ||
         runtimeState->water.waterSurfaceCacheSignature != activeScene->waterSurfaceSignature ||
         runtimeState->water.waterSurfaceCacheWarmup.worker.joinable() ||
         runtimeState->water.waterSurfaceCachePreprocessPending)) {
        // Preserve the last settled topology while the one immutable surface
        // artifact for this scene is still loading/preprocessing. Installation
        // invalidates once, avoiding a display-cloud fallback build followed by
        // an immediate second topology build.
        return;
    }
    const auto effectiveInvocations = EffectiveWaterSeepageShaderInvocations(*runtimeState);
    const auto evaluatedWaterFrame = frameState == nullptr
                                         ? ResolveWaterFrameState(runtimeState)
                                         : WaterFrameState{};
    const auto& activeWater = frameState != nullptr ? *frameState : evaluatedWaterFrame;
    std::size_t totalBytes = 0U;
    std::uint32_t overflowCells = 0U;
    std::unordered_set<std::string> activeAttachmentKeys;
    std::unordered_set<std::string> activeSemanticKeys;
    std::unordered_set<std::string> activeGuideKeys;
    std::unordered_map<std::string, std::string>
        activeSemanticParamsFingerprints;

    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState->sessions.size(); ++sessionIndex) {
        const auto& session = runtimeState->sessions[sessionIndex];
        // Seepage is an appearance effect for the authored ROCK/VEG/SAND
        // support clouds. Generated Flow/Mesh Flow/Ripple/Field sessions own
        // different GPU resources; a newly dispatched GPU Flow source can be
        // renderable while its settled point count is still zero. Treating it
        // as Seepage support would call the terrain-only upload API during
        // that valid pending state.
        if (!IsRenderablePointCloudSource(*runtimeState, session) ||
            !IsAuthoredWaterTerrainSession(session)) {
            continue;
        }
        const auto attachmentKey = WaterSeepageLayerAttachmentKey(sessionIndex);
        const auto semanticKey = WaterSeepageSemanticTopologyKey(*runtimeState, session);
        activeAttachmentKeys.insert(attachmentKey);
        const bool firstSemanticUse = activeSemanticKeys.insert(semanticKey).second;
        if (runtimeState->water.waterSurfaceCache != nullptr &&
            !EnsureWaterSeepageSupportSelectionQueued(
                runtimeState,
                session,
                semanticKey)) {
            // Keep the prior descriptor generation visible until the complete
            // node-local connected selection is ready or reports a bounded
            // failure. Never publish a transient fan for a cache-backed scene.
            return;
        }
        auto gridIt = runtimeState->water.seepageRuntimeGrids.find(semanticKey);
        if (gridIt == runtimeState->water.seepageRuntimeGrids.end()) {
            WaterSeepageSpatialGrid grid;
            std::string surfaceGuideKey;
            const auto supportIt = runtimeState->water.seepageSupportSelections.find(semanticKey);
            const bool hasConnectedSelection =
                supportIt != runtimeState->water.seepageSupportSelections.end();
            // Cache-backed grouped scenes no longer trace or reduce an
            // eight-station fan. Their immutable connected-cell selection is
            // already the complete topology; guides remain only as the
            // bounded standalone-cloud compatibility path.
            const auto* surfaceGuides = hasConnectedSelection
                                            ? nullptr
                                            : EnsureWaterSeepageSurfaceGuidesForSession(
                                                  runtimeState,
                                                  session,
                                                  &surfaceGuideKey);
            const auto guideSpan = surfaceGuides == nullptr
                                       ? std::span<const WaterSeepageSurfaceGuide>{}
                                       : std::span<const WaterSeepageSurfaceGuide>{*surfaceGuides};
            const auto guidedNodes = WaterSeepageNodesWithValidSurfaceGuides(
                runtimeState->water.seepageNodes,
                guideSpan);
            const auto roleNodes = WaterSeepageNodesForRole(
                runtimeState->water.seepageNodes,
                session.sceneRole);
            const auto supportSpan = !hasConnectedSelection
                                         ? std::span<const WaterSeepageSupportSelection>{}
                                         : std::span<const WaterSeepageSupportSelection>{supportIt->second};
            std::vector<WaterSeepageNode> connectedNodes;
            if (hasConnectedSelection) {
                connectedNodes.reserve(roleNodes.size());
                for (const auto& node : roleNodes) {
                    if (std::any_of(
                            supportIt->second.begin(),
                            supportIt->second.end(),
                            [&](const WaterSeepageSupportSelection&
                                    selection) {
                                return selection.nodeId == node.id &&
                                       !selection.cells.empty() &&
                                       !selection.fingerprint.empty();
                            })) {
                        connectedNodes.push_back(node);
                    }
                }
            }
            const auto nodesForGrid = hasConnectedSelection
                                          ? std::span<const WaterSeepageNode>{connectedNodes}
                                          : std::span<const WaterSeepageNode>{guidedNodes};
            grid = invisible_places::water::BuildWaterSeepageSpatialGrid(
                nodesForGrid,
                runtimeState->water.seepageLookProfiles,
                runtimeState->water.defaultSeepageLook,
                session.sceneRole,
                false,
                runtimeState->water.collisionRainSettings,
                effectiveInvocations,
                guideSpan,
                activeWater.seepageScenarioState,
                activeWater.nodeStates,
                supportSpan,
                runtimeState->water.seepageResponseProfiles);
            if (grid.diagnostics.supportOverflowCellCount > 0U ||
                grid.diagnostics.droppedSupportReferenceCount > 0U) {
                // More than eight authored nodes intersecting one 10 mm cell
                // is an invalid topology, not a licence to publish a partial
                // selection. Keep every existing descriptor/resource alive;
                // reducing an authored selection limit changes the semantic
                // key and retries this role asynchronously.
                runtimeState->water.seepageSupportFailedKeys.insert(semanticKey);
                runtimeState->water.seepageSupportWarning =
                    "Connected Seepage support exceeds eight nodes in a 10 mm cell; "
                    "reduce Selection Reach/Width limits. The last settled topology is retained.";
                return;
            }
            gridIt = runtimeState->water.seepageRuntimeGrids.emplace(
                semanticKey,
                std::move(grid)).first;
            runtimeState->water.seepageSupportFailedKeys.erase(semanticKey);
            ++runtimeState->water.seepageTopologyBuildRevision;
            if (!surfaceGuideKey.empty()) {
                runtimeState->water.seepageRuntimeGuideKeys[semanticKey] = surfaceGuideKey;
            }
        } else if (firstSemanticUse) {
            // This touches only one compact record per active node. The hash
            // table, references, guide samples, and point cloud remain intact.
            invisible_places::water::ApplyWaterSeepageRuntimeParameters(
                &gridIt->second,
                runtimeState->water.seepageNodes,
                runtimeState->water.seepageLookProfiles,
                runtimeState->water.defaultSeepageLook,
                activeWater.seepageScenarioState,
                runtimeState->water.collisionRainSettings,
                effectiveInvocations,
                activeWater.nodeStates,
                runtimeState->water.seepageResponseProfiles);
        }
        if (const auto guideKey = runtimeState->water.seepageRuntimeGuideKeys.find(semanticKey);
            guideKey != runtimeState->water.seepageRuntimeGuideKeys.end()) {
            activeGuideKeys.insert(guideKey->second);
        }
        auto& grid = gridIt->second;
        if (firstSemanticUse) {
            // The compact reference field changes only with authored shape.
            // Shader frame time advances it continuously, so clock-only
            // frames do not change this fingerprint or publish parameters.
            invisible_places::water::PrepareWaterSeepagePulseFields(
                &grid,
                0.0F);
            activeSemanticParamsFingerprints.emplace(
                semanticKey,
                invisible_places::water::
                    WaterSeepageParamsFingerprint(grid));
        }
        const auto paramsFingerprintIt =
            activeSemanticParamsFingerprints.find(semanticKey);
        if (paramsFingerprintIt ==
            activeSemanticParamsFingerprints.end()) {
            runtimeState->errorMessage =
                "Seepage parameter preparation did not settle for " +
                semanticKey + '.';
            runtimeState->statusMessage.clear();
            continue;
        }
        const auto& paramsFingerprint =
            paramsFingerprintIt->second;
        const auto topologyIt = runtimeState->water.seepageTopologyFingerprints.find(attachmentKey);
        const auto semanticAttachmentIt =
            runtimeState->water.seepageAttachmentSemanticKeys.find(attachmentKey);
        // The semantic key already contains every topology-generating input and
        // the immutable cache identity. Once a grid is attached under that key,
        // live reach/width/look/animation changes cannot alter its cells. Avoid
        // walking and hashing up to 262,144 support references per node every
        // frame; compute the large fingerprint only for a new layer attachment.
        const bool topologyCurrent =
            topologyIt != runtimeState->water.seepageTopologyFingerprints.end() &&
            semanticAttachmentIt !=
                runtimeState->water.seepageAttachmentSemanticKeys.end() &&
            semanticAttachmentIt->second == semanticKey &&
            viewport->WaterSeepageNodeCount(sessionIndex) == grid.nodes.size();
        try {
            if (!topologyCurrent) {
                const auto topologyFingerprint =
                    invisible_places::water::WaterSeepageTopologyFingerprint(grid);
                viewport->UploadWaterSeepageTopology(sessionIndex, grid);
                runtimeState->water.seepageTopologyFingerprints[attachmentKey] = topologyFingerprint;
                runtimeState->water.seepageAttachmentSemanticKeys[attachmentKey] = semanticKey;
                runtimeState->water.seepageParamsFingerprints[attachmentKey] = paramsFingerprint;
                ++runtimeState->water.seepageDescriptorAttachmentRevision;
                ++runtimeState->water.seepageTopologyUploadRevision;
                ++runtimeState->water.seepageParamsUploadRevision;
            } else {
                const auto paramsIt = runtimeState->water.seepageParamsFingerprints.find(attachmentKey);
                if (paramsIt == runtimeState->water.seepageParamsFingerprints.end() ||
                    paramsIt->second != paramsFingerprint) {
                    try {
                        viewport->UpdateWaterSeepageParams(sessionIndex, grid);
                        ++runtimeState->water.seepageParamsUploadRevision;
                    } catch (const std::exception&) {
                        viewport->UploadWaterSeepageTopology(sessionIndex, grid);
                        ++runtimeState->water.seepageDescriptorAttachmentRevision;
                        ++runtimeState->water.seepageTopologyUploadRevision;
                        ++runtimeState->water.seepageParamsUploadRevision;
                    }
                    runtimeState->water.seepageParamsFingerprints[attachmentKey] = paramsFingerprint;
                }
            }
        } catch (const std::exception& error) {
            runtimeState->errorMessage = "GPU upload failed for Seepage: " + std::string{error.what()};
            runtimeState->statusMessage.clear();
            continue;
        }
        const auto residentBytes =
            viewport->WaterSeepageResidentBytes(sessionIndex);
        totalBytes =
            residentBytes >
                    std::numeric_limits<std::size_t>::max() - totalBytes
                ? std::numeric_limits<std::size_t>::max()
                : totalBytes +
                      static_cast<std::size_t>(residentBytes);
        if (firstSemanticUse) {
            overflowCells += grid.diagnostics.overflowCellCount;
            overflowCells += grid.diagnostics.supportOverflowCellCount;
        }
    }

    std::erase_if(
        runtimeState->water.seepageTopologyFingerprints,
        [&](const auto& entry) { return !activeAttachmentKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageAttachmentSemanticKeys,
        [&](const auto& entry) { return !activeAttachmentKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageParamsFingerprints,
        [&](const auto& entry) { return !activeAttachmentKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageRuntimeGrids,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSupportSelections,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSupportNodeFingerprints,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepagePendingSupportSelections,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepagePendingSupportNodeFingerprints,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSupportFailedKeys,
        [&](const auto& key) { return !activeSemanticKeys.contains(key); });
    std::erase_if(
        runtimeState->water.seepageRuntimeGuideKeys,
        [&](const auto& entry) { return !activeSemanticKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSurfaceGuides,
        [&](const auto& entry) { return !activeGuideKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSurfaceGuideFingerprints,
        [&](const auto& entry) { return !activeGuideKeys.contains(entry.first); });
    std::erase_if(
        runtimeState->water.seepageSurfaceGuideNodeFingerprints,
        [&](const auto& entry) { return !activeGuideKeys.contains(entry.first); });
    runtimeState->water.seepageGpuBytes = totalBytes;
    runtimeState->water.seepageOverflowCellCount = overflowCells;
}

bool PreviewWaterSeepageRequiresSceneRedraw(
    const PreviewRuntimeState& runtimeState) {
    std::unordered_set<std::string> visitedSemanticKeys;
    for (const auto& session : runtimeState.sessions) {
        if (!IsRenderablePointCloudSource(runtimeState, session) ||
            !IsAuthoredWaterTerrainSession(session)) {
            continue;
        }
        const auto semanticKey = WaterSeepageSemanticTopologyKey(runtimeState, session);
        if (!visitedSemanticKeys.insert(semanticKey).second) {
            continue;
        }
        const auto grid = runtimeState.water.seepageRuntimeGrids.find(semanticKey);
        // Only time-animating seepage needs a redraw every frame. Static
        // looks stay correct in the cached scene image: any slider edit or
        // animation-track change re-uploads the params (fingerprint check in
        // EnsureWaterSeepageRuntimeUpToDate), which bumps the viewport's
        // scene revision and re-renders once.
        if (grid != runtimeState.water.seepageRuntimeGrids.end() &&
            invisible_places::water::WaterSeepageGridHasTimeAnimatingViewportEffect(grid->second)) {
            return true;
        }
    }
    return false;
}

bool PreviewLiveVisualEffectsRequireSceneRedraw(
    const PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    float currentFlowTimeSeconds) {
    // Evaluate the same transient Rain state as BuildRenderState. A keyed
    // level can activate authored-disabled Rain, while a run that keys only
    // wind or appearance must continue advancing authored-enabled Rain.
    auto effectiveRain = runtimeState.water.collisionRainSettings;
    auto scenario = ResolveActiveWaterScenarioState(runtimeState);
    invisible_places::water::WaterFeatureTimingOverlay overlay;
    const invisible_places::water::WaterFeatureTimingOverlay* overlayPtr =
        nullptr;
    if (const auto* entry = FindScenarioFeatureRuns(
            runtimeState.water,
            ActiveWaterTimingScenarioId(runtimeState));
        entry != nullptr) {
        overlay = invisible_places::water::BuildWaterFeatureTimingOverlay(
            entry->waterFeatureTimingRuns,
            std::clamp(
                runtimeState.animationPanel.scrubAmount,
                0.0F,
                1.0F));
        overlayPtr = &overlay;
        invisible_places::water::ApplyWaterFeatureTimingOverlayToRainSettings(
            overlay,
            &effectiveRain,
            nullptr);
        if (scenario.has_value()) {
            invisible_places::water::ApplyWaterFeatureTimingOverlayToScenario(
                overlay,
                &scenario.value());
        }
    }
    if (effectiveRain.enabled && effectiveRain.rainLevel > 1.0e-5F) {
        return true;
    }
    // Once emission reaches zero, keep advancing only until the last
    // possible GPU impact has aged out. Otherwise scene caching would freeze
    // wetness/rings on their final rainy frame.
    if (viewport.RainImpactEffectsRequireRedraw(currentFlowTimeSeconds)) {
        return true;
    }
    // While an offline render owns the frame pump, the live Mesh Flow update
    // (and with it the activity stamp) is paused, so the quiescence tail
    // cannot be compared against the still-advancing live clock — keep the
    // pre-existing always-redraw behaviour for the export's duration.
    if (kMeshFlowWaterRuntimeEnabled &&
        runtimeState.water.dynamicMeshFlowSettings.enabled &&
        runtimeState.water.dynamicMeshFlowSettings.showTrails &&
        (runtimeState.offlineRenderJob.active ||
         !DynamicMeshFlowIsQuiescent(runtimeState, currentFlowTimeSeconds))) {
        return true;
    }
    if (PreviewWaterSeepageRequiresSceneRedraw(runtimeState)) {
        return true;
    }
    const bool fastBasicRenderer =
        FastBasicPointRendererActive(runtimeState.projectSettings) &&
        !VisibleGeneratedWaterTrailOverlayPresent(runtimeState);

    // Project-owned Shoreline effects animate continuously whenever visible.
    // Resolve them exactly as BuildRenderState will so a keyed-zero list does
    // not latch redraws and legacy point-visual shoreline fields are ignored.
    const auto resolvedShorelines =
        ResolveShorelinesForFrame(
            runtimeState.water.shorelineInstances,
            overlayPtr,
            scenario);

    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState.sessions.size(); ++sessionIndex) {
        const auto& session = runtimeState.sessions[sessionIndex];
        if (!IsRenderablePointCloudSource(runtimeState, session)) {
            continue;
        }
        auto renderStyle = MakeSceneRenderStyle(runtimeState, session, session.pointStyle);
        ClearPointCloudStyleShoreline(&renderStyle);
        if (!resolvedShorelines.empty() &&
            SceneRoleIs(session.sceneRole, "sand")) {
            return true;
        }
        if (!runtimeState.projectSettings.liveVisualEffects ||
            fastBasicRenderer) {
            continue;
        }
        // A trail-overlay session at zero flow activity renders nothing: the
        // shader multiplies every trail's opacity and emission by the
        // activity gate, so neither its trail overlay nor its flow
        // animation can change pixels until activity returns (which changes
        // the render-state signature and resumes redraws).
        const bool trailOverlayContentVisible =
            !renderStyle.waterTrailOverlay ||
            renderStyle.waterFlowActivity > 0.0F;
        if (((renderStyle.flowAnimation || renderStyle.waterTrailOverlay) &&
             trailOverlayContentVisible) ||
            invisible_places::renderer::pointcloud::PointCloudStyleHasActiveRoughnessMotion(renderStyle) ||
            invisible_places::renderer::pointcloud::PointCloudStyleHasActiveCaustics(renderStyle) ||
            (kRippleWaterRuntimeEnabled &&
             viewport.SparseWaterRippleEffectCount(sessionIndex) > 0U)) {
            return true;
        }
    }
    return false;
}

WaterSurfaceRole RainCollisionRoleForSession(const PreviewLayerSession& session) {
    const auto role = invisible_places::scene::ParseScenePointCloudRole(session.sceneRole);
    if (!role.has_value()) {
        return WaterSurfaceRole::None;
    }
    switch (role.value()) {
        case invisible_places::scene::ScenePointCloudRole::Rock:
            return WaterSurfaceRole::Rock;
        case invisible_places::scene::ScenePointCloudRole::Sand:
            return WaterSurfaceRole::Sand;
        case invisible_places::scene::ScenePointCloudRole::Vegetation:
            return WaterSurfaceRole::Vegetation;
    }
    return WaterSurfaceRole::None;
}

invisible_places::renderer::core::SceneRenderState BuildRenderState(
    PreviewRuntimeState& runtimeState,
    const invisible_places::renderer::core::VulkanViewportShell& viewport,
    float flowTimeSeconds,
    const WaterFrameState* frameState = nullptr) {
    invisible_places::renderer::core::SceneRenderState renderState;
    const auto aspectRatio = CurrentAspectRatio(viewport);
    const auto matrices = runtimeState.camera.Matrices(aspectRatio);
    const bool fastBasicRenderer =
        FastBasicPointRendererActive(runtimeState.projectSettings) &&
        !VisibleGeneratedWaterTrailOverlayPresent(runtimeState);

    renderState.view = matrices.view;
    renderState.projection = matrices.projection;
    renderState.viewProjection = matrices.viewProjection;
    renderState.cameraPosition = matrices.position;
    renderState.backgroundColor = glm::vec4{
        runtimeState.projectSettings.backgroundColor[0],
        runtimeState.projectSettings.backgroundColor[1],
        runtimeState.projectSettings.backgroundColor[2],
        runtimeState.projectSettings.backgroundColor[3],
    };
    renderState.proResAlphaPreviewEnabled = runtimeState.projectSettings.proResAlphaPreviewEnabled;
    renderState.previewPerformanceMode = runtimeState.projectSettings.previewPerformanceMode;
    renderState.pointCloudRendererMode =
        fastBasicRenderer ? PointCloudRendererMode::FastBasic : PointCloudRendererMode::Beauty;
    renderState.eyeDomeLightingEnabled =
        runtimeState.projectSettings.eyeDomeLightingEnabled &&
        !fastBasicRenderer;
    renderState.eyeDomeLightingThickness = runtimeState.projectSettings.eyeDomeLightingThickness;
    renderState.nearPlane = runtimeState.camera.NearPlane();
    renderState.farPlane = runtimeState.camera.FarPlane();
    const auto cameraState = runtimeState.camera.CaptureState();
    renderState.hasDepthOfField =
        cameraState.hasDepthOfField && !fastBasicRenderer;
    renderState.focusDistance = cameraState.focusDistance;
    renderState.apertureFStops = cameraState.apertureFStops;
    renderState.depthOfFieldMaxBlurPixels = cameraState.depthOfFieldMaxBlurPixels;
    renderState.gaussianSplatFootprintBoost = runtimeState.projectSettings.gaussianSplatFootprintBoost;
    renderState.flowTimeSeconds = flowTimeSeconds;
    renderState.pointSizeScale = 1.0F;
    renderState.rainSettings = runtimeState.water.collisionRainSettings;
    const auto evaluatedWaterFrame = frameState == nullptr
                                         ? ResolveWaterFrameState(&runtimeState)
                                         : WaterFrameState{};
    const auto& waterFrame = frameState != nullptr ? *frameState : evaluatedWaterFrame;
    const auto& activeWaterScenario = waterFrame.rawScenarioState;
    const auto* activeColouriseEffects =
        ActiveTimingColouriseEffects(runtimeState);
    renderState.rainVisual = runtimeState.water.rainVisual;
    invisible_places::water::ApplyWaterFeatureTimingOverlayToRainSettings(
        waterFrame.featureOverlay,
        &renderState.rainSettings,
        &renderState.rainVisual);
    renderState.rainSpawnCentre = runtimeState.camera.OrbitCenter();
    const auto resolvedShorelines = ResolveShorelinesForFrame(
        runtimeState.water.shorelineInstances,
        &waterFrame.featureOverlay,
        activeWaterScenario);
    if (resolvedShorelines.size() > 1U) {
        renderState.additionalShorelines.assign(
            resolvedShorelines.begin() + 1,
            resolvedShorelines.end());
    }

    for (std::size_t sessionIndex = 0; sessionIndex < runtimeState.sessions.size(); ++sessionIndex) {
        const auto& session = runtimeState.sessions[sessionIndex];
        if (session.kind == LayerKind::PointCloud) {
            if (!IsRenderablePointCloudSource(runtimeState, session)) {
                continue;
            }
            auto drawPointCount = std::min<std::uint64_t>(
                EffectivePointDrawCount(runtimeState, session),
                std::numeric_limits<std::uint32_t>::max());
            auto renderStyle = MakeSceneRenderStyle(
                runtimeState,
                session,
                session.pointStyle);
            ApplyWaterFlowSourceActivityToStyle(
                runtimeState.water,
                session,
                activeWaterScenario,
                &renderStyle,
                &waterFrame.featureOverlay);
            ClearPointCloudStyleShoreline(&renderStyle);
            if (SceneRoleIs(session.sceneRole, "sand") &&
                !resolvedShorelines.empty()) {
                invisible_places::renderer::pointcloud::
                    ApplyPointCloudShorelineWaveSettings(
                        &renderStyle,
                        resolvedShorelines.front());
            }
            renderState.pointCloudLayers.push_back(
                {.layerId = sessionIndex,
                 .style = fastBasicRenderer
                              ? MakeEffectiveFastBasicStyle(
                                    renderStyle,
                                    session.hasSourceRgb,
                                    IsGeneratedWaterOverlaySession(session))
                              : renderStyle,
                 .timingColourise =
                     activeColouriseEffects != nullptr &&
                             IsAuthoredTimingColouriseLayer(session)
                         ? ResolveTimingColouriseStack(
                               *activeColouriseEffects,
                               session.scalarFields,
                               session.hasNormals,
                               waterFrame.normalizedTime)
                         : invisible_places::renderer::pointcloud::
                           ResolvedTimingColouriseStack{},
                 .scalarFields = session.scalarFields,
                 .generatedWaterOverlay =
                     IsGeneratedWaterOverlaySession(session),
                 .regionWaterEffectsEnabled =
                     kRippleWaterRuntimeEnabled ||
                     kFieldWaterRuntimeEnabled,
                 .hasSourceRgb = session.hasSourceRgb,
                 .hasNormals = session.hasNormals,
                 .timingColouriseEligible =
                     IsAuthoredTimingColouriseLayer(session),
                 .shorelineInstancesEligible =
                     SceneRoleIs(session.sceneRole, "sand"),
                 .worldZBoundsValid = session.bounds.valid,
                 .worldMinZ = session.bounds.minimum.z,
                 .worldMaxZ = session.bounds.maximum.z,
                 .drawPointCount = static_cast<std::uint32_t>(drawPointCount),
                 .densityCompensation = ResolveSessionDensityCompensation(runtimeState, session),
                 .rainCollisionRole = RainCollisionRoleForSession(session)});
        } else {
            if (!session.loaded || !session.visible) {
                continue;
            }
            const auto effectiveFrame = ComputeEffectiveLayerFrame(runtimeState, session);
            if (effectiveFrame.bounds.valid &&
                !BoundsIntersectsViewFrustum(effectiveFrame.bounds, renderState.viewProjection)) {
                continue;
            }

            auto effectiveStyle = session.gsplatStyle;
            effectiveStyle.qualityMode = EffectiveGaussianSplatQualityMode(runtimeState, session);
            renderState.gaussianSplatLayers.push_back(
                {.layerId = sessionIndex,
                 .style = effectiveStyle,
                 .localToWorld = EffectiveGsplatLocalToWorld(runtimeState.projectSettings, session)});
        }
    }

    const auto& ghost = runtimeState.animationPanel.matchingFrameGhost;
    const bool ghostOwnsActiveAnimation =
        ghost.uploaded && ghost.visible &&
        ghost.matchingFrameAvailable &&
        ghost.captureMatchesCurrentFrame &&
        !runtimeState.offlineRenderJob.active &&
        !runtimeState.activeRenderSetupOverride.has_value() &&
        !runtimeState.animationPanel.currentFilePath.empty() &&
        PathsLexicallyEqual(
            std::filesystem::path{
                runtimeState.animationPanel.currentFilePath},
            ghost.currentFilePath);
    const auto ghostPartnerIndex = ghostOwnsActiveAnimation
        ? FindAnimationRegistryIndex(
              runtimeState.animationPanel,
              ghost.partnerFilePath)
        : std::nullopt;
    const auto* ghostPartner = ghostPartnerIndex.has_value()
        ? RegistryAnimationPath(
              runtimeState,
              ghostPartnerIndex.value())
        : nullptr;
    const bool ghostPairStillValid =
        ghostOwnsActiveAnimation &&
        runtimeState.animationPanel.currentPath.has_value() &&
        runtimeState.animationPanel.currentPath->velocityBlendLink
            .has_value() &&
        ghostPartner != nullptr &&
        ghostPartner->velocityBlendLink.has_value() &&
        runtimeState.animationPanel.currentPath->velocityBlendLink
                ->pairId == ghost.pairId &&
        ghostPartner->velocityBlendLink->pairId == ghost.pairId;
    if (ghostPairStillValid && ghost.capturedPointCount > 0U) {
        PointCloudStyleState ghostStyle;
        ghostStyle.geometryMode = PointCloudGeometryMode::ScreenSprites;
        ghostStyle.screenSpriteSizeMode =
            PointCloudScreenSpriteSizeMode::WorldMillimeters;
        ghostStyle.falloffProfile = PointCloudFalloffProfile::HardDisc;
        ghostStyle.colorMode = PointCloudColorMode::SolidColor;
        ghostStyle.solidColor = {1.0F, 1.0F, 1.0F, 1.0F};
        ghostStyle.exposure = 1.0F;
        ghostStyle.flowAnimation = false;
        ghostStyle.waterPathView = false;
        ghostStyle.waterTrailOverlay = false;
        ghostStyle.rainImpactEffects = false;
        ghostStyle.causticAnimation = false;
        ghostStyle.causticIntensity = 0.0F;
        ghostStyle.roughnessMotionStrength = 0.0F;
        ghostStyle.shorelineWaveEnabled = false;
        ghostStyle.depthFade.active = false;
        invisible_places::style::SetScalarConstant(
            &ghostStyle.pointSize,
            1.0F);
        invisible_places::style::SetScalarConstant(
            &ghostStyle.surfelDiameter,
            std::clamp(
                ghost.pointSizeMillimeters,
                0.5F,
                50.0F) /
                1000.0F);
        invisible_places::style::SetScalarConstant(
            &ghostStyle.opacity,
            std::clamp(ghost.opacity, 0.02F, 1.0F));
        invisible_places::style::SetScalarConstant(
            &ghostStyle.emissiveStrength,
            0.0F);
        invisible_places::style::SetScalarConstant(
            &ghostStyle.depthFade,
            0.0F);
        renderState.pointCloudLayers.push_back(
            {.layerId = kAnimationMatchingFrameGhostLayerId,
             .style = ghostStyle,
             .generatedWaterOverlay = false,
             .regionWaterEffectsEnabled = false,
             .hasSourceRgb = false,
             .hasNormals = false,
             .timingColouriseEligible = false,
             .shorelineInstancesEligible = false,
             .drawPointCount = static_cast<std::uint32_t>(
                 std::min<std::size_t>(
                     ghost.capturedPointCount,
                     std::numeric_limits<std::uint32_t>::max())),
             .densityCompensation = {},
             .rainCollisionRole = WaterSurfaceRole::None});
    }

    return renderState;
}

std::string JsonEscape(std::string_view value) {
    std::ostringstream output;
    for (const char character : value) {
        switch (character) {
            case '\\':
                output << "\\\\";
                break;
            case '"':
                output << "\\\"";
                break;
            case '\n':
                output << "\\n";
                break;
            case '\r':
                output << "\\r";
                break;
            case '\t':
                output << "\\t";
                break;
            default:
                output << character;
                break;
        }
    }
    return output.str();
}

void PumpGuiSmokeFrame(
    platform::Window* window,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    std::vector<double>* frameTimesMs = nullptr) {
    if (window == nullptr || runtimeState == nullptr || viewport == nullptr) {
        return;
    }
    const auto frameStart = std::chrono::steady_clock::now();
    window->PollEvents();
    EnsureWaterSurfaceCacheReady(runtimeState, viewport);
    PollWaterRegionPointPreviewJob(runtimeState);
    PollWaterFlowTrailBuildJob(runtimeState, viewport);
    PollWaterRippleLiveEffectRefresh(runtimeState, viewport);
    SyncWaterRegionPointPreviewHighlights(runtimeState, viewport);
    const auto waterFrameState = ResolveWaterFrameState(runtimeState);
    EnsureWaterSeepageRuntimeUpToDate(runtimeState, viewport, &waterFrameState);
    viewport->BeginUiFrame();
    DrawWaterRegionOverlay(runtimeState, *viewport);
    DrawWaterRegionPointPreviewOverlay(runtimeState, *viewport);
    DrawManualFlowPathOverlay(runtimeState, *viewport);
    DrawWaterSeepageOverlay(runtimeState, *viewport);
    viewport->SetDiagnosticsEnabled(true);
    viewport->SetSceneCachingEnabled(false);
    viewport->SetLiveSceneRenderingEnabled(true);
    const float previewFlowTimeSeconds =
        std::chrono::duration<float>(std::chrono::steady_clock::now() - runtimeState->startedAt).count();
    EnsureWaterDynamicMeshFlowGpuUpToDate(
        runtimeState,
        viewport,
        waterFrameState,
        previewFlowTimeSeconds);
    viewport->UpdateRenderState(
        BuildRenderState(
            *runtimeState,
            *viewport,
            previewFlowTimeSeconds,
            &waterFrameState));
    viewport->DrawFrame();
    if (frameTimesMs != nullptr) {
        frameTimesMs->push_back(
            std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - frameStart).count());
    }
}

// Acceptance smokes use the same queued display/cache ordering as the live
// application. The single WaterFrameState produced here is deliberately
// shared by Seepage and the viewport render for the sampled animation frame.
WaterFrameState PumpWaterIntegrationSmokeFrame(
    platform::Window* window,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    float simulatedSeconds,
    bool drawFrame = true,
    bool sceneCachingEnabled = false) {
    if (window == nullptr || runtimeState == nullptr || viewport == nullptr) {
        return {};
    }

    window->PollEvents();
    PollPendingLayerLoad(runtimeState, viewport);
    EnsureWaterSurfaceCacheReady(runtimeState, viewport);
    PollWaterRegionPointPreviewJob(runtimeState);
    PollWaterFlowTrailBuildJob(runtimeState, viewport);
    PollWaterRippleLiveEffectRefresh(runtimeState, viewport);
    SyncWaterRegionPointPreviewHighlights(runtimeState, viewport);
    CommitReadySceneDisplaySwitches(runtimeState, viewport);
    EnsureWaterSurfaceCacheReady(runtimeState, viewport);
    StartQueuedLayerLoadIfIdle(runtimeState);

    const auto waterFrameState = ResolveWaterFrameState(runtimeState);
    EnsureWaterSeepageRuntimeUpToDate(runtimeState, viewport, &waterFrameState);
    EnsureWaterDynamicMeshFlowGpuUpToDate(
        runtimeState,
        viewport,
        waterFrameState,
        simulatedSeconds);
    if (drawFrame) {
        viewport->BeginUiFrame();
    viewport->SetDiagnosticsEnabled(true);
    viewport->SetSceneCachingEnabled(sceneCachingEnabled);
    viewport->SetLiveSceneRenderingEnabled(true);
    viewport->SetLiveRainSimulationEnabled(true);
        viewport->UpdateRenderState(
            BuildRenderState(
                *runtimeState,
                *viewport,
                simulatedSeconds,
                &waterFrameState));
        viewport->DrawFrame();
    }
    return waterFrameState;
}

void PumpExportBenchmarkFrame(
    platform::Window* window,
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (window == nullptr || runtimeState == nullptr || viewport == nullptr) {
        return;
    }

    window->PollEvents();
    PollPendingLayerLoad(runtimeState, viewport);
    PollWaterRegionPointPreviewJob(runtimeState);
    PollWaterFlowTrailBuildJob(runtimeState, viewport);
    PollWaterRippleLiveEffectRefresh(runtimeState, viewport);
    SyncWaterRegionPointPreviewHighlights(runtimeState, viewport);
    if (!runtimeState->offlineRenderJob.active) {
        CommitReadySceneDisplaySwitches(runtimeState, viewport);
        StartQueuedLayerLoadIfIdle(runtimeState);
    }
    const auto waterFrameState = ResolveWaterFrameState(runtimeState);
    EnsureWaterSeepageRuntimeUpToDate(runtimeState, viewport, &waterFrameState);
    viewport->BeginUiFrame();
    viewport->SetDiagnosticsEnabled(true);
    viewport->SetSceneCachingEnabled(false);
    viewport->SetLiveSceneRenderingEnabled(!runtimeState->offlineRenderJob.active);
    viewport->SetLiveRainSimulationEnabled(
        !runtimeState->offlineRenderJob.active);
    if (!runtimeState->offlineRenderJob.active) {
        const float previewFlowTimeSeconds =
            std::chrono::duration<float>(std::chrono::steady_clock::now() - runtimeState->startedAt).count();
        EnsureWaterDynamicMeshFlowGpuUpToDate(
            runtimeState,
            viewport,
            waterFrameState,
            previewFlowTimeSeconds);
        viewport->UpdateRenderState(
            BuildRenderState(
                *runtimeState,
                *viewport,
                previewFlowTimeSeconds,
                &waterFrameState));
    }
    viewport->DrawFrame();
    if (runtimeState->offlineRenderJob.active) {
        ProcessOfflineRenderJobStep(runtimeState, viewport);
    }
}

double DurationSeconds(std::chrono::steady_clock::duration duration) {
    return std::chrono::duration<double>(duration).count();
}

std::string CsvEscape(std::string_view value) {
    const bool needsQuotes =
        value.find_first_of(",\"\n\r") != std::string_view::npos;
    if (!needsQuotes) {
        return std::string{value};
    }
    std::string escaped;
    escaped.reserve(value.size() + 2U);
    escaped.push_back('"');
    for (const char character : value) {
        if (character == '"') {
            escaped += "\"\"";
        } else {
            escaped.push_back(character);
        }
    }
    escaped.push_back('"');
    return escaped;
}

std::string BenchmarkFormatLabel(invisible_places::output::AnimationExportMode mode) {
    switch (mode) {
        case invisible_places::output::AnimationExportMode::FastPreviewMp4:
        case invisible_places::output::AnimationExportMode::HevcAlphaMp4:
            return "MP4";
        case invisible_places::output::AnimationExportMode::TestMp4:
            return "Test MP4";
        case invisible_places::output::AnimationExportMode::ProRes422Mov:
        case invisible_places::output::AnimationExportMode::ProRes422HqMov:
        case invisible_places::output::AnimationExportMode::ProRes422AlphaMatteMov:
        case invisible_places::output::AnimationExportMode::ProRes422HqAlphaMatteMov:
        case invisible_places::output::AnimationExportMode::ProRes422VideoToolboxMov:
        case invisible_places::output::AnimationExportMode::ProRes422HqVideoToolboxMov:
            return "ProRes 422";
        case invisible_places::output::AnimationExportMode::ProRes4444Mov:
        case invisible_places::output::AnimationExportMode::ProRes4444XqMov:
        case invisible_places::output::AnimationExportMode::ProRes4444VideoToolboxMov:
        case invisible_places::output::AnimationExportMode::ProRes4444XqVideoToolboxMov:
            return "ProRes 4444";
        case invisible_places::output::AnimationExportMode::PngStack:
            return "PNG Stack";
        case invisible_places::output::AnimationExportMode::FastPngStack:
            return "Fast PNG Stack";
        case invisible_places::output::AnimationExportMode::HqPreviewDensityExr:
            return "HQ EXR";
    }
    return "Export";
}

std::string BenchmarkSlug(std::string_view value) {
    std::string slug;
    slug.reserve(value.size());
    bool previousUnderscore = false;
    for (const char character : value) {
        const auto unsignedCharacter = static_cast<unsigned char>(character);
        if (std::isalnum(unsignedCharacter) != 0) {
            slug.push_back(static_cast<char>(std::tolower(unsignedCharacter)));
            previousUnderscore = false;
        } else if (!previousUnderscore && !slug.empty()) {
            slug.push_back('_');
            previousUnderscore = true;
        }
    }
    while (!slug.empty() && slug.back() == '_') {
        slug.pop_back();
    }
    return slug.empty() ? std::string{"variant"} : slug;
}

struct ExportBenchmarkVariant {
    invisible_places::output::AnimationExportMode mode =
        invisible_places::output::AnimationExportMode::FastPreviewMp4;
    invisible_places::output::AnimationExportQuality quality =
        invisible_places::output::AnimationExportQuality::Normal;
    bool useVideoToolbox = false;
};

